-- 0107_article_rewrite: replace the shared boilerplate template that
-- migration 0095 used for every one of the 262 published blog articles.
--
-- WHAT WAS WRONG. Every article shared one fixed body template word for
-- word -- the same opening line ("is best understood as a practical
-- question, not a slogan"), the same closing paragraph, the same four
-- FAQ questions verbatim -- with only the ingredient name substituted
-- into a few slots. All 262 excerpts and SEO descriptions were the same
-- sentence, title lower-cased and inserted: "A practical, evidence-aware
-- guide to {title}, including quality checks, kitchen use, storage and
-- common mistakes." Confirmed live on www.truegritin.com on 2026-08-17.
--
-- THE FIX. Every article below is rewritten individually: real, specific
-- claims about the actual ingredient or comparison, no shared paragraph,
-- no shared bullet item, no shared FAQ question, no dash used as a clause
-- connector (reads as AI-written), checked by the generator script that
-- produced this file -- the same cross-article duplicate detection
-- migration 0102 used for discussions and migration 0105 used for world
-- recipes, extended here to also cover the new bullet_list block type.
--
-- FORMAT. Short intro, a bullet_list for the actual substance, a
-- product_collection linking real SKUs, an inline community-discussion
-- link where one genuinely fits, then FAQ. Deliberately short: a body
-- floor of 120 words replaces the old 650-word floor that forced filler
-- into every article in the first place.
--
-- WHAT IS PRESERVED. Same id, same slug, same title, same hero image --
-- these URLs are already live and indexed, and changing them would break
-- inbound links and throw away whatever crawl history they have. A new
-- article_versions row is inserted (version 2) rather than mutating the
-- existing published version in place, matching how a real edit-and-
-- republish would work through the CMS.
PRAGMA foreign_keys = ON;

-- 001. What Is Kathiya Wheat? Origin, Taste, Texture & Uses
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_001_2','art_truegrit_001',2,'{"blocks":[{"id":"blk_article_1_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya is a bread wheat landrace grown on rain fed land in Madhya Pradesh and Rajasthan. The grain is denser and harder than modern high yield wheat, which is exactly why it stayed a small batch crop rather than a commodity one."]}},{"id":"blk_article_1_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually makes it different","items":["Dense, vitreous kernel. Hold one to the light and you can often see through the edge, similar to durum wheat.","Needs more water and a longer rest than standard atta. The harder starch takes longer to hydrate fully.","Milled slightly coarser than refined atta, which suits daliya and thick roti but fights a soft phulka.","Lower yield than modern wheat, which is the honest reason it costs more, not a certified health claim.","Harvested a couple of weeks later than high yield wheat grown in the same district."]}},{"id":"blk_article_1_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kathiya products","source":"manual","productSlugs":["organic-kathiya-wheat","kathiya-wheat-flour"],"limit":2}},{"id":"blk_article_1_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya wheat questions","items":[{"question":"Is Kathiya wheat the same as emmer wheat?","answer":"No. Emmer is a distinct, older wheat species. Kathiya is a bread wheat landrace, related to standard atta wheat, just a harder regional variety of it."},{"question":"Why does Kathiya cost more than ordinary atta?","answer":"Lower yield, rain fed cultivation, and a smaller pool of farmers still growing it. The price reflects scarcity, not a health claim."},{"question":"Can I use Kathiya flour in any roti recipe?","answer":"Yes, but add slightly more water and rest the dough longer than you would for regular atta."},{"question":"Does Kathiya flour need different storage?","answer":"The coarser milling means a little more bran exposed to air, so keep it airtight and use it within a few weeks for best flavour."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
