INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_001','What Is Kathiya Wheat? Origin, Taste, Texture & Uses','what-is-kathiya-wheat-origin-taste-texture-and-uses','A hard, low-yielding wheat landrace grown mainly in Madhya Pradesh and Rajasthan. What actually distinguishes it in the kitchen.','Kathiya wheat, heritage wheat, hard wheat variety, Indian wheat');

-- 002. What Is Banshi Wheat? A Complete Guide
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_002_2','art_truegrit_002',2,'{"blocks":[{"id":"blk_article_2_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Banshi is a bread wheat landrace grown on the Malwa plateau''s black cotton soil in Madhya Pradesh. It sits closer to the middle of the hardness scale than Kathiya, which is exactly its appeal."]}},{"id":"blk_article_2_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What makes it easy to cook with","items":["Medium texture. Doughs come together with the water ratios most home cooks already use.","Puffs and softens like a standard atta roti, without Kathiya''s noticeably chewier bite.","Warmer, creamier colour than heavily refined maida, from retained bran and germ.","Moderate input crop. Needs more water than Kathiya but less than fully dwarf high yield hybrids.","The easiest of the three landraces for a first time buyer, since it needs almost no technique adjustment.","Works well in yeasted bread too, giving a denser but still workable loaf compared to a dedicated bread flour."]}},{"id":"blk_article_2_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Banshi products","source":"manual","productSlugs":["banshi-wheat-flour"],"limit":1}},{"id":"blk_article_2_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Banshi wheat questions","items":[{"question":"Is Banshi wheat gluten free?","answer":"No. It is a bread wheat and contains gluten. Anyone with coeliac disease or a gluten sensitivity should avoid it entirely."},{"question":"How is Banshi different from Kathiya?","answer":"Banshi is softer and hydrates faster, giving a roti closer to standard atta. Kathiya is harder and needs more water and rest."},{"question":"Can Banshi flour be used for baking bread?","answer":"Yes, though the loaf will be denser than one made with a dedicated high protein bread flour."},{"question":"Does a creamier colour mean the flour is unrefined?","answer":"Not on its own. Colour depends on how much bran and germ the mill kept, which varies by batch."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The softer, more everyday relative of Kathiya, grown on the Malwa plateau. The difference that actually matters at the stove.', seo_description='Banshi wheat explained: where it is grown, how it differs from harder landraces like Kathiya, and what it suits best.', seo_keywords='Banshi wheat, soft wheat variety, Madhya Pradesh wheat', reading_minutes=3, published_version_id='arv_truegrit_002_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_002';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_002';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_002','What Is Banshi Wheat? A Complete Guide','what-is-banshi-wheat-a-complete-guide','The softer, more everyday relative of Kathiya, grown on the Malwa plateau. The difference that actually matters at the stove.','Banshi wheat, soft wheat variety, Madhya Pradesh wheat');

-- 003. What Is Paigambari Wheat? Everything You Need to Know
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_003_2','art_truegrit_003',2,'{"blocks":[{"id":"blk_article_3_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Paigambari is a bread wheat landrace grown in Bundelkhand, spanning southern Uttar Pradesh and northern Madhya Pradesh. Farmers and millers who handle it all say the same thing first: it smells more of wheat than either Kathiya or Banshi."]}},{"id":"blk_article_3_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What defines it","items":["Aroma fades over weeks of storage, so freshly ground is not just a marketing phrase here.","Smaller grain than Banshi, moderately hard, firmer than a soft commodity wheat.","Grown on rain fed land in a hot, semi arid climate that historically rewarded drought tolerance over yield.","Best in plain dishes where the wheat carries the flavour: simple roti, ghee brushed paratha, plain daliya.","Buy in small quantities and use within a month if the aroma is why you''re buying it.","Store it away from strong smelling spices in the pantry. Flour absorbs odours easily."]}},{"id":"blk_article_3_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Paigambari products","source":"manual","productSlugs":["paigambari-wheat-flour"],"limit":1}},{"id":"blk_article_3_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Paigambari wheat questions","items":[{"question":"Why is Paigambari more expensive than the other two?","answer":"Smaller grain, lower yield, and cultivation concentrated in one region. Scarcity drives the price, not a health claim."},{"question":"Does the aroma mean the flour is fresher than other brands?","answer":"It means the variety is naturally more aromatic. Aroma still fades with storage time regardless of variety."},{"question":"Is Paigambari good for daliya too?","answer":"Yes, its moderate hardness holds up reasonably well, though most buyers pick it for roti where the aroma stands out."},{"question":"How do I know a bag has lost its aroma?","answer":"Smell it directly rather than trusting the pack date. A flat, dusty smell means use it soon."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The aromatic outlier of the three: smaller grained, more fragrant when milled, and the one to reach for when a dish should taste of wheat.', seo_description='Paigambari wheat explained: its aroma, where it is grown, and the dishes where fresh flour is worth the higher price.', seo_keywords='Paigambari wheat, aromatic wheat, Bundelkhand wheat', reading_minutes=3, published_version_id='arv_truegrit_003_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_003';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_003';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_003','What Is Paigambari Wheat? Everything You Need to Know','what-is-paigambari-wheat-everything-you-need-to-know','The aromatic outlier of the three: smaller grained, more fragrant when milled, and the one to reach for when a dish should taste of wheat.','Paigambari wheat, aromatic wheat, Bundelkhand wheat');

-- 004. Kathiya Wheat vs Regular Wheat: What’s the Difference?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_004_2','art_truegrit_004',2,'{"blocks":[{"id":"blk_article_4_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Regular wheat almost always means a semi dwarf high yield variety bred for volume and milling consistency, with flavour and hardness as an afterthought. Kathiya was never part of that programme."]}},{"id":"blk_article_4_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The real differences","items":["Hardness. Kathiya''s kernel is dense and vitreous. Commodity wheat is bred softer and more uniform.","Hydration. Commodity atta recipes assume a water ratio that Kathiya needs more of, plus a longer rest.","Texture. Kathiya gives a firmer, chewier roti. Commodity wheat gives a softer, more uniform one.","Yield and price. Commodity wheat exists for high output at low cost. Kathiya''s smaller harvest is priced into every packet.","Seed saving. Kathiya farmers often replant saved seed. Commodity growers usually buy fresh certified seed each season.","Cooking time. Kathiya daliya generally needs a longer soak than daliya cracked from a softer commodity wheat."]}},{"id":"blk_article_4_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Try it yourself","source":"manual","productSlugs":["kathiya-wheat-flour","organic-kathiya-wheat"],"limit":2}},{"id":"blk_article_4_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya vs regular wheat questions","items":[{"question":"Is Kathiya more nutritious than regular wheat?","answer":"There is no verified, consistent nutritional advantage. Treat flavour and texture as the honest reason to choose it."},{"question":"Can I mix Kathiya and regular wheat flour?","answer":"Yes. Many cooks start around a quarter Kathiya to three quarters regular flour and adjust from there."},{"question":"Why does regular wheat flour look whiter?","answer":"Milling degree matters more than variety. Heavily refined atta removes more bran, which lightens the colour."},{"question":"Will Kathiya work in a bread machine set up for regular flour?","answer":"It can, but expect a denser loaf and may need to add water manually."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Regular wheat means a high yield dwarf variety bred since the 1960s for volume. Here is what that breeding history changed, set against Kathiya.', seo_description='Kathiya wheat compared against standard high yield bread wheat: hardness, dough behaviour, yield, and what is marketing versus real.', seo_keywords='Kathiya wheat vs regular wheat, heritage wheat comparison', reading_minutes=3, published_version_id='arv_truegrit_004_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_004';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_004';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_004','Kathiya Wheat vs Regular Wheat: What’s the Difference?','kathiya-wheat-vs-regular-wheat-what-s-the-difference','Regular wheat means a high yield dwarf variety bred since the 1960s for volume. Here is what that breeding history changed, set against Kathiya.','Kathiya wheat vs regular wheat, heritage wheat comparison');

-- 005. Banshi Wheat vs Regular Wheat
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_005_2','art_truegrit_005',2,'{"blocks":[{"id":"blk_article_5_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Of the three landraces, Banshi behaves most like the commodity wheat most Indian households already cook with. Both are bread wheat. The difference is entirely breeding history and scale."]}},{"id":"blk_article_5_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where they actually diverge","items":["Hardness is close enough that most cooks won''t notice a big hydration difference switching between them.","Flavour is where Banshi stands out, described as slightly more wheaty than commodity atta.","Price sits higher for Banshi, from lower yield and a smaller, less mechanised supply chain.","Milling consistency favours commodity atta, which comes from large mills blending huge harvests.","Traceability favours Banshi. A bag can often be traced to a specific district; pooled commodity grain cannot.","A blind taste test between the two is genuinely informative here, since the gap is close enough to actually check yourself."]}},{"id":"blk_article_5_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Try Banshi","source":"manual","productSlugs":["banshi-wheat-flour"],"limit":1}},{"id":"blk_article_5_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Banshi vs regular wheat questions","items":[{"question":"Will switching to Banshi change my roti recipe much?","answer":"Very little. Its hydration and gluten development are close enough to standard atta."},{"question":"Is Banshi worth the extra cost?","answer":"Depends what you value. If flavour and supporting smaller farms matter, yes. If price is the priority, commodity atta wins."},{"question":"Does Banshi keep as long as regular atta once opened?","answer":"Roughly the same, assuming similar milling and storage. Neither keeps forever."},{"question":"Can Banshi replace regular flour for thickening a gravy?","answer":"Yes, it behaves close enough to standard whole wheat flour for that."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Banshi sits closest to commodity wheat of the three landraces, which makes this comparison narrower and more useful.', seo_description='Banshi wheat against standard high yield atta: what changes in dough handling, flavour and price.', seo_keywords='Banshi wheat vs regular wheat, atta comparison', reading_minutes=3, published_version_id='arv_truegrit_005_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_005';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_005';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_005','Banshi Wheat vs Regular Wheat','banshi-wheat-vs-regular-wheat','Banshi sits closest to commodity wheat of the three landraces, which makes this comparison narrower and more useful.','Banshi wheat vs regular wheat, atta comparison');

-- 006. Paigambari Wheat vs Modern Wheat Varieties
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_006_2','art_truegrit_006',2,'{"blocks":[{"id":"blk_article_6_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Modern wheat is bred for a supply chain that prioritises predictable protein content and a shelf life measured in months. Paigambari sits at the other end: its aroma is strongest right after milling and fades from there."]}},{"id":"blk_article_6_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why they rarely compete for the same buyer","items":["Modern wheat''s uniform protein suits recipes that need reliable gluten, like yeasted bread.","Paigambari''s batch to batch variation makes it less predictable for that kind of baking.","Paigambari wins in plain dishes built around the wheat''s own flavour, like simple roti.","Buying Paigambari in bulk to save money is a false economy. The aroma fades regardless of quantity.","A modern harvest can take weeks or months to reach a shelf. Paigambari''s supply chain is short enough that sellers can often name the district it came from."]}},{"id":"blk_article_6_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Try Paigambari","source":"manual","productSlugs":["paigambari-wheat-flour"],"limit":1}},{"id":"blk_article_6_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Paigambari vs modern wheat questions","items":[{"question":"Does modern wheat have less flavour, or just different flavour?","answer":"Both, to some extent. Modern varieties were bred for yield and consistency, so most people find them milder."},{"question":"Is Paigambari harder to bake bread with?","answer":"It can be, mostly from batch to batch protein variation rather than the variety itself."},{"question":"Why don''t large bakeries use varieties like Paigambari?","answer":"Limited, inconsistent supply makes it impractical at industrial scale."},{"question":"Is there a middle ground?","answer":"Blending a small proportion of Paigambari into a modern flour is a common way to add aroma without losing predictability."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Modern breeding optimised for yield and shelf stable milling, exactly the two things Paigambari''s aroma tends to lose first.', seo_description='Paigambari wheat set against modern high yield varieties: why aroma fades in commodity milling and what that means for buying it.', seo_keywords='Paigambari wheat vs modern wheat, wheat breeding comparison', reading_minutes=3, published_version_id='arv_truegrit_006_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_006';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_006';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_006','Paigambari Wheat vs Modern Wheat Varieties','paigambari-wheat-vs-modern-wheat-varieties','Modern breeding optimised for yield and shelf stable milling, exactly the two things Paigambari''s aroma tends to lose first.','Paigambari wheat vs modern wheat, wheat breeding comparison');

-- 007. Kathiya vs Banshi vs Paigambari Wheat: Complete Comparison
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_007_2','art_truegrit_007',2,'{"blocks":[{"id":"blk_article_7_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["These three are often sold side by side, which invites treating them as interchangeable. They are not. Each was kept alive by a different farming community for a different reason."]}},{"id":"blk_article_7_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The quick version","items":["Kathiya. Hardest and most demanding. Firmer, chewier texture, best for daliya and thick roti.","Banshi. The middle ground and easiest entry point. Soft, forgiving, a modest flavour lift over commodity wheat.","Paigambari. The aroma outlier. Smaller grain, distinctly wheaty smell, best appreciated fresh in simple dishes.","Grown in three different, non overlapping regions of central India, which is part of why each developed its own character."]}},{"id":"blk_article_7_3","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Matching variety to dish","items":["Daliya with distinct chewy grains: Kathiya first, Paigambari second, Banshi softest of the three.","Everyday soft roti and paratha: Banshi is the least fuss.","A dish meant to taste of the wheat itself: Paigambari, if it''s genuinely fresh.","If you can only try one to start: Banshi needs the least adjustment to existing technique."]}},{"id":"blk_article_7_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"All three wheat varieties","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_7_5","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[Households comparing all three long term tend to keep two in rotation](/community/dsc_truegrit_030), a large everyday bag and a smaller specialty one, rather than settling on a single variety."]}},{"id":"blk_article_7_6","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya, Banshi and Paigambari questions","items":[{"question":"Which is best for pasta or vermicelli at home?","answer":"Kathiya''s hardness makes it the closest match to durum wheat, though all three can work with adjusted technique."},{"question":"Can the three be blended together?","answer":"Yes. Blending Kathiya with Banshi gives some firmer texture without the full hydration adjustment Kathiya needs alone."},{"question":"Is one of the three definitively the healthiest?","answer":"No verified ranking exists. Differences in flavour and texture are real; health claims beyond that deserve scepticism."},{"question":"What if my household cooking is genuinely varied?","answer":"Keep Banshi as the everyday default and add a small bag of Kathiya for daliya rather than trying to force one flour to do everything."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Three landraces, three different jobs: Kathiya for structure, Banshi for everyday ease, Paigambari for aroma.', seo_description='A side by side comparison of Kathiya, Banshi and Paigambari wheat: hardness, hydration, flavour, price and which dish suits each.', seo_keywords='Kathiya Banshi Paigambari comparison, traditional wheat varieties', reading_minutes=4, published_version_id='arv_truegrit_007_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_007';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_007';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_007','Kathiya vs Banshi vs Paigambari Wheat: Complete Comparison','kathiya-vs-banshi-vs-paigambari-wheat-complete-comparison','Three landraces, three different jobs: Kathiya for structure, Banshi for everyday ease, Paigambari for aroma.','Kathiya Banshi Paigambari comparison, traditional wheat varieties');

-- 008. Traditional Wheat Varieties of India You Should Know About
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_008_2','art_truegrit_008',2,'{"blocks":[{"id":"blk_article_8_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya, Banshi and Paigambari are the three most visible landraces today, but they are a small fraction of what Indian farmers grew before high yield varieties took over most cultivated area from the late 1960s onward."]}},{"id":"blk_article_8_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What happened to the rest","items":["Every region once kept its own locally adapted landrace, selected over generations for that specific soil and rainfall.","Most were never commercially named. They disappeared from farms as growers switched to higher yielding varieties.","Many survive only in gene banks now, kept specifically as a hedge against losing that genetic diversity entirely.","The handful that stayed in commercial cultivation share one trait: a distinguishing characteristic strong enough to justify the yield trade off.","This is not unique to wheat. Rice, millet and pulse landraces went through the same consolidation."]}},{"id":"blk_article_8_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"The survivors","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_8_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Traditional wheat variety questions","items":[{"question":"Why did most traditional wheat varieties disappear?","answer":"Lower yield made them uneconomical once government supported high yield varieties spread from the 1960s onward."},{"question":"Are traditional wheat varieties always more expensive?","answer":"Generally yes, from lower yield and smaller scale farming, not from an automatic health advantage."},{"question":"Can these varieties scale up if demand grows?","answer":"Only partially. Many were selected for hardiness on poor soil, a trait that trades off against yield by nature."},{"question":"Where can I learn about wheat native to my own region?","answer":"State agricultural universities and local Krishi Vigyan Kendras keep records of regional landraces."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Kathiya, Banshi and Paigambari are three survivors of a much larger list of regional landraces that defined Indian roti before the Green Revolution.', seo_description='An overview of India''s traditional wheat landraces beyond the big three, and why most quietly disappeared from farms after the 1960s.', seo_keywords='traditional Indian wheat varieties, wheat landraces India', reading_minutes=4, published_version_id='arv_truegrit_008_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_008';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_008';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_008','Traditional Wheat Varieties of India You Should Know About','traditional-wheat-varieties-of-india-you-should-know-about','Kathiya, Banshi and Paigambari are three survivors of a much larger list of regional landraces that defined Indian roti before the Green Revolution.','traditional Indian wheat varieties, wheat landraces India');

-- 009. Why Traditional Indian Wheat Varieties Are Making a Comeback
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_009_2','art_truegrit_009',2,'{"blocks":[{"id":"blk_article_9_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The wheat has not changed. What changed is a segment of buyers now willing to pay for traceable, small batch food and curious enough to ask where an ingredient came from."]}},{"id":"blk_article_9_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What''s actually driving it","items":["Rising interest in food provenance generally, plus social media making regional food visible outside its home area.","Urban buyers, with less informal local knowledge about farms, are often the most willing to pay for traceability.","Distinct flavour and texture are the defensible reasons to pay more, not an unverified health claim.","Supporting small scale, often rain fed farming that would otherwise have little economic reason to continue.","Every landrace still grown commercially is also working genetic material breeders may need for future traits like drought tolerance.","Not every product marketed as heritage or traditional deserves the premium it charges. Ask which district and season the grain came from."]}},{"id":"blk_article_9_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traceable, small batch wheat","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_9_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Heritage wheat demand questions","items":[{"question":"Is this backed by new scientific research?","answer":"Not primarily. It is driven more by interest in traceability and flavour than by new nutrition science."},{"question":"Will prices come down as demand grows?","answer":"Not necessarily. Yield per acre is fixed by the variety, so scaling supply is harder than for commodity wheat."},{"question":"Is buying heritage wheat actually helping small farmers?","answer":"It can, if the supply chain is genuinely traceable rather than blended and relabelled."},{"question":"Should I switch entirely for health reasons?","answer":"There is no established evidence of a health benefit from switching. Choose based on flavour and values around sourcing."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The renewed interest in landraces like Kathiya tracks a shift toward traceable, small batch food, not a scientific breakthrough.', seo_description='The real reasons traditional wheat landraces are seeing renewed demand: traceability and flavour, not new nutrition science.', seo_keywords='traditional wheat comeback, heritage grain demand India', reading_minutes=3, published_version_id='arv_truegrit_009_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_009';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_009';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_009','Why Traditional Indian Wheat Varieties Are Making a Comeback','why-traditional-indian-wheat-varieties-are-making-a-comeback','The renewed interest in landraces like Kathiya tracks a shift toward traceable, small batch food, not a scientific breakthrough.','traditional wheat comeback, heritage grain demand India');

-- 010. Ancient Wheat vs Modern Wheat: What Actually Changes?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_010_2','art_truegrit_010',2,'{"blocks":[{"id":"blk_article_10_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Modern semi dwarf wheat was bred from the 1960s onward to solve one problem: tall wheat collapsed under the weight of grain when given enough fertiliser to yield well. Shorter, stiffer plants fixed that."]}},{"id":"blk_article_10_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What''s established versus what''s overstated","items":["Established: modern wheat is shorter, more fertiliser responsive, and bred for milling consistency at scale.","Overstated: broad claims that modern wheat has meaningfully more gluten or is harder to digest than older varieties.","Gluten content varies by variety, soil and season. It is not a clean ancient versus modern split.","No wheat variety, ancient or modern, is safe for coeliac disease. Variety choice does not substitute for avoiding gluten.","The Green Revolution also sharply reduced famine risk across South Asia. The trade offs were real, but so was the problem it solved."]}},{"id":"blk_article_10_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditional varieties to compare","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour"],"limit":2}},{"id":"blk_article_10_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Ancient vs modern wheat questions","items":[{"question":"Does ancient wheat have less gluten?","answer":"Not reliably. Gluten content varies by variety, soil and season more than by an ancient versus modern split."},{"question":"Is ancient wheat safer for gluten sensitivity?","answer":"No wheat variety is safe for coeliac disease. Get guidance from a clinician, not a marketing claim."},{"question":"Why is modern wheat shorter than older varieties?","answer":"Semi dwarf breeding shortened the plant so it could carry a heavier, fertiliser boosted harvest without collapsing."},{"question":"Is there any verified nutritional benefit to ancient wheat?","answer":"Evidence is mixed and often contested. There is no settled consensus that it is nutritionally superior as a category."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Claims about ancient wheat being easier to digest or lower gluten are mostly overstated. What breeding since the 1960s actually changed.', seo_description='A grounded look at what wheat breeding since the Green Revolution actually altered, versus popular claims about gluten and digestibility.', seo_keywords='ancient wheat vs modern wheat, wheat breeding facts', reading_minutes=4, published_version_id='arv_truegrit_010_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_010';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_010';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_010','Ancient Wheat vs Modern Wheat: What Actually Changes?','ancient-wheat-vs-modern-wheat-what-actually-changes','Claims about ancient wheat being easier to digest or lower gluten are mostly overstated. What breeding since the 1960s actually changed.','ancient wheat vs modern wheat, wheat breeding facts');

-- 011. How Wheat Variety Changes the Taste of Your Roti
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_011_2','art_truegrit_011',2,'{"blocks":[{"id":"blk_article_11_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Roti flavour advice usually focuses on technique, resting the dough, pan temperature, kneading. All of that matters, but it sits on top of a flavour baseline the wheat variety sets before you even start."]}},{"id":"blk_article_11_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to run a fair comparison","items":["Same water ratio by weight, same rest time, same pan, same person cooking both.","Taste plain first, without dal or ghee masking the flavour.","Use flour bought around the same time. An old bag of one variety against a fresh bag of another mostly tests freshness, not variety.","Repeat a week later. A result that holds up twice is a real preference; one that flips is noise.","Try involving others who eat your roti regularly. Flavour perception varies between people tasting the same bread.","Maillard browning on the tawa interacts with variety too, since different sugar and protein levels colour and toast differently."]}},{"id":"blk_article_11_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Run your own comparison","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_11_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat variety and roti flavour questions","items":[{"question":"Does home grinding matter more than variety?","answer":"Freshness from home grinding is real but separate. The two effects add together rather than replacing each other."},{"question":"Why do professional kitchens sometimes prefer blander flour?","answer":"Consistency. A strongly flavoured wheat can clash with a dish''s other ingredients in a way neutral flour won''t."},{"question":"Can ghee mask the flavour difference between varieties?","answer":"Yes, to a degree. A plain phulka eaten with nothing added is the fairest comparison."},{"question":"Is flavour consistent for a variety across seasons?","answer":"Not entirely. The same variety can taste subtly different harvest to harvest, similar to wine vintages."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Two doughs, same water, same pan, same hands, and the roti still tastes different. Variety is doing more work than most cooks credit.', seo_description='Why the wheat variety behind your atta changes roti flavour independent of technique, and how to taste the difference yourself.', seo_keywords='wheat variety roti taste, atta flavour difference', reading_minutes=3, published_version_id='arv_truegrit_011_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_011';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_011';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_011','How Wheat Variety Changes the Taste of Your Roti','how-wheat-variety-changes-the-taste-of-your-roti','Two doughs, same water, same pan, same hands, and the roti still tastes different. Variety is doing more work than most cooks credit.','wheat variety roti taste, atta flavour difference');

-- 012. Why Freshly Ground Wheat Flour Tastes Different
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_012_2','art_truegrit_012',2,'{"blocks":[{"id":"blk_article_12_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A wheat kernel protects its oil rich germ inside a tough bran layer. Milling breaks that open, and the oils start oxidising from that moment on."]}},{"id":"blk_article_12_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What that means in practice","items":["Oxidation is gradual. Old flour doesn''t spoil overnight, but the aroma fades steadily over weeks.","Most whole wheat flour is genuinely best within two to four weeks of milling.","Heat and humidity both speed the process up. A pack date alone doesn''t account for how it was actually stored.","A quick check: rub a pinch between your fingers and smell it directly, rather than sniffing the bag from a distance.","Refined flour keeps far longer, since most of the oil carrying germ has already been removed."]}},{"id":"blk_article_12_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One thread compares how many days after chakki grinding people can actually tell the difference](/community/dsc_truegrit_008), worth a look if you''re deciding how often to buy."]}},{"id":"blk_article_12_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Freshly milled flour","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_12_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Fresh flour questions","items":[{"question":"How do I know if flour has gone rancid rather than just stale?","answer":"Rancid flour smells sharp and almost paint like, different from the mild flatness of merely old flour."},{"question":"Does refrigerating flour slow this down?","answer":"Yes, but only if the container is genuinely airtight, or condensation can introduce moisture instead."},{"question":"Is a home flour mill worth it?","answer":"For households that cook a lot of roti and value the aroma, yes. For occasional cooks, smaller packs bought more often achieve most of the same benefit."},{"question":"Does old flour ever become unsafe, or just less tasty?","answer":"Properly stored flour that has simply aged loses flavour rather than becoming unsafe. Visible mould or insects is a separate, real problem."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Flour starts losing its best flavour compounds within days of milling. The mechanism, and how much of a window you actually have.', seo_description='The chemistry behind why freshly milled wheat flour tastes different, and how long the difference actually lasts.', seo_keywords='fresh flour taste, freshly milled atta, flour oxidation', reading_minutes=3, published_version_id='arv_truegrit_012_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_012';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_012';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_012','Why Freshly Ground Wheat Flour Tastes Different','why-freshly-ground-wheat-flour-tastes-different','Flour starts losing its best flavour compounds within days of milling. The mechanism, and how much of a window you actually have.','fresh flour taste, freshly milled atta, flour oxidation');

-- 013. Stone-Ground vs Roller-Milled Wheat Flour
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_013_2','art_truegrit_013',2,'{"blocks":[{"id":"blk_article_13_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Stone milling crushes whole kernels between two rotating discs in a single pass. Roller milling, the industrial standard since the late 1800s, separates bran and germ through a sequence of steel rollers before optionally recombining them."]}},{"id":"blk_article_13_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The real differences","items":["Texture. Stone ground flour is coarser and less uniform. Roller milled whole wheat is finer and more even.","Heat. Stone mills run slower and generate less friction heat, which slightly slows the oxidation that causes staleness.","Scale. Roller mills produce far more uniform flour, far faster, which is why they became the industrial standard.","The word chakki traditionally means stone milled, but some products use the label loosely for a roller milled flour cut coarser to match the texture.","Genuine stone milling stays viable mainly at small scale, since stones wear down and need regular resurfacing that limits throughput."]}},{"id":"blk_article_13_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Stone ground options","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_13_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Stone ground vs roller milled questions","items":[{"question":"Is stone ground flour always healthier?","answer":"The difference is generally modest, not dramatic. Whether it''s genuinely whole grain matters more than the milling method."},{"question":"Why is stone ground flour usually more expensive?","answer":"Slower throughput and smaller batches mean higher production cost per kilogram."},{"question":"Can I substitute one for the other in any recipe?","answer":"Mostly yes, though stone ground flour may need slightly more water and a longer rest."},{"question":"Does chakki atta always mean stone ground?","answer":"Traditionally yes, but check the product description if the milling method specifically matters to you."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The two milling methods produce genuinely different flour, not just marketing language. The difference in texture, heat and what survives.', seo_description='How stone ground and roller milled wheat flour actually differ in process, texture and nutrient retention.', seo_keywords='stone ground vs roller milled flour, chakki atta milling', reading_minutes=3, published_version_id='arv_truegrit_013_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_013';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_013';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_013','Stone-Ground vs Roller-Milled Wheat Flour','stone-ground-vs-roller-milled-wheat-flour','The two milling methods produce genuinely different flour, not just marketing language. The difference in texture, heat and what survives.','stone ground vs roller milled flour, chakki atta milling');

-- 014. Whole Wheat Flour vs Refined Flour
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_014_2','art_truegrit_014',2,'{"blocks":[{"id":"blk_article_14_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A wheat kernel has three parts: starchy endosperm, fibrous bran, and oil rich germ. Whole wheat flour keeps all three. Refined flour, maida, removes the bran and germ."]}},{"id":"blk_article_14_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What that trade actually buys you","items":["Removing bran and germ is what gives refined flour its long, stable shelf life.","Bran and germ carry most of the fibre, B vitamins and minerals, along with whole wheat''s characteristic flavour.","Refined flour is lighter and more elastic by design, useful for pastries and some flatbreads.","For everyday roti and paratha, whole wheat is the standard choice and generally the more complete one nutritionally.","A small proportion of refined flour blended into a mostly whole wheat dough adds elasticity without losing most of the fibre.","Check the ingredient list rather than the front label. Multigrain doesn''t always mean fully whole grain."]}},{"id":"blk_article_14_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole wheat options","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_14_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole wheat vs refined flour questions","items":[{"question":"Is maida the same as all purpose flour?","answer":"Broadly similar, both refined wheat flour, though exact protein content can differ by brand."},{"question":"Does whole wheat always taste better?","answer":"Most people find it more flavourful, but some dishes genuinely benefit from refined flour''s neutral flavour."},{"question":"Can I substitute whole wheat for refined flour one for one?","answer":"Not always cleanly. Whole wheat absorbs more liquid and gives a denser result."},{"question":"Which keeps longer once opened?","answer":"Refined flour, since the oil rich germ that causes staleness has already been removed."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The bran and germ are the whole difference. What they add nutritionally, what they cost in shelf life, and when refined flour makes sense.', seo_description='Whole wheat atta compared against refined maida: what milling removes and when each makes sense.', seo_keywords='whole wheat vs refined flour, atta vs maida', reading_minutes=3, published_version_id='arv_truegrit_014_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_014';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_014';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_014','Whole Wheat Flour vs Refined Flour','whole-wheat-flour-vs-refined-flour','The bran and germ are the whole difference. What they add nutritionally, what they cost in shelf life, and when refined flour makes sense.','whole wheat vs refined flour, atta vs maida');

-- 015. How to Identify Good Quality Whole Wheat Flour
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_015_2','art_truegrit_015',2,'{"blocks":[{"id":"blk_article_15_1","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Before you buy","items":["Smell it if you can. Good flour smells mildly sweet and grainy. Sharp or musty means age or poor storage.","Check the milling date, not just the pack date. They aren''t always the same thing.","Look at the ingredient list. Plain whole wheat flour should list only wheat.","Consider how the seller stores it. Flour kept in a hot shop front ages faster than the pack date suggests."]}},{"id":"blk_article_15_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Once it''s in your kitchen","items":["Texture should be reasonably consistent, without hard lumps that suggest moisture got in.","Colour varies naturally by variety and milling degree. It''s not a reliable quality signal on its own.","Mix a small amount into a dough. It should come together smoothly, without unusual grittiness or stickiness.","Keep a mental note of how a trusted bag normally behaves, so a new one has a real baseline to be judged against."]}},{"id":"blk_article_15_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Quality flour worth trying","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_15_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flour quality check questions","items":[{"question":"Does whiter flour mean it''s been bleached?","answer":"Not necessarily. Colour depends on variety and milling degree as much as any bleaching agent."},{"question":"Is clumped flour always spoiled?","answer":"Not always. Mild clumping from humidity that breaks apart easily is usually fine. Hard, damp clumps with an off smell are not."},{"question":"Should whole wheat flour always be sifted?","answer":"Not required, but it can reveal foreign particles or unusually coarse bran worth noticing."},{"question":"How do I check for weevils?","answer":"Spread a small amount on a plate in good light and look for moving specks or fine webbing."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Smell, texture and colour tell you more about a bag of atta than the label does. What to check before and after buying.', seo_description='A practical checklist for judging whole wheat flour quality by smell, texture and appearance.', seo_keywords='how to identify good atta, whole wheat flour quality check', reading_minutes=3, published_version_id='arv_truegrit_015_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_015';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_015';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_015','How to Identify Good Quality Whole Wheat Flour','how-to-identify-good-quality-whole-wheat-flour','Smell, texture and colour tell you more about a bag of atta than the label does. What to check before and after buying.','how to identify good atta, whole wheat flour quality check');

-- 016. How to Store Organic Wheat Flour Correctly
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_016_2','art_truegrit_016',2,'{"blocks":[{"id":"blk_article_16_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The same germ and bran that give whole wheat flour its flavour also make it more perishable than refined flour. Three things determine how long a bag stays good: air exposure, temperature, and humidity."]}},{"id":"blk_article_16_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The routine that actually works","items":["Transfer flour to an airtight container as soon as you open the original packaging.","Keep it away from the stove and direct sunlight. Ambient heat from cooking accelerates staleness over weeks.","In humid climates, consider refrigeration for flour you won''t use soon, in a genuinely airtight container.","Buy quantities matched to how quickly your household actually finishes a bag, not the largest pack on the shelf.","Don''t top up an old container with a fresh bag. Finish the old stock first, or use a second container."]}},{"id":"blk_article_16_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[This thread on storing atta through a coastal monsoon](/community/dsc_truegrit_007) is worth reading if you''re in a humid climate without reliable refrigeration space."]}},{"id":"blk_article_16_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Store fresh, buy fresh","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_16_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat flour storage questions","items":[{"question":"Can whole wheat flour be frozen?","answer":"Yes, freezing slows oxidation well. Let it reach room temperature before opening to avoid condensation."},{"question":"How long does it last once opened?","answer":"Best flavour within four to eight weeks with good storage. It stays safely usable well beyond that, just less flavourful."},{"question":"Is plastic as good as steel or glass for storage?","answer":"A well sealed plastic container works fine. What matters is a genuinely airtight seal."},{"question":"Should containers be labelled with a date?","answer":"Yes, it makes first in first out rotation much easier to actually follow."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Whole wheat flour is more perishable than most kitchens treat it. The fix is container choice, temperature, and buying the right quantity.', seo_description='A practical guide to storing whole wheat flour so it stays fresh: containers, temperature, humidity, and realistic shelf life.', seo_keywords='how to store wheat flour, atta storage tips', reading_minutes=3, published_version_id='arv_truegrit_016_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_016';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_016';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_016','How to Store Organic Wheat Flour Correctly','how-to-store-organic-wheat-flour-correctly','Whole wheat flour is more perishable than most kitchens treat it. The fix is container choice, temperature, and buying the right quantity.','how to store wheat flour, atta storage tips');

-- 017. Why Wheat Flour Goes Rancid and How to Prevent It
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_017_2','art_truegrit_017',2,'{"blocks":[{"id":"blk_article_17_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Rancidity is a chemical reaction between oxygen and the unsaturated fats in the wheat germ. It starts the moment a kernel is milled and never fully stops, though storage conditions change its speed enormously."]}},{"id":"blk_article_17_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What speeds it up, and what slows it down","items":["Heat and light both accelerate oxidation directly. Moisture adds its own separate spoilage risk.","An airtight container beats a loosely closed bag by a wide margin.","A cool pantry shelf away from the stove outlasts a warmer spot with the exact same flour.","Buying fresher stock more often matters more for whole wheat than for refined flour, which has little germ oil to oxidise.","Trust your nose over the calendar. Transport and storage conditions move the real timeline more than a printed date.","High turnover kitchens rarely see rancidity for exactly this reason. Fast use naturally solves the storage problem."]}},{"id":"blk_article_17_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Buy what you''ll use fresh","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour"],"limit":2}},{"id":"blk_article_17_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Rancid flour questions","items":[{"question":"Is it dangerous to eat slightly rancid flour?","answer":"Mildly rancid flour is unpleasant tasting rather than acutely dangerous, but it''s best discarded since quality has clearly degraded."},{"question":"Does rancid flour smell different from mouldy flour?","answer":"Yes. Rancidity smells sharp and paint like. Mould or insects usually show visible signs and a different, musty smell."},{"question":"Does refined flour ever go rancid?","answer":"Much more slowly, since most of the germ that drives rancidity has already been removed."},{"question":"Can rancidity be reversed by any storage method?","answer":"No. Once the oxidation has happened, it can''t be undone. Prevention is the only real strategy."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Rancidity is oxidation. Once you know what''s oxidising, prevention is mostly about keeping air, heat and time away from the flour.', seo_description='The science of why whole wheat flour turns rancid, how to recognise it, and the storage habits that actually slow it down.', seo_keywords='why flour goes rancid, prevent atta spoilage', reading_minutes=3, published_version_id='arv_truegrit_017_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_017';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_017';
