-- 018. Does Freshly Milled Atta Make Better Rotis?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_018_2','art_truegrit_018',2,'{"blocks":[{"id":"blk_article_18_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Freshly milled flour has more of its aromatic compounds intact, since those compounds degrade from the moment of milling onward. The improvement is real but incremental, not transformative."]}},{"id":"blk_article_18_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Is it worth chasing","items":["For flour already bought and stored well, the marginal gain from grinding at home is real but modest.","For flour that sits in a hot kitchen for months, fixing storage and buying smaller amounts recovers most of the gap.","A home mill pays off for households that cook roti daily and genuinely value the flavour difference.","Some local mills grind to order at the point of sale, which captures most of the freshness benefit without owning a mill."]}},{"id":"blk_article_18_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One thread gets specific about how many days after grinding people can actually taste a difference](/community/dsc_truegrit_008)."]}},{"id":"blk_article_18_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Milled fresh","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour"],"limit":2}},{"id":"blk_article_18_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Fresh atta questions","items":[{"question":"How fresh does atta need to be to notice a difference?","answer":"Most people can tell flour milled within two weeks from flour milled two or more months earlier."},{"question":"Is home grinding worth it for daily cooking?","answer":"For heavy roti making households, often yes. For occasional cooks, buying smaller packs more often achieves most of the benefit."},{"question":"Does grinding at home save money?","answer":"Not usually, once the cost of a mill is factored in. The main benefit is freshness and control."},{"question":"Can I tell freshness just by looking?","answer":"Not reliably. Smell is a far better indicator than appearance, and packaging often prevents smelling before buying."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Yes, but the honest answer is about how much better, and whether it''s worth chasing for every meal.', seo_description='Whether freshly milled atta genuinely produces better rotis than shelf bought flour, and how large the difference actually is.', seo_keywords='fresh atta rotis, freshly milled flour benefits', reading_minutes=2, published_version_id='arv_truegrit_018_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_018';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_018';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_018','Does Freshly Milled Atta Make Better Rotis?','does-freshly-milled-atta-make-better-rotis','Yes, but the honest answer is about how much better, and whether it''s worth chasing for every meal.','fresh atta rotis, freshly milled flour benefits');

-- 019. Chakki Atta vs Packaged Atta: Understanding the Difference
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_019_2','art_truegrit_019',2,'{"blocks":[{"id":"blk_article_19_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Chakki atta traditionally means stone milled flour, often bought fresh from a local mill. Packaged atta usually means commercially branded flour with a longer distribution chain. These are two separate things marketing often blurs into one."]}},{"id":"blk_article_19_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually determines quality","items":["Freshness usually favours local chakki flour, mainly from a shorter gap between milling and purchase.","Whole grain content varies on both sides. Some packaged atta is fully whole wheat; some blends in refined flour.","Consistency favours packaged atta, since industrial milling and quality control are built for that.","Some local mills offer custom grinding, where you bring your own wheat to be ground fresh on the spot.","Many households use both: packaged atta as the everyday default, a local mill when a dish wants the freshest flour possible."]}},{"id":"blk_article_19_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Packaged, genuinely whole wheat","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_19_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Chakki vs packaged atta questions","items":[{"question":"Is chakki atta always stone ground?","answer":"Traditionally yes, but some products use the term loosely. Check with the seller if the method matters to you."},{"question":"Which is cheaper?","answer":"It varies by region and product. A local mill can beat a premium branded atta, or lose to a basic commodity one."},{"question":"Does packaged atta always contain preservatives?","answer":"No, many packaged whole wheat attas contain only wheat. Check the ingredient list rather than assuming."},{"question":"Should I seek out a local mill if good packaged atta is available?","answer":"If freshness and a direct relationship with a mill matter to you, yes. Otherwise a reliable packaged atta works fine."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Chakki atta isn''t automatically better than packaged atta. The real variables are milling method, freshness and whole grain content.', seo_description='What genuinely separates chakki atta from packaged commodity atta, and why the distinction is often smaller than marketing suggests.', seo_keywords='chakki atta vs packaged atta, local mill flour', reading_minutes=3, published_version_id='arv_truegrit_019_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_019';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_019';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_019','Chakki Atta vs Packaged Atta: Understanding the Difference','chakki-atta-vs-packaged-atta-understanding-the-difference','Chakki atta isn''t automatically better than packaged atta. The real variables are milling method, freshness and whole grain content.','chakki atta vs packaged atta, local mill flour');

-- 020. How Flour Particle Size Affects Roti Texture
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_020_2','art_truegrit_020',2,'{"blocks":[{"id":"blk_article_20_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Particle size determines how much surface area flour presents to water. Finer flour absorbs faster and more evenly. Coarser flour absorbs more slowly, which is why coarser doughs need a longer rest."]}},{"id":"blk_article_20_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Choosing the right grind","items":["Fine grind suits soft roti and paratha, developing gluten more fully with less resting time needed.","Coarse grind is the actual goal for daliya, giving the bite that keeps it from cooking into porridge.","Larger bran flakes in a coarse whole wheat flour can interrupt gluten formation, adding to its denser feel.","If flour feels coarser than expected for roti, add more water and rest longer rather than switching flours.","A quick home test: rub a pinch between your fingers. Fine flour feels almost powdery. Coarse flour feels distinctly grainy."]}},{"id":"blk_article_20_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Different grinds for different jobs","source":"manual","productSlugs":["kathiya-wheat-flour","daliya-kathiya-wheat"],"limit":2}},{"id":"blk_article_20_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flour particle size questions","items":[{"question":"Can I make flour finer at home?","answer":"Running it briefly through a dry grinder helps somewhat, but won''t fully match a mill''s even grind."},{"question":"Does a coarser grind mean more fibre?","answer":"Not necessarily. Particle size and bran content are related but distinct."},{"question":"Why does packaged atta feel more consistent than home ground flour?","answer":"Industrial mills sift and regrind through multiple passes to get a uniform size."},{"question":"Is finer flour always better for baking bread?","answer":"Generally yes for standard loaves, though some rustic styles deliberately use a coarser grind."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Fine versus coarse isn''t just texture preference. Particle size changes hydration, gluten development and how the roti behaves as it cools.', seo_description='How fine versus coarse milled flour changes dough hydration, gluten development and roti texture.', seo_keywords='flour particle size roti texture, coarse vs fine atta', reading_minutes=3, published_version_id='arv_truegrit_020_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_020';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_020';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_020','How Flour Particle Size Affects Roti Texture','how-flour-particle-size-affects-roti-texture','Fine versus coarse isn''t just texture preference. Particle size changes hydration, gluten development and how the roti behaves as it cools.','flour particle size roti texture, coarse vs fine atta');

-- 021. Best Wheat Flour for Soft Rotis
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_021_2','art_truegrit_021',2,'{"blocks":[{"id":"blk_article_21_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Three things decide softness, in order of impact: flour, hydration, and storage after cooking. Flour sets the ceiling. Banshi is the easiest path to soft, since its moderate gluten forgives average technique."]}},{"id":"blk_article_21_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Getting there","items":["Use lukewarm water. It hydrates flour faster and more completely than cold water.","Rest the dough at least 20 minutes, covered. This is the step most people skip, and the biggest lever.","Stack cooked rotis in a covered container right away. Left uncovered, they firm up within minutes.","A light brush of ghee off the tawa helps seal moisture in too.","If Kathiya is what you have, add more water, rest it longer, and keep the same covered storage habit."]}},{"id":"blk_article_21_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook worked through the exact same hydration problem with Kathiya here](/community/dsc_truegrit_001), worth a read if that''s the flour you''re using."]}},{"id":"blk_article_21_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"For soft rotis","source":"manual","productSlugs":["banshi-wheat-flour","kathiya-wheat-flour"],"limit":2}},{"id":"blk_article_21_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Soft roti questions","items":[{"question":"Does oil in the dough itself help?","answer":"A small amount can soften the texture slightly, but hydration and resting time matter more."},{"question":"Why do my rotis go hard within minutes of cooking?","answer":"Most often, moisture loss from being left uncovered. Stack them in a covered container instead."},{"question":"Is milk better than water for softer roti?","answer":"Some cooks use a milk and water mix for a softer, richer result, though it''s more preference than requirement."},{"question":"Can Kathiya ever make a genuinely soft roti?","answer":"With extra water, a longer rest and careful storage, it gets closer, though it still won''t fully match Banshi."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Soft roti is mostly about flour choice and hydration, not a secret technique. What actually gets you there.', seo_description='A practical guide to choosing wheat flour and technique for consistently soft rotis, comparing Banshi, Kathiya and standard atta.', seo_keywords='best flour for soft rotis, soft roti atta', reading_minutes=3, published_version_id='arv_truegrit_021_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_021';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_021';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_021','Best Wheat Flour for Soft Rotis','best-wheat-flour-for-soft-rotis','Soft roti is mostly about flour choice and hydration, not a secret technique. What actually gets you there.','best flour for soft rotis, soft roti atta');

-- 022. Best Wheat Variety for Chapati
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_022_2','art_truegrit_022',2,'{"blocks":[{"id":"blk_article_22_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Chapati wants thin, even rolling and, ideally, a puff of steam that separates two layers on the tawa. Both favour a dough with even, moderate gluten development."]}},{"id":"blk_article_22_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Getting the puff right","items":["Banshi''s moderate gluten supports thin rolling and puffing more reliably than Kathiya''s firmer structure.","Roll evenly. Uneven thickness is the most common reason chapati fails to puff, since steam escapes the thin spots first.","A hot, well preheated tawa matters as much as flour choice. Low heat means the surface won''t seal fast enough.","If chapati won''t puff despite good technique, check the dough''s moisture before blaming anything else.","Cooking directly on an open flame after the tawa stage gives more even, controllable puffing for many cooks.","Puffing improves noticeably with practice. Cooks who make chapati daily develop a feel for rolling thickness and tawa timing that''s hard to teach."]}},{"id":"blk_article_22_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"For chapati","source":"manual","productSlugs":["banshi-wheat-flour","kathiya-wheat-flour"],"limit":2}},{"id":"blk_article_22_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Chapati flour questions","items":[{"question":"Is there a real difference between chapati and roti?","answer":"Regional usage varies. Some traditions use the terms interchangeably, others distinguish by thickness or method."},{"question":"Why won''t my chapati puff even with good flour?","answer":"Uneven rolling and insufficient tawa heat are the most common causes, ahead of flour choice."},{"question":"Does resting the dough affect puffing?","answer":"Yes. A properly rested dough rolls more evenly and traps steam better."},{"question":"Can Kathiya chapati ever puff well?","answer":"With careful, even rolling and a very hot tawa, yes, though it demands more skill than a softer variety."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Chapati''s demand for thin, even rolling and a good puff points toward one variety over the others.', seo_description='Which wheat variety best suits chapati, and why the puffing and rolling demands of the dish favour one grain.', seo_keywords='best wheat for chapati, chapati flour variety', reading_minutes=3, published_version_id='arv_truegrit_022_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_022';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_022';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_022','Best Wheat Variety for Chapati','best-wheat-variety-for-chapati','Chapati''s demand for thin, even rolling and a good puff points toward one variety over the others.','best wheat for chapati, chapati flour variety');

-- 023. Best Wheat Flour for Paratha
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_023_2','art_truegrit_023',2,'{"blocks":[{"id":"blk_article_23_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Paratha is typically layered, folded, and often stuffed, and needs to hold together without tearing. That favours a flour with stronger gluten development than one bred purely for softness."]}},{"id":"blk_article_23_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Technique for stuffed and layered parathas","items":["Kathiya''s firmer structure, a liability for soft chapati, becomes an asset here, holding stuffing better.","Roll the outer dough slightly thicker before stuffing. A too thin base is the most common cause of tearing.","Seal stuffed parathas fully at the edges, and roll gently rather than pressing hard.","For layered parathas, rest between folding stages, not just once at the start.","Cook on medium heat, which gives the fat between folds time to render and separate the layers properly.","Drain wet fillings like grated aloo before stuffing. Excess moisture is a common cause of tearing."]}},{"id":"blk_article_23_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"For paratha","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour"],"limit":2}},{"id":"blk_article_23_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Paratha flour questions","items":[{"question":"Is Kathiya worth the extra hydration effort just for paratha?","answer":"For frequently stuffed or layered parathas, many cooks find it worthwhile. For plain paratha, Banshi is easier."},{"question":"Why does my stuffed paratha keep tearing?","answer":"Usually a too thin outer layer, an incomplete seal, or over stuffing relative to the dough''s strength."},{"question":"Does ghee in the dough help structure?","answer":"Ghee affects flakiness and richness more than raw strength, which comes mainly from gluten."},{"question":"Can refined flour be blended in for a more elastic dough?","answer":"Yes, a small proportion is sometimes used for extra elasticity, at the cost of some fibre and flavour."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Paratha wants structure, not softness. It needs to hold layers and stuffing without tearing, which changes the calculus from roti.', seo_description='Choosing wheat flour for paratha, where structural strength for layering and stuffing matters more than softness.', seo_keywords='best flour for paratha, paratha wheat variety', reading_minutes=3, published_version_id='arv_truegrit_023_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_023';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_023';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_023','Best Wheat Flour for Paratha','best-wheat-flour-for-paratha','Paratha wants structure, not softness. It needs to hold layers and stuffing without tearing, which changes the calculus from roti.','best flour for paratha, paratha wheat variety');

-- 024. Best Wheat for Daliya
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_024_2','art_truegrit_024',2,'{"blocks":[{"id":"blk_article_24_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Daliya''s appeal is texture: distinct, chewy grains, not mush. Kathiya''s density, a liability for soft roti, is exactly the advantage here."]}},{"id":"blk_article_24_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Getting the texture right","items":["Grind matters as much as variety. Even Kathiya daliya milled too fine cooks down fast and loses its bite.","Soak 30 minutes if you have time. Shortens cooking and gives more even results than starting dry.","Watch the ratio. Too much water and any variety turns to mush. Start around 1:2.5 grain to liquid.","Don''t over stir once liquid''s in. Daliya breaks down faster with frequent stirring, same as rice.","Toast the raw grain in ghee first for a nutty depth plain water cooked daliya lacks."]}},{"id":"blk_article_24_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[Others are comparing coarseness for savoury versus sweet daliya here](/community/dsc_truegrit_006) if you want more opinions on grind size."]}},{"id":"blk_article_24_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Daliya, all three varieties","source":"manual","productSlugs":["daliya-kathiya-wheat","daliya-banshi-wheat","daliya-paigambari-wheat"],"limit":3}},{"id":"blk_article_24_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya wheat questions","items":[{"question":"Can Banshi or Paigambari daliya still turn out well?","answer":"Yes, both work, but expect a softer result than Kathiya under the same cooking time."},{"question":"Does daliya grind size vary by brand?","answer":"Yes, considerably. Check the product description or a photo if grain size matters to your recipe."},{"question":"Is soaking necessary or just helpful?","answer":"Not strictly necessary, but it shortens cooking time and improves evenness."},{"question":"How do I fix daliya that turned out mushy?","answer":"There''s no fix for that batch. Next time, reduce liquid slightly and check texture a few minutes earlier."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Daliya is where wheat hardness stops being a hydration inconvenience and becomes the whole point.', seo_description='Which wheat variety and grind produce the best daliya texture, and why hardness that hurts roti helps here.', seo_keywords='best wheat for daliya, daliya grain variety', reading_minutes=3, published_version_id='arv_truegrit_024_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_024';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_024';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_024','Best Wheat for Daliya','best-wheat-for-daliya','Daliya is where wheat hardness stops being a hydration inconvenience and becomes the whole point.','best wheat for daliya, daliya grain variety');

-- 025. Which Wheat Is Best for Pasta?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_025_2','art_truegrit_025',2,'{"blocks":[{"id":"blk_article_25_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Traditional pasta uses durum wheat, a distinct species from the bread wheat these three landraces belong to. None of them will fully replicate durum''s firm bite, but Kathiya''s hardness gets closest."]}},{"id":"blk_article_25_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect and how to cook it","items":["Whole wheat pasta from these varieties is generally denser and cooks down faster if overdone than durum pasta.","Check doneness earlier than the package suggests, tasting from about two minutes before the stated time.","The flavour trade off runs the other way: noticeably more wheat flavour and a more rustic texture.","Robust sauces, tomato, garlic and chilli, pair better with this pasta than a delicate cream sauce would.","A longer dough rest, thirty minutes to an hour, helps if you''re making pasta at home from these flours."]}},{"id":"blk_article_25_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[Cooks working through Banshi pasta''s narrower al dente window share their timing here](/community/dsc_truegrit_004)."]}},{"id":"blk_article_25_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Wheat pasta","source":"manual","productSlugs":["pasta-kathiya-wheat","pasta-banshi-wheat","pasta-paigambari-wheat"],"limit":3}},{"id":"blk_article_25_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat pasta questions","items":[{"question":"Can I make proper al dente pasta with Kathiya flour?","answer":"You can get a firm bite, but the cooking window is narrower than durum pasta, so watch it closely."},{"question":"Why does whole wheat pasta cook faster than regular pasta?","answer":"A less tightly structured gluten network than durum semolina, plus often a different drying process."},{"question":"Is this pasta more nutritious than durum pasta?","answer":"It generally retains more fibre from using the whole grain, though check the specific product."},{"question":"Does pasta shape matter more with these flours?","answer":"Shorter, sturdier shapes hold together better than long thin strands."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Traditional pasta wants durum wheat''s specific hardness. None of these three are durum, so here''s the honest expectation.', seo_description='Whether Kathiya, Banshi or Paigambari wheat can substitute for durum wheat in pasta making, and what texture to expect.', seo_keywords='best wheat for pasta, wheat pasta at home', reading_minutes=3, published_version_id='arv_truegrit_025_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_025';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_025';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_025','Which Wheat Is Best for Pasta?','which-wheat-is-best-for-pasta','Traditional pasta wants durum wheat''s specific hardness. None of these three are durum, so here''s the honest expectation.','best wheat for pasta, wheat pasta at home');

-- 026. Which Wheat Variety Has the Most Distinctive Flavour?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_026_2','art_truegrit_026',2,'{"blocks":[{"id":"blk_article_26_1","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Ranking flavour honestly","items":["Paigambari: the most aromatic and flavourful when fresh, a pronounced wheaty smell the others don''t match.","Kathiya: fuller, nuttier flavour tied to its denser grain, a different kind of distinctiveness than aroma.","Banshi: the mildest of the three, a modest flavour lift over commodity atta rather than a dramatic departure.","A strongly flavoured flour can clash with a heavily spiced dish, masking the exact thing you paid extra for.","Distinctiveness fades fastest for Paigambari, so it demands the most attention to buying and storage habits.","Intensity isn''t the only axis. Kathiya''s nuttiness and Paigambari''s aroma are different characters, not just different volumes.","A ranking by intensity alone shouldn''t replace actually tasting all three. The one you personally prefer may not be the most intense."]}},{"id":"blk_article_26_2","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Taste them side by side","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_26_3","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat flavour questions","items":[{"question":"Does distinctive flavour mean objectively better quality?","answer":"No, it''s a characteristic, not a ranking. A milder wheat used well can still make excellent food."},{"question":"Can I get Paigambari''s flavour without the freshness sensitivity?","answer":"Not really, the flavour and the fading come from the same chemistry."},{"question":"Is flavour intensity consistent across seasons?","answer":"Not entirely. Growing conditions in a given season affect it, similar to wine vintages."},{"question":"Which is best for someone new to trying traditional wheat?","answer":"Banshi, since its lift over commodity atta is real but not so strong it demands rethinking your recipes."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='If flavour intensity alone decides it, Paigambari wins clearly. But most distinctive and best for your dish aren''t always the same thing.', seo_description='Comparing the flavour intensity of Kathiya, Banshi and Paigambari wheat, and why the most intense option isn''t always the best choice.', seo_keywords='most flavourful wheat variety, distinctive wheat taste', reading_minutes=2, published_version_id='arv_truegrit_026_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_026';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_026';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_026','Which Wheat Variety Has the Most Distinctive Flavour?','which-wheat-variety-has-the-most-distinctive-flavour','If flavour intensity alone decides it, Paigambari wins clearly. But most distinctive and best for your dish aren''t always the same thing.','most flavourful wheat variety, distinctive wheat taste');

-- 027. How to Choose Wheat Flour for Your Family
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_027_2','art_truegrit_027',2,'{"blocks":[{"id":"blk_article_27_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The most common mistake is picking based on marketing appeal rather than what your household actually cooks. A family eating mostly soft roti gains little from a harder, more demanding variety."]}},{"id":"blk_article_27_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"A practical way to decide","items":["List what gets cooked most: roti, paratha, daliya, some baking. Weight the decision toward the dominant use.","For genuinely varied cooking, one all purpose flour like Banshi plus a small bag of Kathiya for daliya often beats one flour trying to do everything.","Budget matters, and there''s no shame in that. Commodity atta used well makes perfectly good food.","A household in a hot, humid climate without reliable storage should buy smaller, more frequent quantities regardless of variety.","Involve everyone who eats the household''s roti in a taste comparison before committing to a switch."]}},{"id":"blk_article_27_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[Households that have tried all three long term share what they settled on here](/community/dsc_truegrit_030)."]}},{"id":"blk_article_27_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Start comparing","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_27_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Choosing family flour questions","items":[{"question":"Should I buy different flours for different dishes?","answer":"Either approach works. One all purpose flour simplifies shopping; a second bag for daliya adds a real texture benefit."},{"question":"Is it worth switching the whole family at once?","answer":"A gradual trial alongside your usual flour is more practical than switching entirely before knowing your household''s preference."},{"question":"How do children''s preferences factor in?","answer":"Milder, softer varieties like Banshi are generally more accepted by children than a firmer or stronger tasting option."},{"question":"Does the choice change with the seasons?","answer":"Not fundamentally, though smaller, more frequent purchases matter more in hot, humid months."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='There''s no single correct answer here. The right flour depends on what your household actually cooks and how much you use.', seo_description='A practical framework for choosing between wheat varieties based on your household''s actual cooking habits.', seo_keywords='how to choose wheat flour, family atta choice guide', reading_minutes=3, published_version_id='arv_truegrit_027_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_027';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_027';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_027','How to Choose Wheat Flour for Your Family','how-to-choose-wheat-flour-for-your-family','There''s no single correct answer here. The right flour depends on what your household actually cooks and how much you use.','how to choose wheat flour, family atta choice guide');

-- 028. How Much Atta Does a Family Need Per Month?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_028_2','art_truegrit_028',2,'{"blocks":[{"id":"blk_article_28_1","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"A rough but useful estimate","items":["About two to three rotis per adult per meal, 25 to 30 grams of flour per roti before cooking.","For an adult eating roti twice a day, that''s roughly 3 to 5.5 kilograms a month.","Multiply by how many people actually eat roti regularly, adjusting down for children.","Add 20 to 30 percent more if paratha, daliya or occasional baking are regular parts of your cooking.","Track actual purchases over two or three months for a more accurate, household specific number."]}},{"id":"blk_article_28_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why buying to that number matters","items":["The biggest bag for a marginally better price per kilogram usually costs you freshness instead.","A four person household using 15 to 20 kilograms a month is well served by a bag that finishes in three to four weeks.","Splitting a month''s supply across two purchases keeps flour fresher throughout without daily shopping trips."]}},{"id":"blk_article_28_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Buy the right quantity","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_28_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Monthly atta quantity questions","items":[{"question":"Does this estimate include paratha and other dishes?","answer":"The base estimate covers roti only. Add 20 to 30 percent more for regular paratha or daliya."},{"question":"Should I buy a month''s supply at once or split it?","answer":"Splitting into two purchases roughly two weeks apart balances convenience and freshness well."},{"question":"How does this change for a household eating more rice than roti?","answer":"Scale the estimate down proportionally to how many weekly meals actually include a wheat staple."},{"question":"Is buying a large bag more economical even with some waste?","answer":"Rarely. The saving per kilogram is usually modest next to the flavour loss from flour sitting too long."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A rough estimate is easy to calculate from how many meals actually include roti, and buying to that number beats buying the biggest bag.', seo_description='A practical way to estimate monthly household atta consumption, and why matching purchase size to actual use matters for freshness.', seo_keywords='how much atta per month, family flour consumption', reading_minutes=2, published_version_id='arv_truegrit_028_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_028';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_028';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_028','How Much Atta Does a Family Need Per Month?','how-much-atta-does-a-family-need-per-month','A rough estimate is easy to calculate from how many meals actually include roti, and buying to that number beats buying the biggest bag.','how much atta per month, family flour consumption');

-- 029. What Is Daliya?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_029_2','art_truegrit_029',2,'{"blocks":[{"id":"blk_article_29_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Daliya is whole wheat cracked into coarse pieces rather than milled into flour. It keeps the bran and germ that flour and semolina both remove, which is exactly why it cooks slower and eats chewier than either."]}},{"id":"blk_article_29_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Made by cracking cleaned whole wheat grains, not grinding them into powder the way atta is.","Sold in coarse, medium and fine grades depending on how many times it passes through the cracking rollers.","Retains the bran and germ, so it needs a longer simmer than a refined grain of similar size.","Cooked two main ways here: savoury with vegetables and dal, or sweet with milk and jaggery.","Different from Western cracked wheat and bulgur, which are usually parboiled before cracking. Daliya is generally cracked raw.","Any of our three wheat varieties can be cracked into daliya. The grain choice, not a separate crop, decides the flavour."]}},{"id":"blk_article_29_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Daliya to try","source":"manual","productSlugs":["daliya-banshi-wheat","daliya-kathiya-wheat"],"limit":2}},{"id":"blk_article_29_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya questions","items":[{"question":"Is daliya the same as the cracked wheat sold abroad?","answer":"Close but not identical. Western cracked wheat and bulgur are usually parboiled before cracking. Daliya is generally cracked raw, so it needs a longer soak or cook."},{"question":"Does daliya contain gluten?","answer":"Yes. It is whole wheat, so anyone avoiding gluten needs to skip it entirely, the same as any wheat product."},{"question":"Is daliya healthier than wheat flour?","answer":"It keeps the bran and germ that refined flour and semolina remove. That is a real processing difference, not a health claim we are making here."},{"question":"Can daliya replace rice in a meal?","answer":"Yes, cooked plain it works well as a rice substitute, though the texture stays noticeably chewier and more textured."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Whole wheat cracked into coarse pieces rather than ground into flour. What that one processing choice actually changes.', seo_description='Daliya explained: how it is made, how it differs from flour and semolina, and the two ways Indian kitchens usually cook it.', seo_keywords='daliya, cracked wheat, broken wheat, dalia', reading_minutes=3, published_version_id='arv_truegrit_029_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_029';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_029';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_029','What Is Daliya?','what-is-daliya','Whole wheat cracked into coarse pieces rather than ground into flour. What that one processing choice actually changes.','daliya, cracked wheat, broken wheat, dalia');

-- 030. How Is Traditional Wheat Daliya Made?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_030_2','art_truegrit_030',2,'{"blocks":[{"id":"blk_article_30_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Making daliya starts the same way as making flour, with clean, sound wheat, and then takes a different turn. Instead of grinding all the way to powder, the grain is cracked into a handful of coarse pieces and stopped there."]}},{"id":"blk_article_30_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The steps","items":["Wheat is cleaned and sometimes lightly dampened before cracking, which keeps the bran from shattering into dust.","Passed through fluted rollers or a stone cracker that breaks each grain into a few pieces rather than flour.","Sieved afterward to sort into coarse, medium and fine grades, usually sold separately rather than blended together.","No parboiling step here, unlike bulgur wheat, which is steamed before it is cracked in most Western processing.","The bran stays attached to most pieces, which is why daliya needs longer on the stove than a hulled or polished grain.","A miller producing atta from a batch will often crack a portion of the same wheat into daliya instead of grinding all of it."]}},{"id":"blk_article_30_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"See the grades","source":"manual","productSlugs":["daliya-kathiya-wheat","daliya-paigambari-wheat"],"limit":2}},{"id":"blk_article_30_4","type":"faq","version":1,"enabled":true,"props":{"heading":"How daliya is made, answered","items":[{"question":"Is daliya milled the same way as flour?","answer":"It starts the same way, cleaning sound wheat, but stops at cracking rather than continuing to a fine powder."},{"question":"Why do daliya grades differ between brands?","answer":"Grading depends on how the sieving stage is set. Coarse, medium and fine are relative terms, so check the actual grain size on the pack."},{"question":"Does daliya making remove the bran?","answer":"No. Unlike semolina or flour milling, cracking leaves the bran attached to most pieces, which is central to what daliya is."},{"question":"Is stone cracked daliya different from roller cracked?","answer":"It can be less uniform in size, which some cooks prefer for texture, though both are legitimate ways to produce it."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Cracking, not grinding. The steps that turn a bag of whole wheat into daliya, and where the grades split off.', seo_description='How daliya is traditionally made: cleaning, cracking and grading whole wheat into coarse, medium and fine daliya.', seo_keywords='how daliya is made, cracked wheat process, dalia making', reading_minutes=3, published_version_id='arv_truegrit_030_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_030';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_030';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_030','How Is Traditional Wheat Daliya Made?','how-is-traditional-wheat-daliya-made','Cracking, not grinding. The steps that turn a bag of whole wheat into daliya, and where the grades split off.','how daliya is made, cracked wheat process, dalia making');

-- 031. Daliya vs Oats: What’s the Difference?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_031_2','art_truegrit_031',2,'{"blocks":[{"id":"blk_article_31_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Daliya and oats get compared constantly as breakfast porridge rivals, but they start from different plants entirely. Daliya is cracked wheat. Oats come from a separate cereal grass, and that single fact explains most of the differences below."]}},{"id":"blk_article_31_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where they actually differ","items":["Different species. Daliya is wheat, oats are oats. They are not two forms of the same grain.","Oats contain avenin, a protein most people with coeliac disease tolerate better than wheat gluten, though cross contact during milling is still a real risk for anyone needing certified gluten free oats.","Oats release beta glucan as they cook, giving a naturally creamy porridge. Daliya stays grainier and holds its shape more.","Daliya leans savoury in most Indian kitchens. Oats lean sweet or toward an internationally styled breakfast bowl.","Daliya generally needs a longer soak or simmer than rolled oats, which are pre steamed and flattened during processing.","Neither is simply the better choice. The decision comes down to texture and what the rest of the dish is built around."]}},{"id":"blk_article_31_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Try daliya instead","source":"manual","productSlugs":["daliya-banshi-wheat"],"limit":1}},{"id":"blk_article_31_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya vs oats questions","items":[{"question":"Is daliya gluten free like some oats are?","answer":"No. Daliya is whole wheat and always contains gluten. Certified gluten free oats are a separate product entirely."},{"question":"Which cooks faster, daliya or rolled oats?","answer":"Rolled oats generally cook faster since they are pre steamed and flattened. Daliya, especially a coarse grade, takes longer."},{"question":"Can I substitute daliya for oats in a recipe?","answer":"You can, but expect a chewier, grainier result rather than a creamy one, and plan for a longer cooking time."},{"question":"Is one more filling than the other?","answer":"Both are whole grains with real fibre content. Neither has a verified advantage worth building a health claim around."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Different plants entirely, not just different textures. What that means for gluten, cooking time and how each is actually used here.', seo_description='Daliya compared with oats: different grain species, different protein, different texture, and where each fits in an Indian kitchen.', seo_keywords='daliya vs oats, dalia vs oats, cracked wheat vs oats', reading_minutes=3, published_version_id='arv_truegrit_031_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_031';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_031';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_031','Daliya vs Oats: What’s the Difference?','daliya-vs-oats-what-s-the-difference','Different plants entirely, not just different textures. What that means for gluten, cooking time and how each is actually used here.','daliya vs oats, dalia vs oats, cracked wheat vs oats');

-- 032. Daliya vs Suji
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_032_2','art_truegrit_032',2,'{"blocks":[{"id":"blk_article_32_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Daliya and suji both start as wheat, and both look vaguely similar in a jar, which is where most of the confusion comes from. What actually separates them is how much of the original grain survives processing."]}},{"id":"blk_article_32_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What separates them","items":["Different part of the grain. Daliya keeps the whole kernel cracked. Suji is only the coarse endosperm left once bran and germ are milled away.","Daliya shows visible bran flecks and an uneven shape. Suji looks uniformly pale and feels sandy rather than chunky.","Suji cooks faster, since there is no bran layer slowing water absorption the way there is with daliya.","Suji suits upma, halwa and rava idli. Daliya suits khichdi and porridge style dishes where a coarser bite is wanted.","Suji is essentially a byproduct of flour milling. Daliya is a separate cracking process applied to the whole grain."]}},{"id":"blk_article_32_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Compare them yourself","source":"manual","productSlugs":["daliya-kathiya-wheat","semolina-kathiya-wheat"],"limit":2}},{"id":"blk_article_32_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya vs suji questions","items":[{"question":"Can suji replace daliya in a recipe?","answer":"Not directly. Suji cooks faster and lacks daliya''s bran texture, so a recipe built for one will not behave the same with the other."},{"question":"Which has more fibre, daliya or suji?","answer":"Daliya, because it keeps the bran that suji milling removes. That is a processing fact, not a marketed nutrition claim."},{"question":"Is one more traditional than the other?","answer":"Both have long histories in Indian kitchens, just for different dishes. Neither is more authentic than the other."},{"question":"Do they store the same way?","answer":"Both need an airtight container, though suji''s finer texture picks up humidity a little faster than coarser daliya grades."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One keeps the whole grain, the other is refined down to the endosperm. The difference shows up in texture before anything else.', seo_description='Daliya compared with suji: which part of the wheat grain each one keeps, and which dishes actually suit each.', seo_keywords='daliya vs suji, dalia vs suji, cracked wheat vs semolina', reading_minutes=2, published_version_id='arv_truegrit_032_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_032';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_032';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_032','Daliya vs Suji','daliya-vs-suji','One keeps the whole grain, the other is refined down to the endosperm. The difference shows up in texture before anything else.','daliya vs suji, dalia vs suji, cracked wheat vs semolina');

-- 033. Daliya vs Broken Wheat
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_033_2','art_truegrit_033',2,'{"blocks":[{"id":"blk_article_33_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["In most Indian kitchens, daliya and broken wheat mean exactly the same thing, whole wheat cracked into coarse pieces. Where a real distinction sometimes shows up is in how deliberately the grain size was controlled."]}},{"id":"blk_article_33_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually check","items":["In everyday use, daliya and broken wheat are the same product, just different words for it.","Where sellers do distinguish them, broken wheat sometimes refers to irregular fragments left over from milling, while packaged daliya is cracked to a controlled, consistent size.","Both keep the bran and germ, unlike suji or refined flour, so neither is a lesser version of the other nutritionally.","If a pack simply says broken wheat with no grade marked, treat it as the coarse end of daliya and plan for a longer cook.","The naming matters less than checking the grade printed on the pack, coarse, medium or fine, before you buy."]}},{"id":"blk_article_33_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Graded daliya","source":"manual","productSlugs":["daliya-banshi-wheat","daliya-paigambari-wheat"],"limit":2}},{"id":"blk_article_33_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya and broken wheat questions","items":[{"question":"Should I buy broken wheat or daliya if both are on the shelf?","answer":"Check the grade on each pack rather than the name. A clearly graded pack is more predictable to cook with either way."},{"question":"Is broken wheat cheaper because it is a lower grade?","answer":"Sometimes, since it can include less consistently sized fragments, but this varies by seller and is not a fixed rule."},{"question":"Does the cooking method differ between the two?","answer":"Not meaningfully if the grain size is similar. Cook by grade and texture, not by which of the two names is on the pack."},{"question":"Can I mix broken wheat and daliya in one dish?","answer":"Yes, if the grades are close in size. A large mismatch in piece size will cook unevenly."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='In most kitchens these are the same product under two names. Here is where a real distinction sometimes exists.', seo_description='Daliya and broken wheat compared: whether they are the same product, and what to check when a pack only says one or the other.', seo_keywords='daliya vs broken wheat, dalia vs broken wheat', reading_minutes=2, published_version_id='arv_truegrit_033_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_033';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_033';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_033','Daliya vs Broken Wheat','daliya-vs-broken-wheat','In most kitchens these are the same product under two names. Here is where a real distinction sometimes exists.','daliya vs broken wheat, dalia vs broken wheat');

-- 034. Traditional Indian Daliya Breakfast Ideas
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_034_2','art_truegrit_034',2,'{"blocks":[{"id":"blk_article_34_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Daliya breakfasts split broadly into savoury and sweet, and most households have a clear preference. Grade matters here too, a coarser daliya suits a savoury upma style dish while a finer one breaks down better into a sweet kheer."]}},{"id":"blk_article_34_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Ways to cook it","items":["Namkeen daliya, tempered with mustard seeds, curry leaves and chopped vegetables, cooked until tender but still separate.","Sweet daliya kheer, simmered slowly in milk with jaggery or sugar and a little cardamom, closer to a porridge than the savoury version.","Daliya upma, cooked the same basic way as suji upma but with a coarser, chewier finished texture.","Rajasthani lapsi, daliya cooked in ghee and jaggery until glossy, traditionally served at festivals and celebrations.","Daliya khichdi, cooked together with moong dal and light spices for a filling one pot breakfast or light dinner."]}},{"id":"blk_article_34_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Start your morning batch","source":"manual","productSlugs":["daliya-banshi-wheat"],"limit":1}},{"id":"blk_article_34_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya breakfast questions","items":[{"question":"Which grade of daliya suits a savoury upma style breakfast?","answer":"A medium to coarse grade holds its shape better and gives the separate texture most savoury daliya dishes want."},{"question":"Can I prepare daliya the night before?","answer":"Yes, soaking or even partly cooking it the night before shortens the morning cooking time considerably."},{"question":"Is sweet daliya kheer the same as rice kheer?","answer":"Same basic method, milk simmered with a grain and sweetener, but daliya gives a chewier bite than rice does."},{"question":"What vegetables work best in namkeen daliya?","answer":"Carrot, peas, beans and onion are common choices. Anything that cooks through in the same time as the daliya works well."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Savoury, sweet and everything between. The daliya breakfasts Indian kitchens actually cook, not a single default recipe.', seo_description='Traditional daliya breakfast ideas: namkeen daliya, sweet daliya kheer, upma style daliya and Rajasthani lapsi.', seo_keywords='daliya breakfast, daliya recipes, dalia for breakfast', reading_minutes=3, published_version_id='arv_truegrit_034_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_034';
