-- 037. One-Pot Masala Daliya
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_037_2','art_truegrit_037',2,'{"blocks":[{"id":"blk_article_37_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Masala daliya done well should look like a savoury pulao, with grains you can see individually, not a thick porridge. The method below is built around keeping it that way, in one pot, start to finish."]}},{"id":"blk_article_37_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Dry roast the daliya in a little ghee for two to three minutes before adding any liquid. This firms each grain and helps it stay separate.","Build a base of onion, tomato and a standard tempering, mustard seeds, cumin and curry leaves, in the same pot before adding the roasted daliya.","Use roughly two and a half parts water to one part daliya in a pressure cooker, less if finishing in an open pot with a longer simmer instead.","Add chopped vegetables like carrot, peas and beans at the same time as the daliya, so everything finishes cooking together.","Pressure cook for two to three whistles on medium heat, then let the pressure drop on its own rather than releasing it immediately.","Finish with a squeeze of lemon and fresh coriander once the lid is off and the steam has settled."]}},{"id":"blk_article_37_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Daliya for this recipe","source":"manual","productSlugs":["daliya-banshi-wheat","daliya-kathiya-wheat"],"limit":2}},{"id":"blk_article_37_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Masala daliya questions","items":[{"question":"Can I make masala daliya without a pressure cooker?","answer":"Yes, simmer covered in an open pot, checking and stirring occasionally, adding a little extra water if it dries out before the grain is tender."},{"question":"Why did my masala daliya turn mushy?","answer":"Usually too much water, too many whistles, or skipping the dry roast step, which is what firms the grain before liquid goes in."},{"question":"Can I add more vegetables than the recipe calls for?","answer":"Yes, though very watery vegetables like tomato in excess can throw off the water ratio, so adjust liquid slightly if you add a lot."},{"question":"Which daliya grade works best for this dish?","answer":"Medium grade is the most forgiving. Coarse needs more water and time, fine can turn softer than this recipe wants."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A pressure cooker method that keeps the grains separate rather than turning the whole pot to porridge.', seo_description='A one pot masala daliya method: roasting, tempering, water ratio and pressure cooker timing for separate, non mushy grains.', seo_keywords='masala daliya recipe, one pot daliya, savoury daliya', reading_minutes=3, published_version_id='arv_truegrit_037_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_037';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_037';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_037','One-Pot Masala Daliya','one-pot-masala-daliya','A pressure cooker method that keeps the grains separate rather than turning the whole pot to porridge.','masala daliya recipe, one pot daliya, savoury daliya');

-- 039. Kathiya Wheat Daliya: Taste & Uses
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_039_2','art_truegrit_039',2,'{"blocks":[{"id":"blk_article_39_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya daliya inherits the same density that makes Kathiya flour behave differently at the stove. Cracked from a harder kernel, it keeps a firmer bite than daliya cracked from Banshi or Paigambari, even after a full simmer."]}},{"id":"blk_article_39_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Needs a longer soak, thirty minutes or more, before it cooks evenly in an open pot.","Keeps a firmer bite even after a full cook, which suits dishes where you want the grain to hold its shape.","Works well in a savoury upma style breakfast or as a pulao substitute where texture matters.","Less suited to a smooth, fully broken down kheer, where a softer wheat gets there faster with less liquid.","Priced the same way Kathiya flour is, lower yield and rain fed cultivation, not a certified nutrition claim."]}},{"id":"blk_article_39_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kathiya daliya","source":"manual","productSlugs":["daliya-kathiya-wheat"],"limit":1}},{"id":"blk_article_39_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya daliya questions","items":[{"question":"Does Kathiya daliya need a longer soak than other varieties?","answer":"Yes, its harder kernel hydrates more slowly, so a longer soak or a few extra pressure cooker whistles helps it cook evenly."},{"question":"Is Kathiya daliya good for a first time cook?","answer":"It is more forgiving to overcook than undercook, but Banshi daliya is generally the easier starting point."},{"question":"Can Kathiya daliya be used for sweet kheer?","answer":"It can, but it stays chewier than a softer wheat kheer would. Many cooks prefer Banshi or Paigambari for the sweet version."},{"question":"Why does Kathiya daliya cost more?","answer":"The same reasons as Kathiya flour, lower yield and rain fed cultivation on a smaller growing area, not an added health claim."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Cracked from the hardest of our three wheats, so it keeps a firmer bite even after a full cook.', seo_description='Kathiya wheat daliya explained: how its hardness changes cooking time, texture and which dishes it suits best.', seo_keywords='Kathiya daliya, Kathiya wheat dalia', reading_minutes=2, published_version_id='arv_truegrit_039_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_039';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_039';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_039','Kathiya Wheat Daliya: Taste & Uses','kathiya-wheat-daliya-taste-and-uses','Cracked from the hardest of our three wheats, so it keeps a firmer bite even after a full cook.','Kathiya daliya, Kathiya wheat dalia');

-- 040. Banshi Wheat Daliya: Taste & Uses
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_040_2','art_truegrit_040',2,'{"blocks":[{"id":"blk_article_40_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Banshi daliya sits in the middle of the hardness range, and that middling quality is exactly its appeal. It cooks close to what a generic daliya recipe already assumes, without the adjustments Kathiya sometimes needs."]}},{"id":"blk_article_40_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Medium hardness cooks predictably, landing close to the water ratios and timing most daliya recipes already assume.","Works equally well in a savoury upma style breakfast and a softer sweet kheer, which is why it suits most households.","Needs less soaking time than Kathiya daliya, usually fifteen to twenty minutes is enough for even cooking.","The most forgiving of the three if you are cooking daliya for the first time and are still learning the timing.","A reasonable everyday choice if you only want to stock one daliya variety rather than rotating between all three."]}},{"id":"blk_article_40_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Banshi daliya","source":"manual","productSlugs":["daliya-banshi-wheat"],"limit":1}},{"id":"blk_article_40_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Banshi daliya questions","items":[{"question":"Is Banshi daliya a good starting choice?","answer":"Yes, its medium hardness cooks close to what most daliya recipes already assume, making it the most forgiving starting point."},{"question":"Does Banshi daliya need soaking?","answer":"A short soak, fifteen to twenty minutes, helps but is less critical than it is for Kathiya daliya."},{"question":"Can Banshi daliya be used for both savoury and sweet dishes?","answer":"Yes, it handles a savoury upma style dish and a softer sweet kheer about equally well."},{"question":"How does Banshi daliya compare to Kathiya in cooking time?","answer":"It cooks a little faster and more predictably, since the kernel is softer and hydrates more evenly."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The most forgiving of the three wheat daliyas, cooking close to what most recipes already assume.', seo_description='Banshi wheat daliya explained: medium hardness, predictable cooking time, and why it suits both savoury and sweet dishes.', seo_keywords='Banshi daliya, Banshi wheat dalia', reading_minutes=2, published_version_id='arv_truegrit_040_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_040';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_040';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_040','Banshi Wheat Daliya: Taste & Uses','banshi-wheat-daliya-taste-and-uses','The most forgiving of the three wheat daliyas, cooking close to what most recipes already assume.','Banshi daliya, Banshi wheat dalia');

-- 041. Paigambari Wheat Daliya: Taste & Uses
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_041_2','art_truegrit_041',2,'{"blocks":[{"id":"blk_article_41_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Paigambari daliya carries through the same aroma that sets Paigambari flour apart, which comes through clearly in a plain, lightly spiced preparation rather than a heavily masala laden one."]}},{"id":"blk_article_41_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Aroma is the main draw here, most noticeable in simple preparations where the grain''s own flavour is not competing with heavy spicing.","Moderately hard, sitting closer to Banshi than Kathiya for cooking time and water needs.","Best suited to a plain, lightly tempered daliya rather than a heavily masala laden version.","Aroma fades with storage time the same way it does in the flour, so buy in quantities you will use within a few weeks.","Store it away from strong smelling spices in the pantry, since the grain picks up odours as readily as the flour does."]}},{"id":"blk_article_41_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Paigambari daliya","source":"manual","productSlugs":["daliya-paigambari-wheat"],"limit":1}},{"id":"blk_article_41_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Paigambari daliya questions","items":[{"question":"Why choose Paigambari daliya over the other two?","answer":"Mainly for its aroma, which shows up best in plain, lightly spiced preparations rather than heavily masala laden ones."},{"question":"Does Paigambari daliya cook faster than Kathiya?","answer":"Yes, it is moderately hard rather than dense, so it cooks a little faster and needs a shorter soak."},{"question":"How should I store Paigambari daliya to keep the aroma?","answer":"Keep it airtight, away from strong smelling spices, and use it within a few weeks rather than stocking a large quantity."},{"question":"Is Paigambari daliya good for sweet kheer?","answer":"It works, though most buyers choose it for plain or lightly spiced savoury dishes where the aroma stands out more clearly."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Carries the same aroma that defines Paigambari flour, best in plain preparations where that flavour can actually show.', seo_description='Paigambari wheat daliya explained: its aroma, cooking behaviour, and which dishes let its flavour show through.', seo_keywords='Paigambari daliya, Paigambari wheat dalia', reading_minutes=2, published_version_id='arv_truegrit_041_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_041';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_041';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_041','Paigambari Wheat Daliya: Taste & Uses','paigambari-wheat-daliya-taste-and-uses','Carries the same aroma that defines Paigambari flour, best in plain preparations where that flavour can actually show.','Paigambari daliya, Paigambari wheat dalia');

-- 042. Kathiya vs Banshi vs Paigambari Daliya
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_042_2','art_truegrit_042',2,'{"blocks":[{"id":"blk_article_42_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The hardness differences that separate Kathiya, Banshi and Paigambari as flours carry straight through into daliya. Cracking the grain does not erase what the variety itself brings to the pot."]}},{"id":"blk_article_42_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Side by side","items":["Cook time. Kathiya needs the longest soak and simmer, Banshi is the quickest, Paigambari sits in between the two.","Texture after cooking. Kathiya stays firmest, Banshi softens most predictably, Paigambari lands close to Banshi.","Best use. Kathiya for dishes that want bite, Banshi for an everyday all purpose batch, Paigambari for plain preparations where aroma should show.","Price. All three cost more than a commodity daliya for the same reasons as the flours, lower yield and a smaller growing region.","Beginners generally do best starting with Banshi, then trying Kathiya or Paigambari once they know how they like their daliya cooked."]}},{"id":"blk_article_42_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[Households who have tried all three long term talk through what they settled on here](/community/dsc_truegrit_030), useful if you are deciding whether to stock one variety or several."]}},{"id":"blk_article_42_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Try all three","source":"manual","productSlugs":["daliya-kathiya-wheat","daliya-banshi-wheat","daliya-paigambari-wheat"],"limit":3}},{"id":"blk_article_42_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Three way daliya questions","items":[{"question":"Which daliya variety should a beginner buy first?","answer":"Banshi. It cooks the most predictably and needs the least adjustment from a generic daliya recipe."},{"question":"Is there a big taste difference between the three as daliya?","answer":"Paigambari''s aroma is the most noticeable difference. Kathiya and Banshi differ more in texture and cook time than in flavour."},{"question":"Do I need to keep all three varieties of daliya stocked?","answer":"No. Most households settle on one everyday variety and buy the others only for a specific dish or occasion."},{"question":"Which is best for a quick weekday breakfast?","answer":"Banshi, since it cooks fastest and most predictably among the three."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same three wheat personalities from the flour comparisons, carried through into how each cooks as daliya.', seo_description='Kathiya, Banshi and Paigambari daliya compared directly: cook time, texture and which dish suits each variety best.', seo_keywords='Kathiya vs Banshi vs Paigambari daliya, wheat daliya comparison', reading_minutes=3, published_version_id='arv_truegrit_042_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_042';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_042';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_042','Kathiya vs Banshi vs Paigambari Daliya','kathiya-vs-banshi-vs-paigambari-daliya','The same three wheat personalities from the flour comparisons, carried through into how each cooks as daliya.','Kathiya vs Banshi vs Paigambari daliya, wheat daliya comparison');

-- 043. How to Cook Daliya Without Making It Mushy
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_043_2','art_truegrit_043',2,'{"blocks":[{"id":"blk_article_43_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Mushy daliya is almost always a timing and ratio problem rather than a bad batch of grain. The fixes below are small, but they matter more here than they would for rice, since daliya moves from tender to mush in a narrower window."]}},{"id":"blk_article_43_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Dry roast the daliya for two to three minutes before adding any liquid. This firms the outside of each piece and slows how fast it breaks down.","Use the water ratio suited to the grade you bought. Coarse daliya needs more liquid and more time than a fine grade of the same wheat.","Do not walk away once it reaches a simmer. Daliya moves from tender to mushy faster than rice does at a similar stage.","Turn off the heat slightly before the grain looks fully done, and let it finish in residual steam with the lid on.","If pressure cooking, count whistles rather than cooking to a fixed timer, since stove strength varies enough to matter here."]}},{"id":"blk_article_43_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One thread works through the exact same coarse versus fine texture question](/community/dsc_truegrit_006), useful if you are trying to get one grade to work for two different dishes."]}},{"id":"blk_article_43_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Daliya to practise on","source":"manual","productSlugs":["daliya-banshi-wheat"],"limit":1}},{"id":"blk_article_43_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Mushy daliya questions","items":[{"question":"Why does my daliya always turn mushy?","answer":"Usually too much water, too long on the heat, or skipping the dry roast step that firms each piece before liquid goes in."},{"question":"Does soaking prevent mushiness?","answer":"It shortens cooking time, which indirectly helps, but the bigger factor is how closely you watch the pot once it is simmering."},{"question":"Can overcooked daliya be saved?","answer":"Not back to a separate texture, but it can be repurposed into a thick porridge or soup where mush is not a problem."},{"question":"Does grade affect how easily daliya turns mushy?","answer":"Yes, finer grades go mushy faster than coarse ones, so adjust your watching and timing to the grade you bought."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The window between properly cooked and mush is narrower than rice. A few technique fixes close most of the gap.', seo_description='How to cook daliya so it stays separate and textured: roasting, water ratio, and timing that avoids a mushy result.', seo_keywords='how to cook daliya, daliya mushy, dalia cooking tips', reading_minutes=3, published_version_id='arv_truegrit_043_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_043';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_043';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_043','How to Cook Daliya Without Making It Mushy','how-to-cook-daliya-without-making-it-mushy','The window between properly cooked and mush is narrower than rice. A few technique fixes close most of the gap.','how to cook daliya, daliya mushy, dalia cooking tips');

-- 044. How Long Should Daliya Be Soaked?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_044_2','art_truegrit_044',2,'{"blocks":[{"id":"blk_article_44_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["There is no single correct soaking time for daliya. Grade and wheat variety both change the answer, and skipping the soak entirely is a legitimate choice, just one with a trade attached."]}},{"id":"blk_article_44_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What changes the answer","items":["Coarse daliya benefits most from soaking, thirty minutes or more, since the pieces are larger and slower to hydrate.","Fine daliya needs little to no soak. It cooks quickly enough on its own that soaking mostly saves a few minutes of simmering.","Kathiya daliya, being the hardest of our three wheat varieties, benefits more from a longer soak than Banshi or Paigambari.","Skipping the soak is not a mistake, only a trade. Expect a longer stovetop time or an extra pressure cooker whistle to compensate.","Soaking in warm rather than cold water shortens the wait noticeably if you are short on time before cooking."]}},{"id":"blk_article_44_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One discussion works through whether the extra cooking time for whole grains like daliya is worth counting in gas cost](/community/dsc_truegrit_028), relevant if you are deciding whether soaking is worth the wait."]}},{"id":"blk_article_44_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Daliya by grade","source":"manual","productSlugs":["daliya-kathiya-wheat","daliya-banshi-wheat"],"limit":2}},{"id":"blk_article_44_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya soaking questions","items":[{"question":"Can I skip soaking daliya entirely?","answer":"Yes, it just needs a longer cooking time or an extra pressure cooker whistle to reach the same result."},{"question":"Does soaking daliya overnight cause problems?","answer":"Refrigerate it if soaking longer than a couple of hours in warm weather, to avoid any fermentation smell developing."},{"question":"Is warm water better than cold for soaking?","answer":"Warm water speeds hydration, useful if you are short on time, though cold water works fine given enough time."},{"question":"Does soaking change the final texture?","answer":"It generally gives a more even texture throughout, since every piece has had time to hydrate before heat is applied."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Depends on grade and variety more than a single fixed number. What actually changes the answer.', seo_description='How long to soak daliya before cooking, by grade and by wheat variety, and what skipping the soak actually costs you.', seo_keywords='daliya soaking time, how long to soak dalia', reading_minutes=2, published_version_id='arv_truegrit_044_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_044';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_044';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_044','How Long Should Daliya Be Soaked?','how-long-should-daliya-be-soaked','Depends on grade and variety more than a single fixed number. What actually changes the answer.','daliya soaking time, how long to soak dalia');

-- 045. Five Ways to Use Daliya Beyond Breakfast
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_045_2','art_truegrit_045',2,'{"blocks":[{"id":"blk_article_45_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Daliya gets typecast as a breakfast grain, mostly because that is where most households first meet it. It holds up just as well later in the day, in dishes that have nothing to do with porridge."]}},{"id":"blk_article_45_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Five places it works","items":["Daliya khichdi, cooked with moong dal and light spices, works as a filling light lunch or dinner, not only a morning dish.","As a pulao substitute, sauteed with whole spices and vegetables the same way rice would be, for a coarser, higher fibre result.","Stirred into a thick vegetable soup near the end of cooking, daliya thickens it naturally without needing a separate roux.","Used as a stuffing base for paratha, cooked soft and mixed with spices before being sealed into the dough.","Added to a homemade granola style mix after light roasting, for a crunch plain rolled oats do not give."]}},{"id":"blk_article_45_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Daliya for the week","source":"manual","productSlugs":["daliya-paigambari-wheat","daliya-banshi-wheat"],"limit":2}},{"id":"blk_article_45_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya beyond breakfast questions","items":[{"question":"Can daliya replace rice in a pulao style dish?","answer":"Yes, sauteed and cooked the same way rice would be, though the result is chewier and higher in fibre."},{"question":"How much daliya should I add to thicken soup?","answer":"Start with a small handful per pot and add more if needed. It thickens more than an equivalent amount of rice would."},{"question":"Does daliya work in a paratha stuffing?","answer":"Yes, cooked soft and spiced first, it holds together well as a stuffing once the dough is sealed and rolled."},{"question":"Can daliya be used in a dinner dish, not just breakfast?","answer":"Yes, khichdi and pulao style preparations both work well as a light dinner, not only a morning meal."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Daliya is not only a morning porridge. Five places it works well later in the day.', seo_description='Five ways to cook with daliya beyond breakfast: khichdi, pulao substitute, soup thickener, paratha stuffing and granola.', seo_keywords='daliya recipes, ways to use daliya, dalia beyond breakfast', reading_minutes=3, published_version_id='arv_truegrit_045_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_045';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_045';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_045','Five Ways to Use Daliya Beyond Breakfast','five-ways-to-use-daliya-beyond-breakfast','Daliya is not only a morning porridge. Five places it works well later in the day.','daliya recipes, ways to use daliya, dalia beyond breakfast');

-- 046. What Is Semolina?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_046_2','art_truegrit_046',2,'{"blocks":[{"id":"blk_article_46_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Semolina is the coarse middlings left over when wheat is milled toward flour, sieved out before the final fine grinding stage. It is not a separate crop or grain, just a different stopping point in the same milling process."]}},{"id":"blk_article_46_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Made from the coarse middlings left over when wheat is milled toward flour, sieved out before the final fine grinding.","Contains almost none of the bran or germ that daliya keeps, which is why it looks pale and feels sandy rather than chunky.","Sold in India as suji in the north and rava in the south, the same product under two regional names.","Comes in different grades, coarse to fine, suited to different dishes from upma to halwa.","Internationally, pasta semolina usually means durum wheat, though Indian suji is more often milled from regular bread wheat."]}},{"id":"blk_article_46_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Semolina to try","source":"manual","productSlugs":["semolina-banshi-wheat","semolina-kathiya-wheat"],"limit":2}},{"id":"blk_article_46_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Semolina questions","items":[{"question":"Is semolina the same as suji?","answer":"Yes, semolina is the English name for the same coarse wheat middlings that suji and rava refer to regionally."},{"question":"Does semolina contain the wheat germ and bran?","answer":"Almost none. Milling sieves most of it out, which is what separates semolina from daliya, a whole cracked grain."},{"question":"Can semolina be made from any wheat variety?","answer":"Yes, any of our three wheat varieties can be milled into semolina. The variety changes the flavour, not the basic process."},{"question":"Is semolina refined or a whole grain?","answer":"It sits closer to refined, since bran and germ are removed, though it is coarser than white flour and not as processed."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The coarse middlings sieved out during flour milling. What that origin means for how it looks, cooks and is named.', seo_description='Semolina explained: how it is milled from wheat, how it differs from flour, and the different names it goes by in India.', seo_keywords='semolina, what is semolina, suji, rava', reading_minutes=3, published_version_id='arv_truegrit_046_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_046';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_046';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_046','What Is Semolina?','what-is-semolina','The coarse middlings sieved out during flour milling. What that origin means for how it looks, cooks and is named.','semolina, what is semolina, suji, rava');

-- 047. Semolina vs Suji: Are They the Same?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_047_2','art_truegrit_047',2,'{"blocks":[{"id":"blk_article_47_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Semolina and suji are the same product wearing two different names. The confusion is entirely regional and linguistic, not a real difference in what is inside the packet."]}},{"id":"blk_article_47_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to check","items":["Semolina and suji describe the same coarse wheat middlings, semolina being the English and international term, suji the Hindi and North Indian one.","Rava is the South Indian name for the same product, so all three words can appear on similar looking packs.","Grading, coarse, medium or fine, varies by brand and region more than the name printed on the pack does.","The only real difference worth checking is the grade, not which of the three words the seller has used.","Some packaging lists more than one name at once, suji, rava or semolina together, precisely because sellers know shoppers search under different terms."]}},{"id":"blk_article_47_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Graded semolina","source":"manual","productSlugs":["semolina-kathiya-wheat"],"limit":1}},{"id":"blk_article_47_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Semolina and suji questions","items":[{"question":"Which word should I look for when buying, semolina or suji?","answer":"Either. They mean the same product. Focus on the grade printed on the pack instead."},{"question":"Is rava a finer version of suji?","answer":"Not necessarily. Rava is simply the South Indian name for the same product, and grading is independent of which name is used."},{"question":"Do semolina and suji cook the same way?","answer":"Yes, since they are the same product, cooking method depends on grade, not on which name is on the packet."},{"question":"Why do some recipes specify suji and others semolina?","answer":"Usually just the regional background of the recipe writer, not a signal that a different ingredient is meant."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Yes, with regional naming as the only real variable. What to actually check when the pack uses one word or the other.', seo_description='Semolina and suji compared: same product, different regional names, and what grading detail actually matters on the pack.', seo_keywords='semolina vs suji, is suji the same as semolina', reading_minutes=2, published_version_id='arv_truegrit_047_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_047';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_047';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_047','Semolina vs Suji: Are They the Same?','semolina-vs-suji-are-they-the-same','Yes, with regional naming as the only real variable. What to actually check when the pack uses one word or the other.','semolina vs suji, is suji the same as semolina');

-- 048. Semolina vs Wheat Flour
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_048_2','art_truegrit_048',2,'{"blocks":[{"id":"blk_article_48_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Semolina and wheat flour can come from the exact same grain, just milled to a different stopping point. Particle size, not ingredient, is the whole difference between them."]}},{"id":"blk_article_48_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Particle size is the whole difference. Flour is ground fine and smooth, semolina is left coarse and gritty on purpose.","Flour absorbs water quickly and binds into a smooth dough. Semolina stays granular and needs more liquid and time to soften.","Flour goes into roti, paratha and bread. Semolina goes into upma, halwa, rava idli and pasta.","Both can come from the same wheat variety, milled to a different stopping point rather than being different grains entirely.","Mixing a little semolina into a flour dough, for puri or thepla, adds a light crunch that flour alone does not give."]}},{"id":"blk_article_48_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Semolina for a change of texture","source":"manual","productSlugs":["semolina-banshi-wheat"],"limit":1}},{"id":"blk_article_48_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Semolina and flour questions","items":[{"question":"Can semolina replace wheat flour in roti?","answer":"Not on its own. It lacks the fine, cohesive texture flour needs to form a rollable dough. A small mix into flour works better."},{"question":"Is semolina less processed than white flour?","answer":"It is coarser and stops earlier in milling, though it is still a refined product with most bran and germ removed."},{"question":"Does semolina absorb water the same as flour?","answer":"No, it absorbs more slowly and needs more liquid overall, since the particles are larger and less surface area is exposed."},{"question":"Can I make bread with semolina alone?","answer":"It is usually blended with flour for bread, since semolina alone does not develop the gluten structure bread needs."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Same grain, different stopping point in the mill. Particle size is the whole story here.', seo_description='Semolina compared with wheat flour: how particle size changes texture, absorption and which dishes each one suits.', seo_keywords='semolina vs wheat flour, suji vs atta', reading_minutes=2, published_version_id='arv_truegrit_048_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_048';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_048';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_048','Semolina vs Wheat Flour','semolina-vs-wheat-flour','Same grain, different stopping point in the mill. Particle size is the whole story here.','semolina vs wheat flour, suji vs atta');

-- 049. Semolina vs Daliya
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_049_2','art_truegrit_049',2,'{"blocks":[{"id":"blk_article_49_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Semolina and daliya sit at opposite ends of how much of the original wheat grain survives processing. That single fact explains their look, their cooking time and which dishes each one belongs in."]}},{"id":"blk_article_49_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The core difference","items":["Semolina is refined endosperm only. Daliya is the whole cracked kernel, bran and germ included.","Semolina looks uniform and pale. Daliya shows visible bran flecks and an uneven, coarser shape.","Semolina cooks faster, since there is no bran layer slowing water absorption the way there is with daliya.","Semolina suits upma, halwa and rava dishes. Daliya suits khichdi, kheer and porridge style breakfasts.","Neither substitutes well for the other in a recipe built around its particular texture, so treat them as separate pantry items.","Many kitchens keep both stocked at once, reaching for whichever texture the dish that day actually calls for."]}},{"id":"blk_article_49_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Both, side by side","source":"manual","productSlugs":["semolina-kathiya-wheat","daliya-kathiya-wheat"],"limit":2}},{"id":"blk_article_49_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Semolina vs daliya questions","items":[{"question":"Which has more fibre, semolina or daliya?","answer":"Daliya, since it keeps the bran that semolina milling removes entirely."},{"question":"Can I use semolina where a recipe calls for daliya?","answer":"Not really. The texture and cooking time both differ enough that the finished dish will not match what was intended."},{"question":"Which cooks faster?","answer":"Semolina, since it has no bran layer to slow water absorption, unlike whole grain daliya."},{"question":"Do they come from the same wheat variety?","answer":"They can. Any of our three landraces can be milled into semolina or cracked into daliya. The variety changes flavour, not the category."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Both start as wheat. What survives the mill, refined endosperm or the whole cracked kernel, decides everything else.', seo_description='Semolina compared with daliya: which part of the wheat grain each keeps, and where each fits in the kitchen.', seo_keywords='semolina vs daliya, suji vs dalia', reading_minutes=2, published_version_id='arv_truegrit_049_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_049';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_049';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_049','Semolina vs Daliya','semolina-vs-daliya','Both start as wheat. What survives the mill, refined endosperm or the whole cracked kernel, decides everything else.','semolina vs daliya, suji vs dalia');

-- 050. How Traditional Wheat Semolina Is Made
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_050_2','art_truegrit_050',2,'{"blocks":[{"id":"blk_article_50_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Semolina is not milled separately from flour. It is sieved out midway through the same process, at the point where the grain has broken into coarse middlings but has not yet been ground fine."]}},{"id":"blk_article_50_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The steps","items":["Wheat is cleaned and conditioned, dampened slightly so the bran loosens without turning soft, before it goes through the mill.","Roller milling breaks the grain in stages, and the coarse middlings are sieved out at an early stage before the rest continues toward fine flour.","What is sieved out at that stage is semolina. What continues through more rollers becomes flour.","Traditional stone mills can produce a coarser, less uniform semolina than a modern roller mill, which some cooks prefer for texture.","The bran and germ removed during this process go into flour blends or other uses rather than being wasted outright."]}},{"id":"blk_article_50_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditionally milled","source":"manual","productSlugs":["semolina-paigambari-wheat"],"limit":1}},{"id":"blk_article_50_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Semolina making questions","items":[{"question":"Is semolina milled from a separate batch of wheat?","answer":"No, it is sieved out from the same milling run as flour, at an earlier, coarser stage of the process."},{"question":"Does stone milled semolina taste different?","answer":"It can be less uniform in texture, which some cooks associate with a more traditional result, though flavour differences are subtle."},{"question":"Why is wheat dampened before milling semolina?","answer":"Conditioning loosens the bran from the endosperm without softening it too much, making a cleaner separation during sieving."},{"question":"What happens to the bran removed during semolina milling?","answer":"It typically goes into flour blends or other uses rather than being discarded."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Where in the milling process semolina actually splits off from flour, and what stone milling changes.', seo_description='How semolina is traditionally made: cleaning, conditioning, milling and sieving wheat into coarse middlings.', seo_keywords='how semolina is made, suji making process', reading_minutes=3, published_version_id='arv_truegrit_050_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_050';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_050';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_050','How Traditional Wheat Semolina Is Made','how-traditional-wheat-semolina-is-made','Where in the milling process semolina actually splits off from flour, and what stone milling changes.','how semolina is made, suji making process');

-- 051. Kathiya Wheat Semolina Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_051_2','art_truegrit_051',2,'{"blocks":[{"id":"blk_article_51_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya''s dense, harder kernel behaves closer to durum wheat during milling, which is part of why semolina made from it tends to hold together well when cooked."]}},{"id":"blk_article_51_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Stays more separate when cooked, resisting the clumping a softer wheat semolina can fall into.","Suits upma and other dishes where a distinct, separate grain is wanted rather than a creamy result.","Behaves closer to durum semolina during milling, thanks to Kathiya''s denser, harder kernel.","Costs more than semolina from a commodity wheat, for the same yield and scarcity reasons as Kathiya flour.","Worth the extra roasting attention if separate, distinct grains matter more to you than a faster, more forgiving cook."]}},{"id":"blk_article_51_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One thread compares Kathiya and Banshi semolina directly for upma texture](/community/dsc_truegrit_002), worth reading if you are deciding between the two."]}},{"id":"blk_article_51_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kathiya semolina","source":"manual","productSlugs":["semolina-kathiya-wheat"],"limit":1}},{"id":"blk_article_51_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya semolina questions","items":[{"question":"Why does Kathiya semolina stay more separate in upma?","answer":"Its denser, harder kernel behaves closer to durum wheat during milling, which resists the clumping softer wheat semolina can fall into."},{"question":"Is Kathiya semolina good for halwa?","answer":"It works, though its firmer texture suits upma better than a smooth, softer halwa."},{"question":"Does Kathiya semolina need different roasting than Banshi?","answer":"Roast both until they smell nutty. Any texture difference is more about the grain than the roasting time."},{"question":"Why is Kathiya semolina pricier than regular suji?","answer":"Lower yield and rain fed cultivation, the same reasons as Kathiya flour, not an added processing cost."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Kathiya''s density carries into its semolina too, staying separate rather than clumping when cooked.', seo_description='Kathiya wheat semolina explained: why its hardness helps it stay separate in upma and other savoury dishes.', seo_keywords='Kathiya semolina, Kathiya suji', reading_minutes=2, published_version_id='arv_truegrit_051_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_051';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_051';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_051','Kathiya Wheat Semolina Explained','kathiya-wheat-semolina-explained','Kathiya''s density carries into its semolina too, staying separate rather than clumping when cooked.','Kathiya semolina, Kathiya suji');

-- 052. Banshi Wheat Semolina Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_052_2','art_truegrit_052',2,'{"blocks":[{"id":"blk_article_52_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Banshi semolina cooks the way most generic upma or halwa recipes already assume, since its medium hardness needs no real adjustment to standard water ratios or roasting times."]}},{"id":"blk_article_52_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Medium hardness gives a semolina that cooks predictably, landing close to the water ratios most upma recipes already assume.","Softens a touch more readily than Kathiya semolina, useful in dishes like halwa where a creamier result is wanted.","The easiest semolina to start with if you have not cooked with different wheat varieties before.","Works well across both savoury and sweet semolina dishes without needing technique adjustments Kathiya sometimes does.","A sensible everyday stock choice if you would rather keep one semolina on hand than rotate between all three."]}},{"id":"blk_article_52_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[The same upma texture comparison thread](/community/dsc_truegrit_002) covers Banshi directly if you want a second opinion before choosing."]}},{"id":"blk_article_52_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Banshi semolina","source":"manual","productSlugs":["semolina-banshi-wheat"],"limit":1}},{"id":"blk_article_52_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Banshi semolina questions","items":[{"question":"Is Banshi semolina good for both upma and halwa?","answer":"Yes, its medium hardness handles both reasonably well without the adjustments a harder or softer wheat might need."},{"question":"How does Banshi semolina compare to Kathiya for upma?","answer":"Banshi softens a touch more readily, while Kathiya tends to stay more distinctly separate. Both work, the choice is texture preference."},{"question":"Is Banshi semolina the best starting choice?","answer":"Generally yes, since it needs the least adjustment from a standard suji recipe."},{"question":"Does Banshi semolina clump easily?","answer":"Less than a very fine, softer semolina might, though roasting technique matters more than variety here."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Medium hardness gives a semolina that cooks close to what most upma and halwa recipes already assume.', seo_description='Banshi wheat semolina explained: predictable cooking, softer texture than Kathiya, and where it suits best.', seo_keywords='Banshi semolina, Banshi suji', reading_minutes=2, published_version_id='arv_truegrit_052_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_052';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_052';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_052','Banshi Wheat Semolina Explained','banshi-wheat-semolina-explained','Medium hardness gives a semolina that cooks close to what most upma and halwa recipes already assume.','Banshi semolina, Banshi suji');

-- 053. Paigambari Wheat Semolina Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_053_2','art_truegrit_053',2,'{"blocks":[{"id":"blk_article_53_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Paigambari semolina carries through the same aroma that defines the flour and the daliya made from this wheat, noticeable from the first few seconds of roasting in ghee."]}},{"id":"blk_article_53_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Carries through the same aroma that defines Paigambari flour and daliya, noticeable in a plain roasted semolina before anything else is added.","Best in simple preparations, a lightly sweetened halwa or plain upma, where the wheat''s own flavour is the point.","Moderately hard, cooking closer to Banshi than to Kathiya in timing and water needs.","Buy in smaller quantities if aroma is the reason you are choosing it, since it fades with storage time.","Keep it sealed away from strongly scented spices in the pantry, the same storage habit that protects the flour and daliya made from it."]}},{"id":"blk_article_53_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Paigambari semolina","source":"manual","productSlugs":["semolina-paigambari-wheat"],"limit":1}},{"id":"blk_article_53_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Paigambari semolina questions","items":[{"question":"Why does Paigambari semolina cost more?","answer":"The same reasons as Paigambari flour, smaller grain, lower yield and cultivation concentrated in one region."},{"question":"Is Paigambari semolina good for plain upma?","answer":"Yes, its aroma shows best in simple, lightly spiced preparations rather than heavily masala laden ones."},{"question":"How long does Paigambari semolina keep its aroma?","answer":"A few weeks in an airtight container. Buy smaller quantities if the aroma is your main reason for choosing it."},{"question":"Does Paigambari semolina cook differently from Banshi?","answer":"Only slightly, it sits close to Banshi in hardness. The aroma, not the cooking behaviour, is the real distinguishing feature."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same aroma that defines Paigambari flour and daliya, noticeable from the first roast.', seo_description='Paigambari wheat semolina explained: its aroma, ideal cooking timing, and the plain dishes where it shows best.', seo_keywords='Paigambari semolina, Paigambari suji', reading_minutes=2, published_version_id='arv_truegrit_053_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_053';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_053';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_053','Paigambari Wheat Semolina Explained','paigambari-wheat-semolina-explained','The same aroma that defines Paigambari flour and daliya, noticeable from the first roast.','Paigambari semolina, Paigambari suji');

-- 054. Which Semolina Is Best for Upma?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_054_2','art_truegrit_054',2,'{"blocks":[{"id":"blk_article_54_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A good upma comes down to grade and roasting more than brand or variety, though variety still plays a real part once the technique is right. Here is what actually moves the result."]}},{"id":"blk_article_54_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually matters","items":["A coarser grade generally holds its shape better in upma, giving the separate, slightly grainy texture most recipes are aiming for.","Roasting the semolina in ghee or oil until it smells nutty matters more to the final result than which wheat variety it came from.","Kathiya semolina tends to stay more separate on its own. Banshi is close behind and more forgiving if roasting time varies a little.","Standing time after cooking, five minutes covered off the heat, finishes the texture as much as the cooking itself does.","If your upma keeps clumping, check the roasting time first before assuming the semolina grade is the problem."]}},{"id":"blk_article_54_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook compares Banshi and Kathiya semolina for upma directly, asking whether the difference is the grain or the roasting](/community/dsc_truegrit_002), worth reading before you settle on one."]}},{"id":"blk_article_54_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Semolina for upma","source":"manual","productSlugs":["semolina-kathiya-wheat","semolina-banshi-wheat"],"limit":2}},{"id":"blk_article_54_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Upma semolina questions","items":[{"question":"Coarse or fine semolina for upma?","answer":"Coarse or medium generally holds its shape better, giving the separate texture most upma recipes want."},{"question":"Does roasting time really change the result?","answer":"Yes, more than most people expect. Under roasted semolina clumps more readily regardless of grade or variety."},{"question":"Is Kathiya semolina better than Banshi for upma?","answer":"Kathiya stays a touch more separate on its own, but Banshi performs close to it once roasted properly."},{"question":"Why does my upma clump even after roasting?","answer":"Check the water ratio and how quickly you added the liquid. Semolina added to boiling water too fast can seize into lumps."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Grade and roasting technique matter more than which wheat variety you choose. Both still play a real part.', seo_description='The best semolina for upma: grade, roasting time and how Kathiya and Banshi semolina compare for a separate texture.', seo_keywords='best semolina for upma, best suji for upma', reading_minutes=3, published_version_id='arv_truegrit_054_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_054';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_054';
