-- 055. Which Suji Is Best for Halwa?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_055_2','art_truegrit_055',2,'{"blocks":[{"id":"blk_article_55_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Halwa asks something different of suji than upma does. A finer grade and a deeper roast in ghee matter more here than the specific wheat variety underneath."]}},{"id":"blk_article_55_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually matters","items":["A finer grade generally gives a smoother, more traditional halwa texture than a coarse upma grade would.","Roasting in ghee until deep golden, not just lightly toasted, is what actually builds halwa''s flavour, more than the wheat variety underneath.","Banshi suji softens a little more readily here, which some cooks prefer for a smoother finished halwa.","The classic ratio, roughly one part suji to one part sugar and enough ghee to coat generously, still holds regardless of variety.","Add the hot water or milk gradually and off direct high heat, since suji can seize into lumps if it goes in all at once."]}},{"id":"blk_article_55_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Suji for halwa","source":"manual","productSlugs":["semolina-banshi-wheat"],"limit":1}},{"id":"blk_article_55_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Halwa suji questions","items":[{"question":"Should halwa suji be roasted longer than upma suji?","answer":"Generally yes, a deeper golden roast builds more flavour, which matters more in halwa than in a savoury upma."},{"question":"Does the wheat variety change the halwa much?","answer":"Less than grade and roasting do. Banshi gives a slightly smoother result, but technique matters more than variety here."},{"question":"Why did my halwa turn lumpy?","answer":"Usually liquid added too quickly or too hot. Add it gradually, off direct high heat, stirring constantly."},{"question":"Can coarse semolina be used for halwa in a pinch?","answer":"Yes, though the texture will be less smooth than a finer grade gives. It still cooks fine."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A finer grade and a deeper ghee roast, more than the wheat variety, decide how a halwa turns out.', seo_description='The best suji for halwa: grade, ghee roasting depth, and how the classic ratio holds across wheat varieties.', seo_keywords='best suji for halwa, best semolina for halwa', reading_minutes=2, published_version_id='arv_truegrit_055_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_055';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_055';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_055','Which Suji Is Best for Halwa?','which-suji-is-best-for-halwa','A finer grade and a deeper ghee roast, more than the wheat variety, decide how a halwa turns out.','best suji for halwa, best semolina for halwa');

-- 059. Semolina Pasta: How It Is Different
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_059_2','art_truegrit_059',2,'{"blocks":[{"id":"blk_article_59_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Semolina pasta almost always means durum wheat internationally, prized for its high protein and firm bite when boiled. Pasta made from a bread wheat semolina, like ours, is a related but genuinely different product."]}},{"id":"blk_article_59_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What differs","items":["Internationally, pasta semolina almost always means durum wheat, prized for its high protein and firm bite when boiled.","Semolina from a regular bread wheat variety, like our three landraces, behaves a little differently, slightly less firm and more prone to going soft if overcooked.","Colour differs too. Durum semolina pasta is a deep gold. Bread wheat semolina pasta is paler, closer to the colour of the grain itself.","What stays the same is the basic method, semolina mixed with water or egg, formed and then dried or cooked fresh.","Treat printed cook times as a guide rather than a rule, and start checking a minute or two before the pack suggests."]}},{"id":"blk_article_59_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Semolina pasta","source":"manual","productSlugs":["pasta-banshi-wheat","pasta-kathiya-wheat"],"limit":2}},{"id":"blk_article_59_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Semolina pasta questions","items":[{"question":"Is bread wheat semolina pasta worse than durum pasta?","answer":"Not worse, just different. It has a softer bite and a paler colour rather than durum''s firm, golden result."},{"question":"Why is my semolina pasta paler than pasta I buy elsewhere?","answer":"Colour comes largely from the wheat variety used. Bread wheat semolina is naturally paler than durum semolina."},{"question":"Should I cook bread wheat semolina pasta shorter than the pack says?","answer":"Start checking a minute or two early, since it can go from firm to soft faster than durum pasta does."},{"question":"Can I use bread wheat semolina pasta the same way as regular pasta?","answer":"Yes, in any sauce or dish, just watch the boiling time more closely than you would with a durum pasta."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Durum semolina is the international pasta standard. Bread wheat semolina pasta, like ours, behaves a little differently.', seo_description='How semolina pasta made from bread wheat differs from classic durum semolina pasta: texture, colour and cook time.', seo_keywords='semolina pasta, wheat pasta, durum vs bread wheat pasta', reading_minutes=3, published_version_id='arv_truegrit_059_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_059';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_059';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_059','Semolina Pasta: How It Is Different','semolina-pasta-how-it-is-different','Durum semolina is the international pasta standard. Bread wheat semolina pasta, like ours, behaves a little differently.','semolina pasta, wheat pasta, durum vs bread wheat pasta');

-- 060. How to Store Semolina Properly
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_060_2','art_truegrit_060',2,'{"blocks":[{"id":"blk_article_60_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Semolina looks shelf stable, dry and granular, but the trace of wheat germ oil left in an unrefined batch means storage still matters. A little care here avoids both rancidity and pests."]}},{"id":"blk_article_60_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Keep it in an airtight container. Semolina left open in humid air clumps and can pick up moisture related off flavours.","Store somewhere cool and dark. The wheat germ trace left in unrefined semolina carries a little natural oil that turns rancid faster in heat.","Roasting semolina lightly before storing extends its shelf life noticeably, which is also why many recipes roast it as a first step regardless.","Check for weevils the same way you would with any whole grain product, especially in a humid climate or during monsoon months.","Use within a few months for the best flavour, sooner if you bought a coarser, less processed grade."]}},{"id":"blk_article_60_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One thread on keeping weevils out of stored grain without chemical tablets](/community/dsc_truegrit_026) applies just as well to semolina as it does to whole grain."]}},{"id":"blk_article_60_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Semolina to store well","source":"manual","productSlugs":["semolina-paigambari-wheat"],"limit":1}},{"id":"blk_article_60_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Semolina storage questions","items":[{"question":"How long does semolina stay good once opened?","answer":"A few months in an airtight container stored cool and dark. Sooner if you bought a coarser, less processed grade."},{"question":"Does semolina need refrigeration?","answer":"Not usually, a cool pantry is enough, though refrigeration helps in a hot, humid climate if you have the space."},{"question":"Why does my semolina smell slightly off after a few months?","answer":"Likely the trace oil turning rancid. Store it cooler and buy smaller quantities if this keeps happening."},{"question":"Does roasting semolina before storing really help?","answer":"Yes, it reduces moisture and can extend shelf life noticeably, which is part of why many recipes roast it as a first step anyway."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The trace oil left in unrefined semolina makes storage matter more than it looks like it should.', seo_description='How to store semolina properly: airtight containers, cool storage, roasting for shelf life and checking for weevils.', seo_keywords='how to store semolina, suji storage tips', reading_minutes=2, published_version_id='arv_truegrit_060_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_060';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_060';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_060','How to Store Semolina Properly','how-to-store-semolina-properly','The trace oil left in unrefined semolina makes storage matter more than it looks like it should.','how to store semolina, suji storage tips');

-- 061. What Is Whole-Wheat Pasta?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_061_2','art_truegrit_061',2,'{"blocks":[{"id":"blk_article_61_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole-wheat pasta is made from whole wheat flour or semolina rather than the refined durum semolina classic Italian pasta uses. That one change, keeping the bran and germ instead of milling them away, decides most of what makes it different at the table."]}},{"id":"blk_article_61_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Made from whole wheat flour or semolina rather than the refined durum semolina classic Italian pasta uses.","Retains the bran and germ, giving a denser texture, a nuttier flavour and a duller colour than refined pasta.","Higher in fibre than refined pasta by virtue of what is left in during milling, not an added ingredient.","Cooks a little differently, generally needing careful timing since the bran layer changes how water moves through each strand.","Can be made from any wheat variety. Ours uses the same three heritage landraces sold as flour and daliya.","Shapes tend to be simpler than the full range refined pasta comes in, since whole wheat dough is less elastic to work with."]}},{"id":"blk_article_61_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole-wheat pasta","source":"manual","productSlugs":["pasta-banshi-wheat","pasta-kathiya-wheat"],"limit":2}},{"id":"blk_article_61_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole-wheat pasta questions","items":[{"question":"Is whole-wheat pasta the same as durum pasta?","answer":"No. Durum pasta is milled from refined durum semolina. Whole-wheat pasta keeps the bran and germ, which changes texture, colour and flavour."},{"question":"Does whole-wheat pasta contain gluten?","answer":"Yes, it is made from wheat, so it contains gluten the same as any wheat product."},{"question":"Is whole-wheat pasta healthier than regular pasta?","answer":"It carries more fibre by virtue of what milling leaves in. Treat that as a real processing difference, not a broader health claim."},{"question":"Can whole-wheat pasta be used in any recipe that calls for pasta?","answer":"Yes, though expect a denser texture and a narrower cooking window than refined pasta gives you."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Pasta made from whole wheat rather than refined durum semolina, keeping the bran and germ most pasta leaves out.', seo_description='Whole-wheat pasta explained: how it differs from classic durum pasta, what it keeps from the grain, and how it cooks.', seo_keywords='whole wheat pasta, what is whole wheat pasta', reading_minutes=3, published_version_id='arv_truegrit_061_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_061';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_061';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_061','What Is Whole-Wheat Pasta?','what-is-whole-wheat-pasta','Pasta made from whole wheat rather than refined durum semolina, keeping the bran and germ most pasta leaves out.','whole wheat pasta, what is whole wheat pasta');

-- 062. Traditional Indian Wheat Pasta: A New Take on an Old Grain
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_062_2','art_truegrit_062',2,'{"blocks":[{"id":"blk_article_62_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Pasta itself has no deep roots in Indian cooking. What is genuinely traditional here is the wheat, Kathiya, Banshi and Paigambari, grain that has mostly gone into roti and daliya for generations, now put into a shape most households already cook with regularly."]}},{"id":"blk_article_62_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What this actually is","items":["Pasta has no deep roots in Indian cooking. What is genuinely traditional here is the wheat, not the shape it is formed into.","Using landrace wheat like Kathiya, Banshi and Paigambari for pasta is a modern application of grain that has mostly gone into roti and daliya.","The aroma and hardness differences that show up in flour and daliya carry through into pasta made from the same grain.","This is not a claim of ancient pasta history in India. It is old wheat put into a format most households already cook regularly.","Indian style tempering and masala pair naturally with whole wheat pasta''s nuttier flavour, more than a plain olive oil sauce does."]}},{"id":"blk_article_62_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[People cooking Banshi pasta talk through its narrower al dente window compared to refined pasta here](/community/dsc_truegrit_004), useful background before your first batch."]}},{"id":"blk_article_62_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Try heritage wheat pasta","source":"manual","productSlugs":["pasta-kathiya-wheat","pasta-paigambari-wheat"],"limit":2}},{"id":"blk_article_62_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Indian wheat pasta questions","items":[{"question":"Is this a traditional Indian dish?","answer":"No, pasta is not traditionally Indian. What is traditional is the wheat used to make it, grain that has mostly gone into roti and daliya."},{"question":"Does the wheat variety actually change the pasta?","answer":"Yes, the same hardness and aroma differences that show up in flour and daliya carry through into pasta made from the same grain."},{"question":"What sauces suit Indian style wheat pasta best?","answer":"Tempered masala sauces and simple tadka based ones tend to pair well with the nuttier flavour whole wheat pasta brings."},{"question":"Is this pasta durum wheat like Italian pasta?","answer":"No, it is made from regular bread wheat landraces, which behaves differently from durum during both milling and cooking."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Pasta has no deep roots in Indian cooking. What is genuinely old here is the wheat, put into a format most kitchens already know.', seo_description='How heritage Indian wheat landraces are used to make pasta, and why that is a new application rather than an old tradition.', seo_keywords='Indian wheat pasta, heritage wheat pasta', reading_minutes=3, published_version_id='arv_truegrit_062_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_062';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_062';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_062','Traditional Indian Wheat Pasta: A New Take on an Old Grain','traditional-indian-wheat-pasta-a-new-take-on-an-old-grain','Pasta has no deep roots in Indian cooking. What is genuinely old here is the wheat, put into a format most kitchens already know.','Indian wheat pasta, heritage wheat pasta');

-- 063. Kathiya Wheat Pasta: What Makes It Different?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_063_2','art_truegrit_063',2,'{"blocks":[{"id":"blk_article_63_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya''s dense, hard kernel gives its pasta a firmer bite than Banshi or Paigambari pasta, closer to what a durum pasta eater already expects, even though the wheat behind it is entirely different."]}},{"id":"blk_article_63_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Firmer bite than Banshi or Paigambari pasta, closer to what durum pasta eaters expect from a good al dente result.","Holds its shape well in a heavier sauce or baked pasta dish, without softening as quickly as a more delicate wheat would.","Needs a slightly longer boil than Banshi pasta to hydrate fully, so start testing a minute or two before the pack time.","Suits a simple tomato or Indian style masala sauce where texture matters as much as the sauce itself.","Priced the same way Kathiya flour and daliya are, lower yield and rain fed cultivation, not a certified nutrition claim."]}},{"id":"blk_article_63_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kathiya pasta","source":"manual","productSlugs":["pasta-kathiya-wheat"],"limit":1}},{"id":"blk_article_63_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya pasta questions","items":[{"question":"Does Kathiya pasta take longer to cook?","answer":"A little, its denser kernel hydrates more slowly, so start testing a minute or two before the printed pack time."},{"question":"Is Kathiya pasta good for baked dishes?","answer":"Yes, its firmer texture holds up well under a baked sauce and cheese layer without turning mushy."},{"question":"How does Kathiya pasta compare to durum pasta in texture?","answer":"Closer than Banshi or Paigambari, though it is still a different wheat entirely with its own flavour and colour."},{"question":"Why is Kathiya pasta pricier than a standard whole wheat pasta?","answer":"The same reasons as Kathiya flour, lower yield and a smaller growing region, not an added processing cost."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Kathiya''s density carries into pasta too, giving a firmer bite closer to what durum pasta drinkers expect.', seo_description='Kathiya wheat pasta explained: firmer texture, longer boil time, and which sauces suit it best.', seo_keywords='Kathiya pasta, Kathiya wheat pasta', reading_minutes=2, published_version_id='arv_truegrit_063_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_063';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_063';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_063','Kathiya Wheat Pasta: What Makes It Different?','kathiya-wheat-pasta-what-makes-it-different','Kathiya''s density carries into pasta too, giving a firmer bite closer to what durum pasta drinkers expect.','Kathiya pasta, Kathiya wheat pasta');

-- 064. Banshi Wheat Pasta: Taste and Texture Guide
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_064_2','art_truegrit_064',2,'{"blocks":[{"id":"blk_article_64_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Banshi pasta cooks the way a standard pasta recipe already assumes, since its medium hardness needs little adjustment to boiling time or water ratios."]}},{"id":"blk_article_64_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Medium hardness gives Banshi pasta the most forgiving cook window of the three, closer to what a standard pasta recipe already assumes.","Softens a touch more readily than Kathiya pasta, without turning as delicate as a fully refined pasta would.","Works well across most sauces, from a simple tomato to a heavier Indian style masala.","The easiest of the three wheat pastas to start with if you have not cooked whole wheat pasta before.","A reasonable everyday choice if you would rather stock one wheat pasta variety than rotate between all three."]}},{"id":"blk_article_64_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One thread tracks exactly how narrow that cook window still is compared to refined pasta](/community/dsc_truegrit_004), worth reading before your first batch."]}},{"id":"blk_article_64_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Banshi pasta","source":"manual","productSlugs":["pasta-banshi-wheat"],"limit":1}},{"id":"blk_article_64_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Banshi pasta questions","items":[{"question":"Is Banshi pasta a good starting choice?","answer":"Yes, its medium hardness cooks close to what a standard pasta recipe already assumes, making it the most forgiving option."},{"question":"Does Banshi pasta have a narrow al dente window?","answer":"Narrower than refined pasta, though more forgiving than Kathiya pasta. Start checking a minute or two before the pack time."},{"question":"What sauces work best with Banshi pasta?","answer":"Most sauces work well, from a simple tomato to a heavier Indian style masala, since its texture is fairly neutral."},{"question":"How does Banshi pasta compare to Kathiya for a baked dish?","answer":"Kathiya holds its shape a little better under a heavy baked sauce. Banshi still works fine, just softens slightly more."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The most forgiving of the three wheat pastas, cooking close to what a standard pasta recipe already assumes.', seo_description='Banshi wheat pasta explained: a forgiving cook window, medium texture, and which sauces suit it best.', seo_keywords='Banshi pasta, Banshi wheat pasta', reading_minutes=2, published_version_id='arv_truegrit_064_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_064';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_064';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_064','Banshi Wheat Pasta: Taste and Texture Guide','banshi-wheat-pasta-taste-and-texture-guide','The most forgiving of the three wheat pastas, cooking close to what a standard pasta recipe already assumes.','Banshi pasta, Banshi wheat pasta');

-- 065. Paigambari Wheat Pasta Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_065_2','art_truegrit_065',2,'{"blocks":[{"id":"blk_article_65_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Paigambari pasta carries through the same aroma that sets the flour and daliya from this wheat apart, noticeable even once a sauce is tossed through it."]}},{"id":"blk_article_65_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Carries through the same aroma that defines Paigambari flour, daliya and semolina, noticeable even under a sauce.","Best paired with a simple sauce, oil and garlic or a light tomato, where the wheat''s own flavour is not overwhelmed.","Sits closer to Banshi than Kathiya on hardness, so boiling time and water needs both stay fairly close to a standard pasta recipe.","Buy in smaller quantities if aroma is your reason for choosing it, since it fades with storage time the same way the flour does.","Pairs naturally with a herb forward finish, basil or coriander, rather than a heavy cream or cheese sauce that would mask it."]}},{"id":"blk_article_65_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Paigambari pasta","source":"manual","productSlugs":["pasta-paigambari-wheat"],"limit":1}},{"id":"blk_article_65_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Paigambari pasta questions","items":[{"question":"Why choose Paigambari pasta over the other two?","answer":"Mainly for its aroma, which shows best under a simple sauce rather than a heavily spiced or sauced dish."},{"question":"Does Paigambari pasta cook faster than Kathiya?","answer":"Yes, it is moderately hard rather than dense, so it cooks a little faster and needs less boiling time."},{"question":"How should I store Paigambari pasta to keep the aroma?","answer":"Keep it airtight, away from strong smelling spices, and use it within a few weeks rather than stocking a large quantity."},{"question":"What sauce suits Paigambari pasta best?","answer":"Something simple, oil and garlic or a light tomato, so the wheat''s own aroma is not competing with heavy spicing."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same aroma that defines Paigambari flour and daliya, noticeable even under a sauce.', seo_description='Paigambari wheat pasta explained: its aroma, cooking behaviour, and which simple sauces let it show through.', seo_keywords='Paigambari pasta, Paigambari wheat pasta', reading_minutes=2, published_version_id='arv_truegrit_065_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_065';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_065';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_065','Paigambari Wheat Pasta Explained','paigambari-wheat-pasta-explained','The same aroma that defines Paigambari flour and daliya, noticeable even under a sauce.','Paigambari pasta, Paigambari wheat pasta');

-- 066. Kathiya vs Banshi vs Paigambari Pasta
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_066_2','art_truegrit_066',2,'{"blocks":[{"id":"blk_article_66_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The hardness and aroma differences that separate Kathiya, Banshi and Paigambari as flours carry straight through into pasta made from each. Forming the dough into a new shape does not erase what the variety itself brings to the pot."]}},{"id":"blk_article_66_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Side by side","items":["Bite. Kathiya holds the firmest texture, Banshi is the most forgiving, Paigambari lands close to Banshi.","Cook time. Kathiya needs the longest boil to hydrate fully, Banshi and Paigambari cook a little faster.","Best sauce pairing. Kathiya for a heavier masala or baked dish, Banshi for an everyday all purpose sauce, Paigambari for something simple that lets the aroma show.","Price. All three cost more than a commodity whole wheat pasta for the same reasons as the flours, lower yield and a smaller growing region.","Beginners generally do best starting with Banshi pasta before trying Kathiya or Paigambari."]}},{"id":"blk_article_66_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Try all three","source":"manual","productSlugs":["pasta-kathiya-wheat","pasta-banshi-wheat","pasta-paigambari-wheat"],"limit":3}},{"id":"blk_article_66_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Three way pasta questions","items":[{"question":"Which pasta variety should a beginner buy first?","answer":"Banshi. It cooks the most predictably and needs the least adjustment from a standard pasta recipe."},{"question":"Is there a big taste difference between the three as pasta?","answer":"Paigambari''s aroma is the most noticeable difference. Kathiya and Banshi differ more in texture and cook time than in flavour."},{"question":"Do I need to stock all three pasta varieties?","answer":"No, most households settle on one everyday variety and buy the others only for a specific dish or occasion."},{"question":"Which holds up best in a baked pasta dish?","answer":"Kathiya, since its firmer texture resists softening under a heavy sauce and cheese layer longer than the other two."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same three wheat personalities from the flour comparisons, carried through into how each cooks and eats as pasta.', seo_description='Kathiya, Banshi and Paigambari pasta compared directly: bite, cook time and which sauce suits each variety best.', seo_keywords='Kathiya vs Banshi vs Paigambari pasta, wheat pasta comparison', reading_minutes=3, published_version_id='arv_truegrit_066_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_066';
