INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_066','Kathiya vs Banshi vs Paigambari Pasta','kathiya-vs-banshi-vs-paigambari-pasta','The same three wheat personalities from the flour comparisons, carried through into how each cooks and eats as pasta.','Kathiya vs Banshi vs Paigambari pasta, wheat pasta comparison');

-- 067. Whole-Wheat Pasta vs Regular Pasta
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_067_2','art_truegrit_067',2,'{"blocks":[{"id":"blk_article_67_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Regular pasta almost always means refined durum semolina, pale gold and smooth. Whole-wheat pasta keeps the bran and germ, and that single processing difference explains nearly everything else that follows."]}},{"id":"blk_article_67_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Regular pasta almost always means refined durum semolina, pale gold and smooth. Whole-wheat pasta keeps the bran and germ, giving a duller colour and denser bite.","Whole-wheat pasta carries more fibre by virtue of what milling leaves in, not an added ingredient.","Regular pasta has a wider forgiving window between al dente and overcooked. Whole-wheat pasta''s window is narrower.","Flavour differs too. Whole-wheat pasta tastes noticeably nuttier and more like the grain itself, where refined pasta stays closer to neutral.","Neither is simply better. The choice is texture, flavour and how the sauce is built around it."]}},{"id":"blk_article_67_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Try whole-wheat","source":"manual","productSlugs":["pasta-banshi-wheat"],"limit":1}},{"id":"blk_article_67_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole-wheat vs regular pasta questions","items":[{"question":"Does whole-wheat pasta taste very different from regular pasta?","answer":"Yes, noticeably nuttier and more grain forward. Regular refined pasta stays closer to neutral in flavour."},{"question":"Is whole-wheat pasta harder to cook well?","answer":"It needs closer attention to timing, since the window between al dente and overcooked is narrower than with regular pasta."},{"question":"Which is more filling?","answer":"Whole-wheat pasta carries more fibre, which can affect how filling a serving feels, though portion size still matters most."},{"question":"Can I substitute whole-wheat pasta directly in any recipe?","answer":"Yes, though expect a denser result and check doneness a little earlier than the recipe''s stated time."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Regular pasta means refined durum semolina almost everywhere. Here is what changes when the bran and germ stay in.', seo_description='Whole-wheat pasta compared against regular refined pasta: colour, fibre, cook time and flavour differences.', seo_keywords='whole wheat pasta vs regular pasta, wheat pasta comparison', reading_minutes=3, published_version_id='arv_truegrit_067_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_067';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_067';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_067','Whole-Wheat Pasta vs Regular Pasta','whole-wheat-pasta-vs-regular-pasta','Regular pasta means refined durum semolina almost everywhere. Here is what changes when the bran and germ stay in.','whole wheat pasta vs regular pasta, wheat pasta comparison');

-- 068. How to Cook Whole-Wheat Pasta Properly
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_068_2','art_truegrit_068',2,'{"blocks":[{"id":"blk_article_68_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole-wheat pasta cooks by the same basic method as any pasta, a large pot of salted, rapidly boiling water, but a few adjustments below actually matter more here than they do for refined pasta."]}},{"id":"blk_article_68_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Use a large pot of well salted water at a full rolling boil, the same starting point as any pasta, whole wheat or not.","Start checking for doneness a minute or two before the pack time, since whole-wheat pasta''s al dente window is narrower than refined pasta''s.","Stir occasionally in the first few minutes. Whole-wheat pasta''s rougher surface can stick more readily than smooth refined pasta.","Reserve a little pasta water before draining. Whole-wheat pasta benefits from it to loosen a sauce, since it can drink up liquid quickly once drained.","Toss with sauce immediately after draining rather than letting it sit, since whole-wheat pasta firms up faster as it cools."]}},{"id":"blk_article_68_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole-wheat pasta to practise on","source":"manual","productSlugs":["pasta-kathiya-wheat"],"limit":1}},{"id":"blk_article_68_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Cooking whole-wheat pasta questions","items":[{"question":"How much salt should the pasta water have?","answer":"Salt it generously, roughly as salty as sea water. This seasons the pasta itself, not just the water around it."},{"question":"Should I add oil to the cooking water?","answer":"It is not necessary and can make sauce cling less well afterward. Stirring occasionally prevents sticking just as effectively."},{"question":"Why does my whole-wheat pasta stick together after draining?","answer":"Usually it sat too long without sauce or oil tossed through it. Combine it with sauce immediately after draining."},{"question":"Can I cook whole-wheat pasta ahead of time?","answer":"You can, but toss it with a little oil to prevent sticking and expect a firmer texture once reheated."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same basic method as any pasta, with a few adjustments the bran layer actually demands.', seo_description='How to cook whole-wheat pasta properly: salting water, timing, stirring and finishing it before it firms up.', seo_keywords='how to cook whole wheat pasta, whole wheat pasta tips', reading_minutes=3, published_version_id='arv_truegrit_068_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_068';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_068';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_068','How to Cook Whole-Wheat Pasta Properly','how-to-cook-whole-wheat-pasta-properly','The same basic method as any pasta, with a few adjustments the bran layer actually demands.','how to cook whole wheat pasta, whole wheat pasta tips');

-- 069. Why Whole-Wheat Pasta Sometimes Feels Hard
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_069_2','art_truegrit_069',2,'{"blocks":[{"id":"blk_article_69_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A hard bite in whole-wheat pasta usually traces back to one of two things, not enough time in the water, or too much time sitting afterward. Both are fixable without changing the pasta itself."]}},{"id":"blk_article_69_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What is actually happening","items":["The bran layer resists softening longer than the starch underneath it, so the surface can feel firm even when the centre is properly cooked.","Undercooking is the most common cause. Whole-wheat pasta often needs slightly longer than the pack suggests, not less.","Pasta left sitting after draining firms up faster than refined pasta does, so a batch that was fine straight out of the pot can feel harder ten minutes later.","A rolling boil that has dropped in temperature when the pasta goes in can also leave it undercooked despite a full timed boil.","If it consistently feels hard, add thirty seconds to a minute next time and test again before draining."]}},{"id":"blk_article_69_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[Cooks working through Kathiya and Banshi''s different timing windows compare notes here](/community/dsc_truegrit_004), useful if the hardness is inconsistent between batches."]}},{"id":"blk_article_69_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole-wheat pasta","source":"manual","productSlugs":["pasta-banshi-wheat"],"limit":1}},{"id":"blk_article_69_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Hard pasta questions","items":[{"question":"Is hard whole-wheat pasta always undercooked?","answer":"Usually, though pasta left sitting too long after draining can also firm up even if it was cooked correctly."},{"question":"Does the wheat variety affect how hard it feels?","answer":"Yes, Kathiya pasta stays firmer by nature. That is a texture trait, not a sign it needs more cooking than usual."},{"question":"Can I fix pasta that has already gone hard?","answer":"A quick toss in hot sauce or a splash of the reserved pasta water can soften it slightly, though it will not fully reset."},{"question":"Should I boil whole-wheat pasta longer than the pack says by default?","answer":"Not by default, but test a minute or two before the pack time so you catch the right point rather than guessing."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Usually undercooking, sometimes just sitting too long after draining. Both have simple fixes.', seo_description='Why whole-wheat pasta can feel hard even after boiling: the bran layer, timing, and how long it sits after draining.', seo_keywords='whole wheat pasta hard, whole wheat pasta undercooked', reading_minutes=3, published_version_id='arv_truegrit_069_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_069';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_069';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_069','Why Whole-Wheat Pasta Sometimes Feels Hard','why-whole-wheat-pasta-sometimes-feels-hard','Usually undercooking, sometimes just sitting too long after draining. Both have simple fixes.','whole wheat pasta hard, whole wheat pasta undercooked');

-- 070. How Long Should Whole-Wheat Pasta Be Boiled?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_070_2','art_truegrit_070',2,'{"blocks":[{"id":"blk_article_70_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["There is no single correct boiling time for whole-wheat pasta that applies everywhere. The pack time is a reasonable starting point, but variety and how closely you check both change the real answer."]}},{"id":"blk_article_70_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What changes the answer","items":["Treat the time printed on the pack as a starting point, not a fixed rule, and start testing a minute or two early.","Kathiya pasta generally needs a little longer than Banshi or Paigambari, in line with its harder kernel.","A full rolling boil throughout cooking matters more for whole-wheat pasta than refined, since a dropped temperature shows up as unevenly cooked strands.","The gap between properly cooked and overcooked is narrower here than with refined pasta, so check more often than you would normally bother to.","Once drained, use it within a few minutes. It firms up and can feel harder the longer it sits."]}},{"id":"blk_article_70_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Wheat pasta","source":"manual","productSlugs":["pasta-paigambari-wheat"],"limit":1}},{"id":"blk_article_70_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Boiling time questions","items":[{"question":"Should I trust the time printed on the pack?","answer":"As a starting point, yes, but start testing a minute or two before it to catch the right texture."},{"question":"Does pasta shape change the boiling time?","answer":"Yes, thinner shapes cook faster than thicker ones, the same as with refined pasta. Check the specific shape''s guideline."},{"question":"Is it better to undercook slightly if serving with a hot sauce?","answer":"Some cooks finish slightly underboiled pasta in the sauce itself, which works well and avoids overcooking by the time it is plated."},{"question":"Why does my pasta cook unevenly?","answer":"Usually the water dropped off a full boil when the pasta went in, or too much pasta was added to too little water at once."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Treat the pack time as a starting point. The real answer depends on variety and how closely you are watching.', seo_description='How long to boil whole-wheat pasta by variety, and why the window between done and overcooked is narrower than refined pasta.', seo_keywords='whole wheat pasta boiling time, how long to cook whole wheat pasta', reading_minutes=2, published_version_id='arv_truegrit_070_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_070';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_070';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_070','How Long Should Whole-Wheat Pasta Be Boiled?','how-long-should-whole-wheat-pasta-be-boiled','Treat the pack time as a starting point. The real answer depends on variety and how closely you are watching.','whole wheat pasta boiling time, how long to cook whole wheat pasta');

-- 074. Simple Tomato Whole-Wheat Pasta
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_074_2','art_truegrit_074',2,'{"blocks":[{"id":"blk_article_74_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["This is a plain, forgiving tomato sauce built with whole-wheat pasta''s particular timing and texture in mind, rather than a refined pasta recipe applied without adjustment."]}},{"id":"blk_article_74_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Boil the pasta in well salted water, checking a minute or two before the pack time given whole wheat''s narrower al dente window.","Build the sauce separately, onion softened in oil, garlic added briefly, then chopped or pureed tomato simmered until it thickens rather than staying watery.","Season simply, salt, a small pinch of sugar to balance the tomato''s acidity, and dried herbs or fresh basil if you have it.","Reserve some pasta water before draining and use it to loosen the sauce if it has thickened too much by the time the pasta is ready.","Toss the drained pasta straight into the sauce rather than serving them separately, so the strands absorb some of it as they finish."]}},{"id":"blk_article_74_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Pasta for this recipe","source":"manual","productSlugs":["pasta-banshi-wheat"],"limit":1}},{"id":"blk_article_74_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Tomato pasta questions","items":[{"question":"Can I use canned tomato instead of fresh?","answer":"Yes, either works well. Canned tomato often needs a slightly shorter simmer since it is already partly cooked down."},{"question":"Why add sugar to the sauce?","answer":"A small pinch balances tomato''s natural acidity. Skip it if your tomatoes are already sweet enough on their own."},{"question":"Can I make this sauce ahead of time?","answer":"Yes, it keeps well refrigerated for a few days. Reheat gently before tossing with freshly boiled pasta."},{"question":"Which wheat pasta variety suits this sauce best?","answer":"Banshi is a reliable everyday choice here, though Kathiya works well too if you want a firmer bite under the sauce."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A basic sauce built to actually suit whole-wheat pasta''s timing and texture, not fight against them.', seo_description='A simple tomato whole-wheat pasta recipe: sauce method, seasoning and timing built around whole wheat''s narrower cook window.', seo_keywords='tomato whole wheat pasta recipe, simple whole wheat pasta', reading_minutes=3, published_version_id='arv_truegrit_074_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_074';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_074';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_074','Simple Tomato Whole-Wheat Pasta','simple-tomato-whole-wheat-pasta','A basic sauce built to actually suit whole-wheat pasta''s timing and texture, not fight against them.','tomato whole wheat pasta recipe, simple whole wheat pasta');

-- 075. Five Indian-Style Pasta Recipes
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_075_2','art_truegrit_075',2,'{"blocks":[{"id":"blk_article_75_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole-wheat pasta takes well to techniques most Indian kitchens already use daily, tempering, tadka and a quick onion tomato masala, more readily than it takes to a classical Italian treatment."]}},{"id":"blk_article_75_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Five to try","items":["Masala pasta, boiled pasta tossed in a quick onion tomato masala with standard tempering spices.","Pasta upma style, cooked the same way suji upma is, with mustard seeds, curry leaves and mixed vegetables.","Pasta in a simple tadka of ghee, cumin and curry leaves, finished with lemon, for a quick weekday meal.","Schezwan style pasta, tossed with a spicy garlic chilli sauce in the Indo-Chinese tradition many households already cook.","Pasta salad with roasted vegetables and a mustard oil dressing, served at room temperature rather than hot."]}},{"id":"blk_article_75_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["None of these need special equipment or an unusual ingredient list. Most reuse a masala base or tempering a household already keeps on hand for other meals."]}},{"id":"blk_article_75_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Pasta for these recipes","source":"manual","productSlugs":["pasta-kathiya-wheat","pasta-paigambari-wheat"],"limit":2}},{"id":"blk_article_75_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Indian style pasta questions","items":[{"question":"Does whole-wheat pasta work well with Indian spices?","answer":"Yes, its nuttier flavour pairs naturally with tempering spices and masala, arguably better than with a very plain sauce."},{"question":"Can I use leftover pasta for the upma style version?","answer":"Yes, day old boiled pasta tossed into the tempering works fine and saves a step."},{"question":"Is Schezwan pasta very spicy?","answer":"It can be, adjust the chilli quantity in the sauce to taste before tossing it through the pasta."},{"question":"What oil should I use for the pasta salad dressing?","answer":"Mustard oil gives a distinct, pungent edge. Use it sparingly at first and adjust once you know how strong you want it."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Pasta run through an Indian kitchen''s usual techniques, tempering, tadka and masala, rather than an Italian one.', seo_description='Five Indian style pasta recipes: masala pasta, upma style pasta, tadka pasta, Schezwan pasta and a mustard oil pasta salad.', seo_keywords='Indian style pasta recipes, masala pasta', reading_minutes=3, published_version_id='arv_truegrit_075_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_075';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_075';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_075','Five Indian-Style Pasta Recipes','five-indian-style-pasta-recipes','Pasta run through an Indian kitchen''s usual techniques, tempering, tadka and masala, rather than an Italian one.','Indian style pasta recipes, masala pasta');

-- 076. What Is Whole-Wheat Vermicelli?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_076_2','art_truegrit_076',2,'{"blocks":[{"id":"blk_article_76_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole-wheat vermicelli is thin strands of wheat dough, extruded or cut fine and then dried, distinct from vermicelli made from rice. It is the base for both savoury sevai and sweet seviyan kheer."]}},{"id":"blk_article_76_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Thin strands of wheat dough, extruded or cut fine and then dried, distinct from vermicelli made from rice.","Most commonly sold roasted, which shortens the cooking time and adds a light toasted flavour before any spice or sweetener is added.","Used in two main styles, savoury sevai upma with vegetables, or sweet kheer style seviyan cooked in milk.","Made from whole wheat, so it carries the bran and germ that a refined maida vermicelli does not.","Can be made from any of our three wheat varieties, each carrying through the same character it has as flour."]}},{"id":"blk_article_76_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole-wheat vermicelli","source":"manual","productSlugs":["vermicelli-banshi-wheat","vermicelli-kathiya-wheat"],"limit":2}},{"id":"blk_article_76_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat vermicelli questions","items":[{"question":"Is wheat vermicelli the same as sevai?","answer":"Sevai is the name for both the ingredient and the savoury dish made from it. The ingredient itself is what this article describes."},{"question":"Does wheat vermicelli need to be roasted before cooking?","answer":"Most is sold pre-roasted, but a quick roast in ghee before adding liquid still improves texture and flavour."},{"question":"Can wheat vermicelli be eaten sweet and savoury?","answer":"Yes, the same base ingredient works in a savoury upma style sevai and a sweet milk based kheer."},{"question":"Does wheat vermicelli contain gluten?","answer":"Yes, it is made from wheat, so it contains gluten the same as any wheat product."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Thin strands of wheat dough, usually sold roasted, distinct from the rice vermicelli used elsewhere in Indian cooking.', seo_description='Whole-wheat vermicelli explained: how it is made, why it is usually sold roasted, and the dishes it goes into.', seo_keywords='wheat vermicelli, what is wheat vermicelli, sevai', reading_minutes=3, published_version_id='arv_truegrit_076_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_076';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_076';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_076','What Is Whole-Wheat Vermicelli?','what-is-whole-wheat-vermicelli','Thin strands of wheat dough, usually sold roasted, distinct from the rice vermicelli used elsewhere in Indian cooking.','wheat vermicelli, what is wheat vermicelli, sevai');

-- 077. Wheat Vermicelli vs Rice Vermicelli
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_077_2','art_truegrit_077',2,'{"blocks":[{"id":"blk_article_77_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Wheat vermicelli and rice vermicelli look similar coiled up in a packet, but they come from entirely different grains, and that decides gluten content, texture and which regional dishes each one shows up in."]}},{"id":"blk_article_77_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Different grains entirely. Wheat vermicelli contains gluten. Rice vermicelli does not, since rice has none.","Rice vermicelli is more common in South Indian and Southeast Asian dishes like idiyappam. Wheat vermicelli is more common in North Indian sevai and kheer.","Texture differs too. Wheat vermicelli has a slightly chewier bite. Rice vermicelli turns softer and more translucent once cooked.","Wheat vermicelli is usually roasted before cooking. Rice vermicelli is more often soaked or briefly boiled rather than dry roasted first.","Neither substitutes cleanly for the other in a recipe built around its particular texture and cooking method."]}},{"id":"blk_article_77_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Wheat vermicelli","source":"manual","productSlugs":["vermicelli-paigambari-wheat"],"limit":1}},{"id":"blk_article_77_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat vs rice vermicelli questions","items":[{"question":"Is rice vermicelli gluten free?","answer":"Yes, since it is made purely from rice. Wheat vermicelli always contains gluten."},{"question":"Can I substitute one for the other in a recipe?","answer":"Not directly. The cooking method and final texture differ enough that the dish will not turn out as intended."},{"question":"Which is used for idiyappam?","answer":"Rice vermicelli, pressed fresh or bought dried, is the traditional base for idiyappam."},{"question":"Which is used for sweet seviyan kheer?","answer":"Wheat vermicelli, usually the roasted kind, is what most seviyan kheer recipes call for."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Different grains entirely, which changes gluten content, texture and which regional dishes each one belongs to.', seo_description='Wheat vermicelli compared with rice vermicelli: gluten, texture, and which dishes and regions each is associated with.', seo_keywords='wheat vermicelli vs rice vermicelli, sevai vs rice noodles', reading_minutes=3, published_version_id='arv_truegrit_077_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_077';
