-- 078. Whole-Wheat Vermicelli vs Maida Vermicelli
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_078_2','art_truegrit_078',2,'{"blocks":[{"id":"blk_article_78_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole-wheat and maida vermicelli are made the same way, just from differently milled wheat. Whole wheat keeps the bran and germ that maida removes, and that single difference shapes texture, colour and flavour."]}},{"id":"blk_article_78_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Whole-wheat vermicelli keeps the bran and germ. Maida vermicelli is made from refined flour with both removed.","Maida vermicelli looks paler and cooks into a smoother, more classically expected seviyan texture.","Whole-wheat vermicelli carries more fibre and a nuttier flavour, by virtue of what milling leaves in rather than an added ingredient.","Whole-wheat vermicelli can clump a little more readily if under roasted, since the bran surface behaves differently from smooth refined dough.","Neither is wrong for kheer. The choice is largely which texture and flavour a household grew up eating."]}},{"id":"blk_article_78_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole-wheat vermicelli","source":"manual","productSlugs":["vermicelli-banshi-wheat"],"limit":1}},{"id":"blk_article_78_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole-wheat vs maida vermicelli questions","items":[{"question":"Is whole-wheat vermicelli more nutritious than maida vermicelli?","answer":"It keeps the bran and germ that maida milling removes, a real processing difference rather than a broader health claim."},{"question":"Does whole-wheat vermicelli taste very different?","answer":"Yes, noticeably nuttier and more grain forward. Maida vermicelli stays closer to neutral in flavour."},{"question":"Why does whole-wheat vermicelli clump more than maida?","answer":"The bran surface behaves differently from smooth refined dough, so even roasting matters more here to prevent clumping."},{"question":"Which is more traditional for seviyan kheer?","answer":"Both are made and eaten widely. Preference tends to follow what a household grew up cooking rather than one being more authentic."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Same basic product, different milling degree. What staying whole grain actually changes at the table.', seo_description='Whole-wheat vermicelli compared with maida vermicelli: fibre, texture, colour and which one clumps more easily.', seo_keywords='whole wheat vermicelli vs maida vermicelli', reading_minutes=2, published_version_id='arv_truegrit_078_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_078';
