INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_078','Whole-Wheat Vermicelli vs Maida Vermicelli','whole-wheat-vermicelli-vs-maida-vermicelli','Same basic product, different milling degree. What staying whole grain actually changes at the table.','whole wheat vermicelli vs maida vermicelli');

-- 079. Kathiya Wheat Vermicelli Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_079_2','art_truegrit_079',2,'{"blocks":[{"id":"blk_article_79_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya''s denser kernel gives its vermicelli a firmer bite that holds up well in a savoury sevai upma, carrying through the same character it has as flour and daliya."]}},{"id":"blk_article_79_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Firmer bite that holds up well in a savoury sevai upma, more than a delicate, quickly softening strand would.","Needs slightly more milk or water to soften fully in a kheer, in line with how Kathiya behaves in other formats.","Roasts a little more slowly than Banshi vermicelli, so watch it closely rather than timing by habit.","Suits dishes where a distinct, separate strand is wanted rather than one that softens completely into the milk.","Priced the same way as Kathiya flour and daliya, lower yield and rain fed cultivation, not an added processing cost."]}},{"id":"blk_article_79_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kathiya vermicelli","source":"manual","productSlugs":["vermicelli-kathiya-wheat"],"limit":1}},{"id":"blk_article_79_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya vermicelli questions","items":[{"question":"Is Kathiya vermicelli good for sevai upma?","answer":"Yes, its firmer bite holds up well and stays separate in a savoury upma style preparation."},{"question":"Does Kathiya vermicelli need more milk for kheer?","answer":"Generally a little more than Banshi or Paigambari, since the denser strand takes longer to soften fully."},{"question":"Why does Kathiya vermicelli need closer roasting attention?","answer":"It roasts a touch more slowly and unevenly than softer wheat vermicelli, so it needs watching rather than a fixed time."},{"question":"Is Kathiya vermicelli pricier than a standard brand?","answer":"Yes, the same reasons as Kathiya flour, lower yield and rain fed cultivation, not an added processing cost."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Kathiya''s density gives its vermicelli a firmer bite that holds up well in a savoury sevai.', seo_description='Kathiya wheat vermicelli explained: firmer texture, longer roasting attention, and which dishes it suits.', seo_keywords='Kathiya vermicelli, Kathiya wheat vermicelli', reading_minutes=2, published_version_id='arv_truegrit_079_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_079';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_079';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_079','Kathiya Wheat Vermicelli Explained','kathiya-wheat-vermicelli-explained','Kathiya''s density gives its vermicelli a firmer bite that holds up well in a savoury sevai.','Kathiya vermicelli, Kathiya wheat vermicelli');

-- 080. Banshi Wheat Vermicelli Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_080_2','art_truegrit_080',2,'{"blocks":[{"id":"blk_article_80_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Banshi vermicelli roasts evenly and cooks close to what a generic sevai or kheer recipe already assumes, which is why it is the easiest of the three to start with if you have not cooked wheat vermicelli before."]}},{"id":"blk_article_80_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Medium hardness makes Banshi vermicelli the most forgiving of the three, cooking close to what a generic sevai recipe already assumes.","Works equally well in a savoury upma style sevai and a softer sweet kheer.","Roasts predictably and evenly, without the extra attention Kathiya vermicelli sometimes needs.","A sensible everyday choice if you would rather stock one vermicelli variety than rotate between all three.","Softens a touch more readily than Kathiya vermicelli does, closer to the texture most kheer recipes already assume without adjustment."]}},{"id":"blk_article_80_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Banshi vermicelli","source":"manual","productSlugs":["vermicelli-banshi-wheat"],"limit":1}},{"id":"blk_article_80_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Banshi vermicelli questions","items":[{"question":"Is Banshi vermicelli a good starting choice?","answer":"Yes, it roasts and cooks predictably, needing the least adjustment from a standard sevai or kheer recipe."},{"question":"Does Banshi vermicelli work for both sevai and kheer?","answer":"Yes, its medium hardness handles both reasonably well without needing separate technique adjustments."},{"question":"How does Banshi vermicelli compare to Kathiya for texture?","answer":"Banshi softens a touch more readily. Kathiya stays firmer and holds a more distinct strand."},{"question":"Is Banshi vermicelli easier to roast evenly?","answer":"Generally yes, it roasts more predictably than Kathiya vermicelli, which needs closer watching."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The most forgiving of the three, roasting evenly and cooking close to what a generic sevai recipe assumes.', seo_description='Banshi wheat vermicelli explained: even roasting, predictable cooking, and why it suits both sevai and kheer.', seo_keywords='Banshi vermicelli, Banshi wheat vermicelli', reading_minutes=2, published_version_id='arv_truegrit_080_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_080';
