INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_080','Banshi Wheat Vermicelli Explained','banshi-wheat-vermicelli-explained','The most forgiving of the three, roasting evenly and cooking close to what a generic sevai recipe assumes.','Banshi vermicelli, Banshi wheat vermicelli');

-- 081. Paigambari Wheat Vermicelli Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_081_2','art_truegrit_081',2,'{"blocks":[{"id":"blk_article_81_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Paigambari vermicelli carries through the same aroma that defines the flour, daliya and pasta made from this wheat, most noticeable in a plain roasted strand before milk or spice is added."]}},{"id":"blk_article_81_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to expect","items":["Carries through the same aroma that defines Paigambari flour, daliya and pasta, most noticeable in a plain roasted vermicelli before milk or spice is added.","Best in simple preparations, a lightly sweetened kheer or plain sevai, where the wheat''s own flavour is the point.","Sits closer to Banshi than Kathiya on hardness, so roasting and liquid needs stay close to a standard vermicelli recipe.","Buy in smaller quantities if aroma is your reason for choosing it, since it fades with storage time.","A light hand with sugar in the kheer lets the wheat''s own aroma come through rather than being buried under sweetness."]}},{"id":"blk_article_81_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Paigambari vermicelli","source":"manual","productSlugs":["vermicelli-paigambari-wheat"],"limit":1}},{"id":"blk_article_81_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Paigambari vermicelli questions","items":[{"question":"Why choose Paigambari vermicelli over the other two?","answer":"Mainly for its aroma, which shows best in a plain roasted strand or simple kheer rather than a heavily spiced dish."},{"question":"Does Paigambari vermicelli cook faster than Kathiya?","answer":"Yes, it is moderately hard rather than dense, so it cooks a little faster and needs less liquid overall."},{"question":"How long does Paigambari vermicelli keep its aroma?","answer":"A few weeks in an airtight container. Buy smaller quantities if the aroma is your main reason for choosing it."},{"question":"Is Paigambari vermicelli good for sevai upma?","answer":"It works, though most buyers choose it for a plainer kheer or lightly spiced sevai where the aroma stands out more clearly."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same aroma that defines Paigambari flour and pasta, most noticeable in a plain roasted strand.', seo_description='Paigambari wheat vermicelli explained: its aroma, ideal use in plain preparations, and how to store it well.', seo_keywords='Paigambari vermicelli, Paigambari wheat vermicelli', reading_minutes=2, published_version_id='arv_truegrit_081_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_081';
