INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_081','Paigambari Wheat Vermicelli Explained','paigambari-wheat-vermicelli-explained','The same aroma that defines Paigambari flour and pasta, most noticeable in a plain roasted strand.','Paigambari vermicelli, Paigambari wheat vermicelli');

-- 086. How to Prevent Vermicelli From Becoming Sticky
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_086_2','art_truegrit_086',2,'{"blocks":[{"id":"blk_article_86_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sticky, clumped vermicelli almost always traces back to one of two things, uneven roasting before it goes in, or liquid that was not hot enough when it did. Both are simple to fix once you know which one is happening."]}},{"id":"blk_article_86_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Roast the vermicelli evenly in a little ghee before adding any liquid. Uneven roasting is the most common cause of clumping.","Add the vermicelli to milk or water that is already at a full boil, not lukewarm, so it starts cooking evenly across every strand.","Do not walk away once it is in the liquid. Vermicelli moves from properly cooked to overly soft and sticky in a short window.","Use the water or milk ratio suited to whether you are making a drier sevai or a wetter kheer, rather than one fixed ratio for both.","Toss with a little extra ghee once cooked and off the heat, which helps keep strands separate as it cools."]}},{"id":"blk_article_86_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook describes this exact problem with sevai kheer clumping into one mass despite dry roasting first](/community/dsc_truegrit_005), worth a read if roasting alone has not fixed it for you."]}},{"id":"blk_article_86_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Vermicelli to practise on","source":"manual","productSlugs":["vermicelli-banshi-wheat"],"limit":1}},{"id":"blk_article_86_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Sticky vermicelli questions","items":[{"question":"Why does my vermicelli always clump in kheer?","answer":"Usually uneven roasting or adding it to milk that was not at a full boil. Both let some strands soften before others."},{"question":"Does more liquid prevent sticking?","answer":"Not on its own. The roasting step and entry temperature matter more than simply adding extra milk or water."},{"question":"Can sticky vermicelli be fixed after cooking?","answer":"A little extra ghee tossed through while it is still warm can loosen it somewhat, though it will not fully separate again."},{"question":"Does the wheat variety affect how easily it clumps?","answer":"Slightly. Kathiya vermicelli''s firmer strand resists clumping a bit more than a softer wheat variety would."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Uneven roasting and the wrong entry temperature into the liquid are the two most common causes.', seo_description='How to prevent vermicelli from becoming sticky: roasting technique, liquid temperature and timing that keep strands separate.', seo_keywords='vermicelli sticky, sevai clumping, seviyan tips', reading_minutes=3, published_version_id='arv_truegrit_086_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_086';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_086';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_086','How to Prevent Vermicelli From Becoming Sticky','how-to-prevent-vermicelli-from-becoming-sticky','Uneven roasting and the wrong entry temperature into the liquid are the two most common causes.','vermicelli sticky, sevai clumping, seviyan tips');

-- 087. Black Mustard Oil vs Yellow Mustard Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_087_2','art_truegrit_087',2,'{"blocks":[{"id":"blk_article_87_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black and yellow mustard oil come from different mustard seeds, and the difference shows up first in the nose, not the ingredient list. Black is sharper and more assertive. Yellow settles into something rounder and easier to use every day."]}},{"id":"blk_article_87_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Pungency is the main difference. Black mustard oil is sharper and more assertive raw. Yellow settles into something rounder and milder.","Black is the traditional choice for Bengali fish curries and pickles, where a strong, distinct bite is wanted. Yellow suits everyday tempering and lighter sabzi.","Both mellow when heated to a light smoke point, a step many traditional recipes call for before cooking with either.","Colour differs too, black mustard oil often runs a deeper amber, yellow a lighter gold, though this varies by batch and pressing.","Neither is a healthier choice over the other in any verified sense. The difference is flavour intensity, not nutrition."]}},{"id":"blk_article_87_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook compares the two directly for Bengali fish, sharper raw versus rounder after smoking](/community/dsc_truegrit_016), useful if you are deciding which to keep on hand."]}},{"id":"blk_article_87_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Both mustard oils","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_87_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Black vs yellow mustard oil questions","items":[{"question":"Which mustard oil is more pungent?","answer":"Black mustard oil is noticeably sharper raw. Yellow is milder and rounder, which is why it suits everyday cooking better."},{"question":"Can I use yellow mustard oil for Bengali fish curry?","answer":"Yes, though the result will be milder than the traditional black mustard oil version most recipes assume."},{"question":"Is one mustard oil healthier than the other?","answer":"There is no verified nutritional advantage either way. The real difference is flavour strength, not a health claim."},{"question":"Do both need to be heated to a smoke point before cooking?","answer":"Both benefit from it if you want a milder result, though black more noticeably needs it than yellow."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Pungency and traditional use are the real differences, not a nutrition contest between the two.', seo_description='Black mustard oil compared with yellow: pungency, colour, and which traditional dishes each one suits best.', seo_keywords='black mustard oil vs yellow mustard oil, mustard oil comparison', reading_minutes=3, published_version_id='arv_truegrit_087_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_087';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_087';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_087','Black Mustard Oil vs Yellow Mustard Oil','black-mustard-oil-vs-yellow-mustard-oil','Pungency and traditional use are the real differences, not a nutrition contest between the two.','black mustard oil vs yellow mustard oil, mustard oil comparison');

-- 088. What Is Black Mustard Oil?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_088_2','art_truegrit_088',2,'{"blocks":[{"id":"blk_article_88_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black mustard oil is pressed from a darker, more pungent mustard seed, giving an oil with a sharper raw bite than the yellow variety and a long history in Bengali and Eastern Indian kitchens."]}},{"id":"blk_article_88_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Pressed from a darker, more pungent mustard seed, giving an oil with a sharper raw bite than the yellow variety.","Traditional in Bengali and Eastern Indian cooking, especially fish curries, pickles and mustard based pastes and marinades.","Usually cold pressed, kachi ghani style, which keeps the pungency and natural colour that refining would otherwise strip out.","Heating it briefly to a light smoke before cooking mellows the raw sharpness, a step many traditional recipes build in as a first move.","Also used as a natural preservative in pickling, where its pungency and oil content both help the pickle keep."]}},{"id":"blk_article_88_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black mustard oil","source":"manual","productSlugs":["black-mustard-oil"],"limit":1}},{"id":"blk_article_88_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black mustard oil questions","items":[{"question":"Is black mustard oil the strongest tasting mustard oil?","answer":"Among the two we sell, yes. It is noticeably sharper raw than yellow mustard oil."},{"question":"Do I need to heat black mustard oil before cooking?","answer":"Many traditional recipes heat it to a light smoke first, which mellows the raw pungency before other ingredients go in."},{"question":"Is black mustard oil good for pickling?","answer":"Yes, it is a traditional pickling oil, valued both for flavour and its natural preservative qualities."},{"question":"Why is black mustard oil associated with Bengali cooking?","answer":"It is the traditional cooking fat in much of Bengali cuisine, especially fish curries built on a mustard seed paste."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Pressed from a sharper, more pungent mustard seed, traditional to Bengali and Eastern Indian cooking.', seo_description='Black mustard oil explained: how it is pressed, its traditional culinary uses, and how it differs from yellow mustard oil.', seo_keywords='black mustard oil, what is black mustard oil', reading_minutes=2, published_version_id='arv_truegrit_088_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_088';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_088';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_088','What Is Black Mustard Oil?','what-is-black-mustard-oil','Pressed from a sharper, more pungent mustard seed, traditional to Bengali and Eastern Indian cooking.','black mustard oil, what is black mustard oil');

-- 089. What Is Yellow Mustard Oil?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_089_2','art_truegrit_089',2,'{"blocks":[{"id":"blk_article_89_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Yellow mustard oil is pressed from a milder mustard seed than the black variety, giving an oil that settles into a rounder flavour and works well as an everyday cooking fat rather than a specialty one."]}},{"id":"blk_article_89_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Pressed from a milder mustard seed, giving an oil that settles into a rounder flavour than the black variety.","The more common everyday choice for tempering and general sabzi across much of North India.","Usually cold pressed the same way as black mustard oil, kachi ghani style, retaining its natural aroma and colour.","Suits dishes where mustard oil''s flavour should support the other spices rather than dominate the finished dish.","A reasonable starting point if you are new to cooking with mustard oil and want something more forgiving than the black variety."]}},{"id":"blk_article_89_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Yellow mustard oil","source":"manual","productSlugs":["yellow-mustard-oil"],"limit":1}},{"id":"blk_article_89_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Yellow mustard oil questions","items":[{"question":"Is yellow mustard oil milder than black?","answer":"Yes, noticeably. It settles into a rounder flavour, which is why it suits everyday cooking better than the sharper black variety."},{"question":"Can yellow mustard oil be used for everything black mustard oil is used for?","answer":"In most dishes yes, though the flavour will be milder than what a recipe built around black mustard oil expects."},{"question":"Is yellow mustard oil good for a first time buyer?","answer":"Yes, it is the more forgiving of the two if you have not cooked with mustard oil before."},{"question":"Does yellow mustard oil need heating before use?","answer":"It benefits from a light smoke the same as black, though the effect is less dramatic since it starts milder."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Pressed from a milder mustard seed, the more common everyday choice for tempering across North India.', seo_description='Yellow mustard oil explained: how it is pressed, its everyday culinary uses, and how it differs from black mustard oil.', seo_keywords='yellow mustard oil, what is yellow mustard oil', reading_minutes=2, published_version_id='arv_truegrit_089_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_089';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_089';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_089','What Is Yellow Mustard Oil?','what-is-yellow-mustard-oil','Pressed from a milder mustard seed, the more common everyday choice for tempering across North India.','yellow mustard oil, what is yellow mustard oil');

-- 090. How Traditional Mustard Oil Is Made
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_090_2','art_truegrit_090',2,'{"blocks":[{"id":"blk_article_90_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Traditional mustard oil is pressed, not extracted with heat or chemicals. Mustard seeds are cleaned and fed into a crusher that pushes the oil out mechanically, and what happens after that decides whether it stays raw and pungent or gets refined into something milder."]}},{"id":"blk_article_90_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The steps","items":["Mustard seeds are cleaned and fed into a crusher, traditionally a wooden or stone ghani, which presses the oil out mechanically.","No external heat is added during kachi ghani pressing, only the mild warmth generated by friction, which is why it is called cold pressed.","The oil is typically left to settle rather than heavily filtered, which is why some natural sediment can appear at the bottom of the bottle.","Refined mustard oil goes through additional heat and chemical processing after pressing, which mellows the flavour and extends shelf stability.","Traditional pressing keeps more of the pungency and colour that refining is specifically designed to remove."]}},{"id":"blk_article_90_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditionally pressed mustard oil","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_90_4","type":"faq","version":1,"enabled":true,"props":{"heading":"How mustard oil is made, answered","items":[{"question":"Is cold pressed mustard oil made without heat at all?","answer":"No external heat is added, though the crushing itself generates some mild warmth. That is different from the deliberate heat used in refining."},{"question":"Why does traditional mustard oil have sediment?","answer":"It is typically left to settle rather than heavily filtered, so some natural sediment from the seed can remain in the bottle."},{"question":"Is a wooden ghani still used commercially?","answer":"Some producers still use one, though most commercial kachi ghani pressing today uses a mechanical version of the same slow crushing method."},{"question":"Does traditional pressing yield less oil than refining methods?","answer":"Generally yes, cold pressing extracts less oil per seed than higher heat or solvent based extraction, which is part of why it costs more."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Mechanical pressing with no added heat, the same basic method behind kachi ghani oil for generations.', seo_description='How mustard oil is traditionally made: cleaning, cold pressing, and what separates it from refined mustard oil.', seo_keywords='how mustard oil is made, mustard oil pressing process', reading_minutes=3, published_version_id='arv_truegrit_090_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_090';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_090';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_090','How Traditional Mustard Oil Is Made','how-traditional-mustard-oil-is-made','Mechanical pressing with no added heat, the same basic method behind kachi ghani oil for generations.','how mustard oil is made, mustard oil pressing process');

-- 091. Cold-Pressed Mustard Oil vs Refined Mustard Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_091_2','art_truegrit_091',2,'{"blocks":[{"id":"blk_article_91_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Cold pressed and refined mustard oil start from the same seed and end up quite different, mainly because of what happens to the oil after it leaves the crusher."]}},{"id":"blk_article_91_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Cold pressed oil is extracted mechanically with no added heat, keeping its natural pungency, colour and some sediment.","Refined oil goes through additional heat and chemical processing that strips out much of the aroma, giving a milder, more neutral oil.","Cold pressed oil often needs heating to a light smoke before cooking to mellow its raw sharpness. Refined oil rarely needs this step.","Refined oil tends to have a longer, more consistent shelf life, since much of what causes natural variation has been processed out.","Traditional recipes, especially Bengali fish curries and pickles, are usually written with cold pressed oil''s stronger flavour in mind."]}},{"id":"blk_article_91_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Cold-pressed mustard oil","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_91_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Cold-pressed vs refined questions","items":[{"question":"Is cold-pressed mustard oil better than refined?","answer":"Neither is simply better. Cold-pressed keeps more flavour and pungency, refined offers a milder, more consistent oil. The choice depends on the dish."},{"question":"Can I use refined mustard oil in a traditional Bengali recipe?","answer":"You can, but expect a milder result than the recipe likely assumes, since it was probably written with cold-pressed oil in mind."},{"question":"Does refined mustard oil need heating before cooking?","answer":"Not in the same way cold-pressed does. Much of the raw pungency that heating mellows has already been processed out."},{"question":"Which lasts longer once opened?","answer":"Refined oil generally has more consistent shelf stability, though properly stored cold-pressed oil still keeps reasonably well."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One keeps the raw pungency and sediment, the other trades both away for a milder, more consistent oil.', seo_description='Cold-pressed mustard oil compared with refined: pungency, sediment, shelf life, and which traditional recipes assume.', seo_keywords='cold pressed mustard oil vs refined, kachi ghani vs refined mustard oil', reading_minutes=3, published_version_id='arv_truegrit_091_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_091';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_091';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_091','Cold-Pressed Mustard Oil vs Refined Mustard Oil','cold-pressed-mustard-oil-vs-refined-mustard-oil','One keeps the raw pungency and sediment, the other trades both away for a milder, more consistent oil.','cold pressed mustard oil vs refined, kachi ghani vs refined mustard oil');

-- 092. Kachi Ghani Mustard Oil Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_092_2','art_truegrit_092',2,'{"blocks":[{"id":"blk_article_92_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kachi ghani means raw crushing, and it describes the traditional method of pressing mustard oil using only mechanical pressure, with no added heat at any stage."]}},{"id":"blk_article_92_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What it actually means","items":["Kachi ghani means raw crushing, the traditional method of pressing mustard oil using only mechanical pressure, no added heat.","Historically done with a wooden ghani turned by bullock power, now more commonly a mechanical version of the same slow crushing.","The lack of added heat is what preserves the oil''s natural pungency, colour and the sediment that settles at the bottom of the bottle.","This is what most cold-pressed mustard oil sold today refers to, whether or not the term kachi ghani appears explicitly on the label.","Both our black and yellow mustard oils are pressed this way, which is why heating them to a light smoke before cooking still matters."]}},{"id":"blk_article_92_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kachi ghani style","source":"manual","productSlugs":["black-mustard-oil"],"limit":1}},{"id":"blk_article_92_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Kachi ghani questions","items":[{"question":"Is kachi ghani the same as cold-pressed?","answer":"Effectively yes. Kachi ghani is the traditional name for the same no-heat mechanical pressing that cold-pressed describes."},{"question":"Does kachi ghani oil cost more than other mustard oil?","answer":"Generally yes, since the method extracts less oil per seed and takes longer than higher heat extraction methods."},{"question":"Is a bullock powered ghani still used today?","answer":"Rarely commercially, though the term persists to describe the same slow, low heat crushing principle a mechanical ghani now performs."},{"question":"Why does kachi ghani oil have visible sediment?","answer":"It is typically settled rather than heavily filtered after pressing, so natural sediment from the seed can remain."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Raw crushing, no added heat. The traditional method behind most cold-pressed mustard oil sold today.', seo_description='Kachi ghani mustard oil explained: the traditional cold-pressing method and what it preserves compared to refining.', seo_keywords='kachi ghani mustard oil, kachi ghani meaning', reading_minutes=2, published_version_id='arv_truegrit_092_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_092';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_092';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_092','Kachi Ghani Mustard Oil Explained','kachi-ghani-mustard-oil-explained','Raw crushing, no added heat. The traditional method behind most cold-pressed mustard oil sold today.','kachi ghani mustard oil, kachi ghani meaning');

-- 093. Why Mustard Oil Has Such a Strong Aroma
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_093_2','art_truegrit_093',2,'{"blocks":[{"id":"blk_article_93_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Mustard oil''s sharp smell is not an additive. It comes from compounds naturally released when the seed''s cells are crushed during pressing, the same chemical family responsible for wasabi and horseradish''s bite."]}},{"id":"blk_article_93_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What is actually happening","items":["The sharp smell comes from compounds released when mustard seed cells are crushed during pressing, the same family responsible for wasabi and horseradish''s bite.","These compounds are naturally present in the seed, not an additive, and are part of what has made mustard oil valued as a pickling agent for generations.","Refining reduces this aroma substantially, which is why refined mustard oil smells noticeably milder than a cold-pressed one.","Heating cold-pressed mustard oil to a light smoke before cooking mellows the sharpest edge of the aroma without removing it entirely."]}},{"id":"blk_article_93_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Full aroma mustard oil","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_93_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard oil aroma questions","items":[{"question":"Is the strong smell a sign the oil has gone bad?","answer":"No, pungency is a natural feature of unrefined mustard oil, not a sign of spoilage."},{"question":"Does heating remove the smell entirely?","answer":"It mellows the sharpest edge but does not remove the aroma completely, which most cooks still want present in the finished dish."},{"question":"Why does refined mustard oil smell so much milder?","answer":"Refining processes substantially reduce the natural compounds responsible for the pungent aroma."},{"question":"Is black mustard oil''s smell stronger than yellow''s?","answer":"Yes, noticeably. This is the main sensory difference between the two."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Compounds released when the seed is crushed, the same family responsible for wasabi and horseradish''s bite.', seo_description='Why mustard oil smells so pungent: the natural compounds released during pressing and how heat changes the aroma.', seo_keywords='why mustard oil smells strong, mustard oil pungent aroma', reading_minutes=2, published_version_id='arv_truegrit_093_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_093';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_093';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_093','Why Mustard Oil Has Such a Strong Aroma','why-mustard-oil-has-such-a-strong-aroma','Compounds released when the seed is crushed, the same family responsible for wasabi and horseradish''s bite.','why mustard oil smells strong, mustard oil pungent aroma');

-- 094. Why Mustard Oil Sometimes Looks Cloudy
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_094_2','art_truegrit_094',2,'{"blocks":[{"id":"blk_article_94_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Cloudiness in mustard oil worries a lot of first time buyers, but it is usually a sign of how the oil was pressed and stored, not that something has gone wrong with it."]}},{"id":"blk_article_94_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What is actually happening","items":["Unrefined mustard oil is not filtered as thoroughly as refined oil, so a natural sediment can settle and cause cloudiness over time.","Cold temperatures can cause some natural compounds in unrefined oil to solidify slightly, clouding it until it warms back to room temperature.","Cloudiness alone is not a reliable sign of spoilage. Smell and taste are better indicators of whether an oil has actually gone off.","Shaking the bottle before use redistributes settled sediment rather than indicating anything is genuinely wrong with the oil."]}},{"id":"blk_article_94_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One thread asks whether sediment in cold-pressed oil bottles goes rancid faster than the clear oil above it](/community/dsc_truegrit_019), worth reading if this has been on your mind."]}},{"id":"blk_article_94_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Cold-pressed and naturally cloudy","source":"manual","productSlugs":["black-mustard-oil"],"limit":1}},{"id":"blk_article_94_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Cloudy mustard oil questions","items":[{"question":"Should I pour off cloudy sediment or shake it back in?","answer":"Either is fine. Shaking redistributes it through the oil, pouring it off simply leaves a clearer oil above the sediment layer."},{"question":"Does cold weather always cause mustard oil to cloud?","answer":"It can, especially with unrefined oil, and it should clear again once the oil returns to room temperature."},{"question":"How do I tell cloudiness from actual spoilage?","answer":"Smell and taste are the real test. A flat or sour smell means spoilage. Cloudiness alone usually does not."},{"question":"Is refined mustard oil ever cloudy?","answer":"Rarely, since refining removes most of the natural sediment and compounds that cause cloudiness in unrefined oil."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Usually natural sediment or cold weather, not spoilage. What to actually check instead.', seo_description='Why cold-pressed mustard oil sometimes looks cloudy: sediment, temperature, and how to tell it apart from spoilage.', seo_keywords='mustard oil cloudy, mustard oil sediment', reading_minutes=2, published_version_id='arv_truegrit_094_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_094';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_094';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_094','Why Mustard Oil Sometimes Looks Cloudy','why-mustard-oil-sometimes-looks-cloudy','Usually natural sediment or cold weather, not spoilage. What to actually check instead.','mustard oil cloudy, mustard oil sediment');

-- 095. How to Identify Pure Mustard Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_095_2','art_truegrit_095',2,'{"blocks":[{"id":"blk_article_95_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["No single check proves a mustard oil is pure on its own. Smell, labelling and price together give a more reliable picture than any one test."]}},{"id":"blk_article_95_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually check","items":["Genuine mustard oil should smell distinctly pungent and sharp. A flat or very mild smell on an unrefined oil is worth questioning.","Check for a certification mark and licence number on the label rather than trusting packaging claims alone.","Extremely low pricing compared to other mustard oil on the same shelf is worth being cautious about.","A cold-pressed oil may naturally cloud or thicken slightly when refrigerated. This alone is not proof of purity or adulteration either way.","When in doubt, buy from a seller who states the pressing method and seed source clearly rather than an unlabelled bottle."]}},{"id":"blk_article_95_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Verified mustard oil","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_95_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Purity questions","items":[{"question":"Does a cloudy oil mean it is adulterated?","answer":"No, cloudiness alone is not a reliable sign either way. Check smell, labelling and certification instead."},{"question":"Is a very cheap bottle of mustard oil a red flag?","answer":"It can be, since genuine kachi ghani pressing is a slower, lower yield process than cheaper extraction methods."},{"question":"What certification should I look for?","answer":"A licence number from a recognised food safety authority, printed clearly on the label rather than a vague general claim."},{"question":"Can smell alone confirm purity?","answer":"It is a strong indicator, since genuine mustard oil is reliably pungent, but it works best combined with checking the label too."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Smell, certification and price together, not any single test on its own.', seo_description='How to identify pure mustard oil: smell, certification marks, pricing red flags and what a cold test does and does not prove.', seo_keywords='pure mustard oil, how to check mustard oil quality', reading_minutes=2, published_version_id='arv_truegrit_095_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_095';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_095';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_095','How to Identify Pure Mustard Oil','how-to-identify-pure-mustard-oil','Smell, certification and price together, not any single test on its own.','pure mustard oil, how to check mustard oil quality');

-- 096. How to Store Mustard Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_096_2','art_truegrit_096',2,'{"blocks":[{"id":"blk_article_96_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Mustard oil is fairly stable as cooking oils go, but a few basic storage habits still make a real difference to how long it stays at its best."]}},{"id":"blk_article_96_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Keep it in a cool, dark place away from direct sunlight, which can gradually degrade both flavour and colour over time.","A tightly sealed bottle or container matters more than refrigeration for most households, though refrigeration helps in a hot climate.","Avoid storing near a stove or other heat source, where ambient temperature stays higher than the rest of the kitchen.","Use within a reasonable time of opening. Mustard oil is fairly stable but still benefits from not sitting open for months on end.","Decanting into a smaller bottle as the level drops reduces the air space above the oil, which slows oxidation slightly."]}},{"id":"blk_article_96_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Mustard oil to store","source":"manual","productSlugs":["yellow-mustard-oil"],"limit":1}},{"id":"blk_article_96_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard oil storage questions","items":[{"question":"Does mustard oil need refrigeration?","answer":"Not usually. A cool, dark pantry is enough for most households, though refrigeration can help in a hot, humid climate."},{"question":"Does the bottle material matter for storage?","answer":"A dark or opaque bottle protects the oil from light better than a clear one, though a clear bottle kept in a dark cupboard works too."},{"question":"How long does mustard oil last once opened?","answer":"Generally a year or more if stored cool, dark and tightly sealed, though flavour is best within the first several months."},{"question":"Can mustard oil be stored next to other cooking oils?","answer":"Yes, there is no interaction concern. Just keep each sealed properly and away from direct heat and light."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Cool, dark and tightly sealed matters more than refrigeration for most households.', seo_description='How to store mustard oil properly: temperature, light exposure, sealing, and how long it stays good once opened.', seo_keywords='how to store mustard oil, mustard oil storage tips', reading_minutes=2, published_version_id='arv_truegrit_096_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_096';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_096';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_096','How to Store Mustard Oil','how-to-store-mustard-oil','Cool, dark and tightly sealed matters more than refrigeration for most households.','how to store mustard oil, mustard oil storage tips');

-- 097. Does Mustard Oil Expire?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_097_2','art_truegrit_097',2,'{"blocks":[{"id":"blk_article_97_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Mustard oil does eventually go off, but it holds up better than many other cooking oils if it is stored with a little care. Knowing what rancidity actually looks like matters more than watching a printed date."]}},{"id":"blk_article_97_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually matters","items":["Yes, eventually, though mustard oil is more stable than many other cooking oils and keeps reasonably well if stored properly.","Rancidity shows up as a flat, slightly sour smell replacing the usual sharp pungency, or a change in taste when cooked.","Cold-pressed oil kept in a cool, dark, tightly sealed container generally lasts a year or more from the pressing date.","If the smell has faded or turned unpleasant, it is past its best even if the expiry date on the label has not technically passed."]}},{"id":"blk_article_97_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Mustard oil","source":"manual","productSlugs":["black-mustard-oil"],"limit":1}},{"id":"blk_article_97_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard oil expiry questions","items":[{"question":"How can I tell if mustard oil has gone rancid?","answer":"A flat, sour smell replacing the usual sharp pungency is the clearest sign, along with an off taste once cooked."},{"question":"Is it safe to use mustard oil slightly past its printed date?","answer":"If it still smells and tastes normal, it is generally fine. Trust your senses over the printed date alone."},{"question":"Does opening the bottle speed up spoilage?","answer":"Yes, air exposure gradually affects any oil. Reseal tightly after each use to slow this down."},{"question":"Is rancid mustard oil dangerous to eat?","answer":"It will taste unpleasant well before it becomes a safety concern, so taste is a reliable early warning either way."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Eventually, yes, though it is more stable than most cooking oils if stored properly.', seo_description='Does mustard oil expire: signs of rancidity, typical shelf life, and how storage affects how long it stays good.', seo_keywords='does mustard oil expire, mustard oil shelf life', reading_minutes=2, published_version_id='arv_truegrit_097_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_097';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_097';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_097','Does Mustard Oil Expire?','does-mustard-oil-expire','Eventually, yes, though it is more stable than most cooking oils if stored properly.','does mustard oil expire, mustard oil shelf life');

-- 098. Why Colour Varies Between Mustard Oils
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_098_2','art_truegrit_098',2,'{"blocks":[{"id":"blk_article_98_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Two bottles of mustard oil sitting side by side can look noticeably different in colour, and that variation traces back to the seed and the processing, not to one bottle being better than the other."]}},{"id":"blk_article_98_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually changes it","items":["Seed variety is the biggest factor. Black mustard oil often runs a deeper amber than the lighter gold of yellow mustard oil.","Degree of refining changes colour too. Refined oil is lighter and more uniform than an unrefined, cold-pressed batch.","Natural variation between harvests and even individual pressings means colour is not a reliable indicator of quality on its own.","Bottle and light exposure can also shift how a colour appears without the oil inside actually having changed at all.","A clear glass bottle held up to daylight will show a different shade than the same oil in dim kitchen lighting."]}},{"id":"blk_article_98_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Both colours, both real","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_98_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard oil colour questions","items":[{"question":"Does darker mustard oil mean stronger flavour?","answer":"Generally the darker black mustard oil is more pungent than the lighter yellow, though colour alone is not a perfect predictor."},{"question":"Should I worry if two bottles of the same oil look different?","answer":"Not necessarily, natural batch variation between harvests and pressings is normal and does not indicate a quality problem."},{"question":"Does refining always lighten mustard oil?","answer":"Yes, refining processes typically produce a lighter, more uniform colour than unrefined, cold-pressed oil."},{"question":"Can I judge quality by colour alone?","answer":"Not reliably. Smell, certification and how the oil behaves in cooking tell you more than colour on its own."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Seed variety and refining degree, not a sign of inconsistent quality.', seo_description='Why mustard oil colour varies between bottles and brands: seed type, refining degree, and natural batch variation.', seo_keywords='mustard oil colour variation, why is mustard oil different colours', reading_minutes=2, published_version_id='arv_truegrit_098_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_098';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_098';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_098','Why Colour Varies Between Mustard Oils','why-colour-varies-between-mustard-oils','Seed variety and refining degree, not a sign of inconsistent quality.','mustard oil colour variation, why is mustard oil different colours');

-- 099. Which Mustard Oil Should You Use for Cooking?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_099_2','art_truegrit_099',2,'{"blocks":[{"id":"blk_article_99_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The right mustard oil depends more on the dish than on a fixed household rule. Matching pungency to what you are cooking gives a more reliable answer than always reaching for the same bottle."]}},{"id":"blk_article_99_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to decide","items":["For fish curries, pickles or dishes that want a strong, distinct mustard flavour, black mustard oil is the traditional choice.","For everyday tempering and general sabzi where mustard oil should support rather than dominate, yellow is usually the easier pick.","Heating either to a light smoke before adding other ingredients mellows the raw pungency, useful if you want a gentler result from either.","If you are new to cooking with mustard oil, yellow is the more forgiving starting point before trying black."]}},{"id":"blk_article_99_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook splits black for fish and yellow for everyday sabzi, and asks whether that is the usual pattern](/community/dsc_truegrit_016), worth reading for a second opinion."]}},{"id":"blk_article_99_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Choose your mustard oil","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_99_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Choosing mustard oil questions","items":[{"question":"Can I use one mustard oil for everything?","answer":"Yes, many households do, usually settling on yellow for its everyday flexibility and buying black only for specific dishes."},{"question":"Is black mustard oil too strong for daily cooking?","answer":"Not necessarily, but its stronger flavour suits dishes built around it better than it suits very mild, everyday sabzi."},{"question":"Should I keep both black and yellow mustard oil stocked?","answer":"If you cook a range of regional dishes, yes. Otherwise one, matched to what you cook most often, is enough."},{"question":"Does heating change which oil I should pick?","answer":"It changes how pungent either tastes in the final dish, but does not change which one suits a given recipe overall."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Depends on the dish more than a fixed rule. Here is a practical way to decide.', seo_description='Which mustard oil to use for cooking: matching black or yellow mustard oil to the dish rather than picking one by default.', seo_keywords='which mustard oil to use, best mustard oil for cooking', reading_minutes=3, published_version_id='arv_truegrit_099_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_099';
