INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_099','Which Mustard Oil Should You Use for Cooking?','which-mustard-oil-should-you-use-for-cooking','Depends on the dish more than a fixed rule. Here is a practical way to decide.','which mustard oil to use, best mustard oil for cooking');

-- 100. Black Mustard vs Yellow Mustard Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_100_2','art_truegrit_100',2,'{"blocks":[{"id":"blk_article_100_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black and yellow mustard seeds differ the same way their pressed oils do, sharper against milder, and that difference shows up whether the seed is tempered whole or pressed into oil."]}},{"id":"blk_article_100_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Black mustard seeds are smaller and sharper in flavour, the classic tempering seed in Eastern Indian and Bengali cooking.","Yellow mustard seeds are milder and larger, more common in pickling spice blends and some North Indian preparations.","Both pop and release aroma quickly when added to hot oil, black doing so more assertively than yellow.","Colour follows the same pattern as the oil, black seeds are visibly darker than the pale yellow of the milder variety.","We press both into oil rather than selling the loose seed, so the pungency difference described here shows up most directly in our black and yellow mustard oils."]}},{"id":"blk_article_100_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Pressed from these seeds","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_100_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard seed questions","items":[{"question":"Do you sell loose mustard seeds?","answer":"No, we press both black and yellow mustard seeds into oil rather than selling them loose."},{"question":"Which mustard seed is more common in tempering?","answer":"Black mustard seeds are the more common tempering choice in Eastern Indian and Bengali cooking specifically."},{"question":"Does the seed difference carry through to the oil?","answer":"Yes, black mustard oil is noticeably more pungent than yellow, tracking the same difference between the two seeds."},{"question":"Are yellow mustard seeds used in pickling?","answer":"Yes, they are a common component of pickling spice blends, alongside their use in some North Indian preparations."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The seed comparison behind the oil comparison, and how it shows up when they are pressed instead of tempered whole.', seo_description='Black mustard seeds compared with yellow: flavour, traditional uses, and how the difference carries into pressed oil.', seo_keywords='black mustard seeds vs yellow mustard seeds', reading_minutes=2, published_version_id='arv_truegrit_100_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_100';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_100';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_100','Black Mustard vs Yellow Mustard Seeds','black-mustard-vs-yellow-mustard-seeds','The seed comparison behind the oil comparison, and how it shows up when they are pressed instead of tempered whole.','black mustard seeds vs yellow mustard seeds');

-- 101. Traditional Indian Foods Cooked in Mustard Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_101_2','art_truegrit_101',2,'{"blocks":[{"id":"blk_article_101_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Mustard oil is a defining ingredient across several regional Indian cuisines, not a single dish''s flavouring. Its pungency shapes the character of everything from fish curry to pickles."]}},{"id":"blk_article_101_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where it shows up","items":["Shorshe maach, Bengali fish curry built on a mustard seed paste and finished with mustard oil, is one of the dish''s best known showcases.","Achaar, Indian pickles, traditionally use mustard oil both for flavour and as a natural preservative that helps the pickle keep.","Aloo posto and other Bengali vegetable preparations often start with a mustard oil tempering rather than a neutral cooking oil.","Everyday tadka across much of North and East India, mustard seeds popped in hot mustard oil, forms the base of countless simple sabzis.","Kashmiri preparations like rogan josh traditionally use mustard oil as the primary cooking fat, contributing to the dish''s depth."]}},{"id":"blk_article_101_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"For these dishes","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_101_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard oil dishes questions","items":[{"question":"Is mustard oil essential to Bengali fish curry?","answer":"It is the traditional cooking fat for shorshe maach specifically, contributing much of the dish''s characteristic flavour."},{"question":"Why is mustard oil used in pickling?","answer":"Both for its flavour and because its natural properties act as a preservative, helping the pickle keep over time."},{"question":"Can I substitute a neutral oil in these recipes?","answer":"You can, but the finished dish will lack the pungency and depth mustard oil specifically contributes to these traditional recipes."},{"question":"Is mustard oil used outside Bengali and Kashmiri cooking?","answer":"Yes, it is a common everyday tempering oil across much of North and East India beyond these signature dishes."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Mustard oil is a defining ingredient across several regional cuisines, not a single dish''s flavouring.', seo_description='Traditional Indian dishes cooked in mustard oil: Bengali fish curry, pickles, Kashmiri cooking and everyday tempering.', seo_keywords='traditional Indian mustard oil dishes, mustard oil recipes', reading_minutes=3, published_version_id='arv_truegrit_101_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_101';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_101';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_101','Traditional Indian Foods Cooked in Mustard Oil','traditional-indian-foods-cooked-in-mustard-oil','Mustard oil is a defining ingredient across several regional cuisines, not a single dish''s flavouring.','traditional Indian mustard oil dishes, mustard oil recipes');

-- 106. Sarson-Based Indian Cooking Guide
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_106_2','art_truegrit_106',2,'{"blocks":[{"id":"blk_article_106_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sarson is the Hindi word for mustard, and it covers more ground than any single product on a shelf, the plant, its seeds, its greens and the oil pressed from the seed all show up across Indian cooking under this one name."]}},{"id":"blk_article_106_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How sarson shows up in the kitchen","items":["Sarson is the Hindi word for mustard, covering the plant, its seeds, its greens and the oil pressed from the seed, all of which show up across Indian cooking.","Mustard oil is the everyday cooking fat in much of the east and north, used both for tempering and as the primary oil in a dish.","Mustard seeds, black or yellow, are a tempering staple, popped in hot oil at the start of countless recipes.","Sarson ka saag, made from mustard greens rather than the seed or oil, is a separate but related dish from the same plant family.","Across all of these, heating mustard oil to a light smoke before cooking is the one technique step worth remembering regardless of dish."]}},{"id":"blk_article_106_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Mustard oil for sarson cooking","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_106_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sarson cooking questions","items":[{"question":"Is sarson ka saag made with mustard oil?","answer":"It is traditionally cooked in mustard oil, though the dish itself is named for mustard greens, a separate part of the plant."},{"question":"Do you sell mustard greens or mustard seeds directly?","answer":"We press mustard seeds into black and yellow mustard oil rather than selling greens or loose seed."},{"question":"Is sarson always mustard, or sometimes something else?","answer":"In Indian cooking, sarson consistently refers to mustard, whether the seed, the oil or the greens depending on context."},{"question":"What is the one technique that matters across sarson dishes?","answer":"Heating mustard oil to a light smoke before cooking, which mellows its raw pungency across nearly every traditional use."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Sarson means mustard in Hindi, covering the oil, the seed and the greens. A practical overview of how each is used.', seo_description='A guide to sarson in Indian cooking: mustard oil, mustard seeds and mustard greens, and how each is traditionally used.', seo_keywords='sarson, mustard in Indian cooking, sarson guide', reading_minutes=3, published_version_id='arv_truegrit_106_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_106';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_106';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_106','Sarson-Based Indian Cooking Guide','sarson-based-indian-cooking-guide','Sarson means mustard in Hindi, covering the oil, the seed and the greens. A practical overview of how each is used.','sarson, mustard in Indian cooking, sarson guide');

-- 107. What Are Flax Seeds?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_107_2','art_truegrit_107',2,'{"blocks":[{"id":"blk_article_107_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flax seeds are a small oilseed, called alsi in Hindi, that shows up in Indian kitchens whole, ground into a coarse meal, or pressed into oil. Each form behaves differently, which is why the same seed appears across such different recipes."]}},{"id":"blk_article_107_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines them","items":["A small, flat oilseed with a hard outer shell, sold whole, roasted, or pressed into oil.","Known as alsi in Hindi and widely used across regional Indian cooking, from chutneys to a simple roasted snack.","Whole seeds pass through digestion largely intact unless chewed thoroughly or ground first, which is why grinding is common.","Higher in oil content than most pulses, which is what makes pressing them into oil possible in the first place.","Comes in golden and brown colour varieties, which differ mainly in appearance rather than in how they are used."]}},{"id":"blk_article_107_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax to try","source":"manual","productSlugs":["plain-flax-seed","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_107_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flax seed questions","items":[{"question":"Is alsi the same as flax seed?","answer":"Yes, alsi is simply the Hindi name for flax seed, the same seed sold under either term."},{"question":"Do flax seeds need to be ground before eating?","answer":"Grinding is common since whole seeds can pass through digestion largely intact, but they can also be eaten whole, especially roasted."},{"question":"Are flax seeds a traditional Indian ingredient?","answer":"Yes, particularly in Maharashtrian cooking, where roasted and ground flax appears in chutneys and everyday condiments."},{"question":"Can flax seeds be pressed into oil at home?","answer":"Not practically. Oil pressing needs equipment beyond a home kitchen, which is why pressed flaxseed oil is bought rather than made at home."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A small oilseed, known as alsi in Hindi, eaten whole, ground or pressed into oil across Indian and international kitchens.', seo_description='Flax seeds explained: what they are, how they are eaten, and the difference between whole, ground and pressed forms.', seo_keywords='flax seeds, alsi seeds, what are flax seeds', reading_minutes=3, published_version_id='arv_truegrit_107_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_107';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_107';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_107','What Are Flax Seeds?','what-are-flax-seeds','A small oilseed, known as alsi in Hindi, eaten whole, ground or pressed into oil across Indian and international kitchens.','flax seeds, alsi seeds, what are flax seeds');

-- 108. Flaxseed vs Linseed: Are They the Same Thing?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_108_2','art_truegrit_108',2,'{"blocks":[{"id":"blk_article_108_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flaxseed and linseed are the same seed from the same plant. The difference is entirely in which word gets used in which context, not in what is actually inside the packet."]}},{"id":"blk_article_108_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually know","items":["Flaxseed and linseed both refer to the seed of the same plant, used interchangeably depending on regional and industry context.","Linseed oil sold for wood finishing and industrial use is a separate, non food grade product, not something to confuse with edible flaxseed oil.","Food grade flaxseed oil and edible flax seed are always clearly labelled for eating, distinct from any industrial linseed product.","The word flaxseed is more common in food and health contexts, while linseed appears more in older or industrial usage.","When buying oil specifically, check that it is labelled edible or food grade rather than assuming from the name alone."]}},{"id":"blk_article_108_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Edible flax","source":"manual","productSlugs":["plain-flax-seed","linseed-flax-seed-oil"],"limit":2}},{"id":"blk_article_108_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed and linseed questions","items":[{"question":"Is linseed oil from the hardware store the same as flaxseed oil?","answer":"No. Industrial linseed oil is processed differently and is not food safe. Always buy oil clearly labelled as edible or food grade."},{"question":"Why does this seed have two names?","answer":"Mostly regional and historical naming. Linseed is the older term, flaxseed became more common in food and health contexts."},{"question":"Does our product use one term or the other?","answer":"We use flax and linseed somewhat interchangeably in naming, but always as the edible, food grade seed and oil."},{"question":"Is there a nutritional difference between the two names?","answer":"No, since they refer to the same edible seed. Any difference is in processing and intended use, not the seed itself."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Yes, the same seed under two names, with the word you hear depending mostly on context rather than the product itself.', seo_description='Flaxseed and linseed compared: same seed, different naming context, and what to check when buying either.', seo_keywords='flaxseed vs linseed, is linseed the same as flaxseed', reading_minutes=2, published_version_id='arv_truegrit_108_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_108';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_108';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_108','Flaxseed vs Linseed: Are They the Same Thing?','flaxseed-vs-linseed-are-they-the-same-thing','Yes, the same seed under two names, with the word you hear depending mostly on context rather than the product itself.','flaxseed vs linseed, is linseed the same as flaxseed');

-- 109. Golden vs Brown Flax Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_109_2','art_truegrit_109',2,'{"blocks":[{"id":"blk_article_109_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Golden and brown flax seeds come from closely related varieties of the same plant, and the difference between them is mostly visual rather than something that changes how you cook with them."]}},{"id":"blk_article_109_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Colour is the main visible difference, golden flax runs pale yellow, brown flax a deeper reddish brown.","Flavour is broadly similar between the two, though some people describe golden flax as very slightly milder.","Brown flax is more widely available and more commonly used in Indian cooking traditions like roasted chutneys.","Both can be used whole, roasted or ground the same way, with no meaningful difference in how they behave in a recipe.","Neither variety has a verified nutritional advantage over the other worth basing a buying decision on."]}},{"id":"blk_article_109_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax seed","source":"manual","productSlugs":["plain-flax-seed"],"limit":1}},{"id":"blk_article_109_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Golden vs brown flax questions","items":[{"question":"Which flax seed do you sell?","answer":"Check the current product listing for the specific variety in stock. Both golden and brown behave the same way in cooking."},{"question":"Does the colour affect how flax seed is used in recipes?","answer":"No, whole, roasted or ground flax works the same regardless of whether it started golden or brown."},{"question":"Is golden flax more expensive than brown?","answer":"Pricing varies by availability and season more than by any inherent difference in quality between the two."},{"question":"Can golden and brown flax be swapped freely in a recipe?","answer":"Yes, they substitute directly for each other with no adjustment needed."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Mainly a colour difference. What actually changes, and what stays the same, between the two.', seo_description='Golden flax seeds compared with brown: colour, flavour, and whether the difference matters when cooking with either.', seo_keywords='golden flax seeds vs brown flax seeds', reading_minutes=2, published_version_id='arv_truegrit_109_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_109';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_109';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_109','Golden vs Brown Flax Seeds','golden-vs-brown-flax-seeds','Mainly a colour difference. What actually changes, and what stays the same, between the two.','golden flax seeds vs brown flax seeds');

-- 110. Roasted vs Raw Flax Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_110_2','art_truegrit_110',2,'{"blocks":[{"id":"blk_article_110_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Roasting flax seed changes its flavour and how easily it grinds, without changing what the seed fundamentally is. Both raw and roasted have a place in the kitchen, just for slightly different uses."]}},{"id":"blk_article_110_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Roasted flax seed has a noticeably nuttier, more developed flavour than raw, which is why it is common in ready to eat chutneys and snacks.","Raw flax seed has a more neutral taste, useful when you want flax added without changing a dish''s existing flavour much.","Roasting can make the seed slightly easier to grind evenly, since the shell softens a little under heat.","Both need grinding for the body to access the seed''s contents more fully. Whole seed, roasted or raw, largely passes through digestion intact.","Roasted flax keeps a little longer than raw before the flavour starts to fade, though both should be stored airtight either way."]}},{"id":"blk_article_110_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Raw and roasted flax","source":"manual","productSlugs":["plain-flax-seed","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_110_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Roasted vs raw flax questions","items":[{"question":"Is roasted flax seed healthier than raw?","answer":"Neither has a verified advantage over the other nutritionally. Roasting mainly changes flavour and grinding ease."},{"question":"Can I roast raw flax seed myself?","answer":"Yes, a dry pan on low to medium heat, stirred frequently until aromatic, works well at home."},{"question":"Does roasting reduce the seed''s oil content?","answer":"Roasting can cause a small amount of oil loss through evaporation, though the difference is minor at home roasting temperatures."},{"question":"Which is better for a chutney?","answer":"Roasted, since its more developed flavour suits a chutney better than the more neutral taste of raw flax."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Roasting changes flavour and ease of grinding more than it changes what the seed fundamentally is.', seo_description='Roasted flax seeds compared with raw: flavour, grinding ease, and which suits which use.', seo_keywords='roasted flax seeds vs raw flax seeds', reading_minutes=2, published_version_id='arv_truegrit_110_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_110';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_110';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_110','Roasted vs Raw Flax Seeds','roasted-vs-raw-flax-seeds','Roasting changes flavour and ease of grinding more than it changes what the seed fundamentally is.','roasted flax seeds vs raw flax seeds');

-- 111. Flax Seeds vs Chia Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_111_2','art_truegrit_111',2,'{"blocks":[{"id":"blk_article_111_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flax and chia are both small seeds that get grouped together in health food conversations, but they behave quite differently once they actually meet liquid or a mixing bowl."]}},{"id":"blk_article_111_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Chia seeds form a gel almost immediately when soaked in liquid. Flax seeds do not gel the same way and need grinding to be used similarly.","Whole flax generally needs grinding for the body to access its contents fully. Whole chia does not, since its soft shell breaks down on its own.","Ground flax has a flour like consistency useful in baking. Chia keeps its distinct small seed texture even when soaked into a pudding.","Both come from entirely different plants, flax from the flax plant, chia from a mint family plant native to Central America.","Neither is simply the better seed. The choice depends on whether you want a gelling texture or a ground, flour like one."]}},{"id":"blk_article_111_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax to try","source":"manual","productSlugs":["plain-flax-seed","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_111_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flax vs chia questions","items":[{"question":"Can flax seed replace chia in a pudding recipe?","answer":"Not directly. Chia''s gelling texture comes from a soft shell flax does not have, so the result will not match."},{"question":"Does flax seed need grinding but chia does not?","answer":"Generally yes, whole flax is harder to digest without grinding, while chia''s soft shell breaks down on its own in liquid."},{"question":"Are flax and chia related plants?","answer":"No, they come from entirely different plant families and only get grouped together because of shared culinary uses."},{"question":"Which is more commonly used in Indian cooking?","answer":"Flax, particularly in Maharashtrian roasted chutneys, has a longer standing place in Indian kitchens than chia."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Both are small seeds valued for fibre and oil content, but they behave very differently once they meet liquid.', seo_description='Flax seeds compared with chia seeds: grinding needs, gelling behaviour, and which suits which recipe.', seo_keywords='flax seeds vs chia seeds', reading_minutes=3, published_version_id='arv_truegrit_111_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_111';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_111';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_111','Flax Seeds vs Chia Seeds','flax-seeds-vs-chia-seeds','Both are small seeds valued for fibre and oil content, but they behave very differently once they meet liquid.','flax seeds vs chia seeds');

-- 112. Flax Seeds vs Sesame Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_112_2','art_truegrit_112',2,'{"blocks":[{"id":"blk_article_112_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flax and sesame are both small oilseeds, but they occupy very different places in Indian cooking. Sesame has centuries of central culinary use behind it. Flax is a comparatively newer, more supplementary addition."]}},{"id":"blk_article_112_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Sesame has a long, central role in Indian sweets, tempering and festival foods. Flax is more often added for its oil content in smaller quantities.","Flavour differs too, sesame has a distinct, slightly sweet nuttiness, while flax tastes milder raw and nuttier once roasted.","Sesame is more commonly pressed into a cooking oil used across whole regions. Flaxseed oil is used more as a small quantity finishing oil.","Both need some processing, roasting or grinding, to bring out their full flavour and make their contents more accessible.","Neither replaces the other in a recipe built around its specific role, so they are worth keeping as separate pantry items."]}},{"id":"blk_article_112_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax seed","source":"manual","productSlugs":["plain-flax-seed","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_112_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flax vs sesame questions","items":[{"question":"Can I substitute flax for sesame in a recipe?","answer":"Not directly. The flavour and traditional role of each differ enough that the dish will not taste as intended."},{"question":"Which has more oil, flax or sesame?","answer":"Both are oil rich seeds, and both are pressed into cooking oils, though they are used differently once pressed."},{"question":"Is sesame more traditional in Indian cooking than flax?","answer":"Yes, sesame has a much longer, more central history in Indian cuisine, particularly in sweets and festival foods."},{"question":"Can flax and sesame be used together?","answer":"Yes, many chutneys and toppings combine both for a mix of flavours and textures."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Different oil content and a very different place in Indian cooking history.', seo_description='Flax seeds compared with sesame seeds: flavour, traditional culinary role, and how each is typically used.', seo_keywords='flax seeds vs sesame seeds', reading_minutes=2, published_version_id='arv_truegrit_112_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_112';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_112';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_112','Flax Seeds vs Sesame Seeds','flax-seeds-vs-sesame-seeds','Different oil content and a very different place in Indian cooking history.','flax seeds vs sesame seeds');

-- 113. What Is Flaxseed Oil?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_113_2','art_truegrit_113',2,'{"blocks":[{"id":"blk_article_113_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flaxseed oil is pressed from flax seeds and used almost entirely raw, stirred into a finished dish or drizzled over one rather than heated in a pan. That single fact shapes how it is bought, stored and used."]}},{"id":"blk_article_113_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Pressed from flax seeds, almost always cold pressed since heat degrades the oil''s delicate fat content.","Used raw, stirred into dal or a finished curry once the flame is off, or drizzled over salads and vegetables.","Not intended for cooking with heat. Its low smoke point and sensitive fat profile break down quickly under a flame.","Has a distinct, slightly grassy, nutty flavour, noticeably different from a neutral cooking oil.","Needs more careful storage than most cooking oils, ideally refrigerated after opening to slow it going off."]}},{"id":"blk_article_113_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flaxseed oil","source":"manual","productSlugs":["linseed-flax-seed-oil"],"limit":1}},{"id":"blk_article_113_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed oil questions","items":[{"question":"Can flaxseed oil be used for frying?","answer":"No, its low smoke point and sensitive fat content mean it is not suited to cooking with heat."},{"question":"How is flaxseed oil best used?","answer":"Stirred into a dish after cooking, or drizzled over salads and vegetables, always added raw rather than heated."},{"question":"Does flaxseed oil taste like a neutral cooking oil?","answer":"No, it has a distinct, slightly grassy, nutty flavour that comes through noticeably in whatever it is added to."},{"question":"Why does flaxseed oil need refrigeration?","answer":"Its fat content is more prone to going rancid than a typical cooking oil, so cold storage slows that process."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='An oil pressed from flax seeds, valued raw for its flavour and fat content, not intended for cooking with heat.', seo_description='Flaxseed oil explained: how it is pressed, its distinct flavour, and why it is used raw rather than for cooking.', seo_keywords='flaxseed oil, what is flaxseed oil, linseed oil edible', reading_minutes=3, published_version_id='arv_truegrit_113_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_113';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_113';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_113','What Is Flaxseed Oil?','what-is-flaxseed-oil','An oil pressed from flax seeds, valued raw for its flavour and fat content, not intended for cooking with heat.','flaxseed oil, what is flaxseed oil, linseed oil edible');

-- 114. How Is Flaxseed Oil Made?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_114_2','art_truegrit_114',2,'{"blocks":[{"id":"blk_article_114_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flaxseed oil is made by cold pressing cleaned flax seeds, a method chosen here almost without exception, since heat is exactly what damages the delicate fat content the oil is valued for in the first place."]}},{"id":"blk_article_114_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The steps","items":["Flax seeds are cleaned and fed into a mechanical press that extracts the oil using pressure rather than added heat.","The oil is filtered to remove solid particles, though it is generally not refined the way many cooking oils are.","Kept away from heat and light throughout processing and bottling, since both accelerate the oil''s natural tendency to go rancid.","Bottled promptly after pressing rather than held in bulk storage for long periods, to preserve freshness as much as possible.","The seeds themselves are cleaned before pressing to remove dust and any damaged seed that could affect the oil''s flavour."]}},{"id":"blk_article_114_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flaxseed oil","source":"manual","productSlugs":["linseed-flax-seed-oil"],"limit":1}},{"id":"blk_article_114_4","type":"faq","version":1,"enabled":true,"props":{"heading":"How flaxseed oil is made, answered","items":[{"question":"Is flaxseed oil ever made with heat?","answer":"Rarely for food grade oil. Heat damages the fat content, so cold pressing is the standard method."},{"question":"Is flaxseed oil refined like some cooking oils?","answer":"Generally no, it is filtered to remove solids but not chemically refined the way many neutral cooking oils are."},{"question":"Why is freshness emphasised so much for flaxseed oil?","answer":"Its fat content degrades faster than more stable oils, so time between pressing and use matters more here."},{"question":"Does the pressing method affect flavour?","answer":"Yes, cold pressing preserves more of the natural flavour and nutrient content than heat based extraction would."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Cold pressed almost without exception, since heat is exactly what damages the oil this seed is valued for.', seo_description='How flaxseed oil is made: cold pressing, filtering, and why heat is avoided throughout the process.', seo_keywords='how flaxseed oil is made, flaxseed oil pressing process', reading_minutes=2, published_version_id='arv_truegrit_114_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_114';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_114';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_114','How Is Flaxseed Oil Made?','how-is-flaxseed-oil-made','Cold pressed almost without exception, since heat is exactly what damages the oil this seed is valued for.','how flaxseed oil is made, flaxseed oil pressing process');

-- 115. Cold-Pressed Flaxseed Oil Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_115_2','art_truegrit_115',2,'{"blocks":[{"id":"blk_article_115_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["With mustard or sesame oil, cold pressing is a meaningful choice between two legitimate options. With flaxseed oil, it is closer to the only sensible method, since heat damages exactly what the oil is valued for."]}},{"id":"blk_article_115_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why it matters here specifically","items":["Cold pressing extracts the oil mechanically with no added heat, preserving the delicate fat content that heat would otherwise break down.","Unlike mustard oil, where cold pressed is one option among several, flaxseed oil is almost always cold pressed for food use.","The trade off is a shorter shelf life and the need for careful, cold storage compared to a more heavily processed oil.","This is also why flaxseed oil is used raw rather than for cooking, the same fat content that makes cold pressing necessary is sensitive to cooking heat too."]}},{"id":"blk_article_115_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Cold-pressed flaxseed oil","source":"manual","productSlugs":["linseed-flax-seed-oil"],"limit":1}},{"id":"blk_article_115_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Cold-pressed flaxseed oil questions","items":[{"question":"Is there a non cold-pressed flaxseed oil worth buying?","answer":"Not really for food use. Cold pressing is the standard method precisely because heat damages the oil''s valued fat content."},{"question":"Does cold-pressed flaxseed oil cost more?","answer":"Generally yes, cold pressing extracts less oil per seed and requires more careful handling throughout."},{"question":"How is this different from cold-pressed mustard oil?","answer":"Mustard oil has a refined alternative that is genuinely usable for cooking. Flaxseed oil''s whole point is staying unheated, both before and after bottling."},{"question":"Does cold pressing affect how long the oil lasts?","answer":"It affects quality more than shelf life directly, though proper cold storage after opening matters more for flaxseed oil than most others."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Not a premium choice here so much as the only sensible one, since heat damages what the oil is valued for.', seo_description='Cold-pressed flaxseed oil explained: why the method matters more here than with most other cooking oils.', seo_keywords='cold pressed flaxseed oil, cold pressed linseed oil', reading_minutes=2, published_version_id='arv_truegrit_115_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_115';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_115';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_115','Cold-Pressed Flaxseed Oil Explained','cold-pressed-flaxseed-oil-explained','Not a premium choice here so much as the only sensible one, since heat damages what the oil is valued for.','cold pressed flaxseed oil, cold pressed linseed oil');

-- 116. Flaxseed Oil vs Mustard Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_116_2','art_truegrit_116',2,'{"blocks":[{"id":"blk_article_116_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flaxseed oil and mustard oil rarely compete for the same job in a kitchen. Mustard oil is a genuine cooking oil that handles real heat. Flaxseed oil is strictly a raw, finishing one."]}},{"id":"blk_article_116_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Mustard oil can be heated for cooking and tempering. Flaxseed oil cannot, its fat content breaks down under heat.","Flavour differs sharply too, mustard oil is pungent and assertive, flaxseed oil is grassy and nutty in a much quieter way.","Mustard oil is used across an entire dish''s cooking process. Flaxseed oil is added in small amounts, always after cooking is done.","Both are valued oils in their own category, so the comparison is really about role rather than one being generally better.","Storage needs differ too, mustard oil tolerates a pantry shelf, while flaxseed oil generally does better refrigerated once opened."]}},{"id":"blk_article_116_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Both oils","source":"manual","productSlugs":["linseed-flax-seed-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_116_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed vs mustard oil questions","items":[{"question":"Can I use flaxseed oil where a recipe calls for mustard oil?","answer":"No, mustard oil is used for cooking with heat, which flaxseed oil cannot handle without breaking down."},{"question":"Do they taste similar?","answer":"No, mustard oil is pungent and sharp, flaxseed oil is milder and grassy. They serve very different flavour roles."},{"question":"Can both be used in the same dish?","answer":"Yes, mustard oil for cooking and a small drizzle of flaxseed oil added at the end are not mutually exclusive."},{"question":"Which has a stronger smell?","answer":"Mustard oil, noticeably, especially the cold-pressed unrefined kind, which is far more pungent than flaxseed oil."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One is a raw finishing oil, the other a cooking oil that can take real heat. Different roles entirely.', seo_description='Flaxseed oil compared with mustard oil: heat tolerance, flavour, and which role each plays in the kitchen.', seo_keywords='flaxseed oil vs mustard oil', reading_minutes=2, published_version_id='arv_truegrit_116_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_116';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_116';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_116','Flaxseed Oil vs Mustard Oil','flaxseed-oil-vs-mustard-oil','One is a raw finishing oil, the other a cooking oil that can take real heat. Different roles entirely.','flaxseed oil vs mustard oil');

-- 117. Flaxseed Oil vs Sesame Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_117_2','art_truegrit_117',2,'{"blocks":[{"id":"blk_article_117_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame oil sits in a middle ground that flaxseed oil does not share. Some sesame oil can handle real cooking heat, while flaxseed oil stays strictly a raw, finishing ingredient regardless of grade."]}},{"id":"blk_article_117_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Some sesame oil, particularly a lighter refined grade, can be used for tempering and light cooking. Flaxseed oil cannot be heated at all.","Toasted or cold-pressed sesame oil is more often used as a finishing oil too, closer to how flaxseed oil is always used.","Flavour differs distinctly, sesame oil brings a warm, toasted nuttiness, flaxseed oil a milder, grassier note.","Both need careful storage, though flaxseed oil is generally the more sensitive of the two to heat and light exposure.","Sesame oil has a longer, more central history in Indian cooking overall, while flaxseed oil remains more of a modern addition."]}},{"id":"blk_article_117_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Both oils","source":"manual","productSlugs":["linseed-flax-seed-oil","sesame-oil"],"limit":2}},{"id":"blk_article_117_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed vs sesame oil questions","items":[{"question":"Can sesame oil handle more heat than flaxseed oil?","answer":"Yes, a lighter refined sesame oil can be used for tempering, while flaxseed oil should never be heated."},{"question":"Are both used as finishing oils?","answer":"Yes, cold-pressed or toasted sesame oil and flaxseed oil are both commonly drizzled over a finished dish rather than heated."},{"question":"Which has the stronger flavour?","answer":"Sesame oil generally, with its warm, toasted character. Flaxseed oil is milder and more subtly grassy."},{"question":"Can I substitute one for the other as a finishing oil?","answer":"You can, though expect a noticeably different flavour, toasted nuttiness against a milder grassy note."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Sesame oil bridges cooking and finishing uses. Flaxseed oil stays firmly on the finishing side only.', seo_description='Flaxseed oil compared with sesame oil: heat tolerance, flavour, and where each fits in Indian cooking.', seo_keywords='flaxseed oil vs sesame oil', reading_minutes=2, published_version_id='arv_truegrit_117_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_117';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_117';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_117','Flaxseed Oil vs Sesame Oil','flaxseed-oil-vs-sesame-oil','Sesame oil bridges cooking and finishing uses. Flaxseed oil stays firmly on the finishing side only.','flaxseed oil vs sesame oil');

-- 118. How to Use Flaxseed Oil in Food
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_118_2','art_truegrit_118',2,'{"blocks":[{"id":"blk_article_118_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flaxseed oil earns its place in a finished dish, not a hot pan. A small amount stirred in at the very end is enough to bring its flavour and fat content without the oil ever touching direct heat."]}},{"id":"blk_article_118_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Ways to use it","items":["Drizzled over a salad as part of the dressing, where its grassy flavour pairs well with lemon or vinegar.","Stirred into dal or a curry after the flame is off, once the dish has finished cooking and cooled slightly.","Blended into a smoothie, where its flavour is mild enough to disappear into fruit and vegetables.","Mixed into raita or yoghurt as a small addition, adding fat content without changing the texture much.","Added straight to a bowl of daliya or oats once cooked, stirred through at the table rather than during cooking."]}},{"id":"blk_article_118_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One household describes exactly this pattern, salads and dal stirred in after cooking, and asks what else people actually do with a bottle](/community/dsc_truegrit_018), worth a read for more ideas."]}},{"id":"blk_article_118_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flaxseed oil","source":"manual","productSlugs":["linseed-flax-seed-oil"],"limit":1}},{"id":"blk_article_118_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Using flaxseed oil questions","items":[{"question":"Can flaxseed oil go into a hot dish at all?","answer":"Only after the dish has finished cooking and the direct heat is off, stirred in rather than heated with the rest of the ingredients."},{"question":"How much flaxseed oil should I add to a dish?","answer":"A small amount, roughly a teaspoon per serving, is enough to add its flavour without overwhelming the dish."},{"question":"Does flaxseed oil work in baking?","answer":"It can be added to no bake preparations, but avoid using it anywhere the batter or dough will be baked with heat."},{"question":"Can I use flaxseed oil daily?","answer":"Many households do, in small quantities across meals, though how much to use is a personal choice rather than a fixed rule."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Added raw, after the cooking is done, in small quantities rather than as a base cooking oil.', seo_description='How to use flaxseed oil in cooking: salads, dal, smoothies and other ways to add it without heating it.', seo_keywords='how to use flaxseed oil, flaxseed oil in food', reading_minutes=2, published_version_id='arv_truegrit_118_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_118';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_118';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_118','How to Use Flaxseed Oil in Food','how-to-use-flaxseed-oil-in-food','Added raw, after the cooking is done, in small quantities rather than as a base cooking oil.','how to use flaxseed oil, flaxseed oil in food');

-- 119. Can Flaxseed Oil Be Used for High-Heat Cooking?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_119_2','art_truegrit_119',2,'{"blocks":[{"id":"blk_article_119_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["No. Flaxseed oil is not suited to high heat cooking, and this is not a minor preference. Its low smoke point and sensitive fat content mean heat is the one thing this particular oil should never be exposed to."]}},{"id":"blk_article_119_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why the answer is no","items":["Flaxseed oil has a low smoke point, meaning it starts breaking down at temperatures a normal frying or tempering process easily reaches.","Heat damages the delicate fat content that makes flaxseed oil worth buying in the first place, defeating the point of using it.","Heated flaxseed oil can also develop an unpleasant, bitter flavour rather than simply losing potency quietly.","For any dish that needs heat, use mustard, sesame or another cooking oil, and add flaxseed oil afterward if wanted.","This is a consistent rule across brands and grades, not something a particular pressing method changes."]}},{"id":"blk_article_119_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"For raw use only","source":"manual","productSlugs":["linseed-flax-seed-oil"],"limit":1}},{"id":"blk_article_119_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed oil and heat questions","items":[{"question":"What happens if I accidentally heat flaxseed oil?","answer":"It is not dangerous, but it loses much of its value and can taste noticeably bitter. It is best not used for that dish''s cooking."},{"question":"Is there a version of flaxseed oil made for cooking?","answer":"Not really, food grade flaxseed oil is consistently intended for raw use rather than heat based cooking."},{"question":"What oil should I use instead for frying?","answer":"Mustard oil, sesame oil or another oil rated for cooking, adding flaxseed oil separately once the dish is off the heat."},{"question":"Does a small amount of heat matter, like a warm dish?","answer":"A gently warm dish is generally fine. It is direct cooking heat, frying or tempering, that causes the real breakdown."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='No. Its low smoke point and sensitive fat content make heat the one thing this oil should never see.', seo_description='Can flaxseed oil be used for high heat cooking: why the answer is no, and what heat actually does to the oil.', seo_keywords='flaxseed oil high heat cooking, can you cook with flaxseed oil', reading_minutes=2, published_version_id='arv_truegrit_119_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_119';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_119';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_119','Can Flaxseed Oil Be Used for High-Heat Cooking?','can-flaxseed-oil-be-used-for-high-heat-cooking','No. Its low smoke point and sensitive fat content make heat the one thing this oil should never see.','flaxseed oil high heat cooking, can you cook with flaxseed oil');

-- 120. How to Store Flaxseed Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_120_2','art_truegrit_120',2,'{"blocks":[{"id":"blk_article_120_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flaxseed oil needs more careful storage than a typical cooking oil, and refrigeration after opening is the single biggest thing that actually helps it stay fresh."]}},{"id":"blk_article_120_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Refrigerate after opening. This slows the oxidation that flaxseed oil is naturally more prone to than most cooking oils.","Keep it in a dark bottle or away from light even before opening, since light exposure accelerates the same breakdown.","Buy in a quantity you will realistically use within a couple of months, rather than a large bottle that sits open for a long time.","Seal the bottle tightly after each use rather than leaving it loosely capped between uses.","Trust smell and taste over a printed date. Flaxseed oil that has gone off smells distinctly different from fresh."]}},{"id":"blk_article_120_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flaxseed oil","source":"manual","productSlugs":["linseed-flax-seed-oil"],"limit":1}},{"id":"blk_article_120_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed oil storage questions","items":[{"question":"Does flaxseed oil really need refrigeration?","answer":"Yes, more than most cooking oils. Its fat content is more prone to oxidation, and cold storage slows that noticeably."},{"question":"How long does flaxseed oil last once opened?","answer":"A couple of months refrigerated is a reasonable expectation, sooner if it is stored at room temperature instead."},{"question":"Can unopened flaxseed oil be kept at room temperature?","answer":"A cool, dark pantry works for an unopened bottle, though refrigeration is still the safer choice if you have the space."},{"question":"How do I know if flaxseed oil has gone rancid?","answer":"A sharp, unpleasant or bitter smell replacing the usual mild, grassy one is the clearest sign."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='More careful than most cooking oils. Refrigeration after opening is the single biggest thing that helps.', seo_description='How to store flaxseed oil properly: refrigeration, light exposure, and how long it stays good once opened.', seo_keywords='how to store flaxseed oil, flaxseed oil storage', reading_minutes=2, published_version_id='arv_truegrit_120_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_120';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_120';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_120','How to Store Flaxseed Oil','how-to-store-flaxseed-oil','More careful than most cooking oils. Refrigeration after opening is the single biggest thing that helps.','how to store flaxseed oil, flaxseed oil storage');

-- 121. Why Flaxseed Oil Needs Careful Storage
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_121_2','art_truegrit_121',2,'{"blocks":[{"id":"blk_article_121_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flaxseed oil''s reputation for needing careful storage is not exaggerated. The same fat content that makes the oil worth buying is also, chemically, more eager to react with air, light and heat than a typical cooking oil''s fat content is."]}},{"id":"blk_article_121_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What is actually happening","items":["Flaxseed oil''s fat content is more chemically reactive than the fat in many other cooking oils, making it break down faster once exposed to air.","Light exposure speeds this same breakdown, which is why flaxseed oil is often sold in a dark bottle.","Heat accelerates it further still, which is the same underlying reason flaxseed oil is never used for cooking.","None of this makes the oil unsafe to buy or use, it simply means the storage window between opening and finishing the bottle should be shorter."]}},{"id":"blk_article_121_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flaxseed oil","source":"manual","productSlugs":["linseed-flax-seed-oil"],"limit":1}},{"id":"blk_article_121_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed oil sensitivity questions","items":[{"question":"Is flaxseed oil unusually fragile compared to other oils?","answer":"Yes, its particular fat content is more reactive to air, light and heat than most common cooking oils."},{"question":"Does this mean flaxseed oil is a lower quality product?","answer":"No, it is simply a property of the oil itself, which is why it needs different storage habits than a typical cooking oil."},{"question":"Does buying a smaller bottle help?","answer":"Yes, finishing a smaller bottle faster reduces the time it spends exposed to air after opening."},{"question":"Is this the same reason it cannot be heated?","answer":"Yes, the same reactive fat content that needs careful storage is what breaks down under cooking heat."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same fat content that makes it valuable also makes it chemically eager to break down.', seo_description='Why flaxseed oil needs more careful storage than most cooking oils, and what is actually happening chemically.', seo_keywords='why flaxseed oil goes rancid, flaxseed oil sensitive to storage', reading_minutes=2, published_version_id='arv_truegrit_121_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_121';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_121';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_121','Why Flaxseed Oil Needs Careful Storage','why-flaxseed-oil-needs-careful-storage','The same fat content that makes it valuable also makes it chemically eager to break down.','why flaxseed oil goes rancid, flaxseed oil sensitive to storage');

-- 122. Whole vs Ground Flax Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_122_2','art_truegrit_122',2,'{"blocks":[{"id":"blk_article_122_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole and ground flax seed are the same seed at two different stages, and the difference between them matters more than it does with many other seeds, since whole flax largely passes through digestion unchanged."]}},{"id":"blk_article_122_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Whole flax seed has a hard outer shell that mostly resists digestion unless chewed very thoroughly or ground beforehand.","Ground flax makes the seed''s contents more accessible, which is why grinding is commonly recommended over eating whole seed.","Ground flax oxidises faster than whole seed once exposed to air, so it benefits from being ground closer to when it will be used.","Whole flax seed keeps longer in storage than ground, since the shell protects the contents from air and light.","Roasted whole seed sits between the two, offering some of ground flax''s easier texture while still keeping reasonably well."]}},{"id":"blk_article_122_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole and ready to grind","source":"manual","productSlugs":["plain-flax-seed","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_122_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole vs ground flax questions","items":[{"question":"Should I always grind flax seed before eating it?","answer":"It is generally recommended for accessing the seed''s full contents, though whole roasted seed still has real value eaten as is."},{"question":"Does ground flax lose value quickly?","answer":"It oxidises faster than whole seed, so grinding smaller batches more often keeps it fresher than grinding a large amount at once."},{"question":"Can I buy flax seed already ground?","answer":"We sell whole seed, plain and roasted, which you can grind at home in the quantity you need."},{"question":"Is roasted whole flax easier to digest than raw whole flax?","answer":"It can be slightly easier to chew and break down, though grinding still makes the biggest practical difference."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Grinding is what actually makes flax seed''s contents accessible. Whole seed largely passes through unchanged.', seo_description='Whole flax seeds compared with ground: digestion, freshness, and why grinding is generally recommended.', seo_keywords='whole flax seeds vs ground flax seeds', reading_minutes=2, published_version_id='arv_truegrit_122_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_122';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_122';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_122','Whole vs Ground Flax Seeds','whole-vs-ground-flax-seeds','Grinding is what actually makes flax seed''s contents accessible. Whole seed largely passes through unchanged.','whole flax seeds vs ground flax seeds');

-- 123. How to Grind Flax Seeds at Home
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_123_2','art_truegrit_123',2,'{"blocks":[{"id":"blk_article_123_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Grinding flax seed at home needs no special equipment, just a small grinder and a habit of doing it in small batches, since ground flax does not keep as well as the whole seed does."]}},{"id":"blk_article_123_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to do it","items":["A small coffee or spice grinder works well for flax seed, pulsed in short bursts rather than run continuously.","Grind only what you expect to use within a week or two, since ground flax oxidises faster than whole seed.","Store the ground portion in an airtight container, ideally refrigerated, to slow that process further.","A mortar and pestle works for small amounts if you do not have a grinder, though the result will be less uniform.","Roasted seed grinds a little more easily than raw, if you have the choice and want a smoother result."]}},{"id":"blk_article_123_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One household compares whether roasted or plain seed keeps longer once ground in small batches](/community/dsc_truegrit_020), useful if you are deciding which to keep on hand for grinding."]}},{"id":"blk_article_123_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax seed to grind","source":"manual","productSlugs":["plain-flax-seed","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_123_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Grinding flax questions","items":[{"question":"Can I use a regular blender to grind flax seed?","answer":"A small dedicated grinder works better for a small quantity. A large blender can struggle to grind a small amount evenly."},{"question":"How much flax seed should I grind at once?","answer":"Enough for a week or two of use is a reasonable batch size, balancing convenience against freshness."},{"question":"Does grinding release the oil inside the seed?","answer":"It exposes it to air, which is part of why ground flax should be stored carefully and used relatively soon."},{"question":"Is store bought ground flax as good as home ground?","answer":"Home ground in small batches is generally fresher, since you control exactly when the grinding happens."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A small coffee or spice grinder, in small batches, ground close to when you will actually use it.', seo_description='How to grind flax seeds at home: equipment, batch size and storage tips for fresher ground flax.', seo_keywords='how to grind flax seeds, grinding flax at home', reading_minutes=2, published_version_id='arv_truegrit_123_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_123';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_123';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_123','How to Grind Flax Seeds at Home','how-to-grind-flax-seeds-at-home','A small coffee or spice grinder, in small batches, ground close to when you will actually use it.','how to grind flax seeds, grinding flax at home');

-- 124. How to Roast Flax Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_124_2','art_truegrit_124',2,'{"blocks":[{"id":"blk_article_124_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Roasting flax seed at home takes a few minutes and no special equipment, just a dry pan and attention, since flax can move from perfectly roasted to burnt faster than you might expect."]}},{"id":"blk_article_124_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to do it","items":["Use a dry pan on low to medium heat, with no oil added, since the seeds already carry enough of their own.","Add the seeds in a thin, even layer rather than a deep pile, so they roast evenly rather than in patches.","Stir or toss frequently, since flax can go from fragrant to burnt quickly once it starts to colour.","Roast until you can smell a distinct nutty aroma and hear a faint popping sound from some seeds.","Cool completely on a plate before storing or grinding, since seeds continue cooking slightly from residual heat if left in the hot pan."]}},{"id":"blk_article_124_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax seed to roast","source":"manual","productSlugs":["plain-flax-seed"],"limit":1}},{"id":"blk_article_124_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Roasting flax questions","items":[{"question":"How long does roasting flax seed take?","answer":"A few minutes over low to medium heat, stirred constantly, is usually enough. Watch for aroma and colour rather than a fixed time."},{"question":"Can I roast flax seed in the oven instead?","answer":"Yes, a low oven works too, though a dry pan on the stovetop gives more direct control and is quicker for small batches."},{"question":"Why did my roasted flax seed turn bitter?","answer":"Likely roasted too long or at too high heat. Flax burns quickly once it starts to darken."},{"question":"Should I roast flax before or after grinding?","answer":"Roast the whole seed first, then grind once it has cooled, for the most even result."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A dry pan, low to medium heat, and constant attention. A simple step that changes flavour a lot.', seo_description='How to roast flax seeds at home: pan method, timing, and what to watch for to avoid burning them.', seo_keywords='how to roast flax seeds, roasting flax at home', reading_minutes=2, published_version_id='arv_truegrit_124_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_124';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_124';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_124','How to Roast Flax Seeds','how-to-roast-flax-seeds','A dry pan, low to medium heat, and constant attention. A simple step that changes flavour a lot.','how to roast flax seeds, roasting flax at home');

-- 125. How to Add Flax Seeds to Indian Meals
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_125_2','art_truegrit_125',2,'{"blocks":[{"id":"blk_article_125_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flax seed fits into Indian cooking most easily as a small addition to something already being made, rather than as a separate dish or routine of its own."]}},{"id":"blk_article_125_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Practical ways to add it","items":["Roasted and ground into a chutney, the traditional Maharashtrian style, eaten alongside roti or rice.","Kneaded directly into roti or paratha dough in small quantity, adding a subtle nuttiness without changing the texture much.","Stirred into dal near the end of cooking, or ground and mixed in for a smoother integration.","Sprinkled over poha, upma or daliya once served, adding crunch and flavour at the table rather than during cooking.","Mixed into raita along with roasted cumin, a simple everyday combination that needs no separate preparation step."]}},{"id":"blk_article_125_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One person asks whether anyone actually measures how much flax they eat weekly, or attaches it to a daily habit instead](/community/dsc_truegrit_022), a useful reality check before setting an ambitious daily target."]}},{"id":"blk_article_125_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax for everyday meals","source":"manual","productSlugs":["roasted-flax-seeds","plain-flax-seed"],"limit":2}},{"id":"blk_article_125_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Adding flax to meals questions","items":[{"question":"Does flax seed change the taste of roti dough much?","answer":"In small quantity, only subtly, adding a light nuttiness without overpowering the roti''s usual flavour."},{"question":"Is flaxseed chutney a real traditional dish?","answer":"Yes, particularly in Maharashtrian cooking, roasted and ground flax chutney is a genuine, longstanding preparation."},{"question":"How much flax seed should I add to a meal?","answer":"A teaspoon or two per serving is a common, manageable amount to start with across most of these uses."},{"question":"Can flax seed be added to rice dishes?","answer":"Yes, stirred through cooked rice or a pulao adds a subtle texture and flavour, similar to how it works in daliya."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Small, practical additions to dishes already on the table, rather than a separate health routine.', seo_description='How to add flax seeds to everyday Indian meals: chutneys, dough, dal and other simple, practical additions.', seo_keywords='how to add flax seeds to Indian food, flax seeds Indian meals', reading_minutes=3, published_version_id='arv_truegrit_125_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_125';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_125';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_125','How to Add Flax Seeds to Indian Meals','how-to-add-flax-seeds-to-indian-meals','Small, practical additions to dishes already on the table, rather than a separate health routine.','how to add flax seeds to Indian food, flax seeds Indian meals');

-- 128. Flaxseed Raita Topping
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_128_2','art_truegrit_128',2,'{"blocks":[{"id":"blk_article_128_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Raita is one of the easiest places to add flax seed, since a small spoonful stirred through or sprinkled on top changes very little about the dish itself while adding real texture and flavour."]}},{"id":"blk_article_128_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to make it","items":["Roast flax seed in a dry pan until fragrant, then let it cool completely before grinding coarsely.","Combine a spoonful of the coarse ground flax with roasted cumin powder, a standard raita seasoning pairing.","Stir most of the mixture into the yoghurt itself, keeping a small pinch back to sprinkle on top just before serving.","Adjust quantity to taste. Flax''s nutty flavour is noticeable but not overpowering even in a modest amount.","This same topping works equally well over cucumber, boondi or plain yoghurt based raita."]}},{"id":"blk_article_128_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax for raita","source":"manual","productSlugs":["roasted-flax-seeds","plain-flax-seed"],"limit":2}},{"id":"blk_article_128_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed raita questions","items":[{"question":"Do I need to roast the flax seed first?","answer":"It is recommended for the best flavour, though pre-roasted flax seed works just as well and saves a step."},{"question":"How coarse should the ground flax be for raita?","answer":"A coarse grind gives more texture. Grind finer if you prefer it to blend more smoothly into the yoghurt."},{"question":"Can I add flax seed directly without grinding?","answer":"Whole roasted seed can be sprinkled on top for crunch, though grinding makes the flavour and texture more evenly spread."},{"question":"Does this topping work on any style of raita?","answer":"Yes, it pairs well with most raita styles, cucumber, boondi or plain, without clashing with the existing flavours."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A simple everyday addition, roasted ground flax stirred through or sprinkled over a bowl of raita.', seo_description='How to make a flaxseed raita topping: roasting, grinding and combining with yoghurt for an easy everyday addition.', seo_keywords='flaxseed raita, flax seed yoghurt topping', reading_minutes=2, published_version_id='arv_truegrit_128_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_128';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_128';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_128','Flaxseed Raita Topping','flaxseed-raita-topping','A simple everyday addition, roasted ground flax stirred through or sprinkled over a bowl of raita.','flaxseed raita, flax seed yoghurt topping');

-- 130. Five Easy Flaxseed Breakfast Ideas
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_130_2','art_truegrit_130',2,'{"blocks":[{"id":"blk_article_130_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["None of these need a separate flax based breakfast built from scratch. Each one adds flax to a dish most households already make regularly, so there is no new routine to keep up beyond having the seed in the pantry."]}},{"id":"blk_article_130_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Five ideas","items":["Sprinkled over poha or upma just before serving, adding a light crunch and nutty flavour to the finished dish.","Blended into a fruit smoothie, where its mild flavour largely disappears into the other ingredients.","Kneaded into paratha dough in small quantity, for a subtle nuttiness in an otherwise familiar breakfast.","Stirred into raita alongside roasted cumin, served as a simple side to whatever else is on the table.","Mixed into a bowl of daliya or oats once cooked, stirred through at the table rather than during cooking."]}},{"id":"blk_article_130_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax for breakfast","source":"manual","productSlugs":["roasted-flax-seeds","plain-flax-seed"],"limit":2}},{"id":"blk_article_130_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flaxseed breakfast questions","items":[{"question":"Which breakfast is easiest to start with?","answer":"Sprinkling roasted flax over poha or upma is the simplest, since it needs no extra preparation beyond having the seed on hand."},{"question":"Can I prepare ground flax the night before?","answer":"Yes, grinding a small batch the evening before saves time and still stays reasonably fresh by morning."},{"question":"Does flax seed change the texture of a smoothie much?","answer":"In moderate quantity, only slightly, mainly adding a little body rather than a noticeable grainy texture."},{"question":"Is one of these ideas better than the others?","answer":"Not really, they are simply different entry points. Pick whichever fits a breakfast you already make regularly."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Small, low effort additions to breakfasts already on rotation, rather than a separate flax based meal.', seo_description='Five easy ways to add flaxseed to breakfast: poha, smoothies, paratha, raita and daliya.', seo_keywords='flaxseed breakfast ideas, flax seed for breakfast', reading_minutes=3, published_version_id='arv_truegrit_130_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_130';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_130';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_130','Five Easy Flaxseed Breakfast Ideas','five-easy-flaxseed-breakfast-ideas','Small, low effort additions to breakfasts already on rotation, rather than a separate flax based meal.','flaxseed breakfast ideas, flax seed for breakfast');

-- 131. What Are Sesame Seeds?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_131_2','art_truegrit_131',2,'{"blocks":[{"id":"blk_article_131_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame seeds, called til in Hindi, are one of the oldest cultivated oilseeds, with a place in Indian cooking that goes back further than most ingredients in a modern pantry. They show up whole, roasted, ground into chutney, or pressed into oil."]}},{"id":"blk_article_131_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines them","items":["A small, flat oilseed with a mild, nutty flavour that becomes noticeably stronger once roasted.","Known as til in Hindi and central to sweets, chutneys and tempering across many regional Indian cuisines.","Comes in a few colour varieties, most commonly white and black, which differ in flavour intensity and traditional use.","High in oil content, which is why sesame has long been pressed into cooking oil alongside being eaten as a seed.","Used both raw and roasted, though roasting is far more common in Indian recipes for its stronger developed flavour."]}},{"id":"blk_article_131_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame to try","source":"manual","productSlugs":["sesame-seed","roasted-sesame-seeds"],"limit":2}},{"id":"blk_article_131_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame seed questions","items":[{"question":"Is til the same as sesame seed?","answer":"Yes, til is simply the Hindi name for sesame seed, the same seed sold under either term."},{"question":"Are sesame seeds always roasted before eating?","answer":"Not always, but most Indian recipes call for roasted sesame, since roasting develops a much stronger, nuttier flavour."},{"question":"How old is sesame cultivation in India?","answer":"Very old, sesame is considered one of the earliest oilseed crops cultivated on the subcontinent, with deep culinary and ritual roots."},{"question":"Can sesame seeds be pressed into oil?","answer":"Yes, sesame oil is a traditional pressed oil, sold separately from the whole seed for cooking use."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Called til in Hindi, one of the oldest cultivated oilseeds, eaten whole, ground into chutney, or pressed into oil.', seo_description='Sesame seeds explained: what they are, how they are used across Indian cooking, and their different forms.', seo_keywords='sesame seeds, til seeds, what are sesame seeds', reading_minutes=3, published_version_id='arv_truegrit_131_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_131';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_131';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_131','What Are Sesame Seeds?','what-are-sesame-seeds','Called til in Hindi, one of the oldest cultivated oilseeds, eaten whole, ground into chutney, or pressed into oil.','sesame seeds, til seeds, what are sesame seeds');

-- 132. Types of Sesame Seeds Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_132_2','art_truegrit_132',2,'{"blocks":[{"id":"blk_article_132_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame seeds come in a handful of colour varieties, and while the underlying seed is closely related across all of them, colour does correlate with some real differences in flavour and traditional use."]}},{"id":"blk_article_132_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The main types","items":["White sesame seeds are the most common in Indian kitchens, mild in flavour and used widely in sweets and tempering.","Black sesame seeds carry a stronger, more pronounced flavour and are common in certain regional dishes and East Asian cooking.","Brown or tan sesame sits between the two in both colour and intensity, though it is less commonly sold separately.","Colour can also reflect whether the outer hull has been removed, hulled seeds tend to look paler than unhulled ones.","All types can generally be roasted, ground or pressed into oil, with colour affecting flavour more than method of use."]}},{"id":"blk_article_132_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame varieties","source":"manual","productSlugs":["sesame-seed","roasted-sesame-seeds"],"limit":2}},{"id":"blk_article_132_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame seed type questions","items":[{"question":"Is black sesame stronger tasting than white?","answer":"Yes, generally black sesame carries a more pronounced, slightly bitter edge compared to the milder white variety."},{"question":"Which type of sesame do you sell?","answer":"Check the current product listing for the specific variety. Our seeds work the same way across roasting, grinding and pressing."},{"question":"Are hulled and unhulled sesame the same nutritionally?","answer":"Hulling removes the outer layer, which changes texture and slightly changes flavour, without being a meaningfully different seed."},{"question":"Can I substitute black sesame for white in a recipe?","answer":"You can, but expect a stronger, more pronounced flavour and a visibly different colour in the finished dish."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='White, black and a few shades between. What actually changes with colour, and what stays the same.', seo_description='Types of sesame seeds explained: white, black and other colour varieties, and how each is traditionally used.', seo_keywords='types of sesame seeds, white vs black sesame', reading_minutes=2, published_version_id='arv_truegrit_132_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_132';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_132';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_132','Types of Sesame Seeds Explained','types-of-sesame-seeds-explained','White, black and a few shades between. What actually changes with colour, and what stays the same.','types of sesame seeds, white vs black sesame');

-- 133. Roasted vs Raw Sesame Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_133_2','art_truegrit_133',2,'{"blocks":[{"id":"blk_article_133_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Roasting changes sesame seed more dramatically than it changes many other seeds, developing a deep, nutty flavour that raw sesame simply does not have. This is part of why so many Indian recipes call for the roasted form specifically."]}},{"id":"blk_article_133_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Roasted sesame develops a strong, nutty, slightly toasty flavour that raw sesame does not carry.","Raw sesame has a much milder, almost neutral taste, useful in preparations where you do not want sesame''s flavour to dominate.","Most Indian sweets, chutneys and tempering recipes specifically call for roasted sesame, not raw.","Roasting also makes the seed slightly easier to grind evenly for chutneys and laddu mixtures.","Raw sesame is more commonly used for pressing into a lighter, milder oil, where the flavour is meant to be subtler."]}},{"id":"blk_article_133_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Raw and roasted sesame","source":"manual","productSlugs":["sesame-seed","roasted-sesame-seeds"],"limit":2}},{"id":"blk_article_133_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Roasted vs raw sesame questions","items":[{"question":"Why do most recipes specify roasted sesame?","answer":"Roasting develops a much stronger, nuttier flavour than raw sesame carries, which most Indian recipes are built around."},{"question":"Can I roast raw sesame seeds myself?","answer":"Yes, a dry pan on medium heat, stirred constantly, works well and takes only a few minutes."},{"question":"Does raw sesame have any culinary use?","answer":"Yes, particularly in pressing a lighter, milder sesame oil, where a subtler flavour is often preferred."},{"question":"How do I know when sesame is properly roasted?","answer":"It turns a light golden colour and releases a distinct nutty aroma, sometimes with a faint popping sound."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Roasting changes sesame more dramatically than it changes most seeds, which is why most Indian recipes call for it.', seo_description='Roasted sesame seeds compared with raw: flavour development, culinary use, and why roasting is so common here.', seo_keywords='roasted sesame seeds vs raw', reading_minutes=2, published_version_id='arv_truegrit_133_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_133';
