INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_133','Roasted vs Raw Sesame Seeds','roasted-vs-raw-sesame-seeds','Roasting changes sesame more dramatically than it changes most seeds, which is why most Indian recipes call for it.','roasted sesame seeds vs raw');

-- 134. Sesame Seeds vs Flax Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_134_2','art_truegrit_134',2,'{"blocks":[{"id":"blk_article_134_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame and flax sit next to each other on many pantry shelves, but sesame carries a far longer, more central role in Indian food culture, from festival sweets to everyday tempering, than flax has traditionally held."]}},{"id":"blk_article_134_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Sesame has deep roots in Indian sweets, tempering and festival foods, particularly around Makar Sankranti. Flax has a smaller, more regional traditional presence.","Roasting transforms sesame''s flavour dramatically. Flax changes more subtly when roasted, staying closer to its raw character.","Sesame is more often eaten whole or ground into a paste or chutney. Flax is more commonly ground fine or pressed into oil.","Both are pressed into oil, though sesame oil sees far wider everyday cooking use than flaxseed oil, which stays a raw finishing oil.","Neither replaces the other in a recipe built around its specific flavour and role, so both are worth keeping separately."]}},{"id":"blk_article_134_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame to try","source":"manual","productSlugs":["sesame-seed","roasted-sesame-seeds"],"limit":2}},{"id":"blk_article_134_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame vs flax questions","items":[{"question":"Which has a longer history in Indian cooking, sesame or flax?","answer":"Sesame, by a wide margin. It is one of the oldest cultivated oilseeds on the subcontinent, with deep ritual and culinary roots."},{"question":"Can sesame replace flax seed in a recipe?","answer":"Not directly. The flavour and traditional role of each differ enough that substituting changes the dish noticeably."},{"question":"Is sesame oil used more widely than flaxseed oil?","answer":"Yes, sesame oil is used across everyday and festival cooking, while flaxseed oil stays a small quantity raw finishing oil."},{"question":"Do sesame and flax seed pair well together?","answer":"Yes, many chutneys and toppings combine both for a mix of flavours and textures."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A much longer culinary history for sesame, against flax''s growing but comparatively recent place in the kitchen.', seo_description='Sesame seeds compared with flax seeds: flavour, traditional use, and how central each is to Indian cooking.', seo_keywords='sesame seeds vs flax seeds, til vs alsi', reading_minutes=2, published_version_id='arv_truegrit_134_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_134';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_134';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_134','Sesame Seeds vs Flax Seeds','sesame-seeds-vs-flax-seeds','A much longer culinary history for sesame, against flax''s growing but comparatively recent place in the kitchen.','sesame seeds vs flax seeds, til vs alsi');

-- 135. How Sesame Oil Is Traditionally Made
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_135_2','art_truegrit_135',2,'{"blocks":[{"id":"blk_article_135_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame oil is pressed from either raw or roasted seed, and that single choice decides much of the final oil''s character, from a lighter, milder pressing to the deep, aromatic oil common in South Indian kitchens."]}},{"id":"blk_article_135_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The steps","items":["Sesame seeds, raw or lightly roasted, are cleaned and fed into a crusher, traditionally a wooden ghani similar to the one used for mustard oil.","Pressing from raw seed gives a lighter, milder oil, while pressing from roasted seed gives a darker, more aromatic one.","In South India, this pressed oil is often called gingelly oil, the same product under a regional name.","The oil is settled and lightly filtered rather than heavily refined, keeping more of its natural flavour and colour.","Refined sesame oil goes through additional processing that produces a much more neutral, lighter coloured oil for general cooking."]}},{"id":"blk_article_135_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditionally pressed sesame oil","source":"manual","productSlugs":["sesame-oil"],"limit":1}},{"id":"blk_article_135_4","type":"faq","version":1,"enabled":true,"props":{"heading":"How sesame oil is made, answered","items":[{"question":"Is gingelly oil different from sesame oil?","answer":"No, gingelly oil is simply the South Indian name for sesame oil, the same product under a regional term."},{"question":"Does roasting the seed before pressing change the oil much?","answer":"Yes, roasted seed gives a darker, more aromatic oil, while raw seed gives a lighter, milder one."},{"question":"Is sesame oil pressed the same way as mustard oil?","answer":"Similarly, both traditionally use a ghani style mechanical press, though the seeds and resulting flavour differ entirely."},{"question":"Why is sesame oil sometimes darker than other cooking oils?","answer":"Oil pressed from roasted seed carries more colour and aroma than oil from raw seed or a heavily refined process."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Pressed from raw or roasted seed depending on the style wanted, sometimes called gingelly oil in South India.', seo_description='How sesame oil is traditionally made: pressing raw or roasted seed, and where the term gingelly oil comes from.', seo_keywords='how sesame oil is made, gingelly oil, til oil', reading_minutes=3, published_version_id='arv_truegrit_135_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_135';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_135';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_135','How Sesame Oil Is Traditionally Made','how-sesame-oil-is-traditionally-made','Pressed from raw or roasted seed depending on the style wanted, sometimes called gingelly oil in South India.','how sesame oil is made, gingelly oil, til oil');

-- 136. Cold-Pressed Sesame Oil Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_136_2','art_truegrit_136',2,'{"blocks":[{"id":"blk_article_136_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Cold-pressed sesame oil sits in a more flexible spot than either mustard or flaxseed oil. Depending on whether it was pressed from raw or roasted seed, it can genuinely handle some cooking, not just finishing."]}},{"id":"blk_article_136_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually matters","items":["Cold-pressed sesame oil from raw seed has a moderate smoke point, suitable for tempering and some everyday cooking.","Cold-pressed oil from roasted seed, closer to what is sold as toasted sesame oil, has a lower smoke point and suits finishing better than direct heat.","Cold pressing generally preserves more of sesame''s natural flavour and colour than a heavily refined pressing does.","Sesame oil is also naturally more resistant to oxidation than many other unrefined oils, thanks to compounds it carries on its own.","Check the label for raw or toasted origin if you specifically want an oil suited to cooking rather than only finishing."]}},{"id":"blk_article_136_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook was surprised to see cold-pressed sesame oil used successfully for tadka despite assuming its smoke point was too low](/community/dsc_truegrit_017), a useful read before deciding how you will use yours."]}},{"id":"blk_article_136_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Cold-pressed sesame oil","source":"manual","productSlugs":["sesame-oil"],"limit":1}},{"id":"blk_article_136_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Cold-pressed sesame oil questions","items":[{"question":"Can cold-pressed sesame oil be used for tadka?","answer":"Yes, particularly oil pressed from raw seed, which has a moderate smoke point suited to tempering."},{"question":"Is cold-pressed sesame oil the same as toasted sesame oil?","answer":"Not always. Toasted usually means pressed from roasted seed specifically, which behaves more like a finishing oil."},{"question":"Why is sesame oil more heat tolerant than flaxseed oil?","answer":"Its fat profile and natural antioxidant compounds make it more stable under heat than flaxseed oil''s more delicate composition."},{"question":"Does cold-pressed sesame oil go rancid quickly?","answer":"Less quickly than many other unrefined oils, thanks to natural compounds in sesame that help resist oxidation."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Unlike flaxseed oil, cold-pressed sesame oil can genuinely handle some cooking, depending on how it was pressed.', seo_description='Cold-pressed sesame oil explained: how raw versus roasted pressing changes whether it suits cooking or finishing.', seo_keywords='cold pressed sesame oil, sesame oil for cooking', reading_minutes=3, published_version_id='arv_truegrit_136_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_136';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_136';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_136','Cold-Pressed Sesame Oil Explained','cold-pressed-sesame-oil-explained','Unlike flaxseed oil, cold-pressed sesame oil can genuinely handle some cooking, depending on how it was pressed.','cold pressed sesame oil, sesame oil for cooking');

-- 137. Sesame Oil vs Mustard Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_137_2','art_truegrit_137',2,'{"blocks":[{"id":"blk_article_137_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame and mustard oil are both traditional Indian cooking oils, but they come from different regional kitchens and taste nothing alike. Choosing between them is largely a matter of which cuisine you are cooking."]}},{"id":"blk_article_137_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Sesame oil is more associated with South Indian cooking. Mustard oil is more associated with North and East Indian cooking.","Flavour differs sharply, sesame oil is nutty and aromatic, mustard oil is sharp and pungent.","Sesame oil pressed from raw seed can handle moderate cooking heat. Cold-pressed mustard oil is often heated to a smoke point first to mellow it.","Both come in cold-pressed and refined versions, with the cold-pressed versions carrying much more of each oil''s distinct character.","Neither is a direct substitute for the other in a recipe built around its specific regional flavour."]}},{"id":"blk_article_137_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Both oils","source":"manual","productSlugs":["sesame-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_137_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame vs mustard oil questions","items":[{"question":"Can I use sesame oil where a recipe calls for mustard oil?","answer":"You can, but expect a noticeably different flavour, nutty rather than pungent, in the finished dish."},{"question":"Which is more common in everyday Indian cooking?","answer":"Both are common, just in different regions, sesame more in the south, mustard more in the north and east."},{"question":"Does either oil need to be heated before cooking?","answer":"Mustard oil more commonly benefits from a brief smoke point heating. Sesame oil generally does not need this step."},{"question":"Which has the stronger aroma?","answer":"Mustard oil is generally more pungent raw. Sesame oil''s aroma is warmer and nuttier rather than sharp."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Two traditional Indian cooking oils from different culinary regions, with distinctly different flavour profiles.', seo_description='Sesame oil compared with mustard oil: flavour, regional tradition, heat tolerance and everyday use.', seo_keywords='sesame oil vs mustard oil', reading_minutes=3, published_version_id='arv_truegrit_137_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_137';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_137';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_137','Sesame Oil vs Mustard Oil','sesame-oil-vs-mustard-oil','Two traditional Indian cooking oils from different culinary regions, with distinctly different flavour profiles.','sesame oil vs mustard oil');

-- 138. Sesame Oil vs Groundnut Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_138_2','art_truegrit_138',2,'{"blocks":[{"id":"blk_article_138_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame and groundnut oil often sit side by side in the same kitchen, doing different jobs. Groundnut oil is the everyday neutral frying oil in much of India, while sesame oil is used more deliberately for its flavour."]}},{"id":"blk_article_138_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Groundnut oil is largely neutral in flavour, making it a common all purpose frying oil in states like Gujarat and Maharashtra.","Sesame oil carries a distinct, nutty aroma that comes through in the finished dish, which is why it is used more deliberately.","Groundnut oil generally has a higher smoke point suited to deep frying. Sesame oil, especially the roasted variety, suits lower heat or finishing use better.","Both are traditional Indian cooking oils, just associated with different regional cuisines and different roles within a dish.","Neither replaces the other cleanly. Groundnut oil for volume frying, sesame oil for flavour where it is wanted."]}},{"id":"blk_article_138_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame oil","source":"manual","productSlugs":["sesame-oil"],"limit":1}},{"id":"blk_article_138_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame vs groundnut oil questions","items":[{"question":"Can I deep fry in sesame oil instead of groundnut oil?","answer":"You can with a raw pressed sesame oil, though it will bring a distinct flavour that a neutral groundnut oil would not."},{"question":"Which is more affordable for everyday cooking?","answer":"Groundnut oil is typically the more affordable, higher volume everyday choice, with sesame oil used in smaller quantities for flavour."},{"question":"Does groundnut oil have any distinct flavour?","answer":"Very little, which is exactly why it works well as an all purpose frying oil that does not compete with other ingredients."},{"question":"Can the two be used together in one dish?","answer":"Yes, frying in groundnut oil and finishing with a small amount of sesame oil is a common combination."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One is aromatic and used with intention. The other is a neutral, everyday frying oil in much of India.', seo_description='Sesame oil compared with groundnut oil: flavour intensity, smoke point, and which suits everyday frying.', seo_keywords='sesame oil vs groundnut oil, sesame vs peanut oil', reading_minutes=2, published_version_id='arv_truegrit_138_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_138';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_138';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_138','Sesame Oil vs Groundnut Oil','sesame-oil-vs-groundnut-oil','One is aromatic and used with intention. The other is a neutral, everyday frying oil in much of India.','sesame oil vs groundnut oil, sesame vs peanut oil');

-- 139. How to Use Sesame Oil in Indian Cooking
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_139_2','art_truegrit_139',2,'{"blocks":[{"id":"blk_article_139_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame oil earns its place across several distinct roles in Indian cooking, not one fixed use. Which role it plays depends mostly on whether the oil was pressed from raw or roasted seed."]}},{"id":"blk_article_139_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Ways to use it","items":["As a tempering oil, popping mustard seeds and curry leaves for South Indian dishes, using the raw pressed, moderate heat variety.","Drizzled over finished dosas or idlis, where its aroma comes through clearly without needing to be cooked further.","In pickle making, where sesame oil, like mustard oil, contributes both flavour and a natural preservative quality.","Ground into chutneys alongside roasted sesame seeds, adding both moisture and flavour to the mixture.","As a finishing drizzle over a simple dal or vegetable dish, added once cooking is complete for maximum aroma."]}},{"id":"blk_article_139_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame oil","source":"manual","productSlugs":["sesame-oil"],"limit":1}},{"id":"blk_article_139_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Using sesame oil questions","items":[{"question":"Is sesame oil used for tempering across all of India?","answer":"It is more associated with South Indian tempering specifically, though it is used elsewhere too."},{"question":"Can sesame oil be used in pickles like mustard oil?","answer":"Yes, it serves a similar role, contributing flavour and helping the pickle keep, in recipes traditionally built around it."},{"question":"Should I use raw or roasted pressed sesame oil for cooking?","answer":"Raw pressed for actual cooking heat, roasted pressed for finishing, where its stronger aroma is the point."},{"question":"Does sesame oil work well in chutneys?","answer":"Yes, it pairs naturally with roasted sesame seeds and other chutney ingredients, adding both moisture and flavour."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Tempering, finishing and pickling, more than a single default use across regional Indian kitchens.', seo_description='How to use sesame oil in Indian cooking: tempering, finishing dosas and idlis, pickling, and chutneys.', seo_keywords='how to use sesame oil, sesame oil Indian cooking', reading_minutes=3, published_version_id='arv_truegrit_139_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_139';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_139';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_139','How to Use Sesame Oil in Indian Cooking','how-to-use-sesame-oil-in-indian-cooking','Tempering, finishing and pickling, more than a single default use across regional Indian kitchens.','how to use sesame oil, sesame oil Indian cooking');

-- 140. How to Store Sesame Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_140_2','art_truegrit_140',2,'{"blocks":[{"id":"blk_article_140_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame oil is more forgiving to store than many unrefined oils, thanks to natural compounds it carries that help resist oxidation, though the same basic care that helps any oil still applies."]}},{"id":"blk_article_140_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Keep it in a cool, dark place away from direct sunlight, the same basic principle that protects most cooking oils.","A tightly sealed container matters more than refrigeration for most households, though a hot climate can still benefit from it.","Sesame oil naturally resists rancidity better than many other unrefined oils, thanks to its own antioxidant compounds.","Roasted sesame oil, being more aromatic, can lose some of its intensity over time even before it technically spoils.","Use within a reasonable time of opening for the best flavour, even though the oil itself keeps fairly well."]}},{"id":"blk_article_140_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame oil","source":"manual","productSlugs":["sesame-oil"],"limit":1}},{"id":"blk_article_140_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame oil storage questions","items":[{"question":"Does sesame oil need refrigeration?","answer":"Not usually. It is naturally more stable than many unrefined oils, so a cool, dark pantry is generally enough."},{"question":"Why is sesame oil more stable than other unrefined oils?","answer":"It carries natural antioxidant compounds that help resist oxidation better than many other seed oils manage on their own."},{"question":"How long does sesame oil last once opened?","answer":"Generally longer than flaxseed oil, often a year or more if kept cool, dark and tightly sealed."},{"question":"Does roasted sesame oil lose flavour over time?","answer":"Its aroma can soften gradually even before spoiling, so using it within several months keeps the flavour at its best."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='More forgiving than flaxseed oil thanks to natural compounds that resist oxidation, though basic care still helps.', seo_description='How to store sesame oil properly: temperature, sealing, and why it is more stable than many unrefined oils.', seo_keywords='how to store sesame oil, sesame oil shelf life', reading_minutes=2, published_version_id='arv_truegrit_140_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_140';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_140';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_140','How to Store Sesame Oil','how-to-store-sesame-oil','More forgiving than flaxseed oil thanks to natural compounds that resist oxidation, though basic care still helps.','how to store sesame oil, sesame oil shelf life');

-- 141. Why Sesame Oil Has a Distinct Aroma
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_141_2','art_truegrit_141',2,'{"blocks":[{"id":"blk_article_141_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame oil''s warm, nutty smell comes largely from what happens when the seed is roasted before pressing, developing compounds that a raw, unroasted pressing does not carry to the same degree."]}},{"id":"blk_article_141_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What is actually happening","items":["Roasting the seed before pressing develops a set of aromatic compounds unique to sesame, giving the oil its characteristic nutty smell.","Oil pressed from raw seed has a much milder aroma, closer to neutral than the deep, toasted smell most people associate with sesame oil.","This is the same underlying reason roasted sesame seeds smell so much stronger than raw ones on their own.","The aroma is a genuine marker of quality here, a flat or very mild smell on a supposedly roasted pressed oil is worth questioning before you buy it."]}},{"id":"blk_article_141_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Aromatic sesame oil","source":"manual","productSlugs":["sesame-oil"],"limit":1}},{"id":"blk_article_141_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame oil aroma questions","items":[{"question":"Why does my sesame oil smell milder than expected?","answer":"It may have been pressed from raw rather than roasted seed, which naturally gives a much subtler aroma."},{"question":"Is a strong aroma a sign of good quality sesame oil?","answer":"Generally yes, for a roasted pressed oil, a strong nutty smell reflects genuine roasting rather than a flat, underdeveloped pressing."},{"question":"Does the aroma fade with storage?","answer":"It can soften somewhat over time, particularly if the oil is not kept sealed and away from light and heat."},{"question":"Is the aroma from roasting or from the seed itself?","answer":"Both play a part, but roasting develops the aroma much more fully than the raw seed carries on its own."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Roasting develops compounds unique to sesame, part of why it smells so different from a neutral oil.', seo_description='Why sesame oil has such a distinct, nutty aroma, and how roasting the seed changes it.', seo_keywords='why sesame oil smells nutty, sesame oil aroma', reading_minutes=2, published_version_id='arv_truegrit_141_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_141';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_141';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_141','Why Sesame Oil Has a Distinct Aroma','why-sesame-oil-has-a-distinct-aroma','Roasting develops compounds unique to sesame, part of why it smells so different from a neutral oil.','why sesame oil smells nutty, sesame oil aroma');

-- 145. Sesame Seed Salad Toppings
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_145_2','art_truegrit_145',2,'{"blocks":[{"id":"blk_article_145_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame seeds work as a salad topping the same way they work almost everywhere else, adding crunch and a nutty flavour with almost no preparation beyond a quick roast."]}},{"id":"blk_article_145_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to use them","items":["Roast sesame seeds in a dry pan for a couple of minutes until fragrant, then let them cool before sprinkling.","A light sprinkle over a green salad adds both texture and a warm, nutty note that pairs well with a simple dressing.","Mix white and black sesame together for visual contrast as well as a slightly layered flavour.","Toss sesame seeds through a cucumber or carrot salad along with a little sesame oil for a more cohesive flavour throughout.","Store any leftover roasted seed in an airtight container so it stays crunchy and ready for the next salad."]}},{"id":"blk_article_145_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One person is looking to use roasted sesame beyond just a garnish and asks where else people use it as an actual ingredient](/community/dsc_truegrit_021), worth a look for more ideas beyond salads."]}},{"id":"blk_article_145_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame for salads","source":"manual","productSlugs":["roasted-sesame-seeds","sesame-oil"],"limit":2}},{"id":"blk_article_145_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame salad topping questions","items":[{"question":"Should I roast sesame seeds before using them on a salad?","answer":"It is recommended for the best flavour, though pre-roasted sesame works just as well and saves a step."},{"question":"How much sesame should I add to a salad?","answer":"A teaspoon or two per serving is a reasonable amount to start with, adjusted to taste."},{"question":"Does sesame oil work in a salad dressing too?","answer":"Yes, a small amount adds a nutty depth that pairs naturally with the seeds themselves in the same salad."},{"question":"Which salads suit sesame seeds best?","answer":"Most work well, though salads with cucumber, carrot or other crisp vegetables are a particularly natural pairing."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A simple crunch and flavour addition that takes seconds to prepare and works across most salads.', seo_description='How to use sesame seeds as a salad topping: roasting, quantity, and which salads suit them best.', seo_keywords='sesame seed salad topping, sesame seeds on salad', reading_minutes=2, published_version_id='arv_truegrit_145_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_145';
