INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_145','Sesame Seed Salad Toppings','sesame-seed-salad-toppings','A simple crunch and flavour addition that takes seconds to prepare and works across most salads.','sesame seed salad topping, sesame seeds on salad');

-- 147. Traditional Indian Uses of Til
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_147_2','art_truegrit_147',2,'{"blocks":[{"id":"blk_article_147_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Til shows up across Indian cooking in more places than most people realise once they start looking, from festival sweets to the tempering that starts an everyday sabzi."]}},{"id":"blk_article_147_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where it shows up","items":["Til laddu, sesame and jaggery rolled into a sweet, a classic winter preparation eaten across much of North India.","Til chikki, a brittle made from sesame and jaggery, sold widely as a simple traditional snack.","Tempering, particularly in South Indian cooking, where sesame oil and sometimes the seed itself starts a dish.","Chutneys, roasted and ground sesame forming the base or a key ingredient in several regional chutney styles.","Pickling, where sesame oil plays a role similar to mustard oil, contributing flavour and helping the pickle keep.","Festival sweets beyond laddu and chikki, where sesame appears in regional variations most households recognise instantly."]}},{"id":"blk_article_147_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Til for traditional dishes","source":"manual","productSlugs":["roasted-sesame-seeds","sesame-oil"],"limit":2}},{"id":"blk_article_147_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Traditional til questions","items":[{"question":"Is til laddu made with sesame seed or sesame oil?","answer":"The seed itself, roasted and combined with jaggery, not the pressed oil."},{"question":"Which region is til chikki most associated with?","answer":"It is popular across much of North and West India, particularly around winter months."},{"question":"Is sesame used in pickling the same way as mustard oil?","answer":"Similarly, sesame oil contributes flavour and a natural preservative quality, though the two oils taste quite different."},{"question":"Do all these traditional uses call for roasted sesame?","answer":"Most do, since roasting develops the flavour these preparations are built around."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Sweets, tempering, chutneys and pickles. Til shows up across regional Indian cooking far more than a single dish.', seo_description='Traditional Indian uses of til (sesame): laddu, chikki, tempering, chutneys and pickling.', seo_keywords='traditional uses of til, sesame in Indian cooking', reading_minutes=3, published_version_id='arv_truegrit_147_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_147';
