INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_147','Traditional Indian Uses of Til','traditional-indian-uses-of-til','Sweets, tempering, chutneys and pickles. Til shows up across regional Indian cooking far more than a single dish.','traditional uses of til, sesame in Indian cooking');

-- 148. Why Sesame Is Important in Indian Food Traditions
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_148_2','art_truegrit_148',2,'{"blocks":[{"id":"blk_article_148_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame''s importance in Indian food traditions goes beyond flavour. It is one of the oldest cultivated oilseeds in the region, with a history that stretches into both everyday cooking and ritual practice."]}},{"id":"blk_article_148_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why it holds this place","items":["Sesame is one of the earliest oilseed crops cultivated on the subcontinent, long predating many ingredients considered staples today.","It carries ritual significance in several traditions, offered in poojas and associated with specific festival foods.","Its oil was historically one of the primary cooking fats in several regions before other oils became widely available.","The seed''s long shelf life and reliable yield made it a dependable crop across generations of farmers.","This depth of history is part of why til appears so consistently across sweets, tempering and festival cooking today."]}},{"id":"blk_article_148_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame","source":"manual","productSlugs":["sesame-seed","roasted-sesame-seeds"],"limit":2}},{"id":"blk_article_148_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame tradition questions","items":[{"question":"Is sesame considered a ritual ingredient?","answer":"Yes, in several Indian traditions, sesame is offered in poojas and appears in specific festival foods beyond its everyday culinary use."},{"question":"Does sesame''s long history affect its price today?","answer":"Not directly, pricing follows current supply and demand more than historical significance, though tradition keeps demand steady."},{"question":"Was sesame oil a primary cooking fat historically?","answer":"In several regions, yes, before other oils became as widely available and affordable as they are today."},{"question":"Does this history affect how sesame is used today?","answer":"It shapes which dishes and festivals sesame appears in, even as everyday cooking has diversified beyond it."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Deep historical roots and a genuine ritual role, not just another ingredient on the shelf.', seo_description='Why sesame holds such an important place in Indian food traditions, from ancient cultivation to ritual use.', seo_keywords='importance of sesame in Indian food, til significance', reading_minutes=2, published_version_id='arv_truegrit_148_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_148';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_148';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_148','Why Sesame Is Important in Indian Food Traditions','why-sesame-is-important-in-indian-food-traditions','Deep historical roots and a genuine ritual role, not just another ingredient on the shelf.','importance of sesame in Indian food, til significance');

-- 149. Makar Sankranti and Sesame: The Food Tradition Behind Til
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_149_2','art_truegrit_149',2,'{"blocks":[{"id":"blk_article_149_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Makar Sankranti, the mid-January harvest festival, has a food tradition built specifically around sesame and jaggery, known as til-gud, that goes well beyond sesame''s everyday culinary use."]}},{"id":"blk_article_149_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The tradition","items":["Til-gud, sesame combined with jaggery, is the signature combination eaten and gifted during Makar Sankranti across much of North and West India.","Til laddu and chikki are the most common forms this takes, both built on the same core pairing of sesame and jaggery.","The custom is tied to a long standing belief that sesame''s warming quality suits the winter timing of the festival.","The phrase exchanged while sharing til-gud sweets, roughly translating to eat sweet and speak sweet, reflects the goodwill the tradition carries.","Regional variations exist in exactly which sweet is made, though sesame and jaggery remain the constant across nearly all of them."]}},{"id":"blk_article_149_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Til for Sankranti","source":"manual","productSlugs":["roasted-sesame-seeds","sesame-seed"],"limit":2}},{"id":"blk_article_149_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Makar Sankranti til questions","items":[{"question":"What does til-gud mean?","answer":"Til means sesame and gud means jaggery. Together they name the sesame and jaggery sweets central to Makar Sankranti."},{"question":"Why is sesame specifically eaten during this festival?","answer":"A long standing belief holds that sesame has a warming quality suited to the cold winter timing of Makar Sankranti."},{"question":"Is til laddu only eaten during Makar Sankranti?","answer":"It is most strongly associated with this festival, though it is enjoyed at other times too, particularly in winter."},{"question":"Does the tradition vary by region?","answer":"Yes, the specific sweet made varies by region, though sesame and jaggery remain the shared core across most versions."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Til-gud sweets mark the festival specifically, tied to a long standing belief about sesame and winter.', seo_description='The tradition behind til and Makar Sankranti: til-gud sweets, laddu, and the winter food custom around sesame.', seo_keywords='Makar Sankranti til, til gud tradition, sesame Sankranti', reading_minutes=3, published_version_id='arv_truegrit_149_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_149';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_149';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_149','Makar Sankranti and Sesame: The Food Tradition Behind Til','makar-sankranti-and-sesame-the-food-tradition-behind-til','Til-gud sweets mark the festival specifically, tied to a long standing belief about sesame and winter.','Makar Sankranti til, til gud tradition, sesame Sankranti');

-- 150. What Is Black Gram?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_150_2','art_truegrit_150',2,'{"blocks":[{"id":"blk_article_150_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram, known as urad in Hindi, is a pulse with a black skin that hides a creamy white interior once split. It shows up whole in dal makhani, split in tempering and khichdi, and ground into both flour and a fermented batter base."]}},{"id":"blk_article_150_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["A pulse with a distinctive black outer skin, revealing a pale, creamy white interior once dehusked and split.","Known as urad in Hindi, central to both North Indian dal cooking and South Indian fermented batters like dosa and idli.","Higher in protein than many common pulses, part of why it holds up well in heavier dishes like dal makhani.","Sold whole, split and skinned, ground into besan, or roasted and ground into sattu, each suited to different dishes.","Its skin carries much of its earthy flavour, which is part of why whole and split urad taste noticeably different."]}},{"id":"blk_article_150_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram to try","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal"],"limit":2}},{"id":"blk_article_150_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black gram questions","items":[{"question":"Is black gram the same as urad?","answer":"Yes, urad is simply the Hindi name for black gram, the same pulse sold under either term."},{"question":"Why does black gram look different in different dishes?","answer":"It is sold whole with its black skin, or split and skinned to a pale white, each suited to different recipes."},{"question":"Is black gram used in South Indian cooking?","answer":"Yes, split urad dal is a core ingredient in dosa and idli batter, alongside its more familiar North Indian dal uses."},{"question":"Can black gram be ground into flour?","answer":"Yes, both a raw besan and a roasted sattu are made from black gram, each used differently in cooking."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A protein rich pulse known as urad in Hindi, central to both South Indian batters and North Indian dal makhani.', seo_description='Black gram explained: what it is, its whole and split forms, and its central role across Indian cooking.', seo_keywords='black gram, urad, what is black gram', reading_minutes=3, published_version_id='arv_truegrit_150_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_150';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_150';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_150','What Is Black Gram?','what-is-black-gram','A protein rich pulse known as urad in Hindi, central to both South Indian batters and North Indian dal makhani.','black gram, urad, what is black gram');

-- 151. Black Gram vs Urad Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_151_2','art_truegrit_151',2,'{"blocks":[{"id":"blk_article_151_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram and urad dal name the same underlying pulse, but in everyday use, urad dal more often points specifically to the split, processed form rather than the whole grain."]}},{"id":"blk_article_151_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually know","items":["Black gram and urad are the same pulse, English and Hindi names for one another.","In common usage, urad dal often specifically means the split, dehusked form rather than the whole black skinned grain.","Whole black gram is sometimes called sabut urad to distinguish it clearly from the split dal form.","The naming can vary by seller, so checking whether a pack is whole or split matters more than the exact word used.","Both forms come from the exact same pulse crop, just processed differently before packaging.","Recipes usually make the intended form clear from context, even when the label alone does not spell it out."]}},{"id":"blk_article_151_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole and split","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal"],"limit":2}},{"id":"blk_article_151_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black gram and urad dal questions","items":[{"question":"Should I buy black gram or urad dal for dal makhani?","answer":"Whole black gram, sometimes labelled sabut urad, is what traditional dal makhani is built on."},{"question":"Is split urad dal the same pulse as whole black gram?","answer":"Yes, it is the same pulse, dehusked and split rather than a different crop entirely."},{"question":"Why do some packs say urad and others say black gram?","answer":"Regional and seller naming preference, both terms refer to the same pulse."},{"question":"Does the name affect how I should cook it?","answer":"No, check whether the pack is whole or split instead, since that is what actually determines cooking time and use."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same pulse under two names, one describing the whole grain, the other more often the processed form.', seo_description='Black gram compared with urad dal: whether they are the same thing, and what the naming actually signals.', seo_keywords='black gram vs urad dal', reading_minutes=2, published_version_id='arv_truegrit_151_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_151';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_151';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_151','Black Gram vs Urad Dal','black-gram-vs-urad-dal','The same pulse under two names, one describing the whole grain, the other more often the processed form.','black gram vs urad dal');

-- 152. Whole Urad vs Split Urad Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_152_2','art_truegrit_152',2,'{"blocks":[{"id":"blk_article_152_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole and split urad dal come from the same pulse, but removing the black skin and splitting the grain changes cooking time, texture and which dish each form is actually built for."]}},{"id":"blk_article_152_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Whole urad keeps its black skin, cooks slower and holds its shape well, suited to a long simmered dal makhani.","Split urad dal is dehusked and split, cooking faster and breaking down more readily into a smoother dal or batter.","Split urad dal is the standard base for dosa and idli batter, since its texture blends smoothly once ground and fermented.","Whole urad''s skin contributes a deeper, earthier flavour that split urad, without the skin, does not carry to the same degree.","Split urad also grinds more easily into a fine batter or flour, since there is no tough skin to work around."]}},{"id":"blk_article_152_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole and split urad","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal"],"limit":2}},{"id":"blk_article_152_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole vs split urad questions","items":[{"question":"Which urad is used for dosa batter?","answer":"Split, dehusked urad dal is the standard choice, since it grinds smoothly and ferments predictably."},{"question":"Does whole urad take much longer to cook?","answer":"Yes, noticeably, which is why traditional dal makhani recipes call for a long, slow simmer or an extended pressure cook."},{"question":"Can I use whole urad for vada instead of split?","answer":"Split is the more common choice since it grinds finer, though some regional recipes do use a mix."},{"question":"Does the skin add real flavour difference?","answer":"Yes, whole urad''s skin contributes a noticeably deeper, earthier taste that split urad lacks."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Skin on or off changes cooking time, texture and which dish each form actually suits.', seo_description='Whole urad compared with split urad dal: cooking time, texture, and which traditional dishes each suits.', seo_keywords='whole urad vs split urad dal', reading_minutes=3, published_version_id='arv_truegrit_152_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_152';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_152';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_152','Whole Urad vs Split Urad Dal','whole-urad-vs-split-urad-dal','Skin on or off changes cooking time, texture and which dish each form actually suits.','whole urad vs split urad dal');

-- 153. Black Gram vs Green Gram
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_153_2','art_truegrit_153',2,'{"blocks":[{"id":"blk_article_153_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram and green gram, urad and moong, are different pulses entirely, not two forms of the same crop. They differ in colour, weight on the plate and which dishes each one anchors."]}},{"id":"blk_article_153_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Black gram, urad, has a black skin and a heavier, earthier flavour. Green gram, moong, is lighter both in colour and in how it eats.","Moong is generally considered easier to digest and lighter on the stomach, which is why it is common in khichdi during recovery from illness.","Urad anchors heavier dishes like dal makhani and fermented batters. Moong anchors lighter dals and simple khichdi.","Both are pulses with real nutritional value, but they are not interchangeable in a recipe built around one specific texture.","Many households keep both stocked, reaching for whichever suits the day''s meal rather than treating one as a substitute for the other."]}},{"id":"blk_article_153_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal"],"limit":2}},{"id":"blk_article_153_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black gram vs green gram questions","items":[{"question":"Can I substitute moong for urad in dal makhani?","answer":"Not really, the dish''s heavier texture and flavour depend specifically on black gram, which moong will not replicate."},{"question":"Is moong lighter to digest than urad?","answer":"Generally considered so, which is part of why moong khichdi is a common choice during recovery from illness."},{"question":"Do black gram and green gram taste similar?","answer":"No, urad has a noticeably heavier, earthier flavour compared to moong''s lighter, milder taste."},{"question":"Is one more expensive than the other?","answer":"Pricing varies by season and region more than by one pulse being inherently pricier than the other."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Two different pulses entirely, differing in colour, weight and which dishes they traditionally anchor.', seo_description='Black gram compared with green gram: different pulses, different texture, and where each is traditionally used.', seo_keywords='black gram vs green gram, urad vs moong', reading_minutes=2, published_version_id='arv_truegrit_153_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_153';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_153';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_153','Black Gram vs Green Gram','black-gram-vs-green-gram','Two different pulses entirely, differing in colour, weight and which dishes they traditionally anchor.','black gram vs green gram, urad vs moong');

-- 154. Black Gram vs Chickpea
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_154_2','art_truegrit_154',2,'{"blocks":[{"id":"blk_article_154_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram and chickpea belong to entirely different pulse families and rarely compete for the same role in a recipe, which makes this less a direct rivalry and more a study in contrast."]}},{"id":"blk_article_154_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Black gram is small, black skinned and earthy. Chickpea is larger, tan coloured and firmer in bite.","Black gram anchors dal makhani, dosa batter and vada. Chickpea anchors chana masala, chole and hummus style preparations.","Ground black gram gives besan and sattu with a heavier, earthier character. Ground chickpea, the more familiar besan, is milder and more widely used.","Cooking times differ too, whole black gram generally softens faster than whole chickpeas of a similar size.","Neither pulse substitutes cleanly for the other, since the dishes each anchors depend on its particular texture and flavour."]}},{"id":"blk_article_154_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram","source":"manual","productSlugs":["black-gram-whole","black-gram-besan"],"limit":2}},{"id":"blk_article_154_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black gram vs chickpea questions","items":[{"question":"Is one more widely used across Indian cooking than the other?","answer":"Both are widely used, just for different dishes, chickpea for chana based curries, black gram for dal makhani and South Indian batters."},{"question":"Can black gram besan replace chickpea besan?","answer":"It can be used, but expect a heavier, earthier result rather than the lighter, more familiar chickpea besan texture."},{"question":"Does black gram cook faster than chickpea?","answer":"Whole black gram generally softens a little faster than whole chickpeas of similar size, though both benefit from soaking."},{"question":"Do you sell chickpea products?","answer":"No, our pulse range in this comparison covers black gram in its whole, split, besan and sattu forms."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Different pulse families entirely, occupying quite different roles across Indian cooking.', seo_description='Black gram compared with chickpea: different pulses, different texture, and how their culinary roles differ.', seo_keywords='black gram vs chickpea, urad vs chana', reading_minutes=2, published_version_id='arv_truegrit_154_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_154';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_154';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_154','Black Gram vs Chickpea','black-gram-vs-chickpea','Different pulse families entirely, occupying quite different roles across Indian cooking.','black gram vs chickpea, urad vs chana');

-- 155. How Urad Dal Is Traditionally Processed
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_155_2','art_truegrit_155',2,'{"blocks":[{"id":"blk_article_155_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Split urad dal starts as whole black gram and reaches its familiar pale form through cleaning, dehusking and splitting, a process similar in spirit to how daliya and semolina are made from whole wheat."]}},{"id":"blk_article_155_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The steps","items":["Whole black gram is cleaned to remove dust, stones and any damaged grain before processing continues.","The pulse is lightly dampened or conditioned, loosening the black skin without softening the grain itself too much.","Milling removes the skin, revealing the pale interior, and splits the grain in the same pass or a separate one.","The resulting split, skinned dal is sieved and graded before packaging, sorted by size and consistency.","Traditional stone milling can produce a slightly less uniform dal than a modern roller mill, which some cooks still prefer."]}},{"id":"blk_article_155_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Split urad","source":"manual","productSlugs":["black-gram-broken-dal"],"limit":1}},{"id":"blk_article_155_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad dal processing questions","items":[{"question":"Is dehusking the same as splitting?","answer":"They usually happen close together, but dehusking specifically removes the skin, while splitting separates the grain into halves."},{"question":"Does processing remove any nutritional value?","answer":"Removing the skin changes texture and some fibre content, a genuine processing trade-off rather than a quality defect."},{"question":"Why is whole black gram not simply split at home?","answer":"Dehusking and splitting need milling equipment beyond what a typical home kitchen has, which is why it is bought processed."},{"question":"Does the milling method affect flavour?","answer":"Subtly, a coarser or less uniform traditional milling can give a slightly different texture, though flavour differences are minor."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Cleaning, dehusking and splitting, the steps that turn whole black gram into the pale split dal most kitchens know.', seo_description='How urad dal is traditionally processed: cleaning, dehusking and splitting whole black gram.', seo_keywords='how urad dal is made, urad dal processing', reading_minutes=3, published_version_id='arv_truegrit_155_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_155';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_155';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_155','How Urad Dal Is Traditionally Processed','how-urad-dal-is-traditionally-processed','Cleaning, dehusking and splitting, the steps that turn whole black gram into the pale split dal most kitchens know.','how urad dal is made, urad dal processing');

-- 156. What Is Black Gram Sattu?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_156_2','art_truegrit_156',2,'{"blocks":[{"id":"blk_article_156_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram sattu is roasted black gram ground into a fine, protein rich flour, used either mixed into a drink or as a stuffing filling, a heavier alternative to the more widely known chana sattu."]}},{"id":"blk_article_156_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Made by roasting whole black gram and grinding it into a fine flour, a process that develops a distinct earthy, nutty flavour.","Used two main ways, mixed into water as a drink, or as a savoury filling for paratha stuffing.","Carries a heavier, earthier flavour than chana sattu, reflecting the difference between the two source pulses.","Already roasted before grinding, so unlike besan it needs no additional cooking before being eaten or drunk.","High in protein, which is part of why sattu drinks have long been a filling, energising option in hot weather."]}},{"id":"blk_article_156_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram sattu","source":"manual","productSlugs":["black-gram-sattu"],"limit":1}},{"id":"blk_article_156_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black gram sattu questions","items":[{"question":"Does black gram sattu need cooking?","answer":"No, it is already roasted before grinding, so it can be eaten or drunk as is, mixed with water or other ingredients."},{"question":"Is black gram sattu the same as regular sattu?","answer":"Sattu can be made from different pulses. Black gram sattu is one variant, chana sattu being the more commonly known one."},{"question":"How is black gram sattu traditionally eaten?","answer":"Most commonly as a mixed drink with water, salt or sugar, or as a filling for stuffed paratha."},{"question":"Does black gram sattu taste different from chana sattu?","answer":"Yes, noticeably heavier and earthier, reflecting the difference between black gram and chickpea as the base pulse."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Roasted black gram ground fine, eaten as a drink or filling, a heavier alternative to the more familiar chana sattu.', seo_description='Black gram sattu explained: how it is made, how it is used, and how it differs from the more familiar chana sattu.', seo_keywords='black gram sattu, urad sattu, what is sattu', reading_minutes=3, published_version_id='arv_truegrit_156_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_156';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_156';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_156','What Is Black Gram Sattu?','what-is-black-gram-sattu','Roasted black gram ground fine, eaten as a drink or filling, a heavier alternative to the more familiar chana sattu.','black gram sattu, urad sattu, what is sattu');

-- 157. Black Gram Sattu vs Chana Sattu
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_157_2','art_truegrit_157',2,'{"blocks":[{"id":"blk_article_157_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Chana sattu, made from roasted chickpea, is the more widely recognised version across North India, particularly Bihar. Black gram sattu is a heavier, earthier variant made from a different base pulse entirely."]}},{"id":"blk_article_157_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Chana sattu is made from roasted chickpea. Black gram sattu is made from roasted urad, a different pulse with a heavier flavour.","Chana sattu is the more traditional, widely known version, especially central to Bihari cuisine.","Black gram sattu carries a noticeably earthier, heavier taste than the milder, more familiar chana sattu.","Both are used similarly, as a mixed drink or a paratha filling, just with a different flavour profile underlying each.","Neither is a straightforward substitute for the other in a recipe specifically built around one sattu''s particular flavour."]}},{"id":"blk_article_157_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram sattu","source":"manual","productSlugs":["black-gram-sattu"],"limit":1}},{"id":"blk_article_157_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black gram vs chana sattu questions","items":[{"question":"Which sattu is more common in Bihari cooking?","answer":"Chana sattu is the more traditional and widely used version in Bihari cuisine specifically."},{"question":"Can I substitute black gram sattu for chana sattu?","answer":"You can, but expect a heavier, earthier flavour rather than the milder taste chana sattu recipes typically assume."},{"question":"Do you sell chana sattu?","answer":"No, our sattu range covers black gram sattu specifically."},{"question":"Is black gram sattu less common for a reason?","answer":"It is more of a regional variant than a lesser product, reflecting local pulse availability more than a quality difference."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Chana sattu is the more traditional, widely known version. Black gram sattu is a heavier regional variant.', seo_description='Black gram sattu compared with chana sattu: flavour, tradition, and which suits which use.', seo_keywords='black gram sattu vs chana sattu', reading_minutes=2, published_version_id='arv_truegrit_157_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_157';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_157';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_157','Black Gram Sattu vs Chana Sattu','black-gram-sattu-vs-chana-sattu','Chana sattu is the more traditional, widely known version. Black gram sattu is a heavier regional variant.','black gram sattu vs chana sattu');

-- 158. What Is Black Gram Besan?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_158_2','art_truegrit_158',2,'{"blocks":[{"id":"blk_article_158_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram besan is flour ground from raw, unroasted black gram, distinct from both the more familiar chickpea besan and from sattu, which starts with roasting before grinding."]}},{"id":"blk_article_158_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines it","items":["Ground from raw black gram, not roasted first, distinguishing it from sattu, which is roasted before grinding.","Heavier and earthier in flavour than the standard chickpea besan most Indian kitchens default to.","Absorbs more water in a batter than chickpea besan does, which changes texture if a recipe is not adjusted for it.","Used mainly in chilla and other savoury pancake style dishes, where its heavier body works well.","Needs cooking, unlike sattu, since it is a raw flour rather than a roasted, ready to eat one.","Rest the batter briefly after mixing, which gives the flour time to hydrate fully before it hits the pan."]}},{"id":"blk_article_158_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram besan","source":"manual","productSlugs":["black-gram-besan"],"limit":1}},{"id":"blk_article_158_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black gram besan questions","items":[{"question":"Is black gram besan the same as regular besan?","answer":"No, standard besan is usually chickpea flour. Black gram besan is a distinct, heavier flour ground from a different pulse."},{"question":"Can black gram besan be eaten raw like sattu?","answer":"No, it needs cooking. Sattu is roasted before grinding, which is what makes it ready to eat as is."},{"question":"Does black gram besan need more water in a batter?","answer":"Generally yes, it absorbs more liquid than chickpea besan, so recipes may need adjusting for consistency."},{"question":"What dishes suit black gram besan best?","answer":"Chilla and other savoury pancake style dishes, where its heavier texture and earthy flavour work well."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Flour ground from raw black gram, heavier and earthier than the familiar chickpea besan most kitchens use.', seo_description='Black gram besan explained: how it is made, how it differs from standard chickpea besan, and how it is used.', seo_keywords='black gram besan, urad besan', reading_minutes=2, published_version_id='arv_truegrit_158_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_158';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_158';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_158','What Is Black Gram Besan?','what-is-black-gram-besan','Flour ground from raw black gram, heavier and earthier than the familiar chickpea besan most kitchens use.','black gram besan, urad besan');

-- 159. Black Gram Besan vs Chickpea Besan
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_159_2','art_truegrit_159',2,'{"blocks":[{"id":"blk_article_159_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Switching from chickpea besan to black gram besan changes more than flavour. The batter itself behaves differently, and a recipe built around one does not automatically work with the other."]}},{"id":"blk_article_159_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Black gram besan feels heavier and holds more water than chickpea besan, changing how a batter comes together.","The finished dish, like chilla, tends to be softer and less crisp at the edges with black gram besan than with chickpea besan.","Flavour is noticeably earthier with black gram besan, milder and more neutral with the standard chickpea version.","Ratios and rest time may need adjusting when switching between the two, since black gram besan''s batter behaves differently.","Neither is simply better. The choice depends on the texture and flavour you actually want in the finished dish."]}},{"id":"blk_article_159_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook switching from chickpea to black gram besan for chilla describes exactly this heavier, softer result and asks how others adjust their ratios](/community/dsc_truegrit_010), a useful read before your first batch."]}},{"id":"blk_article_159_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram besan","source":"manual","productSlugs":["black-gram-besan"],"limit":1}},{"id":"blk_article_159_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Besan comparison questions","items":[{"question":"Why is my black gram besan chilla softer than usual?","answer":"Black gram besan holds more water and generally gives a softer result with less crisp edges than chickpea besan."},{"question":"Should I thin the batter differently for black gram besan?","answer":"Many cooks thin it slightly less or rest it longer, since it absorbs more water than chickpea besan does."},{"question":"Does black gram besan taste very different?","answer":"Yes, noticeably earthier than the milder, more neutral flavour of standard chickpea besan."},{"question":"Can I mix the two besans together?","answer":"Yes, some cooks blend both for a middle ground of texture and flavour, adjusting water as needed."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Heavier, thirstier and earthier. The real differences a cook notices switching from one to the other.', seo_description='Black gram besan compared with chickpea besan: texture, water absorption, flavour and how to adjust a recipe.', seo_keywords='black gram besan vs chickpea besan', reading_minutes=3, published_version_id='arv_truegrit_159_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_159';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_159';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_159','Black Gram Besan vs Chickpea Besan','black-gram-besan-vs-chickpea-besan','Heavier, thirstier and earthier. The real differences a cook notices switching from one to the other.','black gram besan vs chickpea besan');

-- 160. Sattu vs Besan: What’s the Difference?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_160_2','art_truegrit_160',2,'{"blocks":[{"id":"blk_article_160_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sattu and besan can come from the same pulse and still be entirely different products, because one crucial step, roasting, happens before grinding for one and not the other."]}},{"id":"blk_article_160_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Sattu is roasted before grinding, making it ready to eat or drink as is. Besan is ground raw and always needs cooking.","Sattu is typically mixed into a drink or used as a filling. Besan is cooked into batters like chilla or pakora.","Flavour differs too, roasting gives sattu a toasted depth that raw besan does not carry until it is cooked.","Both can be made from black gram specifically, sharing a base pulse but ending up as very different pantry staples.","Checking whether a product is labelled sattu or besan tells you immediately whether it needs cooking or not."]}},{"id":"blk_article_160_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Both from black gram","source":"manual","productSlugs":["black-gram-sattu","black-gram-besan"],"limit":2}},{"id":"blk_article_160_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sattu vs besan questions","items":[{"question":"Can besan be eaten raw like sattu?","answer":"No, besan is a raw ground flour and needs cooking. Sattu is already roasted, which is what makes it ready to eat."},{"question":"Is sattu just roasted besan?","answer":"Effectively, yes, though the grinding stage and end use both differ enough that they are treated as separate products."},{"question":"Can I substitute sattu for besan in a chilla recipe?","answer":"No, sattu''s roasted flavour and different texture will not behave like raw besan when cooked into a batter."},{"question":"Do both come from black gram?","answer":"Both can, and both of ours do, though sattu and besan are also commonly made from other pulses like chickpea."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Roasted and ready to eat against raw and needing cooking. The processing step is the whole story.', seo_description='Sattu compared with besan: roasting, texture, and why one can be eaten raw while the other cannot.', seo_keywords='sattu vs besan, difference between sattu and besan', reading_minutes=2, published_version_id='arv_truegrit_160_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_160';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_160';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_160','Sattu vs Besan: What’s the Difference?','sattu-vs-besan-what-s-the-difference','Roasted and ready to eat against raw and needing cooking. The processing step is the whole story.','sattu vs besan, difference between sattu and besan');

-- 161. Whole Pulse vs Dal vs Flour
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_161_2','art_truegrit_161',2,'{"blocks":[{"id":"blk_article_161_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole pulse, split dal and flour are not three different ingredients so much as three stages of the same one. Black gram makes the pattern especially clear, since all three forms are common and used quite differently."]}},{"id":"blk_article_161_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The three stages","items":["Whole pulse, unprocessed beyond cleaning, keeps its skin and full shape, cooking slowly into dishes like dal makhani.","Dal, dehusked and split, cooks faster and suits tempered dals, khichdi and fermented batters like dosa.","Flour, ground fine either raw as besan or roasted as sattu, moves furthest from the original pulse shape and into batters, fillings or drinks.","Each stage trades cooking time and versatility for a different texture, with no single form being simply the best.","Keeping a household stocked with more than one form, rather than just one, covers a wider range of dishes without special shopping trips."]}},{"id":"blk_article_161_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"All three forms","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal","black-gram-besan"],"limit":3}},{"id":"blk_article_161_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Pulse processing questions","items":[{"question":"Is flour always the most processed form?","answer":"Yes, of the three, flour moves furthest from the whole pulse, whether ground raw as besan or roasted first as sattu."},{"question":"Does more processing mean less nutritional value?","answer":"Processing changes texture and some fibre content more than it strips out nutrition broadly, though it is a real trade-off worth knowing about."},{"question":"Which form should a beginner start with?","answer":"Split dal is generally the most versatile starting point, cooking faster than whole pulse while suiting more dishes than flour alone."},{"question":"Can I grind whole pulse into flour myself?","answer":"Not practically at home. Milling into besan or sattu needs equipment beyond a typical home kitchen."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Three stages of the same pulse, each suited to different dishes, using black gram as the example.', seo_description='Whole pulse, dal and flour explained using black gram: what changes at each processing stage and why it matters.', seo_keywords='whole pulse vs dal vs flour, pulse processing stages', reading_minutes=3, published_version_id='arv_truegrit_161_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_161';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_161';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_161','Whole Pulse vs Dal vs Flour','whole-pulse-vs-dal-vs-flour','Three stages of the same pulse, each suited to different dishes, using black gram as the example.','whole pulse vs dal vs flour, pulse processing stages');

-- 162. How to Store Urad Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_162_2','art_truegrit_162',2,'{"blocks":[{"id":"blk_article_162_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Urad dal stores well with basic care, though whole and split forms behave a little differently once in the pantry, which is worth knowing before you buy in bulk."]}},{"id":"blk_article_162_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Keep urad dal in an airtight container, away from humidity, which can encourage both spoilage and pests.","Whole black gram, with its skin intact, generally keeps a little longer than split dal, which has more exposed surface.","Check periodically for weevils or other pests, especially in a humid climate or during monsoon months.","Store away from direct sunlight and heat sources, which can gradually affect both flavour and cooking behaviour over time.","Buy quantities you will realistically use within a few months rather than stocking more than your kitchen turns over."]}},{"id":"blk_article_162_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Urad to store","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal"],"limit":2}},{"id":"blk_article_162_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad dal storage questions","items":[{"question":"Does split urad dal spoil faster than whole?","answer":"It can, since dehusking exposes more surface area, though both keep well for months if stored properly."},{"question":"How do I check for weevils in stored dal?","answer":"Look for small holes, fine dust, or actual insects. Freezing new stock briefly before storing can help prevent an infestation taking hold."},{"question":"Can urad dal be stored in the refrigerator?","answer":"It is not necessary in most climates, though it can help extend freshness in a hot, humid environment."},{"question":"How long does urad dal last if stored well?","answer":"Generally six months to a year in an airtight container kept cool and dry, sometimes longer for whole grain."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Airtight, cool and dry, with whole and split forms keeping slightly differently once stored.', seo_description='How to store urad dal properly: airtight containers, checking for pests, and how whole differs from split.', seo_keywords='how to store urad dal, urad dal storage tips', reading_minutes=2, published_version_id='arv_truegrit_162_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_162';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_162';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_162','How to Store Urad Dal','how-to-store-urad-dal','Airtight, cool and dry, with whole and split forms keeping slightly differently once stored.','how to store urad dal, urad dal storage tips');

-- 163. How to Identify Good Quality Pulses
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_163_2','art_truegrit_163',2,'{"blocks":[{"id":"blk_article_163_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Good quality pulses are easy to check with a quick look before buying, and the same basic signs apply whether you are looking at black gram, red lentils or any other dal."]}},{"id":"blk_article_163_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually check","items":["Colour should be reasonably uniform across the batch, without a large proportion of noticeably discoloured or faded grains.","Size and shape should be fairly consistent, since a lot of variation can mean a poorly sorted or mixed batch.","Check for dust, stones or visible debris in the packet, which suggests less careful cleaning before packaging.","Look closely for small holes or fine powder, both signs of insect activity that a good batch should not show.","A large proportion of broken pieces, rather than mostly whole grains, is a sign of lower grade sorting."]}},{"id":"blk_article_163_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal"],"limit":2}},{"id":"blk_article_163_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Pulse quality questions","items":[{"question":"Does colour variation always mean poor quality?","answer":"Some natural variation is normal, but a large proportion of faded or discoloured grains is worth questioning."},{"question":"Is a small amount of dust in the packet normal?","answer":"A trace amount can happen even with careful processing, but a noticeable layer suggests less thorough cleaning."},{"question":"How can I tell if pulses have insect damage before cooking?","answer":"Look for small holes in individual grains or fine powder settled at the bottom of the packet."},{"question":"Does a higher proportion of broken pieces affect cooking?","answer":"It can cause uneven cooking, since broken pieces soften faster than whole ones in the same pot."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Colour, uniformity and a quick look for damage tell you more than a brand name does.', seo_description='How to identify good quality pulses: colour, uniformity, debris, and simple checks before buying.', seo_keywords='how to identify good pulses, pulse quality check', reading_minutes=3, published_version_id='arv_truegrit_163_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_163';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_163';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_163','How to Identify Good Quality Pulses','how-to-identify-good-quality-pulses','Colour, uniformity and a quick look for damage tell you more than a brand name does.','how to identify good pulses, pulse quality check');

-- 164. Traditional Dal Makhani Using Whole Black Gram
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_164_2','art_truegrit_164',2,'{"blocks":[{"id":"blk_article_164_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Dal makhani''s depth comes mostly from time, not a long ingredient list. Whole black gram simmered slowly, with butter and cream added toward the end, is the traditional foundation most recipes still follow."]}},{"id":"blk_article_164_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Soak whole black gram overnight, which shortens cooking time and gives a more even, less patchy final texture.","Pressure cook until fully tender, then simmer uncovered on low heat for as long as you reasonably can, traditionally an hour or more.","Build a simple base of onion, tomato, ginger and garlic, kept relatively restrained so the black gram''s own flavour carries through.","Add butter partway through the long simmer, and cream toward the very end, rather than all at once at the start.","The long, slow simmer, more than any single ingredient, is what gives traditional dal makhani its characteristic depth and body."]}},{"id":"blk_article_164_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook compares soaking whole black gram overnight against pressure cooking straight from dry](/community/dsc_truegrit_012), useful if you are deciding whether the extra step is worth it for you."]}},{"id":"blk_article_164_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole black gram","source":"manual","productSlugs":["black-gram-whole"],"limit":1}},{"id":"blk_article_164_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Dal makhani questions","items":[{"question":"Do I have to soak whole black gram overnight?","answer":"It is not strictly required, but it shortens cooking time and gives a more even texture than skipping the soak."},{"question":"How long should dal makhani actually simmer?","answer":"As long as practical, traditionally an hour or more on low heat, which is what builds its characteristic depth."},{"question":"Can I make dal makhani without cream?","answer":"Yes, though the texture will be lighter. A little extra butter can help compensate for some of the richness."},{"question":"Why does my dal makhani taste thin compared to a restaurant version?","answer":"Usually not enough simmering time. The long, slow cook is what builds the dish''s body more than any single ingredient."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A long, slow simmer is the real secret, more than any single spice or amount of butter.', seo_description='Traditional dal makhani using whole black gram: soaking, slow cooking, and what actually builds the dish''s depth.', seo_keywords='dal makhani recipe, whole black gram dal makhani', reading_minutes=3, published_version_id='arv_truegrit_164_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_164';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_164';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_164','Traditional Dal Makhani Using Whole Black Gram','traditional-dal-makhani-using-whole-black-gram','A long, slow simmer is the real secret, more than any single spice or amount of butter.','dal makhani recipe, whole black gram dal makhani');

-- 165. Urad Dal Tadka
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_165_2','art_truegrit_165',2,'{"blocks":[{"id":"blk_article_165_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Urad dal tadka keeps the dish simple, letting split black gram''s own earthy flavour do most of the work, finished with a straightforward tempering rather than a long spice list."]}},{"id":"blk_article_165_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Cook split urad dal with turmeric and salt until soft, either in a pressure cooker or a covered pot.","Prepare a tempering separately, cumin seeds, garlic and dried red chilli in ghee or oil until fragrant.","Pour the hot tempering over the cooked dal just before serving, rather than mixing it in during cooking.","A squeeze of lemon and fresh coriander at the end brightens the dal''s naturally heavier, earthier flavour.","Adjust consistency with a little hot water if the dal has thickened more than you want by the time it is done."]}},{"id":"blk_article_165_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Split urad","source":"manual","productSlugs":["black-gram-broken-dal"],"limit":1}},{"id":"blk_article_165_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad dal tadka questions","items":[{"question":"Should I soak split urad dal before cooking?","answer":"A short soak, twenty to thirty minutes, helps but is not strictly necessary since split dal cooks reasonably quickly either way."},{"question":"Can I add vegetables to this dal?","answer":"Yes, spinach or other greens work well stirred in toward the end of cooking."},{"question":"Why does my urad dal tadka taste bland?","answer":"Check the tempering, freshly heated ghee or oil with properly bloomed spices makes a noticeable difference to the final flavour."},{"question":"Is this dal similar to dal makhani?","answer":"Related in flavour but much simpler and faster, since it skips the long simmer and butter and cream finish."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A simple tempered dal that leans on the pulse''s own earthy flavour rather than a heavy spice list.', seo_description='A simple urad dal tadka recipe: cooking the split dal and building a straightforward tempering to finish it.', seo_keywords='urad dal tadka, urad dal recipe', reading_minutes=2, published_version_id='arv_truegrit_165_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_165';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_165';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_165','Urad Dal Tadka','urad-dal-tadka','A simple tempered dal that leans on the pulse''s own earthy flavour rather than a heavy spice list.','urad dal tadka, urad dal recipe');

-- 166. Urad Dal Khichdi
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_166_2','art_truegrit_166',2,'{"blocks":[{"id":"blk_article_166_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Urad dal khichdi trades moong''s lightness for a heavier, earthier bowl, built the same basic way but landing quite differently on the plate once it is done."]}},{"id":"blk_article_166_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Cook rice and split urad dal together with turmeric and salt, in roughly the same ratio a moong khichdi would use.","Expect a heavier, more textured result than moong khichdi, since urad''s flavour and body are more pronounced.","A simple tempering of cumin, ghee and asafoetida finishes it, the same basic approach most khichdi recipes share.","Adjust water for a thicker or looser consistency depending on preference, urad tends to thicken more as it sits.","Pairs well with a simple yoghurt or pickle on the side, cutting through the dish''s heavier character.","A little extra ghee stirred in at the end rounds out the flavour further, the same trick many khichdi recipes rely on."]}},{"id":"blk_article_166_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Split urad for khichdi","source":"manual","productSlugs":["black-gram-broken-dal"],"limit":1}},{"id":"blk_article_166_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad khichdi questions","items":[{"question":"How is urad khichdi different from moong khichdi?","answer":"Noticeably heavier and earthier, since black gram has a stronger flavour and body than the lighter, milder moong."},{"question":"Is urad khichdi harder to digest than moong khichdi?","answer":"Generally considered a little heavier on the stomach, which is why moong is more commonly used for a very light meal."},{"question":"Can I add vegetables to urad khichdi?","answer":"Yes, the same way you would with any khichdi, added partway through cooking so they finish tender."},{"question":"Does urad khichdi thicken a lot on standing?","answer":"Yes, more than a moong version, so add a little hot water when reheating if it has thickened too much."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A heavier, earthier take on khichdi than the usual moong version, built around split black gram.', seo_description='Urad dal khichdi: how it differs from moong khichdi, and a simple method for cooking it well.', seo_keywords='urad dal khichdi, black gram khichdi', reading_minutes=2, published_version_id='arv_truegrit_166_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_166';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_166';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_166','Urad Dal Khichdi','urad-dal-khichdi','A heavier, earthier take on khichdi than the usual moong version, built around split black gram.','urad dal khichdi, black gram khichdi');

-- 167. Urad Dal Chilla
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_167_2','art_truegrit_167',2,'{"blocks":[{"id":"blk_article_167_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Urad dal chilla starts from the soaked, ground pulse itself rather than a pre-ground flour, giving it a different texture from the more familiar besan version most households already make."]}},{"id":"blk_article_167_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Soak split urad dal for a few hours, then grind with a small amount of water into a smooth, thick batter.","Season the batter with salt, green chilli, ginger and chopped coriander, mixed in just before cooking.","Spread thinly on a hot, lightly oiled griddle, the same technique used for a standard besan chilla.","Cook until the edges lift and the underside is golden, then flip and finish the other side briefly.","Serve hot with chutney or pickle, the same accompaniments a besan chilla would typically pair with.","A drizzle of oil around the edges while cooking helps it release cleanly from the griddle once done."]}},{"id":"blk_article_167_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Urad for chilla","source":"manual","productSlugs":["black-gram-broken-dal"],"limit":1}},{"id":"blk_article_167_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad dal chilla questions","items":[{"question":"How is this different from besan chilla?","answer":"This starts from soaked, freshly ground split urad dal rather than a pre-ground flour, giving a different texture and flavour."},{"question":"How long should urad dal soak before grinding?","answer":"A few hours is generally enough, though soaking longer, even overnight, works fine too."},{"question":"Can I ferment the batter like a dosa?","answer":"Some cooks let it sit for a short ferment for extra flavour, though it is not required for a basic chilla."},{"question":"Why is my urad dal chilla sticking to the pan?","answer":"Usually the pan was not hot enough or not oiled evenly before the batter went on."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A savoury pancake built on soaked, ground urad dal, distinct from the more familiar besan chilla.', seo_description='How to make urad dal chilla: soaking, grinding and cooking a savoury pancake from split black gram.', seo_keywords='urad dal chilla recipe, black gram chilla', reading_minutes=2, published_version_id='arv_truegrit_167_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_167';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_167';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_167','Urad Dal Chilla','urad-dal-chilla','A savoury pancake built on soaked, ground urad dal, distinct from the more familiar besan chilla.','urad dal chilla recipe, black gram chilla');

-- 168. Black Gram Sattu Drink
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_168_2','art_truegrit_168',2,'{"blocks":[{"id":"blk_article_168_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A black gram sattu drink is simple in theory, sattu mixed into water, but getting a smooth result rather than a gritty one takes a small technique adjustment most people discover by trial and error."]}},{"id":"blk_article_168_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to make it well","items":["Start with a small amount of water and the sattu, mixing into a thick, smooth paste before thinning further.","Adding all the water at once tends to leave sattu settling into a gritty layer rather than blending in evenly.","Once the paste is smooth, thin it gradually with more water, whisking as you go, to your preferred consistency.","Season with salt, roasted cumin and a little lemon for a savoury version, or jaggery for a sweet one.","Drink soon after mixing, since sattu can settle again over time even after being properly blended in."]}},{"id":"blk_article_168_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One person describes exactly this settling problem and asks whether making a thick paste first genuinely fixes it](/community/dsc_truegrit_009), a useful confirmation if you have run into the same thing."]}},{"id":"blk_article_168_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram sattu","source":"manual","productSlugs":["black-gram-sattu"],"limit":1}},{"id":"blk_article_168_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Sattu drink questions","items":[{"question":"Why does my sattu drink separate at the bottom of the glass?","answer":"Usually the water was added too quickly. Making a thick paste first, then thinning gradually, largely fixes this."},{"question":"Does water temperature matter for mixing sattu?","answer":"Room temperature or cool water generally works well. Very cold water can make the paste stage a little harder to smooth out."},{"question":"Can I make a sattu drink ahead of time?","answer":"It is best drunk soon after mixing, since sattu can settle again even after being properly blended in."},{"question":"Is the sweet or savoury version more traditional?","answer":"Both have long traditions, the choice tends to come down to regional and personal preference rather than one being more authentic."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A simple, filling drink, with one common texture problem and an easy fix for it.', seo_description='How to make a black gram sattu drink: method, common texture problems, and how to fix them.', seo_keywords='black gram sattu drink, sattu drink recipe', reading_minutes=2, published_version_id='arv_truegrit_168_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_168';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_168';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_168','Black Gram Sattu Drink','black-gram-sattu-drink','A simple, filling drink, with one common texture problem and an easy fix for it.','black gram sattu drink, sattu drink recipe');

-- 169. Savoury Sattu Drink
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_169_2','art_truegrit_169',2,'{"blocks":[{"id":"blk_article_169_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The savoury sattu drink leans fully into salt, roasted cumin and lemon, a traditional combination that pairs well with sattu''s naturally earthy flavour rather than fighting it."]}},{"id":"blk_article_169_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Mix sattu into a small amount of water first, forming a smooth, thick paste before adding more liquid.","Thin gradually with cool water, whisking to avoid the settling that happens when water is added too quickly.","Season with salt, roasted cumin powder and a good squeeze of lemon, adjusting each to taste.","A small pinch of black salt and finely chopped green chilli or mint are common regional additions.","Serve immediately, ideally chilled, since this is typically drunk fresh rather than stored for later.","Some households add a little roasted onion or garlic for a more savoury, heartier version still built on the same base."]}},{"id":"blk_article_169_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"For savoury sattu","source":"manual","productSlugs":["black-gram-sattu"],"limit":1}},{"id":"blk_article_169_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Savoury sattu drink questions","items":[{"question":"What makes this different from the basic sattu drink?","answer":"It leans fully savoury, with roasted cumin, lemon and often black salt, rather than being left plain or sweetened."},{"question":"Can I add mint to a savoury sattu drink?","answer":"Yes, finely chopped mint is a common addition that pairs well with the cumin and lemon."},{"question":"Should the drink be served hot or cold?","answer":"Cold or at room temperature is standard, especially since it is often drunk as a cooling option in hot weather."},{"question":"Is roasted cumin necessary, or can I use regular?","answer":"Roasted cumin gives a deeper flavour, though plain cumin powder works in a pinch."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Salt, roasted cumin and lemon, built the same way as the base drink but leaning fully savoury.', seo_description='A savoury black gram sattu drink recipe: seasoning, method, and tips for a smooth, well balanced result.', seo_keywords='savoury sattu drink recipe', reading_minutes=2, published_version_id='arv_truegrit_169_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_169';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_169';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_169','Savoury Sattu Drink','savoury-sattu-drink','Salt, roasted cumin and lemon, built the same way as the base drink but leaning fully savoury.','savoury sattu drink recipe');

-- 170. Black Gram Sattu Paratha
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_170_2','art_truegrit_170',2,'{"blocks":[{"id":"blk_article_170_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sattu paratha''s biggest common problem is a filling that stays powdery and cracks the dough while rolling, usually because the fix people reach for first, more oil, is not actually what the filling needs."]}},{"id":"blk_article_170_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Mix sattu with finely chopped onion, green chilli, ajwain, a little mustard oil and salt into a filling.","If the filling stays powdery and does not hold together, add a small amount of water rather than more oil.","Letting the mixed filling sit for a few minutes lets the onion release some moisture, which also helps it bind.","Divide dough and filling into equal portions, seal the filling inside carefully, and roll gently to avoid tearing.","Cook on a medium hot tawa with a little oil or ghee, turning until both sides are evenly golden."]}},{"id":"blk_article_170_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook describes the exact same powdery, cracking filling and gets a suggestion to add water rather than more oil](/community/dsc_truegrit_013), worth reading if you have hit the same wall."]}},{"id":"blk_article_170_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram sattu","source":"manual","productSlugs":["black-gram-sattu"],"limit":1}},{"id":"blk_article_170_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Sattu paratha questions","items":[{"question":"Why does my sattu filling keep cracking the dough?","answer":"The filling is usually too dry. A small amount of water, rather than more oil, helps it bind into a cohesive mass."},{"question":"How long should the filling rest before stuffing?","answer":"A few minutes is usually enough for the onion to release moisture and help the mixture come together."},{"question":"Can I add other vegetables to the filling?","answer":"Yes, though keep additions modest so the filling does not become too wet or too bulky to seal properly."},{"question":"What oil is traditionally used in the filling?","answer":"Mustard oil is a common traditional choice, adding its own distinct pungency to the finished paratha."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A filling that wants moisture more than fat, the fix for a stuffing that keeps drying out and cracking the dough.', seo_description='Black gram sattu paratha: how to make a filling that binds properly rather than cracking the dough while rolling.', seo_keywords='sattu paratha recipe, black gram sattu paratha', reading_minutes=3, published_version_id='arv_truegrit_170_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_170';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_170';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_170','Black Gram Sattu Paratha','black-gram-sattu-paratha','A filling that wants moisture more than fat, the fix for a stuffing that keeps drying out and cracking the dough.','sattu paratha recipe, black gram sattu paratha');

-- 171. Black Gram Besan Chilla
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_171_2','art_truegrit_171',2,'{"blocks":[{"id":"blk_article_171_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram besan chilla needs its own ratios rather than a straight swap for a chickpea besan recipe, since the batter behaves differently from the start."]}},{"id":"blk_article_171_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Whisk black gram besan with water gradually, expecting to need more liquid than a chickpea besan batter would.","Season with salt, chopped onion, green chilli, coriander and a pinch of ajwain, the same standard chilla additions.","Rest the batter briefly, a little longer than you might for chickpea besan, to let it fully hydrate.","Cook on a hot, lightly oiled griddle, expecting a softer result with less crisp edges than a chickpea version.","Cook a touch longer per side if needed, since the denser batter can take slightly more time to set through.","Serve hot, since this style firms up less on standing than a crisper chickpea besan chilla would."]}},{"id":"blk_article_171_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram besan","source":"manual","productSlugs":["black-gram-besan"],"limit":1}},{"id":"blk_article_171_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Black gram besan chilla questions","items":[{"question":"Why is my black gram besan chilla soft rather than crisp?","answer":"This is expected. Black gram besan holds more water and typically gives a softer result than chickpea besan does."},{"question":"Should I thin the batter more for black gram besan?","answer":"Generally you will need more water than a chickpea besan recipe calls for, added gradually until it reaches the right consistency."},{"question":"Can I mix black gram and chickpea besan for this recipe?","answer":"Yes, blending the two is a common way to get a middle ground of texture between soft and crisp."},{"question":"Does black gram besan chilla taste very different?","answer":"Yes, noticeably earthier than the milder flavour of a standard chickpea besan chilla."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Heavier and softer than the standard version, with a batter that needs its own ratios rather than a direct swap.', seo_description='Black gram besan chilla: a recipe adjusted for the heavier, thirstier texture of black gram besan.', seo_keywords='black gram besan chilla recipe', reading_minutes=2, published_version_id='arv_truegrit_171_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_171';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_171';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_171','Black Gram Besan Chilla','black-gram-besan-chilla','Heavier and softer than the standard version, with a batter that needs its own ratios rather than a direct swap.','black gram besan chilla recipe');

-- 172. Traditional Urad Papad
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_172_2','art_truegrit_172',2,'{"blocks":[{"id":"blk_article_172_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Urad papad is traditionally a household batch process, rolled thin and sun dried over days, more than a quick recipe made fresh for a single meal."]}},{"id":"blk_article_172_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How it is traditionally made","items":["Split urad dal is soaked, ground into a thick paste, and mixed with spices like black pepper, cumin and asafoetida.","The dough is rolled or pressed into thin discs, traditionally by hand, though modern methods use simple presses too.","Discs are laid out to sun dry over one or more days, turned periodically until fully dried and crisp.","Once dried, papad keeps for months in an airtight container, ready to fry or roast whenever needed.","Regional recipes vary in spicing, some adding black pepper heavily, others keeping the base plain for versatility.","Humid weather can slow drying considerably, which is why papad making is traditionally timed to drier months."]}},{"id":"blk_article_172_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Urad for papad","source":"manual","productSlugs":["black-gram-broken-dal","black-gram-besan"],"limit":2}},{"id":"blk_article_172_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad papad questions","items":[{"question":"Can papad be made without sun drying?","answer":"Sun drying is traditional, though a low oven or dehydrator can substitute if sunlight and time are limited."},{"question":"How long does urad papad keep once dried?","answer":"Several months in an airtight container, kept away from humidity, which can soften it prematurely."},{"question":"Is urad papad fried or roasted before eating?","answer":"Either works, frying gives a puffier, richer result, roasting over a flame is the lighter alternative."},{"question":"Can I buy pre-made urad papad instead of making it?","answer":"Yes, ready made papad is widely available, though many households still make their own in batches seasonally."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A thin, sun dried crisp made from urad, traditionally a household batch process rather than a quick recipe.', seo_description='Traditional urad papad explained: how it is made, sun drying, and how it differs from other papad styles.', seo_keywords='urad papad, black gram papad', reading_minutes=2, published_version_id='arv_truegrit_172_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_172';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_172';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_172','Traditional Urad Papad','traditional-urad-papad','A thin, sun dried crisp made from urad, traditionally a household batch process rather than a quick recipe.','urad papad, black gram papad');

-- 173. Urad Dal Vada
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_173_2','art_truegrit_173',2,'{"blocks":[{"id":"blk_article_173_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A good urad dal vada depends on a batter light enough to float, which comes down to soaking time and how much air gets beaten in, more than any single ingredient in the mix."]}},{"id":"blk_article_173_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Soak split urad dal for at least three to four hours, longer if your kitchen tends to run cool.","Grind with as little water as possible into a thick, smooth batter, since too much water works against a light texture.","Beat the batter by hand or with a whisk for several minutes, incorporating air until it noticeably lightens.","Test readiness by dropping a small amount into water. A properly beaten batter floats rather than sinking.","Shape and fry in hot oil once the batter passes the float test, adjusting heat to avoid a pale, undercooked centre."]}},{"id":"blk_article_173_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook whose vada consistently sinks rather than floats asks about soaking time and beating method](/community/dsc_truegrit_011), a useful comparison if your batter is not passing the float test either."]}},{"id":"blk_article_173_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Urad for vada","source":"manual","productSlugs":["black-gram-broken-dal"],"limit":1}},{"id":"blk_article_173_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad dal vada questions","items":[{"question":"Why does my vada batter sink instead of float?","answer":"Usually not enough air has been beaten in, or the batter has too much water. Beat longer and use minimal water when grinding."},{"question":"How long should urad dal soak for vada?","answer":"At least three to four hours, longer if your kitchen runs cool, to soften enough for smooth grinding."},{"question":"Can I use a mixer instead of beating by hand?","answer":"A mixer can grind the batter, but hand beating afterward still helps incorporate the air a light vada needs."},{"question":"Why are my vada dense in the centre?","answer":"Oil temperature that is too high can brown the outside before the inside cooks through. Moderate, steady heat works better."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A batter that needs to float before frying, and the soaking and beating that actually gets it there.', seo_description='Urad dal vada: soaking, grinding and beating the batter for a light, properly aerated fritter.', seo_keywords='urad dal vada recipe, black gram vada', reading_minutes=3, published_version_id='arv_truegrit_173_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_173';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_173';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_173','Urad Dal Vada','urad-dal-vada','A batter that needs to float before frying, and the soaking and beating that actually gets it there.','urad dal vada recipe, black gram vada');

-- 174. Medu Vada Using Urad Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_174_2','art_truegrit_174',2,'{"blocks":[{"id":"blk_article_174_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Medu vada starts from the same light, well beaten urad dal batter as any good vada, but the shaping technique, a hand formed ring with a hole in the centre, is what actually defines this specific South Indian dish."]}},{"id":"blk_article_174_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What makes it specific","items":["The batter is prepared the same way as a general urad dal vada, soaked, ground with minimal water, and well beaten for air.","Traditionally shaped by wetting your palm, flattening a portion of batter, and poking a hole through the centre before frying.","The centre hole helps it cook through evenly, since the vada fries as a ring rather than a solid ball.","Curry leaves, black pepper and sometimes grated ginger are common additions specific to the medu vada style.","Served classically with sambar and coconut chutney, a pairing that defines the dish as much as the vada itself."]}},{"id":"blk_article_174_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Urad for medu vada","source":"manual","productSlugs":["black-gram-broken-dal"],"limit":1}},{"id":"blk_article_174_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Medu vada questions","items":[{"question":"What makes medu vada different from a regular vada?","answer":"Mainly the shaping, a hand formed ring with a centre hole, and the traditional pairing with sambar and coconut chutney."},{"question":"Why does medu vada have a hole in the middle?","answer":"It helps the vada cook through evenly during frying, since it fries as a ring rather than a thicker solid shape."},{"question":"Can I shape medu vada without wetting my hands?","answer":"Wet hands make the sticky batter much easier to work with. Dry hands tend to make shaping frustrating and messy."},{"question":"Is the batter different from a standard urad vada batter?","answer":"The base batter is essentially the same. What differs is the shaping technique and some traditional flavour additions."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same base batter as a standard vada, but shaping technique is what actually defines this South Indian classic.', seo_description='Medu vada using urad dal: batter preparation and the shaping technique specific to this South Indian classic.', seo_keywords='medu vada recipe, urad dal medu vada', reading_minutes=3, published_version_id='arv_truegrit_174_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_174';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_174';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_174','Medu Vada Using Urad Dal','medu-vada-using-urad-dal','The same base batter as a standard vada, but shaping technique is what actually defines this South Indian classic.','medu vada recipe, urad dal medu vada');

-- 175. Urad Dal Dosa Batter Guide
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_175_2','art_truegrit_175',2,'{"blocks":[{"id":"blk_article_175_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Dosa batter comes down to three variables that actually matter, the ratio of rice to urad dal, how long each soaks, and how the batter ferments, more than any single secret ingredient."]}},{"id":"blk_article_175_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually matters","items":["A common starting ratio is roughly three parts rice to one part split urad dal, adjusted from there to taste and texture.","Soak rice and dal separately, generally four to six hours or overnight, since they hydrate at slightly different rates.","Grind the urad dal first, aiming for a light, well aerated paste, then grind the rice separately before combining.","Ferment the combined batter in a warm spot for eight to twelve hours, longer in a cool climate, until visibly risen and slightly bubbly.","Salt is often added after fermentation rather than before, since salt can slow the fermentation process down."]}},{"id":"blk_article_175_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Urad for dosa batter","source":"manual","productSlugs":["black-gram-broken-dal"],"limit":1}},{"id":"blk_article_175_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Dosa batter questions","items":[{"question":"Why is my dosa batter not fermenting properly?","answer":"Usually the environment is too cold. A warm spot, or a slightly longer fermentation time, generally fixes this."},{"question":"Should salt be added before or after fermentation?","answer":"Many cooks add it after, since salt can slow down the fermentation process if added too early."},{"question":"Can I adjust the rice to urad dal ratio?","answer":"Yes, more urad dal generally gives a softer, more elastic dosa, while more rice gives a crisper result."},{"question":"How long does fermented dosa batter keep?","answer":"A few days refrigerated, with flavour continuing to develop slightly as it sits."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Ratios, soaking and fermentation, the three variables that actually decide how a dosa batter turns out.', seo_description='A guide to urad dal dosa batter: rice to dal ratio, soaking time, grinding and fermentation.', seo_keywords='urad dal dosa batter, dosa batter guide', reading_minutes=3, published_version_id='arv_truegrit_175_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_175';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_175';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_175','Urad Dal Dosa Batter Guide','urad-dal-dosa-batter-guide','Ratios, soaking and fermentation, the three variables that actually decide how a dosa batter turns out.','urad dal dosa batter, dosa batter guide');

-- 176. What Are Red Lentils?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_176_2','art_truegrit_176',2,'{"blocks":[{"id":"blk_article_176_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Red lentils, known as masoor in Hindi, are one of the fastest cooking pulses in an Indian kitchen. Sold whole with a brownish green skin or split into the familiar orange red dal, both forms trace back to the same small lens shaped seed."]}},{"id":"blk_article_176_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines them","items":["A small, lens shaped pulse, sold whole with a brownish green skin or split and dehusked into an orange red dal.","Known as masoor in Hindi, among the fastest cooking common pulses, often needing little to no soaking.","Whole masoor holds its shape better in cooking. Split masoor breaks down quickly into a smooth dal.","Colour changes noticeably once dehusked, the skin''s brownish green giving way to the orange red interior most people picture as red lentils.","A common everyday pulse across much of India, valued as much for convenience as for flavour."]}},{"id":"blk_article_176_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Red lentils to try","source":"manual","productSlugs":["red-lentils-whole","red-lentils-broken"],"limit":2}},{"id":"blk_article_176_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Red lentil questions","items":[{"question":"Is masoor dal the same as red lentils?","answer":"Yes, masoor is the Hindi name for red lentils, the same pulse sold under either term."},{"question":"Why are split red lentils orange rather than red?","answer":"The colour is closer to orange or pink once dehusked. Red lentils is simply the common English name for the pulse."},{"question":"Do red lentils need soaking before cooking?","answer":"Not much, if at all. Masoor is among the fastest cooking common pulses, especially in split form."},{"question":"Is whole masoor the same pulse as split masoor dal?","answer":"Yes, whole masoor keeps its skin, while split masoor dal has been dehusked and split, changing colour and cooking time."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A small, fast cooking pulse known as masoor, sold whole with its skin on or split into the familiar orange dal.', seo_description='Red lentils explained: what masoor is, its whole and split forms, and why it cooks faster than most pulses.', seo_keywords='red lentils, masoor dal, what are red lentils', reading_minutes=3, published_version_id='arv_truegrit_176_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_176';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_176';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_176','What Are Red Lentils?','what-are-red-lentils','A small, fast cooking pulse known as masoor, sold whole with its skin on or split into the familiar orange dal.','red lentils, masoor dal, what are red lentils');

-- 177. Whole Masoor vs Split Masoor Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_177_2','art_truegrit_177',2,'{"blocks":[{"id":"blk_article_177_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole and split masoor are the same pulse at two different processing stages, and the difference between them is more visible than with many pulses, since dehusking changes the colour dramatically."]}},{"id":"blk_article_177_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Whole masoor keeps its brownish green skin, holds its shape well, and takes a little longer to cook.","Split masoor dal is dehusked and split, revealing an orange red interior, and cooks quickly into a smooth dal.","Whole masoor suits a curry where you want the lentil to hold together. Split masoor suits a quick, everyday dal.","Split masoor dal is the more commonly stocked form in most kitchens, simply for its speed and convenience.","Both come from the same crop, so neither is a lesser or better version of the other, just suited to different dishes."]}},{"id":"blk_article_177_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One cook who keeps both whole and split red lentils on hand found the actual cooking time difference smaller than expected](/community/dsc_truegrit_014), worth a read before assuming whole always means a much longer wait."]}},{"id":"blk_article_177_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole and split masoor","source":"manual","productSlugs":["red-lentils-whole","red-lentils-broken"],"limit":2}},{"id":"blk_article_177_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole vs split masoor questions","items":[{"question":"Which masoor cooks faster?","answer":"Split masoor dal, since dehusking and splitting expose more surface area to water, speeding up cooking noticeably."},{"question":"Does whole masoor need soaking?","answer":"It benefits from a short soak more than split masoor does, though it still cooks faster than many other whole pulses."},{"question":"Can I use whole masoor where a recipe calls for split?","answer":"You can, but expect a longer cooking time and a more textured result rather than a smooth dal."},{"question":"Why is split masoor more commonly sold?","answer":"Mainly convenience, its fast, predictable cooking time suits everyday dal making better for most households."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Skin on or off changes colour, cooking time and which curry each form actually suits.', seo_description='Whole masoor compared with split masoor dal: colour, cooking time, and which dishes each suits.', seo_keywords='whole masoor vs split masoor dal', reading_minutes=2, published_version_id='arv_truegrit_177_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_177';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_177';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_177','Whole Masoor vs Split Masoor Dal','whole-masoor-vs-split-masoor-dal','Skin on or off changes colour, cooking time and which curry each form actually suits.','whole masoor vs split masoor dal');

-- 178. Red Lentils vs Yellow Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_178_2','art_truegrit_178',2,'{"blocks":[{"id":"blk_article_178_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Yellow dal is not one specific pulse, it is a loose description that can point to moong dal, toor dal, or occasionally split masoor itself, depending on who is using the term. Red lentils, by contrast, specifically means masoor."]}},{"id":"blk_article_178_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually check","items":["Red lentils specifically means masoor, whole or split, with a distinct orange red colour once dehusked.","Yellow dal is a looser term, commonly referring to moong dal or toor dal, both genuinely yellow rather than orange red.","Split masoor is sometimes casually grouped under yellow dal in conversation, despite its colour leaning more orange or pink.","Flavour and cooking time differ between these pulses regardless of what a recipe calls them, so checking the actual pulse matters more than the label.","When a recipe says yellow dal without specifying, moong or toor is the safer assumption over masoor."]}},{"id":"blk_article_178_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Red lentils","source":"manual","productSlugs":["red-lentils-broken","red-lentils-whole"],"limit":2}},{"id":"blk_article_178_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Red lentils and yellow dal questions","items":[{"question":"Is masoor dal ever called yellow dal?","answer":"Occasionally in casual conversation, though its colour leans more orange or pink than true yellow."},{"question":"What pulse does yellow dal usually mean?","answer":"Most often moong dal or toor dal, both of which are genuinely yellow rather than the orange red of masoor."},{"question":"Can I substitute masoor for a recipe calling for yellow dal?","answer":"It depends on the dish. Masoor cooks faster and has a different flavour than moong or toor, so check what the recipe actually needs."},{"question":"Why is this naming so inconsistent?","answer":"Colour based names vary by region and household rather than following one fixed standard across India."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Different pulses hiding behind a loose colour description that gets used inconsistently.', seo_description='Red lentils compared with yellow dal: clarifying which pulses the term yellow dal actually refers to.', seo_keywords='red lentils vs yellow dal, masoor vs yellow dal', reading_minutes=2, published_version_id='arv_truegrit_178_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_178';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_178';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_178','Red Lentils vs Yellow Dal','red-lentils-vs-yellow-dal','Different pulses hiding behind a loose colour description that gets used inconsistently.','red lentils vs yellow dal, masoor vs yellow dal');

-- 179. Masoor Dal vs Moong Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_179_2','art_truegrit_179',2,'{"blocks":[{"id":"blk_article_179_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Masoor and moong dal both earn their place as everyday, fast cooking staples, but they are not interchangeable. Flavour, texture and how gentle each is on digestion set them apart."]}},{"id":"blk_article_179_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Masoor dal has a richer, slightly earthier flavour. Moong dal is milder and lighter tasting.","Moong dal is generally considered gentler on digestion, which is why it is a common choice during recovery from illness.","Masoor cooks into a smoother, thicker dal quickly. Moong holds a bit more texture unless cooked down further.","Colour differs too, masoor''s orange red against moong''s yellow, both losing some vibrancy once fully cooked.","Many households keep both stocked, reaching for masoor for a heartier dal and moong for something lighter.","Both are commonly used in khichdi, though the character of the finished dish shifts noticeably depending on which one is used."]}},{"id":"blk_article_179_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Masoor dal","source":"manual","productSlugs":["red-lentils-broken","red-lentils-whole"],"limit":2}},{"id":"blk_article_179_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Masoor vs moong dal questions","items":[{"question":"Which cooks faster, masoor or moong?","answer":"Both are quick, but masoor generally has a slight edge, breaking down into a smooth dal a little faster."},{"question":"Is moong dal easier to digest than masoor?","answer":"Generally considered so, which is why moong is the more common choice for a very light meal or during illness."},{"question":"Can masoor and moong dal be swapped in a recipe?","answer":"You can, but expect a difference in flavour and slightly different texture, since the two pulses are not identical."},{"question":"Which is more commonly used in khichdi?","answer":"Moong is the more traditional default, though masoor khichdi is a genuine, faster cooking variation many households make."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Both are fast cooking, everyday dals, but they differ in flavour, texture and how gentle they are on digestion.', seo_description='Masoor dal compared with moong dal: cooking time, flavour, texture and which suits which meal.', seo_keywords='masoor dal vs moong dal', reading_minutes=3, published_version_id='arv_truegrit_179_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_179';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_179';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_179','Masoor Dal vs Moong Dal','masoor-dal-vs-moong-dal','Both are fast cooking, everyday dals, but they differ in flavour, texture and how gentle they are on digestion.','masoor dal vs moong dal');

-- 180. How Red Lentils Are Processed
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_180_2','art_truegrit_180',2,'{"blocks":[{"id":"blk_article_180_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Split masoor dal starts as whole masoor and reaches its familiar orange red form through the same basic cleaning, dehusking and splitting process used for other split pulses."]}},{"id":"blk_article_180_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The steps","items":["Whole masoor is cleaned to remove dust, stones and damaged grain before any further processing.","The pulse is lightly conditioned to loosen the brownish green skin without softening the interior too much.","Milling removes the skin and splits the grain, revealing the orange red interior most people recognise as red lentils.","The split dal is sieved and graded for size and consistency before packaging.","This process is similar in principle to how split urad or split moong dal are produced from their whole pulses.","Traditional stone processing can yield a slightly less uniform dal than modern roller methods, which some cooks still prefer for texture."]}},{"id":"blk_article_180_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Split red lentils","source":"manual","productSlugs":["red-lentils-broken"],"limit":1}},{"id":"blk_article_180_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Red lentil processing questions","items":[{"question":"Does processing change red lentils'' cooking time?","answer":"Yes, dehusked and split masoor cooks noticeably faster than the whole, skin on form."},{"question":"Is the colour change from processing or from the seed itself?","answer":"The orange red colour is the natural interior of the seed, simply hidden by the outer skin until it is removed."},{"question":"Can whole masoor be split at home?","answer":"Not practically. Dehusking and splitting need milling equipment beyond a typical home kitchen."},{"question":"Does processing remove nutritional value?","answer":"Removing the skin changes fibre content somewhat, a genuine processing trade-off rather than a defect."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Cleaning, dehusking and splitting, the same basic steps that turn whole masoor into the familiar orange dal.', seo_description='How red lentils are processed: cleaning, dehusking and splitting whole masoor into split dal.', seo_keywords='how red lentils are made, masoor dal processing', reading_minutes=2, published_version_id='arv_truegrit_180_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_180';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_180';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_180','How Red Lentils Are Processed','how-red-lentils-are-processed','Cleaning, dehusking and splitting, the same basic steps that turn whole masoor into the familiar orange dal.','how red lentils are made, masoor dal processing');

-- 181. Whole vs Split Lentils
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_181_2','art_truegrit_181',2,'{"blocks":[{"id":"blk_article_181_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The pattern that separates whole masoor from split masoor dal holds broadly across most lentils, whole keeps the skin and shape, split trades both away for speed and a smoother finished texture."]}},{"id":"blk_article_181_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The general pattern","items":["Whole lentils keep their outer skin, hold their shape during cooking, and generally take longer to soften fully.","Split lentils are dehusked and separated into halves, cooking faster and breaking down more readily into a smooth dal.","Colour often changes noticeably once split, since the skin frequently carries a different colour than the interior.","Whole lentils suit dishes and curries where texture matters. Split lentils suit everyday dal and quick cooking.","This pattern applies across masoor, urad, moong and most other common pulses, not just one specific lentil."]}},{"id":"blk_article_181_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole and split masoor","source":"manual","productSlugs":["red-lentils-whole","red-lentils-broken"],"limit":2}},{"id":"blk_article_181_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole vs split lentil questions","items":[{"question":"Does this pattern apply to all pulses?","answer":"It applies broadly across most common lentils and pulses, though exact cooking times and colour changes vary by type."},{"question":"Is split always better than whole?","answer":"Neither is universally better, split suits speed and smoothness, whole suits texture and shape in a finished dish."},{"question":"Why does colour change so much with splitting?","answer":"The outer skin often carries a different pigment than the interior, so dehusking reveals a genuinely different colour."},{"question":"Should a beginner start with whole or split lentils?","answer":"Split is generally the more forgiving starting point, cooking faster and more predictably than whole lentils."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same skin on, skin off pattern that shows up across pulses, applied broadly to lentils generally.', seo_description='Whole lentils compared with split lentils generally: cooking time, texture, and which suits which dish.', seo_keywords='whole vs split lentils, lentil processing', reading_minutes=2, published_version_id='arv_truegrit_181_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_181';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_181';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_181','Whole vs Split Lentils','whole-vs-split-lentils','The same skin on, skin off pattern that shows up across pulses, applied broadly to lentils generally.','whole vs split lentils, lentil processing');

-- 182. How Long Should Masoor Dal Be Soaked?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_182_2','art_truegrit_182',2,'{"blocks":[{"id":"blk_article_182_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Masoor dal is the pulse where soaking matters least among common dals. Split masoor cooks quickly enough on its own that many cooks skip soaking it entirely without any real downside."]}},{"id":"blk_article_182_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually matters","items":["Split masoor dal generally needs no soaking at all, cooking fully in fifteen to twenty minutes from dry.","Whole masoor benefits from a short soak, thirty minutes or so, though it still cooks faster than many other whole pulses.","Soaking split masoor briefly, ten minutes or so, can shave a small amount off cooking time if you are in a hurry.","This is a genuine contrast to pulses like urad or chana, where soaking makes a much bigger practical difference.","If a recipe assumes a long soak for masoor specifically, it is likely written with a different pulse''s habits in mind."]}},{"id":"blk_article_182_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Red lentils","source":"manual","productSlugs":["red-lentils-broken","red-lentils-whole"],"limit":2}},{"id":"blk_article_182_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Masoor dal soaking questions","items":[{"question":"Do I need to soak split masoor dal?","answer":"Not really. It cooks quickly enough from dry that soaking is optional rather than necessary."},{"question":"Does whole masoor need a longer soak than split?","answer":"A short soak helps whole masoor, though it still cooks faster than many other whole pulses even without one."},{"question":"Does skipping the soak change the final texture?","answer":"Minimally for split masoor, since its fast cooking time already gives a smooth, predictable result either way."},{"question":"Why do some recipes still call for soaking masoor?","answer":"Often habit carried over from other pulses, or a preference for a slightly faster stovetop time, rather than a strict requirement."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Less than almost any other common dal, and often not needed at all for the split form.', seo_description='How long to soak masoor dal, and why it needs less soaking than most other common pulses.', seo_keywords='masoor dal soaking time, how long to soak red lentils', reading_minutes=2, published_version_id='arv_truegrit_182_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_182';
