INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_182','How Long Should Masoor Dal Be Soaked?','how-long-should-masoor-dal-be-soaked','Less than almost any other common dal, and often not needed at all for the split form.','masoor dal soaking time, how long to soak red lentils');

-- 183. How to Cook Masoor Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_183_2','art_truegrit_183',2,'{"blocks":[{"id":"blk_article_183_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Masoor dal is one of the most forgiving pulses to cook, ready in a fraction of the time many other dals need, with very little technique required to get a good result."]}},{"id":"blk_article_183_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Rinse split masoor dal, then cook with turmeric and salt in roughly three parts water to one part dal.","It cooks in fifteen to twenty minutes in an open pot, or a single whistle or two in a pressure cooker.","The dal breaks down into a smooth texture quickly, so check consistency earlier than you would with a slower cooking pulse.","Finish with a simple tempering, cumin, garlic and dried red chilli in ghee, poured over just before serving.","Adjust thickness with hot water at the end, since masoor thickens further as it sits after cooking."]}},{"id":"blk_article_183_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Masoor for cooking","source":"manual","productSlugs":["red-lentils-broken"],"limit":1}},{"id":"blk_article_183_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Cooking masoor dal questions","items":[{"question":"Do I need a pressure cooker for masoor dal?","answer":"No, it cooks well enough in an open pot in fifteen to twenty minutes, though a pressure cooker speeds it up further."},{"question":"Why did my masoor dal turn out too thick?","answer":"It thickens noticeably as it sits after cooking. Add a little hot water to loosen it back to your preferred consistency."},{"question":"Can I add vegetables to masoor dal while cooking?","answer":"Yes, quick cooking vegetables like spinach or tomato work well added partway through, since the dal itself cooks so fast."},{"question":"Is masoor dal good for a quick weeknight meal?","answer":"Yes, it is one of the fastest common dals to cook, making it a reliable choice when time is short."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One of the most forgiving dals to cook, ready in minutes with almost no technique to get wrong.', seo_description='How to cook masoor dal: water ratio, timing, and a simple tempering to finish it.', seo_keywords='how to cook masoor dal, red lentil dal recipe', reading_minutes=2, published_version_id='arv_truegrit_183_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_183';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_183';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_183','How to Cook Masoor Dal','how-to-cook-masoor-dal','One of the most forgiving dals to cook, ready in minutes with almost no technique to get wrong.','how to cook masoor dal, red lentil dal recipe');

-- 185. Whole Masoor Curry
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_185_2','art_truegrit_185',2,'{"blocks":[{"id":"blk_article_185_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole masoor curry leans on the lentil''s ability to hold its shape, giving a heartier, more textured dish than the smooth dal split masoor typically becomes."]}},{"id":"blk_article_185_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Soak whole masoor for thirty minutes to an hour, which shortens cooking time without being strictly necessary.","Cook the soaked lentils in water with turmeric until tender but still holding their shape, not fully broken down.","Build a separate onion, tomato and ginger garlic masala base, with standard curry spices like coriander and cumin powder.","Combine the cooked lentils with the masala base and simmer briefly to let the flavours come together.","Finish with fresh coriander and a squeeze of lemon, serving with rice or roti.","A dollop of ghee stirred in right before serving rounds out the flavour, the same finishing touch many dal recipes use."]}},{"id":"blk_article_185_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole masoor","source":"manual","productSlugs":["red-lentils-whole"],"limit":1}},{"id":"blk_article_185_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole masoor curry questions","items":[{"question":"Do I have to soak whole masoor for this curry?","answer":"It is not strictly necessary but shortens cooking time and helps the lentils cook more evenly."},{"question":"How is this different from a split masoor dal?","answer":"The whole lentils hold their shape rather than breaking down, giving a heartier, more textured curry."},{"question":"Can I use a pressure cooker for whole masoor curry?","answer":"Yes, though watch the timing carefully since whole masoor still cooks faster than many other whole pulses."},{"question":"What should I serve with whole masoor curry?","answer":"Rice or roti both work well, the same as most Indian curries built on a pulse."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Whole masoor''s ability to hold its shape makes for a heartier curry than the smooth split version.', seo_description='A whole masoor curry recipe: soaking, cooking, and a masala base that lets the lentil hold its shape.', seo_keywords='whole masoor curry recipe, sabut masoor recipe', reading_minutes=3, published_version_id='arv_truegrit_185_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_185';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_185';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_185','Whole Masoor Curry','whole-masoor-curry','Whole masoor''s ability to hold its shape makes for a heartier curry than the smooth split version.','whole masoor curry recipe, sabut masoor recipe');

-- 186. Masoor Dal Khichdi
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_186_2','art_truegrit_186',2,'{"blocks":[{"id":"blk_article_186_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Masoor dal khichdi trades moong''s very light character for a slightly heartier, earthier bowl, cooked the same basic way but ready noticeably faster thanks to masoor''s quick cooking nature."]}},{"id":"blk_article_186_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Cook rice and split masoor dal together with turmeric and salt, in a similar ratio to a standard moong khichdi.","Expect a faster overall cooking time than moong khichdi, since masoor breaks down quickly on its own.","A simple tempering of cumin, ghee and asafoetida finishes the dish, the same basic approach most khichdi shares.","The finished texture tends to be a touch smoother than moong khichdi, since masoor breaks down more readily.","Serve with a simple side of yoghurt or pickle, the same pairing most khichdi variations use.","A small pat of ghee stirred through just before serving finishes the dish the way most khichdi recipes expect."]}},{"id":"blk_article_186_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Masoor for khichdi","source":"manual","productSlugs":["red-lentils-broken"],"limit":1}},{"id":"blk_article_186_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Masoor khichdi questions","items":[{"question":"Is masoor khichdi faster to make than moong khichdi?","answer":"Generally yes, since masoor cooks quickly and needs little to no soaking beforehand."},{"question":"Does masoor khichdi taste different from moong khichdi?","answer":"Yes, slightly earthier and heartier, though still much lighter than a urad based khichdi."},{"question":"Can I add vegetables to masoor khichdi?","answer":"Yes, added partway through cooking so they finish tender alongside the rice and dal."},{"question":"Is masoor khichdi suitable for a light meal?","answer":"Yes, though moong is generally considered the lightest option if digestion is a specific concern."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A faster cooking alternative to moong khichdi, with a slightly heartier, earthier flavour.', seo_description='Masoor dal khichdi: how it compares to moong khichdi and a simple method for cooking it.', seo_keywords='masoor dal khichdi recipe', reading_minutes=2, published_version_id='arv_truegrit_186_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_186';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_186';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_186','Masoor Dal Khichdi','masoor-dal-khichdi','A faster cooking alternative to moong khichdi, with a slightly heartier, earthier flavour.','masoor dal khichdi recipe');

-- 188. Five Easy Masoor Dal Meals
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_188_2','art_truegrit_188',2,'{"blocks":[{"id":"blk_article_188_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Masoor''s speed makes it an easy pulse to build a whole meal around, not just a side dal, especially on a weeknight when time is short and a long simmer is not an option."]}},{"id":"blk_article_188_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Five ideas","items":["A simple tempered dal, cooked with turmeric and finished with a cumin and garlic tadka, ready in under thirty minutes.","Masoor khichdi, cooked together with rice for a complete, one pot meal.","A masoor lentil soup, simmered with vegetables and blended partly or fully smooth, seasoned simply.","Whole masoor curry, built on a proper onion tomato masala base for a heartier main dish.","A masoor salad, cooked lentils tossed with chopped vegetables, lemon and a light dressing, served warm or at room temperature.","A masoor and vegetable stew, simmered longer with root vegetables for a heartier, more filling one pot dinner."]}},{"id":"blk_article_188_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Masoor for these meals","source":"manual","productSlugs":["red-lentils-broken","red-lentils-whole"],"limit":2}},{"id":"blk_article_188_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Masoor meal ideas questions","items":[{"question":"Which of these is fastest to make?","answer":"The simple tempered dal, since split masoor cooks in fifteen to twenty minutes with minimal preparation."},{"question":"Can masoor soup be made ahead of time?","answer":"Yes, it keeps well refrigerated for a few days and often tastes even better the next day."},{"question":"Is a masoor salad served hot or cold?","answer":"Either works, warm or at room temperature, depending on preference and the season."},{"question":"Are these meals suitable for meal prep?","answer":"Yes, masoor''s fast cooking time makes it a practical pulse to prepare in advance for the week."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Fast enough to build a whole meal around on a weeknight, in more ways than a single simple dal.', seo_description='Five easy meals built around masoor dal: simple dal, khichdi, soup, curry and a quick lentil salad.', seo_keywords='masoor dal meal ideas, red lentil recipes', reading_minutes=3, published_version_id='arv_truegrit_188_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_188';
