INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_188','Five Easy Masoor Dal Meals','five-easy-masoor-dal-meals','Fast enough to build a whole meal around on a weeknight, in more ways than a single simple dal.','masoor dal meal ideas, red lentil recipes');

-- 189. How to Store Lentils for Long Periods
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_189_2','art_truegrit_189',2,'{"blocks":[{"id":"blk_article_189_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Lentils store well for extended periods with a few consistent habits, the same basic principles that apply across most dried pulses rather than anything specific to one type."]}},{"id":"blk_article_189_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Keep lentils in an airtight container, which protects against both humidity and pests far better than an open bag.","Store in a cool, dark place away from direct sunlight and heat sources like a stove.","Check periodically for weevils or other pests, especially during humid months or after a fresh batch arrives.","Whole lentils generally keep a little longer than split ones, since the skin offers some extra protection.","Label containers with a purchase date if you buy in bulk, so older stock gets used before newer stock.","Avoid storing near a stove or other heat source, where ambient temperature runs consistently higher than elsewhere in the kitchen."]}},{"id":"blk_article_189_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Lentils to store","source":"manual","productSlugs":["red-lentils-broken","red-lentils-whole"],"limit":2}},{"id":"blk_article_189_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Long term lentil storage questions","items":[{"question":"How long do lentils last if stored properly?","answer":"Generally six months to a year in an airtight container kept cool and dry, sometimes longer for whole forms."},{"question":"Does freezing lentils help them last longer?","answer":"It can extend shelf life further, though most households find a well sealed pantry container sufficient for normal use."},{"question":"Should I buy lentils in bulk to save money?","answer":"Only if you will use them within a reasonable time. Otherwise, smaller, more frequent purchases keep them fresher."},{"question":"Do split lentils need different storage than whole?","answer":"The same basic principles apply to both, though split lentils benefit slightly more from careful sealing since they spoil a touch faster."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Airtight, cool and dry, with a check for pests every so often, keeps most lentils good for months.', seo_description='How to store lentils for long periods: containers, temperature, and checking for pests over time.', seo_keywords='how to store lentils long term, lentil storage tips', reading_minutes=2, published_version_id='arv_truegrit_189_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_189';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_189';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_189','How to Store Lentils for Long Periods','how-to-store-lentils-for-long-periods','Airtight, cool and dry, with a check for pests every so often, keeps most lentils good for months.','how to store lentils long term, lentil storage tips');

-- 190. What Are White Field Peas?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_190_2','art_truegrit_190',2,'{"blocks":[{"id":"blk_article_190_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["White field peas, called safed matar in Hindi, are dried, fully mature peas, quite different from the fresh green peas most people picture when they hear the word. Where green peas are eaten young and sweet, field peas are dried and starchy."]}},{"id":"blk_article_190_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines them","items":["Dried, mature peas, harvested later than fresh green peas and left to dry rather than eaten young.","Pale cream to white in colour, with a starchy, slightly earthy flavour quite different from sweet fresh peas.","Sold dried, needing soaking and cooking before use, unlike fresh or frozen green peas which cook quickly.","Central to dishes like ghugni and ragda, both built around the pea''s texture once properly cooked.","A separate crop and product from fresh green peas, despite the shared name suggesting a closer relationship."]}},{"id":"blk_article_190_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"White field peas","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_190_4","type":"faq","version":1,"enabled":true,"props":{"heading":"White field pea questions","items":[{"question":"Are white field peas the same as fresh green peas?","answer":"No, they are the same plant harvested at a much later, dried stage, resulting in a very different texture and flavour."},{"question":"Do white field peas need soaking?","answer":"Yes, being a dried mature legume, they benefit significantly from soaking before cooking."},{"question":"What is safed matar used for?","answer":"Most commonly ghugni and ragda, both traditional Indian dishes built around the cooked pea''s texture."},{"question":"Can I substitute frozen green peas for white field peas?","answer":"No, the texture and flavour are different enough that recipes built on one will not work well with the other."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Dried, mature field peas, distinct from the fresh green peas most people picture, used in ghugni and ragda.', seo_description='White field peas explained: what they are, how they differ from fresh green peas, and how they are used.', seo_keywords='white field peas, safed matar, what are white peas', reading_minutes=3, published_version_id='arv_truegrit_190_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_190';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_190';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_190','What Are White Field Peas?','what-are-white-field-peas','Dried, mature field peas, distinct from the fresh green peas most people picture, used in ghugni and ragda.','white field peas, safed matar, what are white peas');

-- 191. Field Peas vs Green Peas
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_191_2','art_truegrit_191',2,'{"blocks":[{"id":"blk_article_191_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Field peas and fresh green peas can come from closely related plants, but harvest timing changes them dramatically, one picked young and sweet, the other left to mature and dry fully before harvest."]}},{"id":"blk_article_191_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Green peas are harvested young, while still sweet and tender, and are typically eaten fresh or frozen.","Field peas are left to mature fully on the plant and then dried, resulting in a starchy, earthy pulse rather than a sweet vegetable.","Cooking differs entirely, green peas need only brief cooking, field peas need soaking and a longer simmer.","Field peas anchor dishes like ghugni and ragda. Green peas appear in pulao, curries and as a simple side vegetable.","Neither substitutes for the other in a recipe built around its specific texture and cooking method."]}},{"id":"blk_article_191_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Field peas","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_191_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Field peas vs green peas questions","items":[{"question":"Can I use frozen green peas instead of dried field peas?","answer":"No, the texture and cooking method differ too much. A recipe built on dried field peas needs the dried, soaked form."},{"question":"Are field peas less nutritious than fresh green peas?","answer":"They are different foods at different maturity stages, not a lesser version of the same one, so a direct comparison is not meaningful."},{"question":"Why are field peas dried rather than eaten fresh?","answer":"Drying allows long term storage and a different culinary use, the same reasoning behind drying most mature legumes."},{"question":"Do field peas taste sweet like green peas?","answer":"No, they are starchier and more earthy in flavour, quite different from fresh green peas'' natural sweetness."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same plant at two very different life stages, harvested young and sweet or dried and starchy.', seo_description='Field peas compared with fresh green peas: harvest timing, texture, flavour and how each is used.', seo_keywords='field peas vs green peas', reading_minutes=2, published_version_id='arv_truegrit_191_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_191';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_191';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_191','Field Peas vs Green Peas','field-peas-vs-green-peas','The same plant at two very different life stages, harvested young and sweet or dried and starchy.','field peas vs green peas');

-- 192. Field Peas vs Chickpeas
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_192_2','art_truegrit_192',2,'{"blocks":[{"id":"blk_article_192_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Field peas and chickpeas are different legumes entirely, and while both are dried, soaked and cooked in broadly similar ways, the dishes each one anchors rarely overlap."]}},{"id":"blk_article_192_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Field peas are smaller and rounder, with a pale cream colour. Chickpeas are larger, more irregular in shape, and tan coloured.","Field peas anchor ghugni and ragda. Chickpeas anchor chana masala, chole and hummus style preparations.","Texture differs once cooked too, field peas break down a little more readily than firmer, more textured chickpeas.","Both need soaking before cooking, though exact times vary between the two.","Neither substitutes cleanly for the other in a recipe built around its specific texture and traditional role.","Price and availability also differ regionally, with each pulse being the more familiar, everyday choice in different parts of the country."]}},{"id":"blk_article_192_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Field peas","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_192_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Field peas vs chickpeas questions","items":[{"question":"Can I use chickpeas instead of field peas for ghugni?","answer":"Not really, the texture and flavour differ enough that the dish will not turn out as intended."},{"question":"Which cooks faster, field peas or chickpeas?","answer":"Field peas generally soften a little faster than chickpeas of similar preparation, though both benefit from a proper soak."},{"question":"Do you sell chickpeas alongside field peas?","answer":"No, our range covers white field peas specifically."},{"question":"Is ragda made with chickpeas anywhere in India?","answer":"Ragda is traditionally built on white field peas, though regional and personal variations do exist."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Different legumes entirely, occupying different dishes across Indian cooking.', seo_description='Field peas compared with chickpeas: different legumes, different texture, and different traditional uses.', seo_keywords='field peas vs chickpeas', reading_minutes=2, published_version_id='arv_truegrit_192_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_192';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_192';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_192','Field Peas vs Chickpeas','field-peas-vs-chickpeas','Different legumes entirely, occupying different dishes across Indian cooking.','field peas vs chickpeas');

-- 193. Field Peas vs White Peas
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_193_2','art_truegrit_193',2,'{"blocks":[{"id":"blk_article_193_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Field peas and white peas overlap heavily in everyday use, both commonly describing the same dried, pale coloured pulse used in ghugni and ragda, rather than two genuinely different products."]}},{"id":"blk_article_193_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually know","items":["In most kitchens, field peas and white peas both refer to the same dried pulse, safed matar in Hindi.","White peas describes the pale colour directly. Field peas describes where and how the crop is grown and harvested.","Neither term signals a different cooking method or use, both need soaking and a proper simmer before eating.","Checking the specific product listing matters more than the exact term used, since naming varies by seller.","Our product is sold and described as white field peas, combining both common terms into one clear name."]}},{"id":"blk_article_193_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"White field peas","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_193_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Field peas and white peas questions","items":[{"question":"Are field peas and white peas different products?","answer":"No, in common usage they refer to the same dried pulse, just described by two overlapping terms."},{"question":"Does one term suggest a different grade or quality?","answer":"Not inherently, though it is always worth checking the specific product listing rather than assuming from the name alone."},{"question":"Which term should I search for when buying?","answer":"Either works, since both refer to the same product, safed matar, in most Indian grocery contexts."},{"question":"Why do two names exist for the same pulse?","answer":"Regional and descriptive naming habits, one referencing colour, the other referencing the crop type, applied to the same product."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same product under two overlapping names, more than a genuine comparison between two different peas.', seo_description='Field peas compared with white peas: clarifying that these largely describe the same dried pulse.', seo_keywords='field peas vs white peas, safed matar naming', reading_minutes=2, published_version_id='arv_truegrit_193_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_193';
