INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_193','Field Peas vs White Peas','field-peas-vs-white-peas','The same product under two overlapping names, more than a genuine comparison between two different peas.','field peas vs white peas, safed matar naming');

-- 194. How to Cook Dried White Peas
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_194_2','art_truegrit_194',2,'{"blocks":[{"id":"blk_article_194_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Dried white peas need a proper soak and simmer to turn tender rather than staying tough, a step that matters more here than it does with faster cooking pulses like masoor."]}},{"id":"blk_article_194_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Soak dried white peas for at least six to eight hours, or overnight, before cooking.","Discard the soaking water and cook in fresh water, with salt added only after the peas have begun to soften.","Pressure cook for several whistles, or simmer in an open pot for an hour or more, until fully tender.","Adding salt too early can slow softening, so hold off until the peas are already partway cooked.","Check a few peas by pressing them between your fingers, they should mash easily and evenly when properly done."]}},{"id":"blk_article_194_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"White field peas","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_194_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Cooking white peas questions","items":[{"question":"How long do dried white peas take to cook?","answer":"An hour or more in an open pot, or several pressure cooker whistles, after a proper overnight soak."},{"question":"Why are my white peas still hard after cooking?","answer":"Likely an insufficient soak, or salt added too early, both of which slow how quickly the peas soften."},{"question":"Can I skip soaking white peas?","answer":"It is not recommended. Skipping the soak significantly extends cooking time and can leave the peas unevenly cooked."},{"question":"Should I use the soaking water to cook the peas?","answer":"Discarding it and using fresh water is common practice, since the soaking water can carry some bitterness."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Soaking first, then a proper simmer, is what actually gets these dried peas tender rather than tough.', seo_description='How to cook dried white field peas: soaking time, water ratio, and simmering until properly tender.', seo_keywords='how to cook white peas, dried field pea recipe', reading_minutes=2, published_version_id='arv_truegrit_194_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_194';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_194';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_194','How to Cook Dried White Peas','how-to-cook-dried-white-peas','Soaking first, then a proper simmer, is what actually gets these dried peas tender rather than tough.','how to cook white peas, dried field pea recipe');

-- 195. Do White Peas Need Soaking?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_195_2','art_truegrit_195',2,'{"blocks":[{"id":"blk_article_195_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Unlike masoor dal, which barely needs soaking at all, white field peas genuinely benefit from it, and skipping the step costs real time and evenness at the stove."]}},{"id":"blk_article_195_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why the answer is yes","items":["White peas are a dried, mature legume with a tough outer layer that softens much more evenly after soaking.","Soaking for six to eight hours, or overnight, significantly shortens the cooking time that follows.","Skipping the soak does not make cooking impossible, but expect a considerably longer simmer and less even results.","This is a genuine contrast to masoor dal, which cooks quickly enough that soaking barely matters there.","If you forget to soak overnight, a quick hot water soak of an hour or two helps, though it is not a full substitute."]}},{"id":"blk_article_195_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"White field peas","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_195_4","type":"faq","version":1,"enabled":true,"props":{"heading":"White pea soaking questions","items":[{"question":"How long should white peas soak?","answer":"Six to eight hours, or overnight, gives the most even, reliable results."},{"question":"Is there a quick soak method if I forgot overnight?","answer":"A hot water soak of an hour or two helps somewhat, though it is not a complete substitute for a full overnight soak."},{"question":"What happens if I cook white peas without soaking?","answer":"They will still cook eventually, but expect a considerably longer simmer and less evenly softened peas."},{"question":"Does soaking affect the flavour of white peas?","answer":"Not significantly, its main effect is on texture and cooking time rather than taste."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Yes, genuinely, unlike some faster cooking pulses. Skipping it costs real time at the stove.', seo_description='Do white field peas need soaking: why the answer is yes, and what skipping it actually costs you.', seo_keywords='do white peas need soaking, field pea soaking time', reading_minutes=2, published_version_id='arv_truegrit_195_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_195';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_195';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_195','Do White Peas Need Soaking?','do-white-peas-need-soaking','Yes, genuinely, unlike some faster cooking pulses. Skipping it costs real time at the stove.','do white peas need soaking, field pea soaking time');

-- 196. Traditional Indian White Pea Recipes
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_196_2','art_truegrit_196',2,'{"blocks":[{"id":"blk_article_196_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["White field peas anchor a handful of well loved Indian dishes, most centred on the pea''s ability to hold a soft, slightly mashable texture once properly cooked and seasoned."]}},{"id":"blk_article_196_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where they show up","items":["Ghugni, a spiced curry of cooked white peas, popular as a snack or light meal across parts of East India.","Ragda, a similar cooked pea preparation, central to street food dishes like ragda pattice and ragda chaat.","Simple white pea curry, cooked with a basic onion tomato masala, served as an everyday side dish.","White pea sundal, a South Indian style tempered preparation, often made for festival offerings.","White pea salad, cooked peas tossed with chopped onion, tomato, chaat masala and lemon for a light snack."]}},{"id":"blk_article_196_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One buyer who mainly used field peas for ghugni asks where else people use them, having found they hold their shape well in a mixed vegetable curry too](/community/dsc_truegrit_015), a good starting point beyond the usual dishes."]}},{"id":"blk_article_196_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"White peas for these dishes","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_196_5","type":"faq","version":1,"enabled":true,"props":{"heading":"White pea recipe questions","items":[{"question":"What is the difference between ghugni and ragda?","answer":"Both are cooked white pea preparations, differing mainly by region and specific spicing rather than the base ingredient."},{"question":"Can white peas be used in a salad?","answer":"Yes, cooked and cooled white peas tossed with vegetables and a light dressing make a simple, filling salad."},{"question":"Is sundal always made with white peas?","answer":"Sundal can be made with several pulses, white field peas being one common option among others."},{"question":"Are these dishes typically vegetarian?","answer":"Yes, all of these preparations are vegetarian, built entirely around the peas and everyday spices."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Ghugni and ragda anchor the tradition, though white peas show up in a few other regional dishes too.', seo_description='Traditional Indian recipes using white field peas: ghugni, ragda, and other regional preparations.', seo_keywords='white pea recipes, safed matar recipes', reading_minutes=3, published_version_id='arv_truegrit_196_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_196';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_196';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_196','Traditional Indian White Pea Recipes','traditional-indian-white-pea-recipes','Ghugni and ragda anchor the tradition, though white peas show up in a few other regional dishes too.','white pea recipes, safed matar recipes');

-- 198. Ragda Using White Peas
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_198_2','art_truegrit_198',2,'{"blocks":[{"id":"blk_article_198_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Ragda is built almost entirely on getting the white peas right, soft, well seasoned and slightly mashable, since the dish itself stays fairly simple once that base is in place."]}},{"id":"blk_article_198_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The method","items":["Soak white peas overnight, then pressure cook until fully soft, mashable between your fingers with light pressure.","Prepare a simple base of ginger, garlic and standard spices, cumin, coriander and turmeric, cooked briefly in oil.","Add the cooked peas along with some of their cooking liquid, simmering until the mixture thickens slightly.","Mash a portion of the peas directly in the pot for a thicker, more cohesive texture, leaving some whole for contrast.","Finish with a squeeze of lemon and fresh coriander, ready to serve on its own or as the base for ragda pattice."]}},{"id":"blk_article_198_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"White peas for ragda","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_198_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Ragda questions","items":[{"question":"How soft should the peas be for ragda?","answer":"Soft enough to mash easily between your fingers, since part of the dish''s texture comes from lightly mashed peas."},{"question":"Can I make ragda without a pressure cooker?","answer":"Yes, a long simmer in an open pot works too, though it will take considerably longer than pressure cooking."},{"question":"What is ragda typically served with?","answer":"Most commonly as ragda pattice, with fried potato patties, or as part of a chaat with various toppings."},{"question":"Can ragda be made ahead of time?","answer":"Yes, it keeps well refrigerated for a few days and reheats easily with a splash of water if it has thickened."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The base for ragda pattice and ragda chaat, built on properly softened, well seasoned white peas.', seo_description='How to make ragda using white field peas: soaking, cooking, and the masala that finishes it.', seo_keywords='ragda recipe, white pea ragda', reading_minutes=3, published_version_id='arv_truegrit_198_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_198';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_198';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_198','Ragda Using White Peas','ragda-using-white-peas','The base for ragda pattice and ragda chaat, built on properly softened, well seasoned white peas.','ragda recipe, white pea ragda');

-- 201. How to Store Dried Field Peas
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_201_2','art_truegrit_201',2,'{"blocks":[{"id":"blk_article_201_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Dried field peas store well using the same basic habits that protect most dried legumes, an airtight container, a cool dry spot, and an occasional check for pests."]}},{"id":"blk_article_201_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Keep dried field peas in an airtight container, protecting against both humidity and pests better than an open bag.","Store in a cool, dark place, away from direct sunlight and heat sources like a stove.","Check periodically for weevils or other pests, particularly during humid months or shortly after a fresh batch arrives.","Buy in a quantity you will realistically use within several months, rather than stocking far more than your kitchen turns over.","Properly stored, dried field peas keep well for a year or more without a noticeable drop in quality."]}},{"id":"blk_article_201_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"White field peas","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_201_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Field pea storage questions","items":[{"question":"How long do dried field peas last?","answer":"A year or more in an airtight container kept cool and dry, without a significant drop in quality."},{"question":"Does storage affect how long they need to soak later?","answer":"Very old stock can take slightly longer to soften even with a proper soak, though this is a gradual effect rather than a sudden one."},{"question":"Do dried field peas need refrigeration?","answer":"Not usually, a cool, dry pantry is sufficient for most households and climates."},{"question":"How do I check for pests in stored field peas?","answer":"Look for small holes in individual peas, fine dust, or visible insects, the same signs worth checking in any dried pulse."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The same basic dried legume storage habits, airtight, cool and checked periodically for pests.', seo_description='How to store dried field peas properly: containers, temperature, and checking for pests over time.', seo_keywords='how to store field peas, white pea storage', reading_minutes=2, published_version_id='arv_truegrit_201_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_201';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_201';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_201','How to Store Dried Field Peas','how-to-store-dried-field-peas','The same basic dried legume storage habits, airtight, cool and checked periodically for pests.','how to store field peas, white pea storage');

-- 202. What Does Organic Food Actually Mean?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_202_2','art_truegrit_202',2,'{"blocks":[{"id":"blk_article_202_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Organic is a legal, certified standard in India, not just marketing language for food grown without chemicals. A product can only carry the term if it has gone through an actual certification process covering how it was grown, handled and recorded."]}},{"id":"blk_article_202_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What it actually covers","items":["Farming without synthetic pesticides or fertilisers, using approved natural alternatives and practices like crop rotation instead.","A restricted list of permitted inputs, not zero inputs, since organic farming can still use certain approved natural substances.","Ongoing record keeping and periodic inspection, not a one time check, to confirm practices are actually being followed.","In India, this must be backed by certification under one of two recognised systems, covered in more detail elsewhere in this guide.","The term legally cannot be used on a food label without this underlying certification in place."]}},{"id":"blk_article_202_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Organic staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_202_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic food questions","items":[{"question":"Is organic simply food grown without any chemicals?","answer":"Not quite. Organic farming can use certain approved natural substances. It is a restricted, certified system rather than a zero substance claim."},{"question":"Can any farmer call their produce organic?","answer":"No, legally the term requires certification under a recognised system, not a self-declared claim."},{"question":"Does organic certification cover processing too?","answer":"Yes, certification generally extends beyond the farm to how a product is handled and processed afterward."},{"question":"Is organic the same as pesticide free?","answer":"Not exactly, some naturally derived pest control methods are permitted, so it is more accurate to call it restricted rather than entirely free of any input."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='More than an absence of chemicals. A legal, certified standard covering how a crop is grown, handled and recorded.', seo_description='What organic food actually means in India: certified farming practices, restricted inputs, and what the label legally requires.', seo_keywords='what does organic mean, organic food definition', reading_minutes=3, published_version_id='arv_truegrit_202_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_202';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_202';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_202','What Does Organic Food Actually Mean?','what-does-organic-food-actually-mean','More than an absence of chemicals. A legal, certified standard covering how a crop is grown, handled and recorded.','what does organic mean, organic food definition');

-- 203. Organic vs Natural: What’s the Difference?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_203_2','art_truegrit_203',2,'{"blocks":[{"id":"blk_article_203_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Organic and natural sound like they should mean similar things, but in India they sit on completely different legal footing. One requires certification and audit. The other, largely, does not."]}},{"id":"blk_article_203_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Organic is a certified, regulated term, requiring third party or peer review verification before it can legally appear on a label.","Natural has no formal, legally defined certification system in India, making it largely a self-declared claim by the brand using it.","A natural product can be entirely genuine in its claims without ever going through any external audit process.","An organic product, by contrast, has to pass an actual inspection and recordkeeping process to legally use the term.","Neither word alone guarantees quality, but organic carries a verification trail that natural, as a term, generally does not."]}},{"id":"blk_article_203_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Certified organic","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole"],"limit":2}},{"id":"blk_article_203_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic vs natural questions","items":[{"question":"Is a product labelled natural necessarily uncertified?","answer":"Generally yes for the natural claim specifically, since no formal certification system exists for that term in India."},{"question":"Can a product be both organic and natural?","answer":"Yes, many organic products are also reasonably described as natural, though the organic claim is the one backed by certification."},{"question":"Should I trust natural claims less than organic ones?","answer":"Not necessarily untrustworthy, but natural claims lack the external verification that organic certification requires."},{"question":"Why does this distinction matter when shopping?","answer":"Knowing which claim is verified helps you judge how much weight to put on a label versus needing to trust the brand''s word alone."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Organic is a regulated, audited claim. Natural, in India, is largely unregulated and self-declared.', seo_description='Organic compared with natural food claims: which is legally certified, and which has no formal regulatory definition in India.', seo_keywords='organic vs natural, is natural the same as organic', reading_minutes=3, published_version_id='arv_truegrit_203_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_203';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_203';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_203','Organic vs Natural: What’s the Difference?','organic-vs-natural-what-s-the-difference','Organic is a regulated, audited claim. Natural, in India, is largely unregulated and self-declared.','organic vs natural, is natural the same as organic');

-- 204. Organic vs Conventional Farming
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_204_2','art_truegrit_204',2,'{"blocks":[{"id":"blk_article_204_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Organic and conventional farming differ mainly in what inputs are allowed and how the soil itself is managed over time, differences that eventually show up in both the food and its price."]}},{"id":"blk_article_204_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Conventional farming allows a wide range of synthetic pesticides and fertilisers. Organic farming restricts inputs to an approved, mostly natural list.","Organic systems lean more heavily on crop rotation, composting and natural pest management to maintain soil health over time.","Yields are often lower under organic practices, part of why organic food frequently costs more than a conventional equivalent.","Conventional farming can achieve more consistent, higher volume output, which is part of why it remains the larger share of production.","Neither system is inherently right for every crop or region, and many farms sit somewhere between the two in practice."]}},{"id":"blk_article_204_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Organic farming practices","source":"manual","productSlugs":["organic-kathiya-wheat"],"limit":1}},{"id":"blk_article_204_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic vs conventional questions","items":[{"question":"Does organic farming ever use any pesticides?","answer":"It can, but only from an approved, mostly natural list, unlike conventional farming''s broader range of synthetic options."},{"question":"Why do organic farms often have lower yields?","answer":"Restricted inputs and reliance on natural pest and soil management typically produce less per acre than conventional methods."},{"question":"Is conventional farming always worse for the environment?","answer":"It varies by practice and region, and this is a genuinely debated question rather than one with a simple universal answer."},{"question":"Can a farm be partly organic and partly conventional?","answer":"Yes, though certification typically applies to specific, clearly separated plots rather than a farm as a whole if practices differ."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Different input rules, different soil practices, and a yield trade-off that shows up in price.', seo_description='Organic farming compared with conventional: input restrictions, soil practices, yield, and what that means for price.', seo_keywords='organic vs conventional farming', reading_minutes=3, published_version_id='arv_truegrit_204_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_204';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_204';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_204','Organic vs Conventional Farming','organic-vs-conventional-farming','Different input rules, different soil practices, and a yield trade-off that shows up in price.','organic vs conventional farming');

-- 205. How Organic Certification Works in India
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_205_2','art_truegrit_205',2,'{"blocks":[{"id":"blk_article_205_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["India recognises two main organic certification systems, NPOP and PGS-India, built for different scales of farming and using genuinely different verification methods to reach the same underlying standard."]}},{"id":"blk_article_205_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The two systems","items":["NPOP, the National Programme for Organic Production, uses accredited third party certification bodies and is common for larger scale and export oriented farming.","PGS-India, the Participatory Guarantee System, uses peer review among groups of farmers, administered through the Ministry of Agriculture, suited to smaller and marginal farms.","Both require documented practices, restricted inputs and some form of verification, just through different mechanisms.","A product certified under either system can carry the Jaivik Bharat logo, covered in more detail elsewhere in this guide.","Which system a farm uses often depends on its scale and whether it is producing primarily for export or the domestic market."]}},{"id":"blk_article_205_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Certified organic staples","source":"manual","productSlugs":["organic-kathiya-wheat","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_205_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic certification questions","items":[{"question":"Is one certification system better than the other?","answer":"They are built for different scales of farming rather than one being superior. Both lead to the same underlying organic standard."},{"question":"Which system suits small farmers better?","answer":"PGS-India, since its peer review approach is generally more accessible and affordable than NPOP''s third party audit process."},{"question":"Can a product carry both certifications?","answer":"It is uncommon, since a farm typically chooses one system suited to its scale rather than pursuing both simultaneously."},{"question":"Does certification need to be renewed?","answer":"Yes, organic certification under either system requires ongoing compliance and periodic reverification, not a one time approval."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Two recognised systems, NPOP and PGS-India, cover different scales of farming with different verification methods.', seo_description='How organic certification works in India: NPOP third-party certification and PGS-India peer review, explained.', seo_keywords='organic certification India, NPOP, PGS-India', reading_minutes=3, published_version_id='arv_truegrit_205_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_205';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_205';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_205','How Organic Certification Works in India','how-organic-certification-works-in-india','Two recognised systems, NPOP and PGS-India, cover different scales of farming with different verification methods.','organic certification India, NPOP, PGS-India');

-- 206. What Is Jaivik Bharat?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_206_2','art_truegrit_206',2,'{"blocks":[{"id":"blk_article_206_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Jaivik Bharat is a unified logo introduced to make genuinely certified organic products easier for shoppers to spot at a glance, rather than a certification system of its own."]}},{"id":"blk_article_206_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What it actually is","items":["A logo introduced by FSSAI to help identify certified organic food products consistently across brands and packaging.","Not a separate certification itself, a product must already be certified under NPOP or PGS-India to display it.","Intended to reduce confusion from the wide variety of organic labelling that existed on packaging before it was introduced.","Appears alongside the underlying certification details, not as a replacement for the certificate number itself.","A useful visual cue when shopping, though it is still worth checking the certification details behind it rather than relying on the logo alone."]}},{"id":"blk_article_206_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Organic products","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole"],"limit":2}},{"id":"blk_article_206_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Jaivik Bharat questions","items":[{"question":"Is the Jaivik Bharat logo a certification on its own?","answer":"No, it is a unifying logo. The underlying certification still comes from NPOP or PGS-India."},{"question":"Who introduced the Jaivik Bharat logo?","answer":"FSSAI introduced it to help consumers identify certified organic products more consistently across different brands."},{"question":"Can a product show the logo without real certification?","answer":"It should not be able to legally, since the logo is meant to be tied to underlying certification, though checking the certificate details is still worthwhile."},{"question":"Does every organic product carry this logo?","answer":"Not universally yet, since labelling updates take time to roll out across all products and brands."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A unified logo introduced to help shoppers spot genuinely certified organic products at a glance.', seo_description='Jaivik Bharat explained: the unified organic logo in India and what certification it actually requires behind it.', seo_keywords='Jaivik Bharat, Jaivik Bharat meaning', reading_minutes=2, published_version_id='arv_truegrit_206_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_206';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_206';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_206','What Is Jaivik Bharat?','what-is-jaivik-bharat','A unified logo introduced to help shoppers spot genuinely certified organic products at a glance.','Jaivik Bharat, Jaivik Bharat meaning');

-- 207. What Does the Jaivik Bharat Logo Mean?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_207_2','art_truegrit_207',2,'{"blocks":[{"id":"blk_article_207_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Seeing the Jaivik Bharat logo on a pack is a useful first signal, but the certificate details printed alongside it are what actually confirm the organic claim behind that logo."]}},{"id":"blk_article_207_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually check","items":["The logo itself signals that the product is meant to be certified organic under NPOP or PGS-India.","A genuine pack should also show a certificate or licence number, not just the logo on its own.","The certifying body''s name is usually printed nearby, which you can look up independently if you want to verify it.","Absence of any certificate number alongside the logo is worth treating as a reason to look more closely before trusting the claim.","This logo is separate from the FSSAI licence number every food business needs, covered in more detail elsewhere in this guide."]}},{"id":"blk_article_207_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Organic staples","source":"manual","productSlugs":["organic-kathiya-wheat"],"limit":1}},{"id":"blk_article_207_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Reading the Jaivik Bharat logo questions","items":[{"question":"Is the logo alone enough to trust a product is organic?","answer":"It is a helpful signal, but checking for an accompanying certificate number gives a more complete picture."},{"question":"Where should the certificate number appear on the pack?","answer":"Typically near the organic logo itself, though exact placement varies by brand and packaging design."},{"question":"Can I look up a certifying body independently?","answer":"Yes, most certifying bodies operating in India can be checked independently if you want to confirm they are legitimate."},{"question":"Is this logo the same as an FSSAI mark?","answer":"No, they are separate. FSSAI licensing is a general food safety requirement, not specific to organic certification."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A quick visual signal, but the certificate number next to it is what actually confirms the claim.', seo_description='What the Jaivik Bharat logo on a food pack signals, and what to check alongside it to confirm the claim.', seo_keywords='Jaivik Bharat logo, organic logo India', reading_minutes=2, published_version_id='arv_truegrit_207_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_207';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_207';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_207','What Does the Jaivik Bharat Logo Mean?','what-does-the-jaivik-bharat-logo-mean','A quick visual signal, but the certificate number next to it is what actually confirms the claim.','Jaivik Bharat logo, organic logo India');

-- 208. What Does FSSAI Certification Mean?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_208_2','art_truegrit_208',2,'{"blocks":[{"id":"blk_article_208_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["FSSAI licensing is a baseline food safety requirement, not an organic endorsement. Every legitimate food business in India needs one, whether or not it sells anything organic at all."]}},{"id":"blk_article_208_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What it actually means","items":["FSSAI, the Food Safety and Standards Authority of India, issues licences confirming a food business meets basic safety and hygiene requirements.","Every legitimate food business needs an FSSAI licence or registration, regardless of whether it sells organic products or not.","It is not an organic certification and does not, on its own, say anything about how a product was farmed.","An FSSAI number and an organic certificate number are two separate things, often both printed on the same organic product''s packaging.","Its presence confirms baseline food safety compliance, a separate and equally important consideration alongside any organic claim."]}},{"id":"blk_article_208_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Certified food products","source":"manual","productSlugs":["organic-kathiya-wheat","sesame-oil"],"limit":2}},{"id":"blk_article_208_4","type":"faq","version":1,"enabled":true,"props":{"heading":"FSSAI certification questions","items":[{"question":"Does an FSSAI number mean a product is organic?","answer":"No, FSSAI licensing is a general food safety requirement, unrelated to whether a product is organic."},{"question":"Is FSSAI licensing mandatory?","answer":"Yes, essentially every legitimate food business operating in India needs an FSSAI licence or registration."},{"question":"Can a product have an FSSAI number but no organic certificate?","answer":"Yes, this is the norm for conventional food products, which still need FSSAI compliance despite not being organic."},{"question":"Where can I check an FSSAI number?","answer":"FSSAI provides a way to verify licence numbers, which is worth doing if a claim seems questionable."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A basic food safety requirement every food business needs, distinct from and unrelated to organic status.', seo_description='What FSSAI certification means: mandatory food safety licensing in India, and how it differs from organic certification.', seo_keywords='FSSAI certification meaning, FSSAI license', reading_minutes=2, published_version_id='arv_truegrit_208_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_208';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_208';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_208','What Does FSSAI Certification Mean?','what-does-fssai-certification-mean','A basic food safety requirement every food business needs, distinct from and unrelated to organic status.','FSSAI certification meaning, FSSAI license');

-- 209. What Does “100% Organic” Mean?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_209_2','art_truegrit_209',2,'{"blocks":[{"id":"blk_article_209_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A 100% organic claim is a specific, legally meaningful statement, not a loose way of saying mostly organic. It requires the full product to be certified, not just some of its ingredients."]}},{"id":"blk_article_209_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What it actually requires","items":["All ingredients in the product must be certified organic for a legitimate 100% organic claim to apply.","A product with even a small proportion of non-organic ingredients cannot legally use this specific phrase.","This differs from a more general organic claim, which can sometimes apply to products with a defined minimum organic content rather than the full product.","Checking the certificate behind a 100% organic claim confirms it covers the entire product, not just a headline ingredient.","Single ingredient products, like a whole grain or a pressed oil, are the simplest case for this claim to apply cleanly."]}},{"id":"blk_article_209_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Fully organic products","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_209_4","type":"faq","version":1,"enabled":true,"props":{"heading":"100% organic claim questions","items":[{"question":"Can a multi-ingredient product be 100% organic?","answer":"Yes, if every single ingredient in it is independently certified organic, not just the main one."},{"question":"Is this claim stricter than a general organic label?","answer":"Yes, it specifically requires full organic content, whereas some organic labelling allows for a defined partial content."},{"question":"Why do single ingredient products use this claim more often?","answer":"There is only one ingredient to certify, making full compliance simpler than for a product with many ingredients."},{"question":"Should I always check the certificate behind a 100% organic claim?","answer":"It is a reasonable habit, particularly for multi-ingredient products where the claim depends on every component being certified."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A specific legal claim requiring full certification, not a phrase that can be used loosely.', seo_description='What a 100% organic claim legally requires in India, and why it cannot be used for partially organic products.', seo_keywords='100% organic meaning, what does 100 percent organic mean', reading_minutes=2, published_version_id='arv_truegrit_209_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_209';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_209';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_209','What Does “100% Organic” Mean?','what-does-100-organic-mean','A specific legal claim requiring full certification, not a phrase that can be used loosely.','100% organic meaning, what does 100 percent organic mean');

-- 210. How to Read an Organic Food Label
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_210_2','art_truegrit_210',2,'{"blocks":[{"id":"blk_article_210_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A genuine organic label carries a handful of specific, checkable details, not just the word organic printed somewhere on the pack. Knowing what those details are makes reading a label much faster."]}},{"id":"blk_article_210_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to actually look for","items":["The Jaivik Bharat logo, or an equivalent organic certification mark, rather than the word organic used without any mark at all.","A certificate or licence number specific to the organic certification, separate from the general FSSAI number.","The name of the certifying body, which you can look up independently if a claim seems worth double checking.","Whether the claim is for the full product or a specific ingredient, particularly on multi-ingredient packaged foods.","A batch or lot number, which supports traceability back to the specific harvest or production run."]}},{"id":"blk_article_210_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One shopper describes checking for a certification number and confirming the certifying body exists as roughly where their own checking stops](/community/dsc_truegrit_023), a reasonable baseline if you are not sure where to start."]}},{"id":"blk_article_210_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Clearly labelled organic","source":"manual","productSlugs":["organic-kathiya-wheat"],"limit":1}},{"id":"blk_article_210_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Reading organic labels questions","items":[{"question":"Is the word organic alone enough on a label?","answer":"No, look for an actual certification mark and certificate number rather than trusting the word alone."},{"question":"What if a label has no certificate number at all?","answer":"That is worth treating cautiously, since a genuine organic claim should be backed by a checkable certificate."},{"question":"Does every organic product need a batch number?","answer":"It is common practice for traceability, though not every product displays it as prominently as the certification mark."},{"question":"How long does checking a label properly take?","answer":"Once you know what to look for, a quick label check takes only a few seconds."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A handful of specific details to check, rather than trusting the word organic printed anywhere on the pack.', seo_description='How to read an organic food label properly: certification marks, certificate numbers, and what to look for.', seo_keywords='how to read organic label, organic label India', reading_minutes=3, published_version_id='arv_truegrit_210_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_210';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_210';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_210','How to Read an Organic Food Label','how-to-read-an-organic-food-label','A handful of specific details to check, rather than trusting the word organic printed anywhere on the pack.','how to read organic label, organic label India');

-- 211. How to Verify Organic Food Certification in India
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_211_2','art_truegrit_211',2,'{"blocks":[{"id":"blk_article_211_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Verifying an organic certification takes a bit more effort than reading a label, but it is the step that actually confirms a claim rather than simply trusting it at face value."]}},{"id":"blk_article_211_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually verify it","items":["Note the certificate or licence number and the certifying body''s name printed on the product or its label.","Search for the certifying body independently to confirm it is a recognised, legitimate organisation operating in India.","Where available, cross check the certificate number against the certifying body''s own public records.","Be cautious of vague claims with no checkable number or unnamed certifying body behind them.","This extra step matters most for higher value purchases or brands you are buying from for the first time.","A brand willing to share certification details openly, without hesitation, is generally a good sign in itself."]}},{"id":"blk_article_211_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Verifiable organic products","source":"manual","productSlugs":["organic-kathiya-wheat","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_211_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Verifying certification questions","items":[{"question":"Is verification necessary for every purchase?","answer":"Not strictly, but it is a reasonable habit for higher value purchases or a brand you have not bought from before."},{"question":"Can I verify a certificate number online?","answer":"Often yes, depending on the certifying body, though not every organisation has a fully public searchable database."},{"question":"What if I cannot verify a certificate at all?","answer":"Treat that as a reason for caution rather than automatic distrust, and consider contacting the seller directly for more detail."},{"question":"Does verification guarantee the product is genuinely organic?","answer":"It confirms the certification is real and current, which is the strongest check available to an individual shopper."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Checking a certificate number against the issuing body is the most reliable step most shoppers skip.', seo_description='How to verify organic food certification in India: checking certificate numbers and certifying bodies before buying.', seo_keywords='how to verify organic certification, check organic certificate India', reading_minutes=3, published_version_id='arv_truegrit_211_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_211';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_211';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_211','How to Verify Organic Food Certification in India','how-to-verify-organic-food-certification-in-india','Checking a certificate number against the issuing body is the most reliable step most shoppers skip.','how to verify organic certification, check organic certificate India');

-- 212. Why Organic Products Can Cost More
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_212_2','art_truegrit_212',2,'{"blocks":[{"id":"blk_article_212_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Organic pricing traces back to real costs in the farming and certification process, not simply a markup attached to the word organic on a label."]}},{"id":"blk_article_212_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually drives the price","items":["Lower yields are common under organic practices, meaning more land and labour are needed for the same volume of output.","Certification itself costs money, whether through NPOP''s third party audits or PGS-India''s group administration.","Organic farming is often more labour intensive, relying on manual and natural methods rather than some mechanised or chemical shortcuts.","Smaller scale production, common among organic farms, generally costs more per unit than large scale conventional farming.","These are real, ongoing costs passed through the supply chain, not a one time premium added purely for marketing.","Transport and handling can also cost more for smaller volumes moving through a less consolidated supply chain."]}},{"id":"blk_article_212_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Certified organic","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole"],"limit":2}},{"id":"blk_article_212_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic pricing questions","items":[{"question":"Is organic food always more expensive?","answer":"Usually, though the gap varies by crop, region and scale of production."},{"question":"Does certification alone add much to the cost?","answer":"It contributes, but lower yields and more labour intensive farming are typically the bigger factors overall."},{"question":"Will organic prices come down over time?","answer":"As more farms adopt organic practices and scale increases, prices can moderate, though this varies by market."},{"question":"Is the price difference worth it?","answer":"That is a personal judgement based on your own priorities, not something this article claims to settle either way."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Lower yields, smaller scale farming and certification costs, not simply a premium markup.', seo_description='Why organic products often cost more: lower yields, certification costs, and smaller scale farming explained.', seo_keywords='why is organic food expensive, organic food price', reading_minutes=3, published_version_id='arv_truegrit_212_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_212';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_212';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_212','Why Organic Products Can Cost More','why-organic-products-can-cost-more','Lower yields, smaller scale farming and certification costs, not simply a premium markup.','why is organic food expensive, organic food price');

-- 213. Why Organic Food May Look Different From Conventional Produce
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_213_2','art_truegrit_213',2,'{"blocks":[{"id":"blk_article_213_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Organic produce often looks less uniform than its conventional counterpart, and that is largely a side effect of the restricted input list organic farming works within, not a sign of lower quality."]}},{"id":"blk_article_213_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What is actually happening","items":["Conventional farming sometimes uses synthetic inputs that promote uniform size and shape, tools organic farming does not have access to.","Natural blemishes and size variation are more common on organic produce, without this reflecting the food''s actual quality.","Colour can vary more between individual pieces or batches, discussed in more detail elsewhere in this guide.","Consumers used to highly uniform supermarket produce sometimes read this natural variation as a flaw rather than a normal characteristic.","This applies mainly to fresh produce. Packaged staples like grains, pulses and oils show far less visible variation."]}},{"id":"blk_article_213_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Organic staples","source":"manual","productSlugs":["organic-kathiya-wheat"],"limit":1}},{"id":"blk_article_213_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic appearance questions","items":[{"question":"Does irregular appearance mean lower quality?","answer":"Not necessarily. It often reflects the absence of synthetic tools used to standardise appearance in conventional farming."},{"question":"Does this apply to packaged grains and pulses too?","answer":"Much less so, since packaged staples show far less visible variation than fresh produce does."},{"question":"Should I be suspicious of very uniform organic produce?","answer":"Not automatically, but it is a reasonable detail to be curious about if it seems unusually consistent for a genuinely organic item."},{"question":"Is taste affected by this variation?","answer":"Not directly. Appearance variation is a cosmetic factor separate from flavour or nutritional content."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Less uniform shape and size is a normal side effect of skipping synthetic growth regulation, not a defect.', seo_description='Why organic food can look different from conventional produce: natural size variation and cosmetic imperfections.', seo_keywords='why organic food looks different, organic produce appearance', reading_minutes=2, published_version_id='arv_truegrit_213_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_213';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_213';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_213','Why Organic Food May Look Different From Conventional Produce','why-organic-food-may-look-different-from-conventional-produce','Less uniform shape and size is a normal side effect of skipping synthetic growth regulation, not a defect.','why organic food looks different, organic produce appearance');

-- 214. Why Organic Product Colour Can Vary Between Batches
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_214_2','art_truegrit_214',2,'{"blocks":[{"id":"blk_article_214_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Colour variation between batches of an organic product is a normal reflection of natural growing conditions, not a sign of inconsistent quality between one bag and the next."]}},{"id":"blk_article_214_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually causes it","items":["Different harvests, even from the same farm, can vary slightly in colour depending on rainfall, soil and growing conditions that season.","Without synthetic standardisation, natural colour variation is simply allowed to show rather than being corrected artificially.","Processing methods, like cold pressing an oil, also let more natural colour variation through than heavily refined processing does.","This variation does not indicate a quality problem, and is discussed in more depth for specific products like mustard oil elsewhere on this site.","Batches from different regions or farmer groups, common under smaller scale organic production, can also show more variation than a single large uniform source."]}},{"id":"blk_article_214_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Naturally varied organic products","source":"manual","productSlugs":["black-mustard-oil","organic-kathiya-wheat"],"limit":2}},{"id":"blk_article_214_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Batch colour variation questions","items":[{"question":"Is colour variation a sign a product is not really organic?","answer":"No, if anything it reflects the natural conditions organic production does not artificially standardise away."},{"question":"Does colour variation affect flavour?","answer":"Not necessarily, colour and flavour can vary somewhat independently depending on the specific product and process."},{"question":"Should I expect the same colour every time I buy?","answer":"Some variation between batches is normal for organic products, more so than for heavily processed conventional ones."},{"question":"Does this happen with packaged grains and pulses too?","answer":"Yes, though it is often less visually obvious than with a liquid product like an unrefined oil."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Natural variation from harvest to harvest, without synthetic standardisation smoothing it out.', seo_description='Why organic product colour can vary between batches: natural harvest and processing variation explained.', seo_keywords='organic product colour variation, batch variation organic', reading_minutes=2, published_version_id='arv_truegrit_214_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_214';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_214';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_214','Why Organic Product Colour Can Vary Between Batches','why-organic-product-colour-can-vary-between-batches','Natural variation from harvest to harvest, without synthetic standardisation smoothing it out.','organic product colour variation, batch variation organic');

-- 215. Why Natural Foods Don’t Always Look Uniform
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_215_2','art_truegrit_215',2,'{"blocks":[{"id":"blk_article_215_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Minimally processed, naturally produced foods rarely look as perfectly uniform as heavily processed ones, and that visible variation is a genuine side effect of less processing, not a quality issue."]}},{"id":"blk_article_215_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What is actually happening","items":["Less processing means fewer steps that would otherwise standardise size, colour or texture artificially.","Natural variation in the raw ingredient carries through more visibly when processing is kept minimal.","This is true whether or not a product is formally certified organic, since it relates to processing degree rather than certification status specifically.","Consumers accustomed to heavily standardised products sometimes mistake this natural variation for inconsistency in quality.","Minor visible variation between batches is a reasonable, expected trait of minimally processed food, not something to be concerned about.","This holds across grains, pulses and pressed oils alike, wherever processing has been kept close to the original ingredient."]}},{"id":"blk_article_215_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Minimally processed staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_215_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Natural food appearance questions","items":[{"question":"Does this apply only to organic foods?","answer":"No, it relates more to how minimally a food is processed than to its certification status specifically."},{"question":"Is more processing always a bad thing?","answer":"Not inherently, processing serves real purposes like safety and shelf life. It simply tends to reduce visible natural variation as a side effect."},{"question":"How can I tell natural variation apart from an actual defect?","answer":"Minor differences in colour, size or texture are normal. Signs like off smells or visible spoilage are the real things to watch for."},{"question":"Will this variation affect how a recipe turns out?","answer":"Rarely in a meaningful way, most natural variation is cosmetic rather than functional in cooking."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Minimal processing means less artificial standardisation, which shows up as visible, harmless variation.', seo_description='Why natural foods do not always look perfectly uniform, and why that variation is normal rather than a flaw.', seo_keywords='natural food appearance, why natural foods vary', reading_minutes=2, published_version_id='arv_truegrit_215_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_215';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_215';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_215','Why Natural Foods Don’t Always Look Uniform','why-natural-foods-don-t-always-look-uniform','Minimal processing means less artificial standardisation, which shows up as visible, harmless variation.','natural food appearance, why natural foods vary');

-- 216. Seasonal Variation in Organic Foods Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_216_2','art_truegrit_216',2,'{"blocks":[{"id":"blk_article_216_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Organic production tends to follow natural growing seasons more closely, since fewer synthetic tools exist to force off-season yields, and that shows up in flavour, appearance and sometimes availability across the year."]}},{"id":"blk_article_216_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually changes with the season","items":["Flavour can shift subtly between harvests, reflecting the specific growing conditions of that particular season.","Appearance, including colour and size, can vary more noticeably across seasons than with conventionally standardised produce.","Availability of certain organic products can be more seasonal, without the same year-round consistency conventional supply chains sometimes offer.","This is a genuine trade-off of working closer to natural growing cycles, not a sign of inconsistent sourcing.","Packaged, shelf stable staples like grains and pressed oils show this effect less directly than fresh seasonal produce does.","Buying seasonally, when a particular organic product is at its peak, often gives the best flavour for the price."]}},{"id":"blk_article_216_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Seasonally sourced staples","source":"manual","productSlugs":["organic-kathiya-wheat"],"limit":1}},{"id":"blk_article_216_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Seasonal organic variation questions","items":[{"question":"Does seasonal variation mean lower quality at certain times of year?","answer":"No, it reflects natural growing conditions rather than a decline in quality."},{"question":"Are packaged staples affected by seasonal variation too?","answer":"Less directly than fresh produce, though the underlying harvest still varies somewhat season to season."},{"question":"Why does conventional produce seem more consistent year round?","answer":"Conventional supply chains often use methods to extend or standardise availability that organic production relies on less."},{"question":"Should I expect the same flavour from every batch?","answer":"Close, but some subtle variation between seasons and harvests is a normal characteristic of organic production."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Fewer synthetic tools to force off-season production means flavour, appearance and availability shift with the calendar.', seo_description='Seasonal variation in organic foods explained: why flavour, appearance and availability shift throughout the year.', seo_keywords='seasonal variation organic food, organic food seasons', reading_minutes=2, published_version_id='arv_truegrit_216_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_216';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_216';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_216','Seasonal Variation in Organic Foods Explained','seasonal-variation-in-organic-foods-explained','Fewer synthetic tools to force off-season production means flavour, appearance and availability shift with the calendar.','seasonal variation organic food, organic food seasons');

-- 217. Common Myths About Organic Food
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_217_2','art_truegrit_217',2,'{"blocks":[{"id":"blk_article_217_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Organic food attracts a handful of widely repeated claims that do not fully hold up once checked against what certification actually requires, in either direction, so it is worth separating what the standard genuinely covers from what people simply assume it does."]}},{"id":"blk_article_217_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Worth checking","items":["Myth: organic means zero pesticides. In reality, certain approved natural pesticides are permitted, just not synthetic ones.","Myth: organic food is always more nutritious. There is no consistently verified evidence supporting a broad nutritional advantage.","Myth: organic automatically means local. Organic certification says nothing about where a product was grown relative to where it is sold.","Myth: any product labelled natural is effectively organic. Natural has no formal certification system in India, unlike organic.","Myth: organic certification is a one time approval. It requires ongoing compliance and periodic reverification, not a single check."]}},{"id":"blk_article_217_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Genuinely certified organic","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_217_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic myths questions","items":[{"question":"Is it true organic food never uses pesticides?","answer":"No, certain approved natural pesticides are permitted under organic standards. Synthetic pesticides are what is restricted."},{"question":"Is organic food proven to be more nutritious?","answer":"There is no consistent, verified evidence for a broad nutritional advantage, so this claim should not be taken as settled."},{"question":"Does organic mean a product travelled less to reach me?","answer":"Not necessarily, organic certification addresses farming practices, not distance travelled or sourcing location."},{"question":"Is natural labelling regulated the same way as organic?","answer":"No, natural has no formal certification system in India, unlike organic, which does require certification."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A few widely repeated claims worth checking, rather than accepting or dismissing organic food on assumption alone.', seo_description='Common myths about organic food, checked against what certification actually requires and what remains unverified.', seo_keywords='organic food myths, organic food misconceptions', reading_minutes=3, published_version_id='arv_truegrit_217_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_217';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_217';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_217','Common Myths About Organic Food','common-myths-about-organic-food','A few widely repeated claims worth checking, rather than accepting or dismissing organic food on assumption alone.','organic food myths, organic food misconceptions');

-- 218. Does Organic Automatically Mean Chemical-Free?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_218_2','art_truegrit_218',2,'{"blocks":[{"id":"blk_article_218_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["No, organic does not automatically mean chemical-free. Certification restricts which inputs are permitted, favouring approved natural substances over synthetic ones, which is a meaningfully different claim than zero chemicals of any kind."]}},{"id":"blk_article_218_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why the answer is no","items":["Organic standards restrict inputs to an approved list, which can still include certain naturally derived pesticides and fertilisers.","Many naturally occurring substances are, strictly speaking, still chemicals, making chemical-free an imprecise claim on any food product.","The more accurate description of organic is restricted synthetic input use, not an absence of all substances beyond the food itself.","This distinction matters because chemical-free is not a term organic certification actually verifies or requires.","A genuinely organic product''s certificate confirms compliance with input restrictions, not a chemical-free claim specifically.","Understanding this difference helps set realistic expectations rather than reading more into a certification than it actually promises."]}},{"id":"blk_article_218_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Certified organic","source":"manual","productSlugs":["organic-kathiya-wheat"],"limit":1}},{"id":"blk_article_218_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic and chemicals questions","items":[{"question":"So what does organic certification actually restrict?","answer":"It restricts which inputs are permitted, favouring an approved, mostly natural list over synthetic pesticides and fertilisers."},{"question":"Is chemical-free ever an accurate food label?","answer":"Rarely in a strict sense, since many natural substances are technically chemicals. It is generally an imprecise, unregulated claim."},{"question":"Should I distrust a product that says chemical-free?","answer":"Treat it as a marketing phrase rather than a certified claim, and look for actual organic certification details instead."},{"question":"Does this mean organic food is not safer?","answer":"This article is not making a safety claim either way, only clarifying that chemical-free is not what organic certification verifies."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='No. Organic restricts inputs to an approved list, which is a different claim than zero substances of any kind.', seo_description='Does organic mean chemical-free: why the answer is no, and what organic certification actually restricts.', seo_keywords='organic chemical free, is organic chemical free', reading_minutes=2, published_version_id='arv_truegrit_218_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_218';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_218';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_218','Does Organic Automatically Mean Chemical-Free?','does-organic-automatically-mean-chemical-free','No. Organic restricts inputs to an approved list, which is a different claim than zero substances of any kind.','organic chemical free, is organic chemical free');

-- 219. Organic Certification vs Homemade/Natural Products
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_219_2','art_truegrit_219',2,'{"blocks":[{"id":"blk_article_219_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A homemade or small batch natural product can be made with entirely good intentions and still not be the same thing, legally or practically, as a certified organic one. The difference is the audit trail behind the claim."]}},{"id":"blk_article_219_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually separates them","items":["Certified organic products have documented practices and external verification behind the claim. Homemade natural products typically do not.","This is not a statement about which is better made, only about which claim can be independently checked and which cannot.","A small producer may follow genuinely careful practices without ever pursuing formal certification, often for cost or scale reasons.","Buyers relying entirely on trust in an uncertified maker are accepting a different level of verification than a certified product offers.","Neither approach is inherently dishonest, but they are not interchangeable claims, and a shopper benefits from knowing the difference."]}},{"id":"blk_article_219_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Independently certified","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole"],"limit":2}},{"id":"blk_article_219_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Certified vs homemade questions","items":[{"question":"Is homemade natural food automatically less safe?","answer":"Not necessarily, but it lacks the external verification that formal certification provides, which is a real, checkable difference."},{"question":"Why don''t all small producers pursue certification?","answer":"Often cost and process complexity, particularly for very small scale producers, make formal certification harder to justify."},{"question":"Can a homemade product ever become certified later?","answer":"Yes, a producer can pursue certification as they scale, though it requires meeting the same documented standards as any other applicant."},{"question":"Should I avoid uncertified natural products entirely?","answer":"That is a personal choice. This article is only clarifying what certification does and does not confirm, not making a blanket recommendation."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Good intentions are not the same as an audit trail. Certification is what actually distinguishes the two.', seo_description='Organic certification compared with homemade or natural products: why an audit trail is the real difference.', seo_keywords='organic certification vs homemade, certified vs natural products', reading_minutes=2, published_version_id='arv_truegrit_219_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_219';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_219';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_219','Organic Certification vs Homemade/Natural Products','organic-certification-vs-homemade-natural-products','Good intentions are not the same as an audit trail. Certification is what actually distinguishes the two.','organic certification vs homemade, certified vs natural products');

-- 220. How Organic Products Are Traced From Farm to Pack
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_220_2','art_truegrit_220',2,'{"blocks":[{"id":"blk_article_220_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Genuine organic certification requires more than a final label, it requires a documented trail connecting the packaged product back to a specific farm and harvest, maintained through every stage in between."]}},{"id":"blk_article_220_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How the trail is maintained","items":["Farms under certification keep records of practices, inputs used and harvest details for each certified plot.","Processors and packers maintain batch or lot records connecting incoming raw material to what eventually reaches a shelf.","Certification audits check this documentation, not just the final product, to confirm the trail holds together end to end.","A batch or lot number on packaging is often the visible piece of this trail a shopper can actually see and reference.","This is what genuinely separates a documented organic supply chain from a claim based purely on trust."]}},{"id":"blk_article_220_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One shopper asks what farm information would genuinely change their buying decision, since a village name alone is hard to verify but a harvest date or specific variety feels checkable](/community/dsc_truegrit_024), a useful frame for thinking about what traceability should actually offer."]}},{"id":"blk_article_220_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traceable organic staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_220_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Farm to pack traceability questions","items":[{"question":"Does every organic product have a visible batch number?","answer":"It is common practice, though how prominently it is displayed varies by brand and packaging design."},{"question":"What does a certification audit actually check?","answer":"It checks documented practices and records at each stage, not only the final packaged product on a shelf."},{"question":"Can a shopper independently trace a product back to its farm?","answer":"Rarely in full detail, though a batch number and certificate can support a more limited verification if needed."},{"question":"Why does traceability matter beyond organic certification?","answer":"It supports accountability and quality control generally, which is discussed further elsewhere on this site."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Certification requires a documented trail, not just a final label, connecting the pack back to a specific harvest.', seo_description='How organic products are traced from farm to pack: batch records, documentation, and what certification requires.', seo_keywords='organic traceability, farm to pack organic', reading_minutes=3, published_version_id='arv_truegrit_220_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_220';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_220';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_220','How Organic Products Are Traced From Farm to Pack','how-organic-products-are-traced-from-farm-to-pack','Certification requires a documented trail, not just a final label, connecting the pack back to a specific harvest.','organic traceability, farm to pack organic');

-- 221. From Farm to Flour: How True Grit Products Are Made
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_221_2','art_truegrit_221',2,'{"blocks":[{"id":"blk_article_221_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Every product in this range follows the same broad journey, sourced from farms growing specific varieties, processed using traditional methods suited to that ingredient, and packaged for the kitchen rather than for a warehouse shelf."]}},{"id":"blk_article_221_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The general journey","items":["Grain, seed or pulse is sourced from farms growing the specific variety a product is built around, rather than a generic commodity blend.","Processing follows traditional methods suited to the ingredient, cracking for daliya, pressing for oil, milling for flour and semolina.","Batches are produced in response to actual demand rather than held in large speculative stock for long periods.","Packaging happens close to processing, aiming to get a fresher product to a kitchen than a long warehousing chain would.","This approach trades some scale and speed for freshness and closer quality control at each step."]}},{"id":"blk_article_221_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Products from this journey","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_221_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Farm to flour questions","items":[{"question":"Does every product follow the exact same steps?","answer":"The broad journey is similar, but the specific processing, cracking, pressing or milling, depends on what the product actually is."},{"question":"Why does this approach take more time than mass production?","answer":"Sourcing specific varieties and traditional processing both take longer than a fully automated, high volume approach."},{"question":"Does this affect how products should be stored?","answer":"Freshly processed products can be more sensitive to storage conditions, which is why storage guidance appears throughout this site."},{"question":"Is this approach used for every single product you sell?","answer":"It describes our general model, though specific practices can vary somewhat by ingredient and product."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Sourcing, traditional processing and packaging, the same broad journey behind every product in this range.', seo_description='How True Grit products are made: sourcing grain from farms, traditional processing, and getting it to your kitchen.', seo_keywords='how True Grit products are made, farm to flour', reading_minutes=3, published_version_id='arv_truegrit_221_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_221';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_221';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_221','From Farm to Flour: How True Grit Products Are Made','from-farm-to-flour-how-true-grit-products-are-made','Sourcing, traditional processing and packaging, the same broad journey behind every product in this range.','how True Grit products are made, farm to flour');

-- 222. What “Made to Order” Food Actually Means
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_222_2','art_truegrit_222',2,'{"blocks":[{"id":"blk_article_222_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Made to order means production happens closer to when a batch is actually needed, rather than sitting finished on a shelf for weeks or months before it is bought."]}},{"id":"blk_article_222_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What it actually means","items":["Production is timed closer to actual demand, rather than building up large speculative stock ahead of time.","This generally means fresher product reaching a customer, since less time passes between processing and delivery.","The trade-off is less instant availability compared to a large pre-stocked warehouse model.","It also allows smaller, more specific batches, useful for products where freshness genuinely affects the final result, like a pressed oil.","This is different from custom made products built to individual specification, which is a separate concept entirely.","It also reduces the amount of unsold stock that might otherwise sit in a warehouse for an extended period."]}},{"id":"blk_article_222_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Freshly produced staples","source":"manual","productSlugs":["black-mustard-oil","organic-kathiya-wheat"],"limit":2}},{"id":"blk_article_222_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Made to order questions","items":[{"question":"Does made to order mean longer delivery times?","answer":"It can, since production is timed closer to demand rather than pulling from a large pre-existing stock."},{"question":"Is made to order the same as custom made?","answer":"No, made to order refers to production timing, not customising a product to individual specification."},{"question":"Why does this matter for something like oil?","answer":"Freshly pressed oil generally has better flavour and a longer useful shelf life than oil that has sat in storage for a long time."},{"question":"Does this apply to all products equally?","answer":"The degree varies by product, since some staples keep well regardless of exact production timing while others benefit more directly."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Producing closer to when an order is placed, rather than holding large stock, trading speed for freshness.', seo_description='What made to order food actually means: producing closer to demand, and the trade-off with instant availability.', seo_keywords='made to order food, what does made to order mean', reading_minutes=2, published_version_id='arv_truegrit_222_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_222';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_222';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_222','What “Made to Order” Food Actually Means','what-made-to-order-food-actually-means','Producing closer to when an order is placed, rather than holding large stock, trading speed for freshness.','made to order food, what does made to order mean');

-- 223. Why We Produce Many Foods in Small Batches
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_223_2','art_truegrit_223',2,'{"blocks":[{"id":"blk_article_223_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Small batch production is a deliberate trade-off, giving up some of the scale and speed a larger production run offers in exchange for closer quality control and a fresher finished product."]}},{"id":"blk_article_223_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why it matters","items":["Smaller batches allow closer attention at each processing step, rather than relying entirely on automated, high volume methods.","Freshness benefits from smaller runs, since less product sits in intermediate storage before reaching packaging.","Quality issues in a smaller batch are easier to catch and address than in a very large production run.","The trade-off is less consistency in exact timing and availability compared to continuous large scale production.","This approach suits ingredients where freshness and traditional processing genuinely affect the final result more than convenience savings would.","It also keeps the total volume of any single run manageable enough for the kind of close attention this guide describes elsewhere."]}},{"id":"blk_article_223_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Small-batch staples","source":"manual","productSlugs":["black-mustard-oil","organic-kathiya-wheat"],"limit":2}},{"id":"blk_article_223_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Small batch production questions","items":[{"question":"Does small batch mean lower quality control?","answer":"The opposite is generally true, smaller batches usually allow closer attention than very large, automated production runs."},{"question":"Why not simply produce everything at a larger scale?","answer":"Scale trades off against freshness and close quality control, which matter more for some products than raw volume does."},{"question":"Does this affect pricing?","answer":"It can, since smaller scale production is often less cost efficient per unit than very large scale manufacturing."},{"question":"Is small batch production slower to restock?","answer":"Sometimes, since production is timed closer to actual demand rather than continuously running at maximum volume."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Closer quality control and fresher product, traded against the scale a larger production run offers.', seo_description='Why small-batch food production is used for many staples: quality control, freshness, and the trade-offs involved.', seo_keywords='small batch food production, why small batch', reading_minutes=2, published_version_id='arv_truegrit_223_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_223';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_223';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_223','Why We Produce Many Foods in Small Batches','why-we-produce-many-foods-in-small-batches','Closer quality control and fresher product, traded against the scale a larger production run offers.','small batch food production, why small batch');

-- 224. The Role of Village Women in Traditional Food Processing
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_224_2','art_truegrit_224',2,'{"blocks":[{"id":"blk_article_224_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Traditional food processing in rural India has long relied on the skill and labour of village women, work that spans cleaning and sorting grain, hand grinding, and the careful packaging that gets a product ready for market."]}},{"id":"blk_article_224_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where this work shows up","items":["Cleaning and sorting grain by hand, removing stones, dust and damaged grain before it moves further down the process.","Traditional grinding and cracking work, historically done with stone tools, now often supported by simpler mechanical equipment.","Quality checks at multiple stages, catching issues that fully automated processing can sometimes miss.","Packaging and final preparation, work that benefits from the same close attention as the earlier processing steps.","This labour has long been central to rural food economies, often organised through community and self help group structures covered elsewhere in this guide."]}},{"id":"blk_article_224_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditionally processed staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole"],"limit":2}},{"id":"blk_article_224_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Village women in food processing questions","items":[{"question":"Is this kind of work still common in India today?","answer":"Yes, traditional processing work remains a significant part of rural food economies alongside more mechanised methods."},{"question":"How does this connect to self help groups?","answer":"Many women engaged in this work are organised through self help groups, a model covered in more detail elsewhere in this guide."},{"question":"Does hand processing produce a different result than machine processing?","answer":"It can, particularly for quality control and catching issues automated methods might miss, discussed further in this guide."},{"question":"Is this labour paid fairly across the industry?","answer":"Practices vary considerably across the industry, and this is a genuine, ongoing concern worth being aware of as a shopper."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A long, genuine tradition across rural India, from grain cleaning and sorting to grinding and packaging.', seo_description='The role of village women in traditional Indian food processing: grain cleaning, grinding, sorting and packaging work.', seo_keywords='village women food processing, women in rural food production', reading_minutes=3, published_version_id='arv_truegrit_224_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_224';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_224';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_224','The Role of Village Women in Traditional Food Processing','the-role-of-village-women-in-traditional-food-processing','A long, genuine tradition across rural India, from grain cleaning and sorting to grinding and packaging.','village women food processing, women in rural food production');

-- 225. What Are Self Help Groups (SHGs)?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_225_2','art_truegrit_225',2,'{"blocks":[{"id":"blk_article_225_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Self Help Groups, usually shortened to SHGs, are small community organised groups, often of women, that pool savings and support each other''s livelihoods, a model that has become genuinely widespread across rural India."]}},{"id":"blk_article_225_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually defines them","items":["A small group, typically ten to twenty members, who pool regular savings and provide mutual financial support.","Widely supported by government programmes, including through the National Rural Livelihood Mission, alongside independent and NGO backed groups.","Often move beyond savings into shared livelihood activities, including food processing, handicrafts and small scale production.","Provide a structure for accessing microfinance and training that would be harder for an individual to access alone.","A genuinely significant part of rural economic activity in India, not a niche or marginal model.","Membership is generally voluntary, with groups forming around shared community ties or a common livelihood interest."]}},{"id":"blk_article_225_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Products from SHG-supported processing","source":"manual","productSlugs":["black-gram-whole","organic-kathiya-wheat"],"limit":2}},{"id":"blk_article_225_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Self help group questions","items":[{"question":"Are SHGs only for savings and finance?","answer":"Many expand into livelihood activities like food processing or handicrafts, beyond their original savings function."},{"question":"Is this a government programme or independent?","answer":"Both exist, government supported groups through programmes like the National Rural Livelihood Mission, alongside independent and NGO backed ones."},{"question":"Are SHGs mostly made up of women?","answer":"Historically and currently, yes, though mixed and men''s groups exist too, women''s groups are the more common model."},{"question":"How large is a typical SHG?","answer":"Often ten to twenty members, though exact size varies by group and region."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Small, community organised groups, often of women, that pool savings and support local livelihoods, including food processing.', seo_description='What Self Help Groups (SHGs) are: how they work in rural India, and their connection to food production.', seo_keywords='what are self help groups, SHG meaning India', reading_minutes=3, published_version_id='arv_truegrit_225_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_225';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_225';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_225','What Are Self Help Groups (SHGs)?','what-are-self-help-groups-shgs','Small, community organised groups, often of women, that pool savings and support local livelihoods, including food processing.','what are self help groups, SHG meaning India');

-- 226. How Rural Self Help Groups Support Local Food Production
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_226_2','art_truegrit_226',2,'{"blocks":[{"id":"blk_article_226_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Self help groups give rural communities a structure for taking on food processing work that would be difficult for a single household to manage alone, pooling resources, skills and access to markets."]}},{"id":"blk_article_226_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How it actually works","items":["Pooled savings can fund shared equipment or working capital that an individual member could not easily afford alone.","Group training programmes build processing and quality skills across members, rather than relying on one person''s expertise.","Collective bargaining gives a group more negotiating power with buyers than an individual seller typically has.","Shared labour allows larger processing tasks, like a full batch of grain cleaning or grinding, to move faster than one person working alone.","This structure has become a genuine backbone of small scale, traditional food production across many parts of rural India."]}},{"id":"blk_article_226_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Community processed staples","source":"manual","productSlugs":["black-gram-whole","organic-kathiya-wheat"],"limit":2}},{"id":"blk_article_226_4","type":"faq","version":1,"enabled":true,"props":{"heading":"SHGs and food production questions","items":[{"question":"Do self help groups only work with one type of food product?","answer":"No, groups engage in a wide range of processing work depending on local crops and market opportunities."},{"question":"Does group work mean less individual quality control?","answer":"Not necessarily, shared training and mutual accountability within a group can support consistent standards across members."},{"question":"How do these groups access buyers?","answer":"Through a mix of local markets, cooperative structures and, increasingly, direct relationships with brands sourcing specific products."},{"question":"Is this model unique to food processing?","answer":"No, self help groups support many livelihood activities beyond food, though food processing is a common and significant one."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Pooled resources and shared skills let small groups take on processing work an individual household could not manage alone.', seo_description='How rural self help groups support local food production: shared resources, training and market access.', seo_keywords='self help groups food production, rural SHG food', reading_minutes=2, published_version_id='arv_truegrit_226_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_226';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_226';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_226','How Rural Self Help Groups Support Local Food Production','how-rural-self-help-groups-support-local-food-production','Pooled resources and shared skills let small groups take on processing work an individual household could not manage alone.','self help groups food production, rural SHG food');

-- 227. Why Hand Processing Still Matters
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_227_2','art_truegrit_227',2,'{"blocks":[{"id":"blk_article_227_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Hand processing has not been made obsolete by mechanisation, particularly for smaller batches where a person can catch and adjust for things a machine tuned for volume is not built to notice."]}},{"id":"blk_article_227_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why it still matters","items":["A person can catch subtle quality issues, discoloured grain or an off smell, that automated sorting is not always tuned to notice.","Hand processing adapts more easily to small, specific batches than large machinery designed for continuous high volume runs.","Some traditional techniques, particular grinding or pressing methods, are genuinely difficult to replicate exactly with modern equipment.","It supports the kind of small batch, made to order production model discussed elsewhere in this guide.","This is not a claim that hand processing is always superior, only that it remains genuinely useful for specific parts of the process."]}},{"id":"blk_article_227_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Hand processed staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_227_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Hand processing questions","items":[{"question":"Is hand processed food always better quality?","answer":"Not automatically, but it allows a level of attention and adjustment that fully automated processing does not always offer."},{"question":"Does hand processing slow production down?","answer":"Generally yes, compared to fully automated methods, which is part of the trade-off behind smaller batch sizes."},{"question":"Which steps benefit most from hand processing?","answer":"Quality checks and sorting tend to benefit most, since a person can catch nuance an automated system might miss."},{"question":"Is machine processing being phased out in favour of hand methods?","answer":"No, most production uses a mix of both, applying each where it genuinely adds value rather than replacing one entirely with the other."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Some quality checks and adjustments are still easier for a person to catch than a machine tuned for volume.', seo_description='Why hand processing still matters in food production: quality control, adaptability, and what machines can miss.', seo_keywords='why hand processing matters, hand processed food', reading_minutes=2, published_version_id='arv_truegrit_227_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_227';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_227';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_227','Why Hand Processing Still Matters','why-hand-processing-still-matters','Some quality checks and adjustments are still easier for a person to catch than a machine tuned for volume.','why hand processing matters, hand processed food');

-- 228. Traditional Food Processing vs Industrial Processing
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_228_2','art_truegrit_228',2,'{"blocks":[{"id":"blk_article_228_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Traditional and industrial food processing solve for different priorities. Industrial methods win on scale, speed and standardisation. Traditional methods win on attention, adaptability and a character that can vary batch to batch."]}},{"id":"blk_article_228_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually differs","items":["Industrial processing runs at high volume and speed, using automated equipment tuned for consistency across huge batches.","Traditional processing runs smaller and slower, with more manual involvement at each step.","Industrial output tends to be highly uniform. Traditional output shows more natural variation, discussed elsewhere in this guide.","Industrial methods generally cost less per unit at scale. Traditional methods cost more but allow closer quality control.","Neither approach is universally better, and many food businesses, including this one, use a mix suited to different products.","The right balance usually depends on the specific ingredient and how much its final quality depends on close attention."]}},{"id":"blk_article_228_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditionally processed","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_228_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Traditional vs industrial processing questions","items":[{"question":"Is traditional processing always more expensive?","answer":"Generally yes per unit, since it trades away the cost efficiencies that come with high volume, fully automated production."},{"question":"Does industrial processing mean lower quality?","answer":"Not necessarily, it simply prioritises consistency and volume differently than traditional methods do."},{"question":"Can the two methods be combined?","answer":"Yes, many products use a mix, applying traditional methods where they add the most value and mechanised steps elsewhere."},{"question":"Which method suits small scale production better?","answer":"Traditional processing generally suits smaller batches better, since it does not require the volume industrial equipment is built around."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Scale, speed and standardisation against attention, adaptability and character. Neither approach wins outright.', seo_description='Traditional food processing compared with industrial processing: scale, speed, quality control and trade-offs.', seo_keywords='traditional vs industrial food processing', reading_minutes=3, published_version_id='arv_truegrit_228_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_228';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_228';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_228','Traditional Food Processing vs Industrial Processing','traditional-food-processing-vs-industrial-processing','Scale, speed and standardisation against attention, adaptability and character. Neither approach wins outright.','traditional vs industrial food processing');

-- 229. Why Small-Batch Food May Vary Between Batches
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_229_2','art_truegrit_229',2,'{"blocks":[{"id":"blk_article_229_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Small batch production naturally shows more variation between runs than large scale industrial manufacturing does, mostly because there is less automated standardisation smoothing out the raw ingredient''s own natural differences."]}},{"id":"blk_article_229_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why this happens","items":["Smaller runs mean each batch reflects its specific raw material more directly, without blending across a huge combined volume.","Hand processing steps introduce some natural variation in exact timing and technique between batches.","Seasonal and harvest differences in the raw ingredient carry through more visibly in a smaller, less blended batch.","This variation is generally cosmetic or minor in flavour, not a sign of inconsistent quality control.","Large industrial batches blend far more raw material together, which naturally smooths out this kind of variation at scale.","Knowing this in advance helps set the right expectation before assuming something is wrong with a specific bag or bottle."]}},{"id":"blk_article_229_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Small-batch staples","source":"manual","productSlugs":["black-mustard-oil","organic-kathiya-wheat"],"limit":2}},{"id":"blk_article_229_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Small batch variation questions","items":[{"question":"Is batch variation a sign of a quality problem?","answer":"Generally no, it is a normal side effect of smaller, less blended production runs rather than a defect."},{"question":"Does this variation affect how I should cook with a product?","answer":"Rarely in a meaningful way, most batch variation is cosmetic rather than functional in cooking."},{"question":"Can small batch production ever be made fully consistent?","answer":"Some consistency can be achieved, but eliminating it entirely would require the kind of large scale blending industrial processing uses."},{"question":"Should I expect noticeable differences between purchases?","answer":"Some minor variation is reasonable to expect, though significant differences are worth raising with the seller."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Less automated standardisation means more of the raw ingredient''s natural variation shows through.', seo_description='Why small-batch food can vary between batches: less standardisation, more natural ingredient variation showing through.', seo_keywords='small batch food variation, why does batch vary', reading_minutes=2, published_version_id='arv_truegrit_229_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_229';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_229';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_229','Why Small-Batch Food May Vary Between Batches','why-small-batch-food-may-vary-between-batches','Less automated standardisation means more of the raw ingredient''s natural variation shows through.','small batch food variation, why does batch vary');

-- 230. The Journey of Wheat From Farm to Atta
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_230_2','art_truegrit_230',2,'{"blocks":[{"id":"blk_article_230_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Wheat''s journey from field to flour follows the same basic stages whether it is Kathiya, Banshi or Paigambari, though each variety''s own character shapes exactly how it behaves along the way."]}},{"id":"blk_article_230_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The journey","items":["Grown on specific fields suited to that variety''s needs, rain fed land for Kathiya and Paigambari, the Malwa plateau''s soil for Banshi.","Harvested at the right point in the season, timing that varies slightly between the three varieties.","Cleaned thoroughly to remove stones, dust and damaged grain before any milling begins.","Milled into flour, or alternatively cracked into daliya or ground into semolina, depending on the intended product.","Packaged promptly after milling, aiming to reach a kitchen while the flour is still genuinely fresh.","Quality checks happen at multiple points along the way, not only at the very end of the process."]}},{"id":"blk_article_230_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Wheat products","source":"manual","productSlugs":["organic-kathiya-wheat","kathiya-wheat-flour"],"limit":2}},{"id":"blk_article_230_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat farm to atta questions","items":[{"question":"Does each wheat variety follow a different journey?","answer":"The broad steps are the same, though growing region, harvest timing and milling behaviour differ between the three varieties."},{"question":"How long does the whole journey typically take?","answer":"From harvest to a packaged product, timing varies by season and demand, generally aiming to be as short as freshness benefits from."},{"question":"Is the flour milled the same way for all three varieties?","answer":"The basic milling process is similar, though each variety''s hardness affects exactly how it behaves during grinding."},{"question":"Why does freshness matter so much for atta?","answer":"Freshly milled flour generally has a stronger flavour and aroma than flour that has sat in storage for a long time."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='From a specific field to a specific bag, following the same basic steps for any of our three wheat landraces.', seo_description='The journey of wheat from farm to atta: growing, harvesting, cleaning and milling into flour.', seo_keywords='wheat farm to atta journey, how wheat becomes flour', reading_minutes=3, published_version_id='arv_truegrit_230_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_230';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_230';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_230','The Journey of Wheat From Farm to Atta','the-journey-of-wheat-from-farm-to-atta','From a specific field to a specific bag, following the same basic steps for any of our three wheat landraces.','wheat farm to atta journey, how wheat becomes flour');

-- 231. The Journey of Mustard Seed From Farm to Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_231_2','art_truegrit_231',2,'{"blocks":[{"id":"blk_article_231_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Mustard''s journey from seed to bottle hinges most on one decision, how the seed is pressed, which shapes whether the finished oil turns out pungent and cold-pressed or milder and refined."]}},{"id":"blk_article_231_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The journey","items":["Grown and harvested from mustard plants, black or yellow seed depending on which oil is being produced.","Cleaned to remove debris and damaged seed before it goes anywhere near a press.","Pressed using the traditional kachi ghani method, mechanical pressure with no added heat, covered in more detail elsewhere in this guide.","Settled and lightly filtered rather than heavily processed, keeping much of the seed''s natural pungency and colour.","Bottled and sent to kitchens where it is often heated briefly to a smoke point before cooking, mellowing its raw sharpness."]}},{"id":"blk_article_231_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Mustard oil","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_231_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard seed to oil questions","items":[{"question":"Does black or yellow mustard follow a different journey?","answer":"The broad journey is the same, though the seed itself differs, giving black and yellow mustard oil their distinct pungency."},{"question":"Why does pressing method matter so much?","answer":"It decides whether the oil stays raw, pungent and cold-pressed or becomes milder through refining, discussed further elsewhere in this guide."},{"question":"How long from harvest to bottle?","answer":"Timing varies by season and demand, generally aiming to keep the gap as short as reasonably possible."},{"question":"Is any part of this journey mechanised?","answer":"Modern kachi ghani pressing typically uses mechanical equipment following the same slow, no added heat principle as traditional methods."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='From field to pressed bottle, with the pressing method deciding much of the oil''s final character.', seo_description='The journey of mustard seed from farm to oil: growing, harvesting, cleaning and traditional cold pressing.', seo_keywords='mustard seed farm to oil journey, how mustard oil is made', reading_minutes=3, published_version_id='arv_truegrit_231_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_231';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_231';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_231','The Journey of Mustard Seed From Farm to Oil','the-journey-of-mustard-seed-from-farm-to-oil','From field to pressed bottle, with the pressing method deciding much of the oil''s final character.','mustard seed farm to oil journey, how mustard oil is made');

-- 232. The Journey of Sesame Seed From Farm to Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_232_2','art_truegrit_232',2,'{"blocks":[{"id":"blk_article_232_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame''s journey from field to bottle includes one distinctive fork in the road, whether the seed is pressed raw or roasted first, a choice that shapes the oil''s final aroma more than almost anything else."]}},{"id":"blk_article_232_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The journey","items":["Grown and harvested from sesame plants, one of the oldest cultivated oilseed crops in the region.","Cleaned to remove debris before either being pressed raw or lightly roasted first, a choice covered in more detail elsewhere in this guide.","Pressed using a traditional ghani style method, similar in principle to how mustard oil is pressed.","Settled and lightly filtered, keeping more of the natural colour and aroma than a heavily refined process would.","Bottled and sent to kitchens, where raw pressed oil suits cooking better and roasted pressed oil suits finishing."]}},{"id":"blk_article_232_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame oil","source":"manual","productSlugs":["sesame-oil"],"limit":1}},{"id":"blk_article_232_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame seed to oil questions","items":[{"question":"Does roasting happen before or after pressing?","answer":"Before, if the oil is meant to be the darker, more aromatic style. Raw seed skips this step entirely."},{"question":"Why choose raw over roasted seed for pressing?","answer":"Raw pressed oil is milder and more suited to cooking, while roasted pressed oil is more aromatic and suited to finishing."},{"question":"Does this journey differ much from mustard oil''s?","answer":"Broadly similar, both traditionally use a ghani style mechanical press, though the seeds and resulting flavours differ."},{"question":"How is sesame''s cultivation history relevant to this journey?","answer":"It reflects just how long this specific pressing tradition has existed, discussed further elsewhere in this guide."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Raw or roasted before pressing is the choice that decides whether the oil ends up light or deeply aromatic.', seo_description='The journey of sesame seed from farm to oil: growing, harvesting, and the raw versus roasted pressing choice.', seo_keywords='sesame seed farm to oil journey, how sesame oil is made', reading_minutes=3, published_version_id='arv_truegrit_232_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_232';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_232';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_232','The Journey of Sesame Seed From Farm to Oil','the-journey-of-sesame-seed-from-farm-to-oil','Raw or roasted before pressing is the choice that decides whether the oil ends up light or deeply aromatic.','sesame seed farm to oil journey, how sesame oil is made');

-- 233. The Journey of Urad From Whole Gram to Dal, Sattu and Besan
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_233_2','art_truegrit_233',2,'{"blocks":[{"id":"blk_article_233_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole black gram''s journey branches in three different directions depending on the end product, split dal, roasted sattu, or raw besan, each needing a different processing choice after the same basic start."]}},{"id":"blk_article_233_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The journey","items":["Grown, harvested and cleaned the same way regardless of which final product the batch is headed toward.","For dal, the pulse is dehusked and split, revealing the pale interior most people recognise as split urad dal.","For sattu, whole black gram is roasted first, then ground into a flour that is already ready to eat.","For besan, black gram is ground raw, without roasting, into a flour that still needs cooking before eating.","All three products start from the exact same whole pulse, differing only in the processing steps applied after cleaning."]}},{"id":"blk_article_233_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram in every form","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal","black-gram-sattu"],"limit":3}},{"id":"blk_article_233_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad journey questions","items":[{"question":"Does the farming stage differ for dal, sattu or besan?","answer":"No, growing and harvesting are identical. The processing choice only diverges after cleaning."},{"question":"Why does sattu need roasting but besan does not?","answer":"Roasting is what makes sattu ready to eat without further cooking. Besan is deliberately left raw for use in cooked batters."},{"question":"Can the same batch of whole black gram become any of the three?","answer":"In principle yes, the processing decision happens after cleaning, based on what the batch is intended to become."},{"question":"Which of the three takes the longest to produce?","answer":"Sattu, since roasting adds a step that split dal and raw besan production do not require."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One pulse, three different destinations, each requiring a different processing choice along the way.', seo_description='The journey of urad from whole black gram to dal, sattu and besan: cleaning, dehusking, roasting and grinding.', seo_keywords='urad farm to dal journey, black gram processing journey', reading_minutes=3, published_version_id='arv_truegrit_233_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_233';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_233';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_233','The Journey of Urad From Whole Gram to Dal, Sattu and Besan','the-journey-of-urad-from-whole-gram-to-dal-sattu-and-besan','One pulse, three different destinations, each requiring a different processing choice along the way.','urad farm to dal journey, black gram processing journey');

-- 234. Why Traceability Matters in Food
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_234_2','art_truegrit_234',2,'{"blocks":[{"id":"blk_article_234_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Traceability is what turns a sourcing claim from something you simply have to trust into something that can actually be checked, connecting a packaged product back through processing to its original source."]}},{"id":"blk_article_234_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why it actually matters","items":["It supports accountability, making it possible to identify where in a supply chain a quality issue actually originated.","It underpins genuine certification claims, like organic status, which require documented records rather than a simple label claim.","It helps confirm sourcing claims are real, rather than marketing language with nothing checkable behind it.","In the event of a safety issue, traceability allows a specific affected batch to be identified rather than an entire product line.","It builds a form of accountability between a business and its customers that trust alone cannot fully provide."]}},{"id":"blk_article_234_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traceable staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole"],"limit":2}},{"id":"blk_article_234_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Traceability questions","items":[{"question":"Is traceability only relevant for large food businesses?","answer":"No, it matters at any scale, though the systems used to maintain it can differ between a small producer and a large one."},{"question":"How is traceability different from certification?","answer":"Certification often requires traceability as part of its standard, but traceability itself is the underlying record keeping that supports many kinds of claims."},{"question":"Can a shopper access traceability records directly?","answer":"Rarely in full detail, though a batch number and certificate can support a more limited check if needed."},{"question":"Does traceability guarantee a product is high quality?","answer":"It confirms sourcing claims can be checked, which supports quality accountability without being a quality guarantee on its own."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Accountability, safety and honest sourcing all depend on being able to trace a product back to its origin.', seo_description='Why traceability matters in food: accountability, safety, and confirming sourcing claims are genuine.', seo_keywords='why traceability matters, food traceability importance', reading_minutes=2, published_version_id='arv_truegrit_234_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_234';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_234';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_234','Why Traceability Matters in Food','why-traceability-matters-in-food','Accountability, safety and honest sourcing all depend on being able to trace a product back to its origin.','why traceability matters, food traceability importance');

-- 235. Meet the People Behind Your Food
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_235_2','art_truegrit_235',2,'{"blocks":[{"id":"blk_article_235_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Every product on a shelf represents real work done by real people, farmers, processors and small producers, whose contribution rarely shows up anywhere on the packaging itself."]}},{"id":"blk_article_235_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What this actually means","items":["Farmers growing specific varieties, often on a smaller scale than commodity agriculture, are the starting point of every ingredient.","Processors, including the village based and self help group workers covered elsewhere in this guide, turn raw ingredients into a usable product.","This work is often invisible on a final label, which lists an ingredient without naming who actually grew or processed it.","Traceable sourcing, discussed in more detail elsewhere in this guide, is one way this human element becomes more visible to a shopper.","Recognising this labour does not require knowing every individual name, only understanding that real people and real work sit behind every product."]}},{"id":"blk_article_235_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One shopper''s question about what farm information would genuinely change a buying decision, a harvest date or variety rather than an unverifiable village name, is a useful way to think about what this visibility should actually offer](/community/dsc_truegrit_024)."]}},{"id":"blk_article_235_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Products with real people behind them","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole"],"limit":2}},{"id":"blk_article_235_5","type":"faq","version":1,"enabled":true,"props":{"heading":"People behind your food questions","items":[{"question":"Can I learn more about the specific farmers behind a product?","answer":"Sourcing detail varies by product. Check individual product pages for whatever specific information is available."},{"question":"Why don''t labels typically name individual farmers?","answer":"Supply chains often involve multiple farmers and processors for a single batch, making individual naming impractical at most scales."},{"question":"Does this connect to self help groups mentioned elsewhere?","answer":"Yes, much of the processing work behind traditional food products is organised through community and self help group structures."},{"question":"How can I support this kind of sourcing as a shopper?","answer":"Choosing products with genuine traceability and certification is one practical way to support more accountable sourcing."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Farmers, processors and small producers whose work rarely shows up on a label, but shapes every product on the shelf.', seo_description='Why knowing the people behind your food matters, and how traceable sourcing connects a product back to real work.', seo_keywords='people behind your food, farmers and processors', reading_minutes=2, published_version_id='arv_truegrit_235_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_235';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_235';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_235','Meet the People Behind Your Food','meet-the-people-behind-your-food','Farmers, processors and small producers whose work rarely shows up on a label, but shapes every product on the shelf.','people behind your food, farmers and processors');

-- 236. Preserving Traditional Indian Grain Varieties
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_236_2','art_truegrit_236',2,'{"blocks":[{"id":"blk_article_236_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Heritage grain varieties like Kathiya, Banshi and Paigambari wheat survive mainly because farmers keep growing them and buyers keep choosing them, not through any automatic protection once modern, higher yield varieties become available."]}},{"id":"blk_article_236_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why this matters","items":["Lower yielding heritage varieties can lose ground to modern hybrids bred specifically for higher volume output.","Once a variety stops being grown at any scale, the seed stock and farming knowledge behind it can be genuinely difficult to recover.","Continued demand from buyers is one of the more direct ways a heritage variety stays commercially viable for farmers to keep growing.","This is not only about nostalgia, different varieties carry different resilience traits that can matter for future farming conditions.","Preservation happens through ordinary market demand as much as through any formal conservation programme."]}},{"id":"blk_article_236_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Heritage wheat varieties","source":"manual","productSlugs":["organic-kathiya-wheat","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_236_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Grain preservation questions","items":[{"question":"Are heritage wheat varieties at risk of disappearing?","answer":"Lower yielding varieties can lose ground to modern hybrids without continued demand keeping them commercially viable."},{"question":"Does buying heritage wheat actually help preserve it?","answer":"Continued market demand is one of the more direct ways a variety stays worth growing for farmers."},{"question":"Is this only relevant to wheat?","answer":"No, the same dynamic applies to many traditional grain and pulse varieties across India, covered further elsewhere in this guide."},{"question":"Why does variety diversity matter beyond flavour?","answer":"Different varieties carry different resilience traits that can matter for future farming conditions, discussed in more depth elsewhere in this guide."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Heritage landraces like Kathiya, Banshi and Paigambari survive mainly because someone keeps growing and buying them.', seo_description='Why preserving traditional Indian grain varieties matters, and what keeps heritage landraces like Kathiya wheat in cultivation.', seo_keywords='preserving traditional grain varieties, heritage Indian wheat', reading_minutes=3, published_version_id='arv_truegrit_236_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_236';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_236';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_236','Preserving Traditional Indian Grain Varieties','preserving-traditional-indian-grain-varieties','Heritage landraces like Kathiya, Banshi and Paigambari survive mainly because someone keeps growing and buying them.','preserving traditional grain varieties, heritage Indian wheat');

-- 237. Why Local Grain Biodiversity Matters
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_237_2','art_truegrit_237',2,'{"blocks":[{"id":"blk_article_237_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Relying heavily on a small number of high yield varieties leaves agriculture more exposed to disease, drought and shifting climate conditions than a wider pool of local varieties would."]}},{"id":"blk_article_237_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Why it actually matters","items":["A wider genetic pool across varieties gives agriculture more options if a particular disease or pest affects one dominant variety.","Local varieties often carry traits suited to specific regional conditions, drought tolerance or particular soil types, developed over generations.","Relying too heavily on a small number of varieties concentrates risk in a way that a more diverse set of crops avoids.","This is a genuine, actively discussed concern in agricultural policy, not a purely theoretical one.","Supporting a range of traditional varieties, alongside modern ones, is one practical way to keep that broader genetic pool available."]}},{"id":"blk_article_237_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Diverse heritage varieties","source":"manual","productSlugs":["organic-kathiya-wheat","banshi-wheat-flour"],"limit":2}},{"id":"blk_article_237_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Grain biodiversity questions","items":[{"question":"Is biodiversity loss a real concern in Indian agriculture?","answer":"Yes, it is an actively discussed issue in agricultural policy, tied to reliance on a narrower set of high yield varieties."},{"question":"Can a single household''s buying choices affect this?","answer":"In aggregate, consistent demand for diverse varieties supports farmers'' decisions to keep growing them commercially."},{"question":"Does biodiversity only matter for wheat?","answer":"No, this concern applies broadly across grains, pulses and other crops, not one ingredient specifically."},{"question":"Are heritage varieties always more resilient than modern ones?","answer":"Not universally, but many carry specific resilience traits developed for local conditions over a long period."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A wider gene pool means more resilience against disease, drought and a changing climate over time.', seo_description='Why local grain biodiversity matters: resilience, climate adaptation, and the risk of relying on too few varieties.', seo_keywords='grain biodiversity, why biodiversity matters in agriculture', reading_minutes=2, published_version_id='arv_truegrit_237_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_237';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_237';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_237','Why Local Grain Biodiversity Matters','why-local-grain-biodiversity-matters','A wider gene pool means more resilience against disease, drought and a changing climate over time.','grain biodiversity, why biodiversity matters in agriculture');

-- 238. Forgotten Indian Grains and Pulses Worth Rediscovering
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_238_2','art_truegrit_238',2,'{"blocks":[{"id":"blk_article_238_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["India''s traditional food system includes a wide range of grains and pulses that fell out of everyday use as a smaller number of commodity crops came to dominate most kitchens and most farmland."]}},{"id":"blk_article_238_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Worth a closer look","items":["Millets like ragi, jowar and bajra, once staple grains in many regions, now often treated as a specialty item rather than an everyday one.","Heritage wheat landraces like Kathiya, Banshi and Paigambari, once common regional wheats, now grown at a smaller scale than modern hybrids.","Regional pulse varieties that vary considerably by state and community, many with limited distribution outside their home region.","Traditional preparations built around these ingredients, daliya, sattu and various regional dals, that remain genuinely practical, not just nostalgic.","Rediscovering these ingredients supports both culinary variety and the broader biodiversity concerns covered elsewhere in this guide."]}},{"id":"blk_article_238_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditional grains and pulses","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole","field-pea-white"],"limit":3}},{"id":"blk_article_238_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Forgotten grains questions","items":[{"question":"Why did these ingredients fall out of everyday use?","answer":"Largely the shift toward a smaller number of high yield commodity crops, which crowded out many traditional regional varieties."},{"question":"Are these ingredients harder to cook with than common staples?","answer":"Not inherently, though some need different techniques, which this guide covers for the specific ingredients it stocks."},{"question":"Is millet the same category as these heritage wheats?","answer":"They are different grains entirely, though both fall into this broader category of traditional ingredients losing ground to commodity crops."},{"question":"Does rediscovering these ingredients support farmers directly?","answer":"Continued demand is one of the more direct ways these varieties stay commercially viable for farmers to keep growing."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Millets, heritage wheats and regional pulses that fell out of everyday use as commodity crops took over.', seo_description='Forgotten Indian grains and pulses worth rediscovering: millets, heritage wheats, and regional pulse varieties.', seo_keywords='forgotten Indian grains, traditional Indian pulses', reading_minutes=3, published_version_id='arv_truegrit_238_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_238';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_238';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_238','Forgotten Indian Grains and Pulses Worth Rediscovering','forgotten-indian-grains-and-pulses-worth-rediscovering','Millets, heritage wheats and regional pulses that fell out of everyday use as commodity crops took over.','forgotten Indian grains, traditional Indian pulses');

-- 258. Kathiya vs Banshi Wheat
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_258_2','art_truegrit_258',2,'{"blocks":[{"id":"blk_article_258_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Narrowed down to just these two, the decision comes down to how much chew you want in your roti and how much you want to think about hydration before you start kneading."]}},{"id":"blk_article_258_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Which to actually buy","items":["Buy Kathiya if you specifically want a firmer, chewier roti and do not mind resting the dough a little longer.","Buy Banshi if you want a flour that behaves like the atta you already know how to cook with, no adjustment needed.","If you are buying your first bag of either, Banshi is the lower risk choice for everyday cooking.","If you already have a favourite atta and want something noticeably different to compare it against, Kathiya is the more distinct pick.","Neither is the wrong buy, this is a texture preference decision, not a quality one."]}},{"id":"blk_article_258_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kathiya and Banshi","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour"],"limit":2}},{"id":"blk_article_258_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya vs Banshi buying questions","items":[{"question":"Which should I buy if I am not sure?","answer":"Banshi, since it needs the least adjustment from whatever atta you are already used to cooking with."},{"question":"Is Kathiya worth the extra effort for a first time buyer?","answer":"If a firmer, chewier roti genuinely appeals to you, yes. Otherwise Banshi is the more forgiving starting point."},{"question":"Can I buy both and decide later?","answer":"Yes, many households do exactly this, keeping both on hand and choosing based on the day''s dish."},{"question":"Does one cost noticeably more than the other?","answer":"Both carry a premium over commodity wheat for similar reasons, without a large price gap between the two."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='If you are choosing between just these two, here is the practical call to make.', seo_description='Kathiya wheat compared directly with Banshi wheat, as a practical buying decision rather than a full property list.', seo_keywords='Kathiya vs Banshi wheat, which wheat to buy', reading_minutes=2, published_version_id='arv_truegrit_258_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_258';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_258';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_258','Kathiya vs Banshi Wheat','kathiya-vs-banshi-wheat','If you are choosing between just these two, here is the practical call to make.','Kathiya vs Banshi wheat, which wheat to buy');

-- 259. Kathiya vs Paigambari Wheat
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_259_2','art_truegrit_259',2,'{"blocks":[{"id":"blk_article_259_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya and Paigambari pull in different directions, one toward a firmer bite, the other toward a more fragrant flour, so the right buy depends on which of those two things you actually want more."]}},{"id":"blk_article_259_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Which to actually buy","items":["Buy Kathiya if texture matters most to you, particularly for daliya or a roti with real chew.","Buy Paigambari if aroma matters most, especially for plain roti or ghee brushed paratha where the wheat''s own smell should carry.","If you cook mostly simple, lightly spiced food, Paigambari''s aroma is more likely to actually stand out in the final dish.","If you cook heartier, more heavily spiced food, Kathiya''s texture is more likely to be the thing you notice.","Buy Paigambari in smaller quantities regardless, since its aroma fades faster in storage than Kathiya''s texture does."]}},{"id":"blk_article_259_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kathiya and Paigambari","source":"manual","productSlugs":["kathiya-wheat-flour","paigambari-wheat-flour"],"limit":2}},{"id":"blk_article_259_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Kathiya vs Paigambari buying questions","items":[{"question":"Which is better for daily roti?","answer":"Depends on preference, Kathiya for texture, Paigambari for aroma. Neither is objectively better for everyday use."},{"question":"Does Paigambari''s aroma really make a difference?","answer":"Most noticeably in plain, lightly spiced dishes, less so once heavier spicing is involved."},{"question":"Should I buy Paigambari in bulk to save money?","answer":"Not recommended, since its aroma fades with storage time, smaller, more frequent purchases suit it better."},{"question":"Is one significantly harder to cook with than the other?","answer":"Kathiya needs more water and a longer rest. Paigambari is closer to standard atta handling."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Density against aroma. Which one wins depends entirely on what you are actually cooking.', seo_description='Kathiya wheat compared directly with Paigambari wheat, as a practical buying decision based on what you cook.', seo_keywords='Kathiya vs Paigambari wheat, which wheat to buy', reading_minutes=2, published_version_id='arv_truegrit_259_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_259';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_259';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_259','Kathiya vs Paigambari Wheat','kathiya-vs-paigambari-wheat','Density against aroma. Which one wins depends entirely on what you are actually cooking.','Kathiya vs Paigambari wheat, which wheat to buy');

-- 260. Banshi vs Paigambari Wheat
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_260_2','art_truegrit_260',2,'{"blocks":[{"id":"blk_article_260_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Banshi and Paigambari sit closer together in hardness than either does to Kathiya, which makes this comparison less about technique and more about whether you want an everyday flour or a specialty one."]}},{"id":"blk_article_260_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Which to actually buy","items":["Buy Banshi as your everyday, all purpose flour, since it needs no real adjustment from standard atta habits.","Buy Paigambari when a specific dish is meant to showcase the wheat''s own aroma, not as your default daily bag.","If you only want to keep one variety stocked, Banshi is the more versatile everyday choice of the two.","If you already have an everyday flour and want to add one specialty option, Paigambari is the more distinctive addition.","Both cook fairly similarly in terms of hydration and timing, so the decision is really about flavour, not technique."]}},{"id":"blk_article_260_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Banshi and Paigambari","source":"manual","productSlugs":["banshi-wheat-flour","paigambari-wheat-flour"],"limit":2}},{"id":"blk_article_260_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Banshi vs Paigambari buying questions","items":[{"question":"Which is the safer everyday choice?","answer":"Banshi, since it behaves closest to standard atta and needs the least adjustment."},{"question":"Is Paigambari harder to cook with than Banshi?","answer":"Not significantly, the two are close in hardness. The main difference is Paigambari''s more pronounced aroma."},{"question":"Should I buy Paigambari as my only flour?","answer":"Most buyers keep it as an addition rather than a sole everyday flour, given its faster fading aroma and smaller batch appeal."},{"question":"Do these two cost about the same?","answer":"Broadly similar, both carry a premium over commodity wheat for comparable reasons."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The easiest everyday choice against the more distinctive specialty pick.', seo_description='Banshi wheat compared directly with Paigambari wheat, as a practical buying decision for everyday versus specialty use.', seo_keywords='Banshi vs Paigambari wheat, which wheat to buy', reading_minutes=2, published_version_id='arv_truegrit_260_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_260';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_260';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_260','Banshi vs Paigambari Wheat','banshi-vs-paigambari-wheat','The easiest everyday choice against the more distinctive specialty pick.','Banshi vs Paigambari wheat, which wheat to buy');

-- 261. Kathiya vs Banshi vs Paigambari Wheat
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_261_2','art_truegrit_261',2,'{"blocks":[{"id":"blk_article_261_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Rather than laying out every property side by side, here is a more direct way to decide, start from what you actually cook most often and work from there."]}},{"id":"blk_article_261_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Start here","items":["If you make roti every day and want zero learning curve, start with Banshi.","If you specifically want a chewier, more textured roti or daliya, start with Kathiya, and budget extra time for hydration.","If aroma is what draws you to heritage wheat in the first place, start with Paigambari, and buy a smaller bag.","If you cannot decide, buying a small quantity of all three to compare directly is a reasonable one time cost.","Whichever you start with, expect it to cost more than commodity wheat for the same reasons, lower yield and a smaller growing region."]}},{"id":"blk_article_261_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[Households who eventually settled on keeping two of the three long term explain which one they dropped and why](/community/dsc_truegrit_030), a useful read once you have tried more than one."]}},{"id":"blk_article_261_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"All three wheat varieties","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_261_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Choosing between the three questions","items":[{"question":"Do I need to try all three before deciding?","answer":"Not necessarily, though it is the most direct way to find your own preference if you are genuinely unsure."},{"question":"Is there a wrong first choice among the three?","answer":"No, all three are legitimate heritage wheats. The right first choice depends on what you value most in a roti."},{"question":"Will most households eventually settle on just one?","answer":"Many do, often keeping one as an everyday flour and buying another only for specific dishes."},{"question":"Is buying small trial quantities of all three worth it?","answer":"For a genuinely undecided buyer, yes, it is a reasonable one time way to make an informed long term choice."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
