-- 262. Black vs Yellow Mustard Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_262_2','art_truegrit_262',2,'{"blocks":[{"id":"blk_article_262_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Rather than picking one mustard oil as a general default, it helps to match the choice to what is actually on your cooking list this week."]}},{"id":"blk_article_262_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Match it to the dish","items":["Cooking Bengali fish curry or making pickles this week? Buy black mustard oil, it is what those recipes are traditionally built around.","Cooking everyday sabzi or tempering? Buy yellow mustard oil, its milder flavour will not overwhelm a simple dish.","Not sure what you will cook? Yellow is the safer general purpose buy for a household new to mustard oil.","Already comfortable with yellow and want to try something more assertive? Black is the natural next bottle to pick up.","If your kitchen leans East Indian or Bengali in its everyday cooking, black may actually be the more useful everyday bottle."]}},{"id":"blk_article_262_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black and yellow mustard oil","source":"manual","productSlugs":["black-mustard-oil","yellow-mustard-oil"],"limit":2}},{"id":"blk_article_262_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard oil buying questions","items":[{"question":"Which should a first time buyer choose?","answer":"Yellow, for its milder, more forgiving flavour across a wider range of everyday dishes."},{"question":"Is it worth buying both from the start?","answer":"If your cooking already spans multiple regional styles, yes. Otherwise, start with one and add the other as needed."},{"question":"Does one go further than the other in cooking?","answer":"Both are used in similar quantities, the difference is flavour intensity, not how much is needed per dish."},{"question":"Can I use black mustard oil for everyday cooking too?","answer":"Yes, though its stronger flavour is more noticeable in simple dishes than yellow''s would be."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
