INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_262','Black vs Yellow Mustard Oil','black-vs-yellow-mustard-oil','Match the oil to what you are actually cooking this week, not a general rule.','black vs yellow mustard oil, which mustard oil to buy');

-- 263. Mustard Oil vs Sesame Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_263_2','art_truegrit_263',2,'{"blocks":[{"id":"blk_article_263_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Choosing between mustard oil and sesame oil is less about which is objectively better and more about which regional cooking style your kitchen already leans toward."]}},{"id":"blk_article_263_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["If your cooking draws more from North or East Indian traditions, mustard oil is likely to see more everyday use in your kitchen.","If your cooking draws more from South Indian traditions, sesame oil is likely to fit more naturally into your routine.","If you want an oil that can handle actual cooking heat as well as finishing, a raw pressed sesame oil is the more flexible single bottle.","If pungency is what you are after specifically, mustard oil delivers that more directly than sesame does.","Buying both is common once a household cooks across regional styles, rather than treating it as an either or choice."]}},{"id":"blk_article_263_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Mustard and sesame oil","source":"manual","productSlugs":["yellow-mustard-oil","sesame-oil"],"limit":2}},{"id":"blk_article_263_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard vs sesame oil buying questions","items":[{"question":"Which is more versatile for a mixed regional kitchen?","answer":"Sesame oil, particularly raw pressed, since it can handle both cooking heat and finishing use more flexibly."},{"question":"Should I pick one over the other if I only want one oil?","answer":"Base it on which regional cuisine you cook most often, since each suits a different cooking tradition more naturally."},{"question":"Does one keep longer than the other?","answer":"Sesame oil generally keeps a little longer thanks to its own natural antioxidant compounds."},{"question":"Can they be used interchangeably in a pinch?","answer":"In some dishes yes, though expect a noticeably different flavour in the finished result."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A regional cooking style question more than a straight quality comparison.', seo_description='Mustard oil compared with sesame oil, as a practical buying decision based on regional cooking style.', seo_keywords='mustard oil vs sesame oil, which oil to buy', reading_minutes=2, published_version_id='arv_truegrit_263_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_263';
