INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_263','Mustard Oil vs Sesame Oil','mustard-oil-vs-sesame-oil','A regional cooking style question more than a straight quality comparison.','mustard oil vs sesame oil, which oil to buy');

-- 264. Mustard Oil vs Flaxseed Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_264_2','art_truegrit_264',2,'{"blocks":[{"id":"blk_article_264_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["This comparison trips people up more than most, because mustard and flaxseed oil are not really competing for the same shelf space, they do completely different jobs in a kitchen."]}},{"id":"blk_article_264_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What you are actually buying","items":["Buy mustard oil to cook with, tempering, frying and building a dish from the ground up.","Buy flaxseed oil to finish with, a small drizzle stirred in once cooking is already done, never heated.","If you only need one oil for actual cooking, flaxseed oil is not a candidate at all, buy mustard.","If you already have a cooking oil sorted and want something to add raw for its own sake, flaxseed oil fills a completely different gap.","These are not substitutes for each other in either direction, buying one does not reduce your need for the other."]}},{"id":"blk_article_264_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Two different jobs","source":"manual","productSlugs":["yellow-mustard-oil","linseed-flax-seed-oil"],"limit":2}},{"id":"blk_article_264_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Mustard vs flaxseed oil buying questions","items":[{"question":"Can flaxseed oil replace mustard oil for cooking?","answer":"No, flaxseed oil cannot be heated at all, so it cannot fill mustard oil''s role in cooking."},{"question":"Do I need both in my kitchen?","answer":"Only if you specifically want flaxseed oil''s raw, finishing role. Otherwise mustard oil alone covers everyday cooking needs."},{"question":"Which is more versatile?","answer":"Mustard oil, by a wide margin, since it handles actual cooking. Flaxseed oil has one specific, narrow use."},{"question":"Is one healthier to buy than the other?","answer":"This article is not making that claim either way, the two simply serve different roles in cooking."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Not really a choice between two similar oils, more a reminder that they do completely different jobs.', seo_description='Mustard oil compared with flaxseed oil, clarifying why these are not interchangeable purchases for the same purpose.', seo_keywords='mustard oil vs flaxseed oil, which oil to buy', reading_minutes=2, published_version_id='arv_truegrit_264_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_264';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_264';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_264','Mustard Oil vs Flaxseed Oil','mustard-oil-vs-flaxseed-oil','Not really a choice between two similar oils, more a reminder that they do completely different jobs.','mustard oil vs flaxseed oil, which oil to buy');

-- 265. Sesame Oil vs Flaxseed Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_265_2','art_truegrit_265',2,'{"blocks":[{"id":"blk_article_265_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The most useful fact for deciding between these two is simple, sesame oil can go in a hot pan and flaxseed oil never can, which settles most of the actual buying decision on its own."]}},{"id":"blk_article_265_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["If you need an oil for actual cooking, sesame oil is the candidate, not flaxseed oil, which stays strictly raw.","If you want a small finishing oil to drizzle over a finished dish, either works, though their flavours differ noticeably.","Buy sesame oil first if you are only adding one new oil to your kitchen and want it to actually be useful for cooking.","Add flaxseed oil once you have a cooking oil sorted and specifically want a raw, grassy finishing note in your rotation.","Neither substitutes cleanly for the other, since one can be heated and the other genuinely cannot."]}},{"id":"blk_article_265_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame and flaxseed oil","source":"manual","productSlugs":["sesame-oil","linseed-flax-seed-oil"],"limit":2}},{"id":"blk_article_265_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Sesame vs flaxseed oil buying questions","items":[{"question":"Which should I buy if I only want one new oil?","answer":"Sesame oil, since it can actually be used for cooking, unlike flaxseed oil which is raw use only."},{"question":"Can both be used as finishing oils?","answer":"Yes, both work drizzled over a finished dish, though their flavours are quite different from each other."},{"question":"Is flaxseed oil ever worth buying instead of sesame?","answer":"Only if you specifically want its raw, finishing role and already have a proper cooking oil elsewhere."},{"question":"Does sesame oil keep longer than flaxseed oil once opened?","answer":"Generally yes, thanks to its own natural resistance to oxidation compared to flaxseed oil''s more delicate composition."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One can go in the pan, one absolutely cannot. That alone should decide most of this purchase.', seo_description='Sesame oil compared with flaxseed oil, clarifying which can be cooked with and which stays strictly raw.', seo_keywords='sesame oil vs flaxseed oil, which oil to buy', reading_minutes=2, published_version_id='arv_truegrit_265_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_265';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_265';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_265','Sesame Oil vs Flaxseed Oil','sesame-oil-vs-flaxseed-oil','One can go in the pan, one absolutely cannot. That alone should decide most of this purchase.','sesame oil vs flaxseed oil, which oil to buy');

-- 266. Raw vs Roasted Flax Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_266_2','art_truegrit_266',2,'{"blocks":[{"id":"blk_article_266_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Deciding between raw and roasted flax seed is really a question about what you plan to make with it, since each suits a genuinely different set of uses."]}},{"id":"blk_article_266_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Match it to your plan","items":["Making a chutney or a dish where flax''s flavour should stand out? Buy roasted, its nuttiness is far more developed.","Adding flax quietly into dough or a smoothie without changing the flavour much? Buy raw, its taste is much more neutral.","Want to roast it yourself at home? Buy raw and roast in small batches as you need it, for the freshest flavour.","Want convenience over control? Buy roasted and skip the extra step entirely.","If you are only buying one, roasted is the more broadly useful default for most Indian recipes that call for flax."]}},{"id":"blk_article_266_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Raw and roasted flax","source":"manual","productSlugs":["plain-flax-seed","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_266_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Raw vs roasted flax buying questions","items":[{"question":"Which is the better default purchase?","answer":"Roasted, for most Indian recipes that specifically call for flax''s developed, nutty flavour."},{"question":"Should I buy raw if I plan to roast it myself?","answer":"Yes, buying raw and roasting fresh in small batches gives the most control over flavour."},{"question":"Is one cheaper than the other?","answer":"Pricing can vary slightly, though the bigger factor is which one actually suits your intended use."},{"question":"Can I buy both for different purposes?","answer":"Yes, many households keep both, roasted for chutneys and raw for quieter additions like dough or smoothies."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Which one to reach for depends on exactly what you are making, not a general preference.', seo_description='Raw flax seeds compared with roasted, as a practical buying decision matched to specific recipes.', seo_keywords='raw vs roasted flax seeds, which flax seed to buy', reading_minutes=2, published_version_id='arv_truegrit_266_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_266';
