INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_266','Raw vs Roasted Flax Seeds','raw-vs-roasted-flax-seeds','Which one to reach for depends on exactly what you are making, not a general preference.','raw vs roasted flax seeds, which flax seed to buy');

-- 267. Raw vs Roasted Sesame Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_267_2','art_truegrit_267',2,'{"blocks":[{"id":"blk_article_267_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["For sesame more than for many seeds, roasted is genuinely the default most Indian recipes are built around, which makes this an easier decision than it might first appear."]}},{"id":"blk_article_267_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["For laddu, chikki, chutneys or tempering, buy roasted, this is what most traditional recipes actually specify.","For pressing into a lighter, milder oil at home or a use where a subtler flavour is wanted, raw is the better base.","If you are not sure what you will make yet, roasted is the more broadly useful default to keep stocked.","Want to roast it yourself for maximum freshness? Buy raw and roast a small batch just before you need it.","Most households only need to keep roasted on hand, adding raw only for a specific reason like home oil pressing."]}},{"id":"blk_article_267_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Raw and roasted sesame","source":"manual","productSlugs":["sesame-seed","roasted-sesame-seeds"],"limit":2}},{"id":"blk_article_267_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Raw vs roasted sesame buying questions","items":[{"question":"Which should most households buy by default?","answer":"Roasted, since most common Indian recipes calling for sesame specifically assume the roasted form."},{"question":"Is there ever a reason to buy raw sesame?","answer":"Yes, mainly for pressing a milder oil or wanting to roast it yourself fresh in small batches."},{"question":"Does roasted sesame cost more than raw?","answer":"Pricing varies, though the practical difference in usefulness usually matters more than a small price gap."},{"question":"Can I substitute raw for roasted in a recipe?","answer":"Not well, most recipes are built around roasted sesame''s stronger, developed flavour."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
