INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_267','Raw vs Roasted Sesame Seeds','raw-vs-roasted-sesame-seeds','For most Indian dishes, the roasted bag is the one you actually want on hand.','raw vs roasted sesame seeds, which sesame seed to buy');

-- 268. Flax Seeds vs Sesame Seeds
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_268_2','art_truegrit_268',2,'{"blocks":[{"id":"blk_article_268_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Starting a seed pantry from scratch, sesame is the more foundational buy, given how deeply it is woven into everyday Indian cooking compared to flax''s smaller, more specific role."]}},{"id":"blk_article_268_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Which to buy first","items":["Buy sesame first if you want a seed that shows up across sweets, chutneys and tempering in genuinely everyday ways.","Buy flax first if your main goal is adding it in small quantities to dishes you already make, without a big recipe repertoire around it.","If you cook traditional Indian sweets or festival foods, sesame will see far more regular use than flax.","If your interest in flax is specifically about its role as a finishing oil ingredient too, that leans toward flax being worth adding sooner.","Most households end up keeping both eventually, this is really a question of which to prioritise buying first."]}},{"id":"blk_article_268_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Both seeds","source":"manual","productSlugs":["roasted-sesame-seeds","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_268_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flax vs sesame buying questions","items":[{"question":"Which seed is more essential to Indian cooking overall?","answer":"Sesame, given its long, central role in sweets, chutneys and tempering across many regional cuisines."},{"question":"Is flax seed worth buying if I already have sesame?","answer":"Yes, if you want its specific fibre and oil content added quietly into meals you already make."},{"question":"Do both seeds need the same storage?","answer":"Broadly similar, airtight and away from heat, though exact shelf life varies slightly between the two."},{"question":"Should a beginner buy both at once?","answer":"Not necessary, prioritising sesame first for its broader everyday use is a reasonable starting point."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Building a seed pantry from nothing? Here is which one to buy first and why.', seo_description='Flax seeds compared with sesame seeds, as a practical buying decision for building a starter seed pantry.', seo_keywords='flax seeds vs sesame seeds, which seed to buy first', reading_minutes=2, published_version_id='arv_truegrit_268_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_268';
