-- 269. Whole Urad vs Urad Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_269_2','art_truegrit_269',2,'{"blocks":[{"id":"blk_article_269_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Whole urad and urad dal are not really substitutes for each other in most kitchens, so the useful question is which specific dish you are planning to cook rather than which one to keep as a default."]}},{"id":"blk_article_269_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Match it to the dish","items":["Making dal makhani? Buy whole urad, sometimes labelled sabut urad, that is what the traditional recipe is built on.","Making dosa or idli batter, tempered dal, or a quick chilla? Buy split urad dal, it grinds and cooks the way those recipes need.","If you only cook one or the other regularly, there is little reason to stock both forms at once.","If your cooking spans both North Indian dal dishes and South Indian batters, both forms earn their place in the pantry.","When unsure which a recipe means by urad, split dal is the safer general assumption for most everyday dishes."]}},{"id":"blk_article_269_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole and split urad","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal"],"limit":2}},{"id":"blk_article_269_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole urad vs urad dal buying questions","items":[{"question":"Do I need both whole and split urad?","answer":"Only if you regularly cook dishes calling for both, dal makhani for whole and dosa batter or tempered dal for split."},{"question":"Which is the safer default if a recipe just says urad?","answer":"Split urad dal is the more common assumption for everyday, non dal makhani specific recipes."},{"question":"Is one significantly more expensive than the other?","answer":"Pricing is generally comparable, since both come from the same underlying pulse, just processed differently."},{"question":"Can I use split urad dal for dal makhani in a pinch?","answer":"You can, but expect a lighter, less textured result than the traditional whole grain version."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
