INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_269','Whole Urad vs Urad Dal','whole-urad-vs-urad-dal','Buy based on the specific dish on your plan this week, not a general household default.','whole urad vs urad dal, which urad to buy');

-- 270. Urad Sattu vs Chana Sattu
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_270_2','art_truegrit_270',2,'{"blocks":[{"id":"blk_article_270_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["For a first sattu purchase, chana sattu is the more traditional, widely recognised starting point, with urad sattu worth trying once you know you like the format."]}},{"id":"blk_article_270_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["Buying sattu for the first time? Chana sattu is the more classic, widely available starting point, especially in Bihari cooking traditions.","Already familiar with chana sattu and want something heavier and earthier? Urad sattu is the natural next bottle to try.","If you specifically want a heavier, more filling drink, urad sattu delivers that more directly than the milder chana version.","For paratha stuffing, either works, the choice comes down to which flavour you personally prefer in the filling.","Neither is objectively better, this is a flavour preference decision once you understand the base difference between the two pulses."]}},{"id":"blk_article_270_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram sattu","source":"manual","productSlugs":["black-gram-sattu"],"limit":1}},{"id":"blk_article_270_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad vs chana sattu buying questions","items":[{"question":"Which sattu should a first time buyer choose?","answer":"Chana sattu is the more traditional, widely recognised starting point for most first time buyers."},{"question":"Is urad sattu harder to find than chana sattu?","answer":"It can be somewhat less common, though it is a genuine regional variant rather than an unusual product."},{"question":"Does urad sattu taste much heavier than chana sattu?","answer":"Yes, noticeably earthier and heavier, which some buyers specifically prefer once they know what to expect."},{"question":"Can I use urad sattu in any recipe that calls for chana sattu?","answer":"Yes, though expect a heavier, earthier flavour in the finished drink or filling."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
