-- 271. Urad Besan vs Chana Besan
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_271_2','art_truegrit_271',2,'{"blocks":[{"id":"blk_article_271_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Chana besan remains the more versatile everyday flour for most Indian kitchens, with urad besan worth adding specifically when you want a heavier, earthier chilla."]}},{"id":"blk_article_271_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["For pakora, most everyday batters and general besan uses, chana besan is still the safer, more familiar default.","For a chilla where you specifically want a heavier, softer, earthier result, urad besan is worth the ratio adjustment it needs.","New to cooking with besan at all? Start with chana besan, since most recipes assume it without adjustment.","Already comfortable adjusting batters and want to try something different? Urad besan is a reasonable next step.","If you only want one besan in the pantry, chana besan covers more everyday ground than urad besan does.","Keep both if your household genuinely likes trying different chilla textures across the week."]}},{"id":"blk_article_271_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram besan","source":"manual","productSlugs":["black-gram-besan"],"limit":1}},{"id":"blk_article_271_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Urad vs chana besan buying questions","items":[{"question":"Which besan should most households default to?","answer":"Chana besan, since most everyday recipes assume it without needing ratio adjustments."},{"question":"When is urad besan actually the better buy?","answer":"When you specifically want a heavier, earthier chilla and are prepared to adjust water and rest time accordingly."},{"question":"Is urad besan harder to cook with for a beginner?","answer":"Slightly, since it absorbs more water and behaves differently than the chana besan most recipes are written for."},{"question":"Can I keep both besans stocked?","answer":"Yes, many households do, using chana besan as the default and urad besan for specific dishes."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='For most everyday cooking, chana besan is still the one to reach for. Here is when urad besan actually wins.', seo_description='Urad besan compared with chana besan, as a practical buying decision for everyday versus specific dishes.', seo_keywords='urad besan vs chana besan, which besan to buy', reading_minutes=2, published_version_id='arv_truegrit_271_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_271';
