-- 272. Whole Masoor vs Split Masoor
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_272_2','art_truegrit_272',2,'{"blocks":[{"id":"blk_article_272_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["For nearly all everyday cooking, split masoor dal is the more useful pantry staple, with whole masoor worth buying specifically when you want a curry that holds its shape."]}},{"id":"blk_article_272_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["For a quick everyday dal or khichdi, buy split masoor, it cooks fast and needs almost no planning ahead.","For a heartier curry where you want the lentil to hold together rather than break down, buy whole masoor and plan for a soak.","New to cooking with masoor? Split is the far more forgiving and versatile starting point.","Already comfortable with split masoor and want more texture in a specific dish? Whole is worth adding to your pantry.","If you can only keep one on hand, split masoor covers more everyday cooking needs than whole does."]}},{"id":"blk_article_272_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Red lentils","source":"manual","productSlugs":["red-lentils-broken","red-lentils-whole"],"limit":2}},{"id":"blk_article_272_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole vs split masoor buying questions","items":[{"question":"Which masoor is more useful for everyday cooking?","answer":"Split masoor dal, since it cooks quickly and needs little planning ahead."},{"question":"Is whole masoor worth buying if I mostly make quick dal?","answer":"Not particularly, split masoor already covers that use well. Whole is more useful for a specific curry style."},{"question":"Does whole masoor need much more planning?","answer":"A short soak helps, though it still cooks faster than many other whole pulses even without one."},{"question":"Can I keep just one form and be fine?","answer":"Yes, split masoor alone covers most everyday needs for a household that does not specifically want the whole curry style."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='For nearly all everyday cooking, split is the one worth having in the pantry.', seo_description='Whole masoor compared with split masoor, as a practical buying decision for everyday versus specific dishes.', seo_keywords='whole masoor vs split masoor, which masoor to buy', reading_minutes=2, published_version_id='arv_truegrit_272_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_272';
