-- 273. Daliya vs Semolina
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_273_2','art_truegrit_273',2,'{"blocks":[{"id":"blk_article_273_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["For a household deciding what to keep stocked for breakfast, the real question is whether you want the coarser bite of daliya or the smoother, faster cooking texture of semolina."]}},{"id":"blk_article_273_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["Want a heartier, more textured breakfast with visible bran? Buy daliya, either for savoury upma style or sweet kheer.","Want a quick, smooth upma or halwa with minimal cooking time? Buy semolina, it cooks faster and finishes smoother.","Cooking for kids or anyone who prefers a smoother texture? Semolina is usually the easier sell.","Want more fibre in your morning routine specifically? Daliya keeps the bran that semolina milling removes.","Most households that cook both upma and porridge style breakfasts end up keeping both stocked rather than choosing just one."]}},{"id":"blk_article_273_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One household juggling one grade of daliya for both a savoury upma and a milk kheer describes exactly this coarseness trade-off](/community/dsc_truegrit_006), a useful read if you are trying to cover both with a single grade."]}},{"id":"blk_article_273_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Daliya and semolina","source":"manual","productSlugs":["daliya-banshi-wheat","semolina-banshi-wheat"],"limit":2}},{"id":"blk_article_273_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya vs semolina buying questions","items":[{"question":"Which is quicker for a weekday breakfast?","answer":"Semolina, since it cooks faster without needing bran to soften first."},{"question":"Which is better for a coarser, more filling breakfast?","answer":"Daliya, thanks to its retained bran and more textured bite."},{"question":"Should I buy both if my family has different preferences?","answer":"Yes, that is a reasonable approach if household members genuinely prefer different textures."},{"question":"Is one significantly cheaper than the other?","answer":"Pricing is generally comparable between the two for a similar wheat variety."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The breakfast decision most households actually face, boiled down to a quick call.', seo_description='Daliya compared with semolina, as a practical buying decision for breakfast and everyday cooking.', seo_keywords='daliya vs semolina, which to buy for breakfast', reading_minutes=2, published_version_id='arv_truegrit_273_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_273';
