INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_273','Daliya vs Semolina','daliya-vs-semolina','The breakfast decision most households actually face, boiled down to a quick call.','daliya vs semolina, which to buy for breakfast');

-- 274. Daliya vs Oats
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_274_2','art_truegrit_274',2,'{"blocks":[{"id":"blk_article_274_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["If you are used to oats and considering daliya, or the other way round, the switch changes more than just the grain, it changes texture, cooking time and whether the dish leans savoury or sweet by default."]}},{"id":"blk_article_274_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually changes","items":["Switching from oats to daliya means a chewier, more textured result and a longer, more hands on cooking process.","Switching from daliya to oats means a creamier, faster cooking porridge, but a step away from the savoury Indian preparations daliya suits.","If your breakfast routine is mostly savoury, tempered and spiced, daliya fits that habit more naturally than oats do.","If your routine leans toward a quick sweet porridge, oats are the lower effort, faster option of the two.","Neither needs to fully replace the other, alternating between them is a reasonable way to diversify breakfast without overhauling your routine."]}},{"id":"blk_article_274_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Daliya","source":"manual","productSlugs":["daliya-banshi-wheat","daliya-kathiya-wheat"],"limit":2}},{"id":"blk_article_274_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Daliya vs oats switching questions","items":[{"question":"Is switching from oats to daliya a big adjustment?","answer":"The main adjustment is cooking time and texture, daliya takes longer and eats chewier than rolled oats."},{"question":"Which is easier for a quick weekday breakfast?","answer":"Oats, generally, since rolled oats are pre steamed and cook faster than most daliya grades."},{"question":"Can I alternate between the two rather than choosing one?","answer":"Yes, many households do exactly this, keeping breakfast varied across the week."},{"question":"Does one require different equipment to cook?","answer":"No, both can be cooked in a standard pot or pressure cooker, no special equipment needed for either."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Switching your breakfast routine? Here is what actually changes, beyond the obvious wheat versus oat difference.', seo_description='Daliya compared with oats, as a practical buying decision for switching or diversifying your breakfast routine.', seo_keywords='daliya vs oats, switching breakfast routine', reading_minutes=2, published_version_id='arv_truegrit_274_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_274';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_274';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_274','Daliya vs Oats','daliya-vs-oats','Switching your breakfast routine? Here is what actually changes, beyond the obvious wheat versus oat difference.','daliya vs oats, switching breakfast routine');

-- 275. Wheat Pasta vs Regular Pasta
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_275_2','art_truegrit_275',2,'{"blocks":[{"id":"blk_article_275_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Rather than picking one pasta as a permanent default, it helps to match the choice to the specific meal, a heavier, nuttier dish suits whole wheat, a lighter, more delicate sauce suits refined pasta better."]}},{"id":"blk_article_275_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["Making a heavier, spiced or masala based pasta dish? Whole wheat pasta''s nuttier flavour holds up well against it.","Making a light, delicate sauce where you want the pasta to stay in the background? Regular refined pasta is the safer choice.","Want more fibre in a regular meal without thinking about it much? Whole wheat pasta is the easy swap.","Cooking for someone new to whole grain pasta? Start with a smaller portion mixed with a familiar sauce rather than switching entirely.","Many households keep both, using whole wheat for weeknight Indian style pasta and refined for a lighter, simpler dish."]}},{"id":"blk_article_275_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Whole-wheat pasta","source":"manual","productSlugs":["pasta-banshi-wheat","pasta-kathiya-wheat"],"limit":2}},{"id":"blk_article_275_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat vs regular pasta buying questions","items":[{"question":"Which pasta suits an Indian style masala sauce better?","answer":"Whole wheat pasta, since its nuttier flavour pairs well with tempering and masala based sauces."},{"question":"Is whole wheat pasta a good first choice for someone new to it?","answer":"Starting with a smaller portion in a familiar sauce is an easier introduction than switching entirely at once."},{"question":"Does one cook noticeably differently from the other?","answer":"Yes, whole wheat pasta has a narrower window between al dente and overcooked, so it needs closer attention."},{"question":"Should I keep both types stocked?","answer":"Many households do, choosing based on the specific dish and sauce planned for that meal."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The occasion, more than a fixed preference, should decide which one goes in the pot tonight.', seo_description='Whole-wheat pasta compared with regular pasta, as a practical buying decision matched to the meal and occasion.', seo_keywords='wheat pasta vs regular pasta, which pasta to buy', reading_minutes=2, published_version_id='arv_truegrit_275_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_275';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_275';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_275','Wheat Pasta vs Regular Pasta','wheat-pasta-vs-regular-pasta','The occasion, more than a fixed preference, should decide which one goes in the pot tonight.','wheat pasta vs regular pasta, which pasta to buy');

-- 276. Wheat Vermicelli vs Rice Vermicelli
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_276_2','art_truegrit_276',2,'{"blocks":[{"id":"blk_article_276_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Wheat and rice vermicelli are built for genuinely different dishes, so the decision is really about what you are cooking rather than a general household preference between the two."]}},{"id":"blk_article_276_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["Making sweet seviyan kheer or a North Indian style sevai? Buy wheat vermicelli, it is what those recipes are built around.","Making idiyappam or a South Indian or Southeast Asian style noodle dish? Buy rice vermicelli instead.","Need something gluten free specifically? Rice vermicelli is the only option between the two, since wheat vermicelli always contains gluten.","Not sure which your family''s recipe traditionally uses? Check for gluten sensitivity first, then default to wheat vermicelli for kheer style dishes.","Households cooking across regional styles often keep both, since neither substitutes well for the other''s traditional dishes."]}},{"id":"blk_article_276_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Wheat vermicelli","source":"manual","productSlugs":["vermicelli-banshi-wheat","vermicelli-kathiya-wheat"],"limit":2}},{"id":"blk_article_276_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Wheat vs rice vermicelli buying questions","items":[{"question":"Which vermicelli should I buy for kheer?","answer":"Wheat vermicelli, typically the roasted kind, is what most seviyan kheer recipes are built on."},{"question":"Which should I buy if I need gluten free?","answer":"Rice vermicelli, since wheat vermicelli always contains gluten and is not suitable for a gluten free diet."},{"question":"Can I substitute one for the other in a pinch?","answer":"Not well, the cooking method and final texture differ enough that the dish will not turn out as intended."},{"question":"Should I keep both stocked?","answer":"If you cook dishes from both traditions regularly, yes, otherwise buy based on whichever dish you make more often."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The dish you are making, not a household default, should decide which vermicelli goes in the pot.', seo_description='Wheat vermicelli compared with rice vermicelli, as a practical buying decision matched to the specific dish.', seo_keywords='wheat vermicelli vs rice vermicelli, which vermicelli to buy', reading_minutes=2, published_version_id='arv_truegrit_276_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_276';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_276';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_276','Wheat Vermicelli vs Rice Vermicelli','wheat-vermicelli-vs-rice-vermicelli-2','The dish you are making, not a household default, should decide which vermicelli goes in the pot.','wheat vermicelli vs rice vermicelli, which vermicelli to buy');

-- 277. How to Cook Every Type of Dal
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_277_2','art_truegrit_277',2,'{"blocks":[{"id":"blk_article_277_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Most dals share the same basic method, boil with turmeric and salt, finish with a tempering, but the specifics that actually matter, soaking, water ratio and timing, vary enough by pulse to be worth knowing in advance."]}},{"id":"blk_article_277_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The pattern by pulse","items":["Split masoor dal needs little to no soaking and cooks in fifteen to twenty minutes, the fastest of the common dals.","Split urad dal benefits from a short soak and cooks reasonably quickly, though it thickens more than masoor as it sits.","Whole urad and whole masoor both benefit from a proper soak and a longer simmer to soften fully and evenly.","Dried white field peas need a genuine overnight soak and a long simmer, cooking far slower than any of the split dals.","Regardless of pulse, a hot tempering, ghee or oil with cumin and garlic, poured over just before serving finishes almost any dal well."]}},{"id":"blk_article_277_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Dal for every method","source":"manual","productSlugs":["red-lentils-broken","black-gram-broken-dal","field-pea-white"],"limit":3}},{"id":"blk_article_277_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Cooking every dal questions","items":[{"question":"Is there one water ratio that works for every dal?","answer":"Roughly three parts water to one part dal is a reasonable starting point, though whole pulses and field peas need more."},{"question":"Which dal is the most forgiving for a beginner?","answer":"Split masoor, since it cooks quickly, needs little soaking, and is hard to get badly wrong."},{"question":"Does the tempering step really matter that much?","answer":"Yes, a freshly heated tempering makes a noticeable flavour difference regardless of which dal it is poured over."},{"question":"Can I use one pot method for every type of dal?","answer":"Broadly yes, though whole pulses and dried peas benefit from a pressure cooker to keep cooking time reasonable."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A few shared principles cover most dals, once you know which pulse needs which adjustment.', seo_description='How to cook every type of dal: shared principles for water ratio, soaking and tempering across common pulses.', seo_keywords='how to cook dal, dal cooking guide', reading_minutes=3, published_version_id='arv_truegrit_277_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_277';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_277';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_277','How to Cook Every Type of Dal','how-to-cook-every-type-of-dal','A few shared principles cover most dals, once you know which pulse needs which adjustment.','how to cook dal, dal cooking guide');

-- 278. Complete Guide to Soaking Indian Pulses
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_278_2','art_truegrit_278',2,'{"blocks":[{"id":"blk_article_278_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Soaking advice gets repeated as a blanket rule far more often than it actually applies as one, since how much a pulse benefits from soaking varies enormously across the common ones an Indian kitchen stocks."]}},{"id":"blk_article_278_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Soaking by pulse","items":["Split masoor dal needs virtually no soaking, cooking quickly enough on its own that skipping it barely costs any time.","Split urad dal and split moong benefit from a short soak, twenty to thirty minutes, though they cook reasonably well without one too.","Whole pulses, whole urad and whole masoor, benefit more noticeably from a proper soak of thirty minutes to a few hours.","Dried white field peas need a genuine overnight soak, six to eight hours at minimum, to cook evenly in a reasonable time.","When unsure, a longer soak rarely hurts a pulse, while skipping a needed one mainly costs extra time at the stove, not a ruined dish."]}},{"id":"blk_article_278_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Pulses to soak","source":"manual","productSlugs":["black-gram-whole","field-pea-white","red-lentils-whole"],"limit":3}},{"id":"blk_article_278_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Pulse soaking guide questions","items":[{"question":"Is it ever harmful to soak a pulse too long?","answer":"Not usually, though very warm weather can risk mild fermentation if soaked far longer than needed. Refrigerate if soaking many hours in heat."},{"question":"Which pulse most benefits from soaking?","answer":"Dried white field peas show the biggest difference, since skipping the soak significantly extends cooking time."},{"question":"Does soaking affect flavour, not just texture?","answer":"Mostly texture and cooking time. Flavour differences from soaking are minor for most common pulses."},{"question":"Can I speed up soaking with hot water?","answer":"Yes, warm water shortens the wait noticeably compared to cold, useful if you are short on time."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Soaking time is not one universal rule. It varies enormously depending on which pulse is in the pot.', seo_description='A complete guide to soaking Indian pulses: which need it, how long, and which can safely skip the step.', seo_keywords='soaking Indian pulses guide, pulse soaking times', reading_minutes=3, published_version_id='arv_truegrit_278_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_278';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_278';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_278','Complete Guide to Soaking Indian Pulses','complete-guide-to-soaking-indian-pulses','Soaking time is not one universal rule. It varies enormously depending on which pulse is in the pot.','soaking Indian pulses guide, pulse soaking times');

-- 279. Which Pulses Need Overnight Soaking?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_279_2','art_truegrit_279',2,'{"blocks":[{"id":"blk_article_279_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Overnight soaking is genuinely necessary for fewer pulses than blanket cooking advice often implies, and knowing which ones actually need it saves unnecessary planning for the rest."]}},{"id":"blk_article_279_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually needs it","items":["Dried white field peas genuinely need overnight soaking, six to eight hours minimum, to cook evenly in a reasonable time.","Whole urad benefits significantly from a long soak, though a few hours rather than a full overnight period is often enough.","Whole masoor benefits from soaking but needs it far less than white peas do, even a short soak helps meaningfully.","Split dals, masoor, urad and moong, do not genuinely need overnight soaking, a short soak or none at all is usually sufficient.","If a recipe insists on overnight soaking for a split dal specifically, that instruction is likely more habit than necessity."]}},{"id":"blk_article_279_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Overnight soak pulses","source":"manual","productSlugs":["field-pea-white","black-gram-whole"],"limit":2}},{"id":"blk_article_279_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Overnight soaking questions","items":[{"question":"Do split dals ever need overnight soaking?","answer":"Rarely, most split dals cook well with a short soak or none at all, unlike dried whole peas."},{"question":"What happens if I forget to soak white peas overnight?","answer":"They will still cook, but expect a considerably longer simmer and less evenly softened peas."},{"question":"Is a four hour soak close enough to overnight for whole pulses?","answer":"For whole urad or masoor, often yes. For dried white peas, a full overnight soak is the safer choice."},{"question":"Can I soak pulses for too long overnight?","answer":"Very long soaks in warm weather can risk mild fermentation, so refrigerate if soaking much longer than necessary."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A short list, not the default assumption most soaking advice implies.', seo_description='Which Indian pulses genuinely need overnight soaking, and which can skip it without much consequence.', seo_keywords='pulses that need overnight soaking', reading_minutes=2, published_version_id='arv_truegrit_279_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_279';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_279';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_279','Which Pulses Need Overnight Soaking?','which-pulses-need-overnight-soaking','A short list, not the default assumption most soaking advice implies.','pulses that need overnight soaking');

-- 280. How Much Water Should You Use for Dal?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_280_2','art_truegrit_280',2,'{"blocks":[{"id":"blk_article_280_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["There is no single water ratio that suits every dal, since how much a pulse absorbs and how thick you want the final result both change the right starting point."]}},{"id":"blk_article_280_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Starting ratios","items":["Split masoor dal generally cooks well with about three parts water to one part dal for a medium consistency.","Split urad dal follows a similar starting ratio, though it thickens more as it sits, so add extra water if serving later.","Whole pulses, urad or masoor, generally need a bit more water, closer to four parts, since they take longer to soften fully.","Dried white field peas need the most water relative to volume, both during soaking and cooking, given how long they simmer.","Treat any ratio as a starting point, adding hot water partway through cooking is easier than trying to correct an overly thin dal."]}},{"id":"blk_article_280_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Dal to practise ratios on","source":"manual","productSlugs":["red-lentils-broken","black-gram-broken-dal"],"limit":2}},{"id":"blk_article_280_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Dal water ratio questions","items":[{"question":"What happens if I use too little water for dal?","answer":"It can cook unevenly or stick to the pot. Add hot water gradually if the dal looks too dry partway through cooking."},{"question":"Should I add water before or during cooking?","answer":"Both, start with an estimated ratio, then adjust with hot water as needed once you can see how it is cooking."},{"question":"Does pressure cooking need less water than an open pot?","answer":"Generally similar, though less evaporates in a pressure cooker, so slightly less water can work there."},{"question":"Why does my dal thicken so much after cooking?","answer":"Most dals continue to absorb liquid and thicken as they sit, which is normal and easily fixed with a little added water."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A starting ratio that actually varies by pulse, not one number that works everywhere.', seo_description='How much water to use for dal: starting ratios by pulse type, and how to adjust as it cooks.', seo_keywords='dal water ratio, how much water for dal', reading_minutes=2, published_version_id='arv_truegrit_280_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_280';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_280';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_280','How Much Water Should You Use for Dal?','how-much-water-should-you-use-for-dal','A starting ratio that actually varies by pulse, not one number that works everywhere.','dal water ratio, how much water for dal');

-- 281. How to Store Pulses Without Insects
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_281_2','art_truegrit_281',2,'{"blocks":[{"id":"blk_article_281_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Keeping insects out of stored pulses comes down to a combination of habits rather than any single trick, since eggs can sometimes arrive with the grain itself before storage even begins."]}},{"id":"blk_article_281_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Use airtight containers rather than the original packaging once opened, reducing both air and pest access significantly.","Freeze new stock for a few days before transferring to long term storage, which can kill any eggs already present in the batch.","Store in a cool, dark spot away from heat sources, since warmth speeds up any pest activity that does take hold.","Check stored pulses periodically rather than assuming a sealed container is permanently safe, since problems can still develop over time.","Use older stock before newer purchases, reducing how long any single batch sits in storage."]}},{"id":"blk_article_281_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Pulses to store well","source":"manual","productSlugs":["black-gram-whole","red-lentils-broken"],"limit":2}},{"id":"blk_article_281_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Pest-free pulse storage questions","items":[{"question":"Does freezing pulses before storage really help?","answer":"It can, freezing for a few days is believed to kill any eggs already present, though results vary and it is not a guaranteed fix."},{"question":"Are neem leaves or dried chillies effective?","answer":"Some households find them helpful as a deterrent, though they are not a guaranteed solution on their own."},{"question":"How often should I check stored pulses for pests?","answer":"Every few weeks is a reasonable habit, more often during humid months when pest activity tends to increase."},{"question":"Is steel or glass better than plastic for storage?","answer":"Any truly airtight container works. Material matters less than how well it actually seals."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A handful of habits that actually reduce risk, more reliable than a single trick alone.', seo_description='How to store pulses without insects: airtight containers, freezing new stock, and other reliable habits.', seo_keywords='how to store pulses without insects, pulse pest prevention', reading_minutes=2, published_version_id='arv_truegrit_281_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_281';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_281';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_281','How to Store Pulses Without Insects','how-to-store-pulses-without-insects','A handful of habits that actually reduce risk, more reliable than a single trick alone.','how to store pulses without insects, pulse pest prevention');

-- 282. How to Store Flour in Indian Weather
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_282_2','art_truegrit_282',2,'{"blocks":[{"id":"blk_article_282_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Humidity, more than temperature alone, is usually the bigger challenge for storing flour well across much of India, particularly during the monsoon months."]}},{"id":"blk_article_282_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually helps","items":["Use a genuinely airtight container, since humid air is what most directly shortens flour''s shelf life and invites spoilage.","Keep flour away from the kitchen''s most humid spots, near a sink or stove, favouring a drier cupboard instead.","During monsoon months, consider buying smaller quantities more often rather than a large bag that sits open for weeks.","Refrigeration can help in a particularly humid or coastal climate, though a well sealed container is the more universal fix.","Freshly milled flour, with more bran exposed, tends to be more sensitive to humidity than heavily refined flour is.","A dry spoon used every time also helps, since even small amounts of moisture introduced during use can add up over time."]}},{"id":"blk_article_282_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flour to store well","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour"],"limit":2}},{"id":"blk_article_282_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Flour storage in Indian weather questions","items":[{"question":"Does coastal humidity affect flour more than inland climates?","answer":"Often yes, coastal humidity tends to be more persistent, which is why buyers in those regions sometimes prefer smaller, more frequent purchases."},{"question":"Should I refrigerate flour during monsoon?","answer":"It can help in particularly humid conditions, though a genuinely airtight container is the more consistently effective fix."},{"question":"Does freshly milled flour need different storage than packaged atta?","answer":"It benefits from slightly more careful storage, since more of the bran is exposed to humidity than in heavily refined flour."},{"question":"How can I tell if flour has been affected by humidity?","answer":"Clumping, a musty smell, or visible mould are all signs. Discard flour showing any of these rather than trying to salvage it."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Humidity, more than heat alone, is what actually shortens flour''s shelf life in most of India.', seo_description='How to store flour properly in Indian weather: managing humidity, monsoon conditions, and container choice.', seo_keywords='how to store flour in India, flour storage monsoon', reading_minutes=2, published_version_id='arv_truegrit_282_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_282';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_282';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_282','How to Store Flour in Indian Weather','how-to-store-flour-in-indian-weather','Humidity, more than heat alone, is what actually shortens flour''s shelf life in most of India.','how to store flour in India, flour storage monsoon');

-- 283. How to Store Cold-Pressed Oils
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_283_2','art_truegrit_283',2,'{"blocks":[{"id":"blk_article_283_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Cold-pressed oils share some basic storage principles, cool, dark and sealed, but they are not all equally sensitive, and treating flaxseed oil the same as mustard oil undersells how much more careful flaxseed actually needs."]}},{"id":"blk_article_283_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What applies across the board","items":["All cold-pressed oils benefit from a cool, dark storage spot away from direct sunlight and heat sources.","Mustard and sesame oil are relatively stable and generally tolerate a pantry shelf well without refrigeration.","Flaxseed oil is meaningfully more sensitive and does best refrigerated after opening, discussed in more depth elsewhere in this guide.","Sesame oil sits closest to mustard in stability, thanks to natural compounds that help it resist oxidation.","Tightly sealing each bottle after use matters across all three, reducing the air exposure that speeds up spoilage."]}},{"id":"blk_article_283_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Cold-pressed oils","source":"manual","productSlugs":["black-mustard-oil","sesame-oil","linseed-flax-seed-oil"],"limit":3}},{"id":"blk_article_283_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Cold-pressed oil storage questions","items":[{"question":"Do all cold-pressed oils need refrigeration?","answer":"No, mustard and sesame oil generally tolerate a pantry shelf well. Flaxseed oil is the one that benefits most from refrigeration."},{"question":"Which cold-pressed oil is the most stable?","answer":"Sesame oil, thanks to natural compounds that help it resist oxidation better than mustard or flaxseed oil."},{"question":"Does bottle colour matter for storage?","answer":"A dark or opaque bottle helps protect against light exposure, though storing any bottle in a dark cupboard achieves a similar effect."},{"question":"How long do cold-pressed oils typically last once opened?","answer":"Mustard and sesame oil often last a year or more properly stored. Flaxseed oil should generally be used within a couple of months."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Not all cold-pressed oils need the same care. Here is what applies across mustard, sesame and flaxseed.', seo_description='How to store cold-pressed oils: shared principles and specific differences between mustard, sesame and flaxseed oil.', seo_keywords='how to store cold pressed oils, cold pressed oil storage', reading_minutes=2, published_version_id='arv_truegrit_283_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_283';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_283';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_283','How to Store Cold-Pressed Oils','how-to-store-cold-pressed-oils','Not all cold-pressed oils need the same care. Here is what applies across mustard, sesame and flaxseed.','how to store cold pressed oils, cold pressed oil storage');

-- 284. Why Cold-Pressed Oils Develop Sediment
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_284_2','art_truegrit_284',2,'{"blocks":[{"id":"blk_article_284_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sediment at the bottom of a cold-pressed oil bottle is a natural consequence of lighter filtration, not a sign something has gone wrong with the oil."]}},{"id":"blk_article_284_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What is actually happening","items":["Cold-pressed oils are typically settled and lightly filtered rather than heavily processed, allowing some natural sediment to remain.","Refined oils go through additional filtration specifically designed to remove this kind of sediment entirely.","The sediment itself is made up of fine particles from the original seed, not a contaminant or sign of spoilage.","Shaking the bottle before use redistributes settled sediment through the oil rather than indicating any problem.","Some buyers prefer to pour off the clearer oil above the sediment, which is a matter of preference rather than necessity."]}},{"id":"blk_article_284_3","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["[One person specifically asks whether sediment goes rancid faster than the oil above it, and whether to pour it off or shake it back in](/community/dsc_truegrit_019), a genuinely common question worth reading through."]}},{"id":"blk_article_284_4","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Naturally settled oils","source":"manual","productSlugs":["black-mustard-oil","sesame-oil"],"limit":2}},{"id":"blk_article_284_5","type":"faq","version":1,"enabled":true,"props":{"heading":"Oil sediment questions","items":[{"question":"Is sediment in cold-pressed oil safe to consume?","answer":"Yes, it is made up of fine natural particles from the seed, not a contaminant."},{"question":"Should I shake the sediment back in or pour it off?","answer":"Either is fine, this comes down to personal preference rather than a right or wrong approach."},{"question":"Does more sediment mean lower quality?","answer":"Not necessarily, the amount can vary by batch and pressing without reflecting a difference in overall quality."},{"question":"Does sediment appear in refined oils too?","answer":"Rarely, since refining specifically removes the particles that would otherwise settle as sediment."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A natural result of skipping heavy filtration, not a sign anything has gone wrong.', seo_description='Why cold-pressed oils develop sediment: the natural filtration difference from refined oils, and what to do about it.', seo_keywords='cold pressed oil sediment, why does oil have sediment', reading_minutes=2, published_version_id='arv_truegrit_284_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_284';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_284';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_284','Why Cold-Pressed Oils Develop Sediment','why-cold-pressed-oils-develop-sediment','A natural result of skipping heavy filtration, not a sign anything has gone wrong.','cold pressed oil sediment, why does oil have sediment');

-- 285. What Oil Should You Use for Different Indian Dishes?
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_285_2','art_truegrit_285',2,'{"blocks":[{"id":"blk_article_285_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Using one oil for every dish is common, but matching the oil to the dish actually changes the result more than most home cooks expect, particularly across the range of oils this range covers."]}},{"id":"blk_article_285_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Matching oil to dish","items":["Bengali fish curry and pickles suit black mustard oil, whose pungency is part of the traditional flavour of both.","Everyday North Indian sabzi and tempering suit yellow mustard oil, milder and more supportive of other spices.","South Indian tempering and tadka suit a raw pressed sesame oil, which can handle the heat and adds its own nutty note.","A finished dal, salad or vegetable dish suits a small drizzle of flaxseed oil, added raw once cooking is done.","Deep frying and high volume cooking suit an oil with a genuinely high smoke point, discussed further elsewhere in this guide."]}},{"id":"blk_article_285_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"The right oil for the dish","source":"manual","productSlugs":["black-mustard-oil","sesame-oil","linseed-flax-seed-oil"],"limit":3}},{"id":"blk_article_285_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Choosing oil by dish questions","items":[{"question":"Can I really taste the difference between oils in a finished dish?","answer":"Yes, particularly with mustard and sesame oil, both of which carry a distinct flavour into the final result."},{"question":"Is it worth keeping more than one oil stocked?","answer":"If you cook across regional styles regularly, yes. A single all purpose oil works but loses some of each dish''s traditional character."},{"question":"Which oil is the safest default if I only keep one?","answer":"Yellow mustard oil works reasonably well across a broad range of everyday Indian dishes."},{"question":"Should flaxseed oil ever be my primary cooking oil?","answer":"No, it should never be heated, so it cannot serve as a primary cooking oil regardless of the dish."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Matching oil to dish, rather than using one oil for everything, changes more than people expect.', seo_description='Which oil to use for different Indian dishes: mustard, sesame and flaxseed matched to specific cooking needs.', seo_keywords='which oil for Indian dishes, best oil for Indian cooking', reading_minutes=3, published_version_id='arv_truegrit_285_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_285';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_285';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_285','What Oil Should You Use for Different Indian Dishes?','what-oil-should-you-use-for-different-indian-dishes','Matching oil to dish, rather than using one oil for everything, changes more than people expect.','which oil for Indian dishes, best oil for Indian cooking');

-- 286. Cooking Oil Smoke Points Explained
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_286_2','art_truegrit_286',2,'{"blocks":[{"id":"blk_article_286_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["An oil''s smoke point is the temperature where it starts to break down and smoke, and knowing roughly where each oil sits explains a lot about what it is actually suited for in a kitchen."]}},{"id":"blk_article_286_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What it actually means","items":["Smoke point marks where an oil begins to break down under heat, developing an unpleasant flavour and losing quality.","Refined oils generally have higher smoke points than unrefined, cold-pressed versions of the same oil.","Cold-pressed mustard and raw pressed sesame oil have moderate smoke points, suited to tempering and everyday cooking heat.","Roasted, toasted sesame oil and flaxseed oil sit at the lower end, better suited to finishing than direct high heat.","Choosing an oil with an appropriate smoke point for the cooking method matters more than chasing the single highest number available."]}},{"id":"blk_article_286_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Oils with different smoke points","source":"manual","productSlugs":["yellow-mustard-oil","sesame-oil","linseed-flax-seed-oil"],"limit":3}},{"id":"blk_article_286_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Smoke point questions","items":[{"question":"What happens if I exceed an oil''s smoke point?","answer":"The oil breaks down, developing an unpleasant, sometimes bitter flavour and losing some of its nutritional quality."},{"question":"Do refined oils always have higher smoke points?","answer":"Generally yes, refining removes compounds that would otherwise break down at lower temperatures."},{"question":"Should I always choose the oil with the highest smoke point?","answer":"Not necessarily, flavour and traditional use matter too, and not every dish needs very high heat cooking."},{"question":"Is flaxseed oil''s low smoke point a defect?","answer":"No, it reflects the same delicate fat content that makes the oil worth using raw in the first place."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The temperature where an oil starts to break down, and why it changes what each oil is actually suited for.', seo_description='Cooking oil smoke points explained: what they mean, and how they compare across mustard, sesame and flaxseed oil.', seo_keywords='cooking oil smoke point, smoke point explained', reading_minutes=2, published_version_id='arv_truegrit_286_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_286';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_286';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_286','Cooking Oil Smoke Points Explained','cooking-oil-smoke-points-explained','The temperature where an oil starts to break down, and why it changes what each oil is actually suited for.','cooking oil smoke point, smoke point explained');

-- 287. Guide to Traditional Indian Cooking Oils
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_287_2','art_truegrit_287',2,'{"blocks":[{"id":"blk_article_287_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Traditional Indian cooking draws on more than one oil, each carrying its own regional history and its own specific role, rather than a single all purpose choice most modern kitchens default to."]}},{"id":"blk_article_287_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The three at a glance","items":["Mustard oil, pungent and traditional to North and East India, available as sharper black or milder yellow, used across everyday cooking and specialty dishes alike.","Sesame oil, nutty and traditional to South India, available raw pressed for cooking or roasted pressed for finishing, and naturally more stable than most unrefined oils.","Flaxseed oil, mild and grassy, a smaller but genuine part of the tradition, used strictly raw as a finishing addition rather than a cooking oil.","Each carries its own regional identity, and using the traditional oil for a traditional dish genuinely changes the final flavour.","Keeping more than one stocked reflects how varied Indian regional cooking actually is, rather than being an unnecessary indulgence."]}},{"id":"blk_article_287_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditional Indian oils","source":"manual","productSlugs":["black-mustard-oil","sesame-oil","linseed-flax-seed-oil"],"limit":3}},{"id":"blk_article_287_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Traditional Indian oils guide questions","items":[{"question":"Which oil is most central to Indian cooking overall?","answer":"Mustard and sesame both carry deep regional significance, mustard in the north and east, sesame more in the south."},{"question":"Is flaxseed oil as traditional as the other two?","answer":"It has a genuine but smaller traditional role, used specifically raw rather than across general cooking."},{"question":"Should I choose just one of these three?","answer":"Not necessarily, each serves a different role, and many households benefit from keeping more than one stocked."},{"question":"Which is the best starting point for someone new to these oils?","answer":"Yellow mustard oil is a reasonably versatile, forgiving starting point for everyday cooking."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Mustard, sesame and flaxseed, three oils with genuinely different roles rather than three versions of the same thing.', seo_description='A guide to traditional Indian cooking oils: mustard, sesame and flaxseed, their traditional roles and how to choose.', seo_keywords='traditional Indian cooking oils guide', reading_minutes=3, published_version_id='arv_truegrit_287_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_287';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_287';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_287','Guide to Traditional Indian Cooking Oils','guide-to-traditional-indian-cooking-oils','Mustard, sesame and flaxseed, three oils with genuinely different roles rather than three versions of the same thing.','traditional Indian cooking oils guide');

-- 288. Guide to Indian Whole Grains
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_288_2','art_truegrit_288',2,'{"blocks":[{"id":"blk_article_288_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Every product in this range built on wheat, flour, daliya, semolina, pasta and vermicelli, traces back to the same grain family, differing mainly in how far processing carries it from its original whole form."]}},{"id":"blk_article_288_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The wheat family at a glance","items":["Whole wheat flour, milled fine, keeps the whole grain''s bran and germ, the base for roti and paratha.","Daliya, cracked rather than ground, keeps the bran and germ in coarse pieces, suited to porridge style dishes.","Semolina, coarse middlings sieved from milling, mostly refined endosperm, suited to upma, halwa and pasta.","Pasta and vermicelli, formed shapes made from flour or semolina, extending the same grain into different everyday dishes.","All of these can come from any of our three wheat landraces, Kathiya, Banshi or Paigambari, each carrying its own character through."]}},{"id":"blk_article_288_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"The wheat family","source":"manual","productSlugs":["kathiya-wheat-flour","daliya-banshi-wheat","semolina-paigambari-wheat"],"limit":3}},{"id":"blk_article_288_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Whole grains guide questions","items":[{"question":"Are daliya, semolina and flour all the same grain?","answer":"Yes, they can all come from the same wheat, differing in how far milling or cracking has processed the grain."},{"question":"Which form should I buy if I am not sure what to cook?","answer":"Flour is the most versatile starting point, since it covers the widest range of everyday dishes."},{"question":"Does the wheat variety matter across all these forms?","answer":"Yes, Kathiya, Banshi and Paigambari each carry their own hardness and flavour through into any form they are processed into."},{"question":"Is pasta really part of the same grain family as roti flour?","answer":"Yes, it is simply a different shape and cooking method built on the same underlying wheat."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Wheat, daliya, semolina, pasta and vermicelli are all the same grain family, shaped by how far processing goes.', seo_description='A guide to Indian whole grains: wheat, daliya, semolina, pasta and vermicelli, and how processing shapes each one.', seo_keywords='Indian whole grains guide, wheat grain forms explained', reading_minutes=3, published_version_id='arv_truegrit_288_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_288';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_288';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_288','Guide to Indian Whole Grains','guide-to-indian-whole-grains','Wheat, daliya, semolina, pasta and vermicelli are all the same grain family, shaped by how far processing goes.','Indian whole grains guide, wheat grain forms explained');

-- 289. Guide to Indian Lentils and Pulses
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_289_2','art_truegrit_289',2,'{"blocks":[{"id":"blk_article_289_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram, red lentils and white field peas each bring a genuinely different texture, cooking time and traditional role to an Indian kitchen, rather than being interchangeable versions of the same basic ingredient."]}},{"id":"blk_article_289_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The pulses at a glance","items":["Black gram, urad, is heavier and earthier, anchoring dal makhani, South Indian batters, sattu and besan.","Red lentils, masoor, are the fastest cooking of the three, ideal for a quick everyday dal or khichdi.","White field peas need the most planning, a genuine overnight soak, but anchor beloved dishes like ghugni and ragda.","Each pulse also comes in whole and processed forms, whole for texture, dal or split for speed, discussed in depth elsewhere in this guide.","A well stocked pantry benefits from at least one of each, since they rarely substitute cleanly for one another."]}},{"id":"blk_article_289_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Indian pulses","source":"manual","productSlugs":["black-gram-whole","red-lentils-broken","field-pea-white"],"limit":3}},{"id":"blk_article_289_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Lentils and pulses guide questions","items":[{"question":"Which pulse should I buy first if I am starting from scratch?","answer":"Split masoor dal, thanks to its fast, forgiving cooking time and broad everyday use."},{"question":"Which pulse needs the most advance planning?","answer":"White field peas, which need a genuine overnight soak before cooking."},{"question":"Can these three pulses substitute for each other?","answer":"Rarely well, each has a distinct texture and cooking time suited to different dishes."},{"question":"Do all three come in more than one processed form?","answer":"Black gram most notably, available whole, split, roasted as sattu, and ground as besan."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Black gram, red lentils and white field peas each anchor a genuinely different set of dishes.', seo_description='A guide to Indian lentils and pulses: black gram, red lentils and white field peas, and how to choose between them.', seo_keywords='Indian lentils and pulses guide', reading_minutes=3, published_version_id='arv_truegrit_289_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_289';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_289';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_289','Guide to Indian Lentils and Pulses','guide-to-indian-lentils-and-pulses','Black gram, red lentils and white field peas each anchor a genuinely different set of dishes.','Indian lentils and pulses guide');

-- 290. Beginner’s Guide to Seeds in Indian Cooking
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_290_2','art_truegrit_290',2,'{"blocks":[{"id":"blk_article_290_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flax and sesame are the two seeds most likely to show up in an Indian pantry, and while they get compared often, they play genuinely different roles, one long central to the cuisine, the other a smaller but real addition."]}},{"id":"blk_article_290_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where to start","items":["Sesame is the more foundational starting point, central to sweets, chutneys and tempering across many regional cuisines for generations.","Flax is a smaller, more specific addition, useful stirred into dough, dal or a smoothie without dominating the dish.","Both can be bought raw or roasted, with roasted being the more broadly useful default for most recipes.","Both can be pressed into oil, though flaxseed oil stays strictly raw while sesame oil can also be used for cooking.","Starting with roasted sesame and roasted flax covers the most common everyday uses without needing to grind or roast at home right away."]}},{"id":"blk_article_290_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Seeds to start with","source":"manual","productSlugs":["roasted-sesame-seeds","roasted-flax-seeds"],"limit":2}},{"id":"blk_article_290_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Seeds beginner guide questions","items":[{"question":"Which seed should a beginner buy first?","answer":"Sesame, given how central it is to a wide range of traditional Indian sweets, chutneys and tempering."},{"question":"Do I need to grind these seeds myself?","answer":"Not necessarily to start, roasted whole seed works well for many uses without any grinding needed."},{"question":"Is flax seed worth adding if I already use sesame?","answer":"Yes, if you want its specific fibre and oil content added quietly to meals you already make."},{"question":"Which is easier to cook with as a beginner?","answer":"Both are fairly easy, though sesame has more established, well known recipes to start from."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Flax and sesame play different roles, one long central to Indian cooking, the other a smaller but genuine addition.', seo_description='A beginner''s guide to seeds in Indian cooking: flax and sesame, their roles, and how to start cooking with each.', seo_keywords='seeds in Indian cooking guide, flax and sesame beginner', reading_minutes=3, published_version_id='arv_truegrit_290_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_290';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_290';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_290','Beginner’s Guide to Seeds in Indian Cooking','beginner-s-guide-to-seeds-in-indian-cooking','Flax and sesame play different roles, one long central to Indian cooking, the other a smaller but genuine addition.','seeds in Indian cooking guide, flax and sesame beginner');

-- 291. Meet Kathiya Wheat: From Farm to Your Kitchen
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_291_2','art_truegrit_291',2,'{"blocks":[{"id":"blk_article_291_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya is the wheat you reach for when you want a roti or daliya with real chew, a dense, rain fed landrace that has stayed a smaller crop precisely because it was never bred for volume."]}},{"id":"blk_article_291_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["Grown on rain fed land in Madhya Pradesh and Rajasthan, a harder wheat than most modern high yield varieties.","Its dense kernel needs more water and a longer rest in dough than standard atta.","Best known for a firmer roti and a daliya that holds its bite even after a full cook.","Costs more than commodity wheat, reflecting lower yield and a smaller growing region, not an added health claim.","A good pick if texture and a specific bite matter more to you than an easy, no adjustment cook."]}},{"id":"blk_article_291_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Kathiya wheat","source":"manual","productSlugs":["organic-kathiya-wheat","kathiya-wheat-flour"],"limit":2}},{"id":"blk_article_291_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet Kathiya questions","items":[{"question":"Is Kathiya a good first heritage wheat to try?","answer":"It is a distinctive choice, though Banshi is generally the more forgiving starting point for a first time buyer."},{"question":"What does Kathiya suit best?","answer":"Dishes where you want a firmer bite, roti with real chew and daliya that holds its shape well."},{"question":"Does Kathiya need special handling?","answer":"Mainly more water and a longer dough rest than standard atta, otherwise it cooks like any wheat flour."},{"question":"Where does Kathiya come from?","answer":"Rain fed land in Madhya Pradesh and Rajasthan, grown as a smaller, lower yield crop for generations."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The hardest and chewiest of our three wheats, grown on rain fed land for generations.', seo_description='Meet Kathiya wheat: a short introduction to its origin, character and place in a kitchen.', seo_keywords='Kathiya wheat introduction, meet Kathiya wheat', reading_minutes=2, published_version_id='arv_truegrit_291_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_291';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_291';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_291','Meet Kathiya Wheat: From Farm to Your Kitchen','meet-kathiya-wheat-from-farm-to-your-kitchen','The hardest and chewiest of our three wheats, grown on rain fed land for generations.','Kathiya wheat introduction, meet Kathiya wheat');

-- 292. Meet Banshi Wheat: From Farm to Your Kitchen
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_292_2','art_truegrit_292',2,'{"blocks":[{"id":"blk_article_292_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Banshi is the wheat that asks the least of you, grown on the Malwa plateau''s black cotton soil and landing right in the middle of the hardness scale, which is exactly why it suits most households first."]}},{"id":"blk_article_292_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["Grown on the Malwa plateau in Madhya Pradesh, a medium hardness wheat that cooks close to standard atta habits.","Puffs and softens like a familiar roti, without Kathiya''s noticeably chewier bite.","The most forgiving of the three for a first time buyer, needing no real technique adjustment.","A warmer, creamier colour than heavily refined maida, from the bran and germ it retains.","A sensible everyday choice if you only want to keep one heritage wheat stocked.","Also holds up reasonably well in a yeasted loaf, denser than a dedicated bread flour but genuinely workable."]}},{"id":"blk_article_292_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Banshi wheat","source":"manual","productSlugs":["banshi-wheat-flour"],"limit":1}},{"id":"blk_article_292_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet Banshi questions","items":[{"question":"Is Banshi the best starting wheat for a beginner?","answer":"Yes, generally, since it needs the least adjustment from standard atta cooking habits."},{"question":"What does Banshi suit best?","answer":"Everyday roti and general cooking, where a reliable, familiar result matters more than a distinctive texture."},{"question":"Does Banshi need any special handling?","answer":"Very little, it behaves close enough to standard atta that most recipes need no real adjustment."},{"question":"Where does Banshi come from?","answer":"The Malwa plateau''s black cotton soil in Madhya Pradesh, grown as a moderate input crop."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The easiest of our three wheats to cook with, grown on the Malwa plateau''s black cotton soil.', seo_description='Meet Banshi wheat: a short introduction to its origin, character and place in a kitchen.', seo_keywords='Banshi wheat introduction, meet Banshi wheat', reading_minutes=2, published_version_id='arv_truegrit_292_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_292';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_292';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_292','Meet Banshi Wheat: From Farm to Your Kitchen','meet-banshi-wheat-from-farm-to-your-kitchen','The easiest of our three wheats to cook with, grown on the Malwa plateau''s black cotton soil.','Banshi wheat introduction, meet Banshi wheat');

-- 293. Meet Paigambari Wheat: From Farm to Your Kitchen
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_293_2','art_truegrit_293',2,'{"blocks":[{"id":"blk_article_293_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Paigambari is the wheat people reach for when they want the grain''s own smell to be part of the dish, grown in Bundelkhand''s hot, semi arid climate and known first for its aroma, not its texture."]}},{"id":"blk_article_293_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["Grown in Bundelkhand, spanning southern Uttar Pradesh and northern Madhya Pradesh, on rain fed, drought tolerant land.","Known first for its aroma, more noticeable than either Kathiya or Banshi, especially freshly milled.","Best in plain dishes, simple roti or ghee brushed paratha, where the wheat''s own flavour is the point.","Aroma fades with storage time, so it is best bought in smaller quantities and used within a few weeks.","A worthwhile addition once you already have an everyday flour and want something more distinctive for specific dishes."]}},{"id":"blk_article_293_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Paigambari wheat","source":"manual","productSlugs":["paigambari-wheat-flour"],"limit":1}},{"id":"blk_article_293_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet Paigambari questions","items":[{"question":"What makes Paigambari different from the other two?","answer":"Its aroma, noticeably stronger and more distinctive than either Kathiya or Banshi."},{"question":"Should I buy Paigambari in large quantities?","answer":"No, its aroma fades with storage time, so smaller, more frequent purchases suit it better."},{"question":"What dishes suit Paigambari best?","answer":"Simple, lightly spiced preparations where the wheat''s own aroma is not competing with heavy spicing."},{"question":"Where does Paigambari come from?","answer":"Bundelkhand, a region spanning southern Uttar Pradesh and northern Madhya Pradesh, on rain fed land."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The most aromatic of our three wheats, grown in the hot, semi arid climate of Bundelkhand.', seo_description='Meet Paigambari wheat: a short introduction to its origin, character and place in a kitchen.', seo_keywords='Paigambari wheat introduction, meet Paigambari wheat', reading_minutes=2, published_version_id='arv_truegrit_293_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_293';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_293';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_293','Meet Paigambari Wheat: From Farm to Your Kitchen','meet-paigambari-wheat-from-farm-to-your-kitchen','The most aromatic of our three wheats, grown in the hot, semi arid climate of Bundelkhand.','Paigambari wheat introduction, meet Paigambari wheat');

-- 294. Meet Black Mustard: From Seed to Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_294_2','art_truegrit_294',2,'{"blocks":[{"id":"blk_article_294_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black mustard is the sharper of our two mustard oils, pressed from a more pungent seed, and it carries a long tradition in Bengali fish curries and pickling that yellow mustard oil does not quite match."]}},{"id":"blk_article_294_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["Pressed from a darker, more pungent mustard seed, kachi ghani style, with no added heat during pressing.","Traditional to Bengali and Eastern Indian cooking, especially fish curries and pickling.","Best heated briefly to a light smoke before cooking, which mellows its raw sharpness.","A more assertive choice than yellow mustard oil, suited to dishes that want a strong, distinct mustard flavour.","A worthwhile addition once you already cook with yellow mustard oil and want something more intense for specific dishes.","Also a classic pickling oil, valued both for flavour and its natural preservative qualities."]}},{"id":"blk_article_294_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black mustard oil","source":"manual","productSlugs":["black-mustard-oil"],"limit":1}},{"id":"blk_article_294_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet black mustard questions","items":[{"question":"Is black mustard oil good for a first time buyer?","answer":"Yellow mustard oil is generally the more forgiving starting point, with black worth trying once you know you want a stronger flavour."},{"question":"What is black mustard oil traditionally used for?","answer":"Bengali fish curries and pickling are its most classic traditional uses."},{"question":"Does black mustard oil need special handling?","answer":"Heating it to a light smoke before cooking is a common, worthwhile step to mellow its raw pungency."},{"question":"How is black mustard oil pressed?","answer":"Kachi ghani style, mechanical pressure with no added heat, discussed in more depth elsewhere in this guide."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The sharper, more assertive of our two mustard oils, traditional to Bengali cooking and pickling.', seo_description='Meet black mustard oil: a short introduction to its character, traditional uses and how to start cooking with it.', seo_keywords='black mustard oil introduction, meet black mustard oil', reading_minutes=2, published_version_id='arv_truegrit_294_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_294';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_294';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_294','Meet Black Mustard: From Seed to Oil','meet-black-mustard-from-seed-to-oil','The sharper, more assertive of our two mustard oils, traditional to Bengali cooking and pickling.','black mustard oil introduction, meet black mustard oil');

-- 295. Meet Yellow Mustard: From Seed to Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_295_2','art_truegrit_295',2,'{"blocks":[{"id":"blk_article_295_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Yellow mustard is the more approachable of our two mustard oils, milder and rounder than black, and it is the one most households across North India already reach for without a second thought."]}},{"id":"blk_article_295_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["Pressed from a milder mustard seed, kachi ghani style, with no added heat during pressing.","The default bottle in most North Indian kitchens for everyday tempering and general sabzi.","Milder and easier to work with than black mustard oil, needing less adjustment to get comfortable cooking with it.","A sensible everyday choice if you only want to keep one mustard oil stocked.","Still benefits from a light smoke before cooking, though the effect is subtler than with black mustard oil.","A dependable everyday bottle for a kitchen that cooks a broad mix of North Indian dishes."]}},{"id":"blk_article_295_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Yellow mustard oil","source":"manual","productSlugs":["yellow-mustard-oil"],"limit":1}},{"id":"blk_article_295_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet yellow mustard questions","items":[{"question":"Should a beginner start here rather than with black mustard oil?","answer":"Yes, it is the more forgiving of our two mustard oils for someone new to cooking with mustard oil."},{"question":"What is yellow mustard oil traditionally used for?","answer":"Everyday tempering and general sabzi across much of North India."},{"question":"Does yellow mustard oil need any special handling?","answer":"Very little, though a light smoke before cooking still helps mellow its flavour slightly."},{"question":"How does it compare to black mustard oil?","answer":"Noticeably milder and rounder, suited to everyday cooking rather than a specific strong flavoured dish."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The milder, more everyday of our two mustard oils, suited to tempering and general sabzi.', seo_description='Meet yellow mustard oil: a short introduction to its character, everyday uses and how to start cooking with it.', seo_keywords='yellow mustard oil introduction, meet yellow mustard oil', reading_minutes=2, published_version_id='arv_truegrit_295_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_295';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_295';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_295','Meet Yellow Mustard: From Seed to Oil','meet-yellow-mustard-from-seed-to-oil','The milder, more everyday of our two mustard oils, suited to tempering and general sabzi.','yellow mustard oil introduction, meet yellow mustard oil');

-- 296. Meet Flax: From Farm to Seed and Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_296_2','art_truegrit_296',2,'{"blocks":[{"id":"blk_article_296_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flax, known as alsi in Hindi, is a small oilseed with a growing place in Indian kitchens, sold whole, roasted, or pressed into an oil used strictly raw rather than for cooking."]}},{"id":"blk_article_296_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["A small oilseed sold whole, roasted, or pressed into oil, known as alsi in Hindi.","Roasted flax carries a much stronger, nuttier flavour than raw, and suits most Indian recipes calling for it.","Flaxseed oil is cold-pressed and used entirely raw, stirred into a finished dish, never heated.","Traditional in Maharashtrian chutneys, and increasingly added to dough, dal and smoothies more broadly.","A good addition once your pantry already covers the everyday staples and you want to diversify further.","Comes in golden and brown colour varieties, differing mainly in appearance rather than in how they are used."]}},{"id":"blk_article_296_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Flax seed and oil","source":"manual","productSlugs":["roasted-flax-seeds","linseed-flax-seed-oil"],"limit":2}},{"id":"blk_article_296_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet flax questions","items":[{"question":"Should I start with the seed or the oil?","answer":"The roasted seed is the easier starting point, useful in more everyday recipes than the oil''s specific raw use case."},{"question":"Can flaxseed oil be used for cooking?","answer":"No, it should always be added raw, after cooking is done, never heated."},{"question":"What is flax traditionally used for in Indian cooking?","answer":"Roasted and ground into chutney, particularly in Maharashtrian cooking, alongside a growing range of everyday additions."},{"question":"Does flax need special storage?","answer":"The oil needs more care than the seed, ideally refrigerated after opening, discussed further elsewhere in this guide."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A small oilseed with a growing place in Indian kitchens, sold whole, roasted, or pressed into a raw finishing oil.', seo_description='Meet flax: a short introduction to the seed, its oil, and how to start cooking with each.', seo_keywords='flax seed introduction, meet flax', reading_minutes=2, published_version_id='arv_truegrit_296_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_296';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_296';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_296','Meet Flax: From Farm to Seed and Oil','meet-flax-from-farm-to-seed-and-oil','A small oilseed with a growing place in Indian kitchens, sold whole, roasted, or pressed into a raw finishing oil.','flax seed introduction, meet flax');

-- 297. Meet Sesame: From Farm to Seed and Oil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_297_2','art_truegrit_297',2,'{"blocks":[{"id":"blk_article_297_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Sesame, called til in Hindi, is one of the oldest cultivated oilseeds in the region, with a history that runs through festival sweets, everyday tempering and a pressed oil used across regional Indian cooking."]}},{"id":"blk_article_297_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["A small oilseed with white and black varieties, known as til in Hindi, central to Indian food traditions for generations.","Roasting transforms its flavour dramatically, which is why most Indian recipes call for the roasted form.","Sesame oil, raw or roasted pressed, can be used for both cooking and finishing, unlike flaxseed oil''s raw only role.","Deeply tied to Makar Sankranti and other festival foods, alongside everyday chutneys and tempering.","A genuinely foundational seed to start with if you are building an Indian pantry from scratch."]}},{"id":"blk_article_297_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Sesame seed and oil","source":"manual","productSlugs":["roasted-sesame-seeds","sesame-oil"],"limit":2}},{"id":"blk_article_297_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet sesame questions","items":[{"question":"Is the seed or the oil the better place to start with sesame?","answer":"The roasted seed is the more foundational starting point, useful across more everyday recipes than the oil alone."},{"question":"Can sesame oil be used for cooking, unlike flaxseed oil?","answer":"Yes, particularly raw pressed sesame oil, which can handle moderate cooking heat as well as finishing use."},{"question":"What festival is sesame most associated with?","answer":"Makar Sankranti, where til-gud sweets are a central, longstanding tradition."},{"question":"How old is sesame cultivation in this region?","answer":"Considered one of the oldest cultivated oilseed crops on the subcontinent, discussed further elsewhere in this guide."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One of the oldest cultivated oilseeds in the region, central to sweets, tempering and pressed oil alike.', seo_description='Meet sesame: a short introduction to the seed, its oil, and its long history in Indian cooking.', seo_keywords='sesame seed introduction, meet sesame', reading_minutes=2, published_version_id='arv_truegrit_297_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_297';
