INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_297','Meet Sesame: From Farm to Seed and Oil','meet-sesame-from-farm-to-seed-and-oil','One of the oldest cultivated oilseeds in the region, central to sweets, tempering and pressed oil alike.','sesame seed introduction, meet sesame');

-- 298. Meet Black Gram: From Farm to Dal, Sattu and Besan
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_298_2','art_truegrit_298',2,'{"blocks":[{"id":"blk_article_298_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram, urad, is a protein rich pulse that branches into more forms than most, whole for dal makhani, split for dosa batter, roasted into sattu, or ground raw into besan."]}},{"id":"blk_article_298_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["A pulse with a black skin and pale white interior, known as urad in Hindi.","Whole black gram anchors slow simmered dal makhani, holding its shape through a long cook.","Split urad dal, dehusked and quicker cooking, is the base for dosa and idli batter as well as tempered dals.","Roasted and ground into sattu, it becomes a ready to eat, protein rich flour for a drink or filling.","Ground raw into besan, it makes a heavier, earthier alternative to the more familiar chickpea besan.","A genuinely versatile pulse once you know which of its four forms suits the dish you have in mind."]}},{"id":"blk_article_298_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Black gram in every form","source":"manual","productSlugs":["black-gram-whole","black-gram-broken-dal","black-gram-sattu"],"limit":3}},{"id":"blk_article_298_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet black gram questions","items":[{"question":"Which form of black gram should I buy first?","answer":"Split urad dal is the most versatile starting point, useful across dal, khichdi and South Indian batters alike."},{"question":"Is urad just another name for this same pulse?","answer":"Yes, urad is simply the Hindi name for black gram, the same pulse under either term."},{"question":"Do I need all four forms, whole, split, sattu and besan?","answer":"Not necessarily, most households pick the forms suited to what they actually cook most often."},{"question":"What makes black gram different from other common pulses?","answer":"Its heavier, earthier flavour and its central role in both North Indian dal and South Indian fermented batters."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='One pulse, three destinations, anchoring everything from dal makhani to dosa batter.', seo_description='Meet black gram: a short introduction to urad in its whole, split, sattu and besan forms.', seo_keywords='black gram introduction, meet black gram, urad', reading_minutes=2, published_version_id='arv_truegrit_298_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_298';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_298';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_298','Meet Black Gram: From Farm to Dal, Sattu and Besan','meet-black-gram-from-farm-to-dal-sattu-and-besan','One pulse, three destinations, anchoring everything from dal makhani to dosa batter.','black gram introduction, meet black gram, urad');

-- 299. Meet Masoor: From Farm to Lentil
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_299_2','art_truegrit_299',2,'{"blocks":[{"id":"blk_article_299_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Masoor, red lentils, is the pulse to reach for when time is short, cooking faster than almost any other common dal while still bringing real flavour to the table."]}},{"id":"blk_article_299_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["A small, lens shaped pulse, sold whole with a brownish green skin or split into the familiar orange red dal.","Among the fastest cooking common pulses, often needing little to no soaking, especially in split form.","Split masoor breaks down into a smooth dal quickly. Whole masoor holds its shape better for a heartier curry.","A reliable weeknight staple, given how little planning it needs compared to most other dals.","A sensible first pulse to buy if you are building a pantry and want something genuinely quick to cook.","Pairs well with almost any simple tempering, cumin, garlic and dried red chilli in ghee."]}},{"id":"blk_article_299_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Masoor","source":"manual","productSlugs":["red-lentils-broken","red-lentils-whole"],"limit":2}},{"id":"blk_article_299_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet masoor questions","items":[{"question":"Is masoor a good starting pulse for a beginner cook?","answer":"Yes, its fast, forgiving cooking time makes it one of the easiest pulses to start with."},{"question":"Should I buy whole or split masoor first?","answer":"Split, for its speed and versatility across everyday dal and khichdi."},{"question":"Does masoor need soaking?","answer":"Barely, split masoor cooks well with little to no soaking, unlike many other common pulses."},{"question":"What dishes is masoor best known for?","answer":"A quick everyday dal and khichdi, along with a heartier whole masoor curry."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='The fastest cooking of the common pulses, sold whole or split, always a reliable weeknight option.', seo_description='Meet masoor: a short introduction to red lentils, their whole and split forms, and everyday uses.', seo_keywords='masoor introduction, meet masoor, red lentils', reading_minutes=2, published_version_id='arv_truegrit_299_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_299';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_299';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_299','Meet Masoor: From Farm to Lentil','meet-masoor-from-farm-to-lentil','The fastest cooking of the common pulses, sold whole or split, always a reliable weeknight option.','masoor introduction, meet masoor, red lentils');

-- 300. Meet White Field Pea: From Farm to Kitchen
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_300_2','art_truegrit_300',2,'{"blocks":[{"id":"blk_article_300_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["White field pea, safed matar, asks for a bit more planning than most pulses, a genuine overnight soak, but rewards that patience with dishes like ghugni and ragda that few other pulses replicate well."]}},{"id":"blk_article_300_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Quick introduction","items":["A dried, mature pea, quite different from fresh green peas, pale cream in colour with a starchy, earthy flavour.","Needs a genuine overnight soak, unlike faster cooking pulses like masoor, to cook evenly in a reasonable time.","Central to ghugni and ragda, both built around the pea''s soft, slightly mashable cooked texture.","A pulse worth adding once you already have faster, everyday staples covered and want to try something more specific.","Stores well dried for a year or more, so buying ahead of when you plan to cook it is entirely reasonable."]}},{"id":"blk_article_300_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"White field peas","source":"manual","productSlugs":["field-pea-white"],"limit":1}},{"id":"blk_article_300_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Meet white field pea questions","items":[{"question":"Is white field pea a good first pulse to buy?","answer":"It is better suited as an addition once you have faster, everyday pulses like masoor covered, given the planning it needs."},{"question":"Does it really need overnight soaking?","answer":"Yes, genuinely, unlike some other common pulses where soaking is more optional."},{"question":"What is white field pea best known for?","answer":"Ghugni and ragda, both classic dishes built around its soft, cooked texture."},{"question":"Is this the same as fresh green peas?","answer":"No, it is the same plant at a much later, dried maturity stage, with a very different texture and flavour."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A dried, starchy pea that needs planning ahead, rewarded with dishes like ghugni and ragda.', seo_description='Meet white field pea: a short introduction to safed matar, its cooking needs, and traditional dishes.', seo_keywords='white field pea introduction, meet white field pea', reading_minutes=2, published_version_id='arv_truegrit_300_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_300';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_300';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_300','Meet White Field Pea: From Farm to Kitchen','meet-white-field-pea-from-farm-to-kitchen','A dried, starchy pea that needs planning ahead, rewarded with dishes like ghugni and ragda.','white field pea introduction, meet white field pea');

-- 301. Know Your Grain: A Beginner’s Guide to Traditional Indian Wheat
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_301_2','art_truegrit_301',2,'{"blocks":[{"id":"blk_article_301_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Kathiya, Banshi and Paigambari are not marketing variations on the same flour, they are genuinely different landraces with their own hardness, aroma and history, and knowing the basics makes a first purchase far less of a guess."]}},{"id":"blk_article_301_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to know before buying","items":["Kathiya is the hardest and chewiest, needing more water and a longer dough rest than standard atta.","Banshi sits in the middle, the easiest to cook with and the safest starting point for a first time buyer.","Paigambari is the most aromatic, best in plain dishes where the wheat''s own smell should carry through.","All three cost more than commodity wheat, reflecting lower yield and smaller growing regions, not a certified health claim.","Trying a small quantity of each is a reasonable way to find your own preference before committing to a regular order."]}},{"id":"blk_article_301_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"All three wheats","source":"manual","productSlugs":["kathiya-wheat-flour","banshi-wheat-flour","paigambari-wheat-flour"],"limit":3}},{"id":"blk_article_301_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Know your grain questions","items":[{"question":"Which wheat should a complete beginner start with?","answer":"Banshi, since it needs the least adjustment from standard atta cooking habits."},{"question":"Are these three wheats nutritionally different from regular wheat?","answer":"There is no verified nutritional advantage, the real differences are texture, aroma and cooking behaviour."},{"question":"Why do these wheats cost more than commodity atta?","answer":"Lower yield and smaller growing regions, the same honest reasons across all three varieties."},{"question":"Can I mix these wheats with regular atta?","answer":"Yes, many cooks start by blending a smaller proportion of a heritage wheat into their regular flour."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Three landraces, three genuinely different personalities, none of them a marketing gimmick.', seo_description='A beginner''s guide to traditional Indian wheat: Kathiya, Banshi and Paigambari, and how to choose your first bag.', seo_keywords='know your grain, traditional Indian wheat guide', reading_minutes=3, published_version_id='arv_truegrit_301_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_301';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_301';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_301','Know Your Grain: A Beginner’s Guide to Traditional Indian Wheat','know-your-grain-a-beginner-s-guide-to-traditional-indian-wheat','Three landraces, three genuinely different personalities, none of them a marketing gimmick.','know your grain, traditional Indian wheat guide');

-- 302. Know Your Oil: A Guide to Traditional Cold-Pressed Oils
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_302_2','art_truegrit_302',2,'{"blocks":[{"id":"blk_article_302_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Cold-pressed does not mean interchangeable. Mustard, sesame and flaxseed oil are all traditionally pressed with no added heat, but each plays a genuinely different role once it reaches the kitchen."]}},{"id":"blk_article_302_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to know before buying","items":["Mustard oil, black or yellow, is a real cooking oil, pungent and traditional to North and East Indian cuisine.","Sesame oil, raw or roasted pressed, spans both cooking and finishing, more central to South Indian cooking.","Flaxseed oil is strictly a raw finishing oil, never heated, added in small amounts once cooking is done.","All three benefit from cool, dark storage, though flaxseed oil specifically needs refrigeration after opening.","A well rounded oil shelf covers at least one genuine cooking oil and, optionally, a finishing oil like flaxseed.","Checking each product''s certification and pressing method before buying helps set the right expectations."]}},{"id":"blk_article_302_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"All three oils","source":"manual","productSlugs":["yellow-mustard-oil","sesame-oil","linseed-flax-seed-oil"],"limit":3}},{"id":"blk_article_302_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Know your oil questions","items":[{"question":"Which oil is essential to have on hand?","answer":"A genuine cooking oil, mustard or sesame, is the essential starting point. Flaxseed is a smaller, optional addition."},{"question":"Is cold-pressed always the right choice over refined?","answer":"It depends on the dish, cold-pressed carries more flavour, refined offers a milder, more neutral result."},{"question":"Do all three oils need the same storage?","answer":"No, flaxseed oil needs more careful, refrigerated storage than mustard or sesame oil generally require."},{"question":"Can flaxseed oil replace a cooking oil in my kitchen?","answer":"No, it should never be heated, so it cannot serve as a primary cooking oil."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Cold-pressed does not mean interchangeable. Each oil in this range plays its own role.', seo_description='A guide to traditional cold-pressed oils: mustard, sesame and flaxseed, and how to build a well rounded oil shelf.', seo_keywords='know your oil, cold pressed oil guide', reading_minutes=3, published_version_id='arv_truegrit_302_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_302';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_302';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_302','Know Your Oil: A Guide to Traditional Cold-Pressed Oils','know-your-oil-a-guide-to-traditional-cold-pressed-oils','Cold-pressed does not mean interchangeable. Each oil in this range plays its own role.','know your oil, cold pressed oil guide');

-- 303. Know Your Pulse: A Guide to Indian Pulses and Lentils
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_303_2','art_truegrit_303',2,'{"blocks":[{"id":"blk_article_303_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Black gram, red lentils and white field peas differ enough in cooking time and traditional use that knowing which is which before you shop saves real guesswork once you are actually at the stove."]}},{"id":"blk_article_303_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What to know before buying","items":["Black gram, urad, is heavier and more versatile, spanning dal, sattu, besan and South Indian batters.","Red lentils, masoor, are the fastest cooking, the pulse to reach for on a genuinely short timeline.","White field peas need the most advance planning, a real overnight soak, but anchor dishes like ghugni and ragda.","Whole forms generally need more soaking and cooking time than split or dehusked forms of the same pulse.","A well stocked pulse shelf covers at least one fast cooking option and one slower, more textured one."]}},{"id":"blk_article_303_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"All three pulses","source":"manual","productSlugs":["black-gram-whole","red-lentils-broken","field-pea-white"],"limit":3}},{"id":"blk_article_303_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Know your pulse questions","items":[{"question":"Which pulse is the most versatile to keep stocked?","answer":"Black gram, given how many forms it comes in, whole, split, sattu and besan, each suited to different dishes."},{"question":"Which pulse is best for a quick weeknight meal?","answer":"Red lentils, thanks to their fast, forgiving cooking time."},{"question":"Which pulse needs the most planning ahead?","answer":"White field peas, which need a genuine overnight soak before cooking."},{"question":"Should I keep all three stocked at once?","answer":"It covers the widest range of dishes, though a smaller household may prefer starting with just one or two."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Different cooking times, different textures, different dishes. Knowing which is which saves real guesswork.', seo_description='A guide to Indian pulses and lentils: black gram, red lentils and white field peas, and how to shop for each.', seo_keywords='know your pulse, Indian pulses guide', reading_minutes=3, published_version_id='arv_truegrit_303_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_303';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_303';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_303','Know Your Pulse: A Guide to Indian Pulses and Lentils','know-your-pulse-a-guide-to-indian-pulses-and-lentils','Different cooking times, different textures, different dishes. Knowing which is which saves real guesswork.','know your pulse, Indian pulses guide');

-- 304. Know Your Farmer: Why Food Provenance Matters
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_304_2','art_truegrit_304',2,'{"blocks":[{"id":"blk_article_304_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Knowing where food comes from matters less because of a specific name on a label and more because of what that information actually lets you check, harvest timing, variety and how a product was handled along the way."]}},{"id":"blk_article_304_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"What actually matters here","items":["Specific, checkable details, harvest date, variety and processing method, tend to matter more than a farm or village name alone.","Provenance information supports accountability, connecting a product back through its supply chain if a question ever arises.","It also supports genuine certification claims, which require documented sourcing rather than a simple label statement.","This is not about romanticising a single farm, it is about the practical value of a traceable, checkable supply chain.","Shoppers who care about provenance are best served by asking what specifically can be verified, not just whether a story sounds good."]}},{"id":"blk_article_304_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traceable staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole"],"limit":2}},{"id":"blk_article_304_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Food provenance questions","items":[{"question":"Is a farm name alone useful information?","answer":"On its own, less than it might seem, since it is often hard for a shopper to independently verify."},{"question":"What provenance information is actually checkable?","answer":"Harvest date, variety and certification details are generally more concretely verifiable than a name alone."},{"question":"Does provenance information connect to certification?","answer":"Yes, genuine organic and other certifications require documented sourcing records as part of the standard."},{"question":"Should I be skeptical of vague provenance claims?","answer":"A reasonable amount of skepticism toward unverifiable claims is a sensible default for any shopper."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Knowing where food comes from is less about a specific name and more about what is genuinely checkable.', seo_description='Why food provenance matters: what knowing your farmer actually offers, and what information is genuinely checkable.', seo_keywords='know your farmer, food provenance', reading_minutes=2, published_version_id='arv_truegrit_304_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_304';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_304';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_304','Know Your Farmer: Why Food Provenance Matters','know-your-farmer-why-food-provenance-matters','Knowing where food comes from is less about a specific name and more about what is genuinely checkable.','know your farmer, food provenance');

-- 305. From Seed to Shelf: The True Grit Food Journey
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_305_2','art_truegrit_305',2,'{"blocks":[{"id":"blk_article_305_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Every product in this range follows a similar arc, sourced grain, seed or pulse, processed using traditional methods suited to the ingredient, and packaged in small batches rather than held in long term bulk storage."]}},{"id":"blk_article_305_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The journey at a glance","items":["Sourcing starts with specific varieties, heritage wheat landraces, particular pulses and oilseeds, rather than a generic commodity blend.","Processing follows traditional methods, cracking, pressing, dehusking or milling, suited to what the specific ingredient actually is.","Production happens in smaller batches, timed closer to demand, discussed in more depth elsewhere in this guide.","Quality checks happen at multiple points along the way, not only at final packaging.","Packaging aims to get a genuinely fresh product to your kitchen, rather than one that has sat in a long supply chain."]}},{"id":"blk_article_305_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Products from this journey","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil","black-gram-whole"],"limit":3}},{"id":"blk_article_305_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Seed to shelf journey questions","items":[{"question":"Does this journey apply to every single product?","answer":"It describes our general approach, though specific steps vary somewhat by ingredient and product."},{"question":"Why does this approach take longer than mass production?","answer":"Sourcing specific varieties and traditional processing both take more time than fully automated, high volume methods."},{"question":"Does following this journey affect what a product costs?","answer":"It can, smaller scale, traditional processing generally costs more per unit than large scale industrial production."},{"question":"How can I learn more about a specific product''s journey?","answer":"Individual product pages carry whatever specific sourcing detail is available for that item."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Sourcing, traditional processing and small batch packaging, the same broad arc behind every product here.', seo_description='The True Grit food journey from seed to shelf: sourcing, traditional processing, and getting products to your kitchen.', seo_keywords='True Grit food journey, seed to shelf', reading_minutes=3, published_version_id='arv_truegrit_305_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_305';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_305';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_305','From Seed to Shelf: The True Grit Food Journey','from-seed-to-shelf-the-true-grit-food-journey','Sourcing, traditional processing and small batch packaging, the same broad arc behind every product here.','True Grit food journey, seed to shelf');

-- 306. Why Traditional Food Processing Deserves a Comeback
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_306_2','art_truegrit_306',2,'{"blocks":[{"id":"blk_article_306_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["The case for traditional food processing is not really about nostalgia, it is about what these methods still do genuinely well, quality control, adaptability and a character that fully industrial processing tends to smooth away."]}},{"id":"blk_article_306_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The genuine case","items":["Traditional methods allow closer attention at each step, catching quality issues that automated sorting can sometimes miss.","Smaller batches suit ingredients where freshness genuinely changes the result, rather than treating every product identically.","Traditional processing supports livelihoods, including the village and self help group work discussed elsewhere in this guide.","It is not a rejection of modern methods entirely, most food businesses, including this one, use a mix suited to different products.","The comeback is less about replacing industrial processing and more about not losing traditional methods entirely to it."]}},{"id":"blk_article_306_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Traditionally processed staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-mustard-oil"],"limit":2}},{"id":"blk_article_306_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Traditional processing comeback questions","items":[{"question":"Is this argument against industrial food processing entirely?","answer":"No, it argues for keeping traditional methods viable alongside industrial ones, not replacing one with the other."},{"question":"What does traditional processing do better specifically?","answer":"Closer quality control and adaptability to smaller batches are the clearest genuine advantages."},{"question":"Does this connect to rural livelihoods?","answer":"Yes, traditional processing supports the kind of village based and self help group work discussed elsewhere in this guide."},{"question":"Is traditional processing always the right choice?","answer":"Not universally, it suits certain products and priorities better than others, discussed further elsewhere in this guide."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Not nostalgia for its own sake, but a genuine case for what traditional methods still do well.', seo_description='Why traditional food processing deserves a comeback: quality control, character and what industrial methods trade away.', seo_keywords='traditional food processing comeback, why traditional methods matter', reading_minutes=2, published_version_id='arv_truegrit_306_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_306';
