INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_306','Why Traditional Food Processing Deserves a Comeback','why-traditional-food-processing-deserves-a-comeback','Not nostalgia for its own sake, but a genuine case for what traditional methods still do well.','traditional food processing comeback, why traditional methods matter');

-- 307. How to Build a Traditional Indian Pantry
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_307_2','art_truegrit_307',2,'{"blocks":[{"id":"blk_article_307_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["A traditional Indian pantry does not need to be extensive to be genuinely useful, a handful of staples across grains, pulses and oils covers a surprising range of everyday cooking."]}},{"id":"blk_article_307_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where to start","items":["A wheat flour, Banshi is the easiest starting point, covers roti and paratha, the daily backbone of most meals.","A fast cooking pulse, split masoor dal, covers quick everyday dal without much planning ahead.","A versatile pulse, split urad dal, extends into tempered dals, khichdi and South Indian batters.","An everyday cooking oil, yellow mustard oil, covers tempering and general sabzi across most regional styles.","From there, daliya, semolina, a second wheat variety or a specialty oil like sesame can be added as your cooking grows more varied.","None of this needs to happen at once, a pantry built gradually still gets you cooking properly from the very first purchase."]}},{"id":"blk_article_307_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Pantry starter set","source":"manual","productSlugs":["banshi-wheat-flour","red-lentils-broken","yellow-mustard-oil"],"limit":3}},{"id":"blk_article_307_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Building a pantry questions","items":[{"question":"What are the absolute essentials to start with?","answer":"A wheat flour, a fast cooking pulse and an everyday cooking oil cover a wide range of meals on their own."},{"question":"Should I buy heritage wheat varieties from the start?","answer":"Banshi is a reasonable starting flour, with Kathiya and Paigambari worth adding once you know your preferences."},{"question":"How many pulses do I really need?","answer":"Two is a reasonable starting point, one fast cooking and one more versatile, adding more as your cooking expands."},{"question":"Is one cooking oil enough to start?","answer":"Yes, a single everyday oil like yellow mustard oil covers most basic cooking needs to begin with."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A handful of staples across grains, pulses and oils covers most traditional Indian cooking.', seo_description='How to build a traditional Indian pantry: essential grains, pulses and oils to start with.', seo_keywords='traditional Indian pantry, Indian pantry essentials', reading_minutes=3, published_version_id='arv_truegrit_307_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_307';
