INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_307','How to Build a Traditional Indian Pantry','how-to-build-a-traditional-indian-pantry','A handful of staples across grains, pulses and oils covers most traditional Indian cooking.','traditional Indian pantry, Indian pantry essentials');

-- 308. Essential Organic Staples for an Indian Kitchen
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_308_2','art_truegrit_308',2,'{"blocks":[{"id":"blk_article_308_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Building an organic kitchen is really about choosing genuinely certified versions of staples you likely already buy, rather than an entirely new shopping list."]}},{"id":"blk_article_308_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"Where to start","items":["A certified organic wheat, like Kathiya, covers the daily staple of roti with a verified sourcing standard behind it.","A certified organic pulse, like whole black gram, extends into dal, sattu and besan with the same verification.","A certified organic cooking oil, like black or yellow mustard oil, covers everyday cooking with a documented supply chain.","Checking the certification details on each, covered in more depth elsewhere in this guide, confirms the organic claim is genuine.","From there, expanding into daliya, semolina or a specialty oil rounds out an organic kitchen at your own pace and budget."]}},{"id":"blk_article_308_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Organic starter staples","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole","black-mustard-oil"],"limit":3}},{"id":"blk_article_308_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Organic staples questions","items":[{"question":"Do I need to replace my entire pantry with organic at once?","answer":"No, starting with a few genuinely certified staples and expanding gradually is a reasonable approach."},{"question":"How do I confirm a product is genuinely organic?","answer":"Check the certification mark and certificate number, covered in more detail elsewhere in this guide."},{"question":"Is organic always significantly more expensive?","answer":"Usually somewhat more, for reasons covered in more depth elsewhere in this guide, lower yield and smaller scale production."},{"question":"Which staple is the easiest first organic purchase?","answer":"A wheat flour is a practical starting point, given how central it is to most Indian kitchens."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='A shorter, more specific list than a general pantry guide, focused on what is genuinely certified organic.', seo_description='Essential organic staples for an Indian kitchen: certified organic grains, pulses and oils to start with.', seo_keywords='organic staples Indian kitchen, essential organic groceries', reading_minutes=3, published_version_id='arv_truegrit_308_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_308';
