INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_308','Essential Organic Staples for an Indian Kitchen','essential-organic-staples-for-an-indian-kitchen','A shorter, more specific list than a general pantry guide, focused on what is genuinely certified organic.','organic staples Indian kitchen, essential organic groceries');

-- 309. How to Choose Between Flour, Daliya, Semolina, Pasta and Vermicelli
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_309_2','art_truegrit_309',2,'{"blocks":[{"id":"blk_article_309_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Flour, daliya, semolina, pasta and vermicelli all trace back to the same wheat, and the fastest way to decide which one you need is to start from the dish rather than the ingredient."]}},{"id":"blk_article_309_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"How to actually decide","items":["Making roti or paratha? You need flour, the most finely milled and widely used of the five forms.","Want a coarser, more textured breakfast, savoury or sweet? You need daliya, cracked rather than ground.","Making upma, halwa or rava idli? You need semolina, the coarse middlings sieved during milling.","Cooking an Indian style pasta dish? You need pasta, formed and dried or cooked fresh from flour or semolina.","Making sevai or seviyan kheer? You need vermicelli, thin strands usually sold pre-roasted.","Not sure which dish you are making yet? Flour is the safest general purpose starting point of the five."]}},{"id":"blk_article_309_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Every wheat form","source":"manual","productSlugs":["kathiya-wheat-flour","daliya-banshi-wheat","semolina-paigambari-wheat"],"limit":3}},{"id":"blk_article_309_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Choosing wheat forms questions","items":[{"question":"Do all five forms come from the same wheat variety?","answer":"They can, any of our three wheat landraces can be processed into any of these five forms."},{"question":"Which form should I buy if I only want one?","answer":"Flour, since it covers the widest range of everyday dishes on its own."},{"question":"Can one form substitute for another in a recipe?","answer":"Rarely well, each is processed differently and suits a genuinely different texture and cooking method."},{"question":"Is there a wrong form to buy for a beginner?","answer":"No, though starting with flour and adding the others as your cooking expands is a practical approach."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='All wheat, all different jobs. A quick way to decide which form actually belongs on your shopping list.', seo_description='How to choose between flour, daliya, semolina, pasta and vermicelli, all wheat forms suited to different dishes.', seo_keywords='choosing between wheat forms, flour daliya semolina pasta vermicelli', reading_minutes=3, published_version_id='arv_truegrit_309_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_309';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_309';
INSERT INTO search_content (entity_type,entity_id,title,slug,excerpt,keywords) VALUES ('article','art_truegrit_309','How to Choose Between Flour, Daliya, Semolina, Pasta and Vermicelli','how-to-choose-between-flour-daliya-semolina-pasta-and-vermicelli','All wheat, all different jobs. A quick way to decide which form actually belongs on your shopping list.','choosing between wheat forms, flour daliya semolina pasta vermicelli');

-- 310. A Complete Guide to True Grit’s Organic Product Range
INSERT INTO article_versions (id,article_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('arv_truegrit_310_2','art_truegrit_310',2,'{"blocks":[{"id":"blk_article_310_1","type":"rich_text","version":1,"enabled":true,"props":{"paragraphs":["Across wheat, pulses and oils, this range is built on the same underlying principle, real named varieties rather than a generic commodity blend, traditional processing suited to each ingredient, and genuine certification behind the organic claim."]}},{"id":"blk_article_310_2","type":"bullet_list","version":1,"enabled":true,"props":{"heading":"The range at a glance","items":["Wheat, in flour, daliya, semolina, pasta and vermicelli forms, across Kathiya, Banshi and Paigambari landraces.","Pulses, black gram, red lentils and white field peas, in whole, split and further processed forms like sattu and besan.","Oils, black and yellow mustard, sesame and flaxseed, each traditionally pressed and suited to a different role.","Every product carries certification details worth checking, covered in more depth elsewhere in this guide.","The range keeps growing gradually rather than all at once, reflecting the traditional, smaller batch approach behind it."]}},{"id":"blk_article_310_3","type":"product_collection","version":1,"enabled":true,"props":{"heading":"Across the range","source":"manual","productSlugs":["organic-kathiya-wheat","black-gram-whole","sesame-oil"],"limit":3}},{"id":"blk_article_310_4","type":"faq","version":1,"enabled":true,"props":{"heading":"Product range guide questions","items":[{"question":"What are the three main categories in this range?","answer":"Wheat in its various forms, pulses, and traditionally pressed cooking and finishing oils."},{"question":"Is everything in the range certified organic?","answer":"Check individual product pages for specific certification details, since this is the reliable way to confirm any organic claim."},{"question":"Where should a new customer start?","answer":"A single everyday staple, like a wheat flour or an everyday cooking oil, is a reasonable first purchase."},{"question":"Does the range expand regularly?","answer":"Gradually, in line with the smaller batch, traditional processing approach described throughout this guide."}]}}]}','published','2026-08-17T09:00:00Z','usr_catalogue_system');
UPDATE articles SET excerpt='Wheat, pulses and oils, all built on the same principle, real varieties, traditional processing, genuine certification.', seo_description='A complete guide to True Grit''s organic product range: wheat, pulses and oils, and how they all connect.', seo_keywords='True Grit organic product range, product range guide', reading_minutes=3, published_version_id='arv_truegrit_310_2', updated_at='2026-08-17T09:00:00Z', updated_by='usr_catalogue_system' WHERE id='art_truegrit_310';
DELETE FROM search_content WHERE entity_type='article' AND entity_id='art_truegrit_310';
